// ─── MINIMUM WAGE ────────────────────────────────────────────────────────────
// Rates include rolled-up holiday pay, so they're compared directly against the
// hourly rate recorded on each staff member. Editable on the Staff page because
// they change every April.
const MIN_WAGE_KEY = "hbf_min_wage_v1";
const MIN_WAGE_DEFAULTS = { under18: 8.46, under21: 11.21, adult: 14.26 };

// Age on a given date. Returns null when no date of birth is recorded, so the
// caller can say "unknown" rather than silently assuming an adult rate.
function ageOn(dob, onIso) {
  if (!isValidEventDate(dob) || !isValidEventDate(onIso)) return null;
  const b = dob.split("-").map(Number), d = onIso.split("-").map(Number);
  let age = d[0] - b[0];
  if (d[1] < b[1] || (d[1] === b[1] && d[2] < b[2])) age--;
  return age;
}

function minWageFor(age, rates) {
  const r = rates || MIN_WAGE_DEFAULTS;
  if (age === null || age === undefined) return null;
  if (age < 18) return Number(r.under18) || 0;
  if (age < 21) return Number(r.under21) || 0;
  return Number(r.adult) || 0;
}

function minWageBandLabel(age) {
  if (age === null || age === undefined) return "unknown age";
  if (age < 18) return "under 18";
  if (age < 21) return "18-20";
  return "21+";
}

// Hourly rate as a number, from free text like "£15 incl Roll Up".
function staffHourlyRate(st) {
  const n = parseFloat(String((st && st.rate) || "").replace(/[^0-9.]/g, ""));
  return isNaN(n) ? null : n;
}
const STAFFING_LABELS = { dayManager:"Day Manager", dayStaff:"Day Staff", barSupervisor:"Bar Supervisor", sunday:"Sunday", bar:"Bar", dayHandy:"Day Handy", eveHandy:"Eve Handy" };

const BOOKING_STORAGE = "hawthbush_bookings_v6";

// ─── GMAIL OAUTH2 ────────────────────────────────────────────────────────────
const GMAIL_CLIENT_ID   = "631658172216-bh6vocim7t41lf8nhr21bdpb2ss2n1mm.apps.googleusercontent.com";
// Uses whatever domain the app is served from, so changing the Netlify subdomain
// won't break OAuth — you only need to add the new URL in the Google/Xero portals.
const APP_ORIGIN        = (typeof window !== "undefined" && window.location && window.location.origin) ? window.location.origin : "https://hawthbushfarm.netlify.app";
const GMAIL_REDIRECT    = APP_ORIGIN + "/";
const GMAIL_SCOPE       = "https://www.googleapis.com/auth/gmail.readonly";

const gmailGetToken  = () => { try { return JSON.parse(sessionStorage.getItem("gmail_token")||"null"); } catch { return null; } };
const gmailSetToken  = (t) => sessionStorage.setItem("gmail_token", JSON.stringify(t));
const gmailClearToken = () => sessionStorage.removeItem("gmail_token");

const gmailGetValidToken = () => {
  const t = gmailGetToken();
  if (!t) return null;
  // Token expired?
  if (Date.now() > t.expires_at - 60000) { gmailClearToken(); return null; }
  return t;
};

// ─── XERO OAUTH2 PKCE ────────────────────────────────────────────────────────
// NOTE on "invalid_scope": it means the requested scope is not in THIS app's
// registered scope list — check developer.xero.com → My Apps → Configuration
// and use exactly the names listed there. It is not a user-permission error,
// and the two scope vocabularies are not interchangeable
// (accounting.transactions vs accounting.invoices).
// Override the client id without redeploying via:
//   localStorage.setItem("xero_client_id_override", "NEW_CLIENT_ID")
const XERO_CLIENT_ID_DEFAULT = "13532E98AD5A449A86B5B6607F547531";

function xeroClientId() {
  try {
    const o = localStorage.getItem("xero_client_id_override");
    if (o && o.trim()) return o.trim();
  } catch (e) { /* private browsing etc. */ }
  return XERO_CLIENT_ID_DEFAULT;
}
// This Xero app is registered with GRANULAR scopes, so invoice access is
// `accounting.invoices` — NOT the broader `accounting.transactions`, which the
// app does not expose and which therefore fails with "invalid_scope".
// (That is also why the original read-only setup used accounting.invoices.read.)
// Everything below is confirmed present in the app's scope list:
//   accounting.invoices   create/read invoices
//   accounting.contacts   find/create the customer contact
//   accounting.settings   look up the "HF with Stripe" branding theme
const XERO_SCOPES_DEFAULT = "openid profile email accounting.invoices accounting.contacts accounting.settings offline_access";

// Changing this list means the existing Xero connection must be disconnected
// and reconnected — an old token still carries the scopes it was granted with.
//
// An override can be set from the browser console without a redeploy:
//   localStorage.setItem("xero_scopes_override", "openid profile email accounting.invoices offline_access")
//   localStorage.removeItem("xero_scopes_override")
// Useful because "invalid_scope" doesn't say WHICH scope Xero rejected, so the
// only way to find it is to try them one at a time.
function xeroScopes() {
  try {
    const o = localStorage.getItem("xero_scopes_override");
    if (o && o.trim()) return o.trim();
  } catch (e) { /* private browsing etc. */ }
  return XERO_SCOPES_DEFAULT;
}
const XERO_REDIRECT_URI = APP_ORIGIN + "/";

const xeroGenerateCodeVerifier = () => {
  const array = new Uint8Array(32);
  crypto.getRandomValues(array);
  return btoa(String.fromCharCode(...array)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=/g,"");
};

const xeroGenerateCodeChallenge = async (verifier) => {
  const data = new TextEncoder().encode(verifier);
  const digest = await crypto.subtle.digest("SHA-256", data);
  return btoa(String.fromCharCode(...new Uint8Array(digest))).replace(/\+/g,"-").replace(/\//g,"_").replace(/=/g,"");
};

const xeroGetToken = () => {
  try { return JSON.parse(sessionStorage.getItem("xero_token") || "null"); } catch { return null; }
};
const xeroSetToken = (t) => sessionStorage.setItem("xero_token", JSON.stringify(t));
const xeroClearToken = () => sessionStorage.removeItem("xero_token");

const xeroRefreshToken = async (refreshToken) => {
  const res = await fetch("https://identity.xero.com/connect/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      grant_type: "refresh_token",
      refresh_token: refreshToken,
      client_id: xeroClientId(),
    }),
  });
  if (!res.ok) throw new Error("Token refresh failed");
  const data = await res.json();
  const token = { ...data, expires_at: Date.now() + data.expires_in * 1000 };
  xeroSetToken(token);
  return token;
};

const xeroGetValidToken = async () => {
  let token = xeroGetToken();
  if (!token) return null;
  if (Date.now() > token.expires_at - 60000) {
    try { token = await xeroRefreshToken(token.refresh_token); } catch { xeroClearToken(); return null; }
  }
  return token;
};

const xeroFetch = async (path) => {
  const token = await xeroGetValidToken();
  if (!token) throw new Error("Not connected to Xero");

  // Get tenant ID via Netlify proxy if we don't have it yet
  if (!token.tenant_id) {
    const tenantsRes = await fetch("/api/xero-connections", {
      headers: {
        Authorization: `Bearer ${token.access_token}`,
        "Content-Type": "application/json",
      },
    });
    if (!tenantsRes.ok) {
      const txt = await tenantsRes.text();
      throw new Error(`Could not fetch Xero organisations (${tenantsRes.status}): ${txt.slice(0,100)}`);
    }
    const tenants = await tenantsRes.json();
    if (!tenants.length) throw new Error("No Xero organisations found");
    token.tenant_id = tenants[0].tenantId;
    xeroSetToken(token);
  }

  // Call Accounting API via Netlify proxy
  const res = await fetch(`/api/xero-api/${path}`, {
    headers: {
      Authorization: `Bearer ${token.access_token}`,
      "Xero-tenant-id": token.tenant_id,
      Accept: "application/json",
    },
  });
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(`Xero API error (${res.status}): ${txt.slice(0,100)}`);
  }
  return res.json();
};
const STAFF_STORAGE   = "hawthbush_staff_v5";

// ═══════════════════════════════════════════════════════════════════════════════
// EVENT INVOICING (pushed to Xero as DRAFT)
// ═══════════════════════════════════════════════════════════════════════════════
// Three stages per event:
//   1  Deposit                              — raised at booking
//   2  50% venue + 50% accom − deposit      — dated 1 Dec of the year BEFORE the event
//   3  50% venue + 50% accom                — dated 4 weeks before the event
// Deposit + stage2 + stage3 == venue + accom, exactly (see the rounding note in
// computeEventInvoiceStages). All figures are VAT-INCLUSIVE, so invoices are
// pushed with LineAmountTypes "Inclusive" — Xero would otherwise treat them as
// net and add 20% on top.
const EVENT_INVOICES_STORAGE = "hbf_event_invoices_v1";
const XERO_ACCOUNT_EVENTS  = "205"; // 205 - Events
const XERO_ACCOUNT_ACCOM   = "200"; // 200 - Holiday Let Rental
const XERO_BRANDING_THEME  = "HF with Stripe";
const INVOICE_STAGE_LABELS = { 1: "Deposit", 2: "Second (1 Dec)", 3: "Final (4 weeks)" };

// Transitional cutoff. Everything up to and including the 2026 season was
// invoiced by hand in Xero and is confirmed correct, so those events are kept
// out of the worklist rather than making someone link dozens of historic
// invoices one by one. 2027 onwards is generated and linked by the app.
// Raising this year is the only change needed if the cutover ever slips.
const INVOICE_FIRST_EVENT_YEAR = 2027;

function isInvoiceableYear(ev) {
  if (!isValidEventDate(ev && ev.date)) return false;
  return parseInt(ev.date.slice(0, 4), 10) >= INVOICE_FIRST_EVENT_YEAR;
}

function round2(n) { return Math.round((Number(n) || 0) * 100) / 100; }

// "Wedding (Peak)" -> "Wedding". Capitalised for use in invoice descriptions.
function eventTypeLabel(ev) {
  var raw = String((ev && ev.eventType) || "").replace(/\s*\(.*?\)\s*$/, "").trim();
  if (!raw) raw = "Event";
  return raw.charAt(0).toUpperCase() + raw.slice(1);
}

// Long-form date for invoice line descriptions, e.g. "29 May 2029"
// "Monday 17 August 2026" — the weekday matters more than the year to whoever
// is planning a week's cleaning, but both are cheap to show.
function fmtWeekdayLong(iso) {
  if (!iso) return "";
  var d = new Date(String(iso).slice(0, 10) + "T00:00:00");
  if (isNaN(d)) return String(iso);
  return d.toLocaleDateString("en-GB", { weekday: "long", day: "numeric", month: "long", year: "numeric" });
}

function fmtDateLong(iso) {
  if (!iso) return "";
  var d = new Date(String(iso).slice(0, 10) + "T00:00:00");
  if (isNaN(d)) return String(iso);
  return d.toLocaleDateString("en-GB", { day: "numeric", month: "long", year: "numeric" });
}

function addDaysIso(iso, n) {
  if (!isValidEventDate(iso)) return null;
  var p = iso.split("-");
  var d = new Date(Date.UTC(+p[0], +p[1] - 1, +p[2]));
  d.setUTCDate(d.getUTCDate() + n);
  return d.getUTCFullYear() + "-" + String(d.getUTCMonth() + 1).padStart(2, "0") + "-" + String(d.getUTCDate()).padStart(2, "0");
}

// Accommodation stays attached to this event, flattened one row per property.
function eventAccomStays(ev, accomBookings) {
  var out = [];
  (accomBookings || []).forEach(function(ab) {
    if (ab.status === "cancelled") return;
    if (ab.bookingType === "Blocked") return;
    if (!ab.linkedEventId || String(ab.linkedEventId) !== String(ev.id)) return;
    var stays = (ab.stays && ab.stays.length) ? ab.stays : [ab];
    stays.forEach(function(s) {
      if (!s.propertyId && !s.propertyName) return;
      out.push({
        propertyName: s.propertyName || s.propertyId || "Accommodation",
        checkIn:  s.checkIn  || "",
        checkOut: s.checkOut || "",
        nights:   Number(s.nights) || 0,
        value:    round2(Number(s.value) || 0)
      });
    });
  });
  return out.sort(function(a, b) { return (a.checkIn || "") > (b.checkIn || "") ? 1 : -1; });
}

// Chargeable extras on accommodation bookings linked to this event.
// Breakage deposits are deliberately excluded — they're refundable, not income.
function eventAccomExtras(ev, accomBookings) {
  const out = [];
  (accomBookings || []).forEach(function(ab) {
    if (ab.status === "cancelled") return;
    if (ab.bookingType === "Blocked") return;
    if (!ab.linkedEventId || String(ab.linkedEventId) !== String(ev.id)) return;
    (ab.extras || []).forEach(function(x) {
      const amt = round2(Number(x.amount) || 0);
      if (!amt) return;
      out.push({ desc: (x.desc || "").trim() || "Extra", amount: amt });
    });
  });
  return out;
}

function accomLineDescription(s, pct) {
  var range = (s.checkIn && s.checkOut)
    ? fmtDateLong(s.checkIn) + " to " + fmtDateLong(s.checkOut)
    : "dates TBC";
  var nights = s.nights > 0 ? " (" + s.nights + " night" + (s.nights === 1 ? "" : "s") + ")" : "";
  return s.propertyName + " — " + range + nights + ", " + pct + "%";
}

// Dates each stage is raised on. Stage 2 is dated 1 Dec of the year immediately
// preceding the event; it becomes actionable from mid-November so it can be
// prepared and sent ahead of that date.
function invoiceStageDates(ev) {
  if (!isValidEventDate(ev.date)) return { 1: null, 2: null, 3: null };
  var eventYear = parseInt(ev.date.slice(0, 4), 10);
  var stage2Date = (eventYear - 1) + "-12-01";
  return {
    1: { invoiceDate: null, readyFrom: null },                                   // at booking
    2: { invoiceDate: stage2Date, readyFrom: (eventYear - 1) + "-11-15" },
    3: (function() { var d = addDaysIso(ev.date, -28); return { invoiceDate: d, readyFrom: d }; })()
  };
}

// Build all three stages with their line items.
function computeEventInvoiceStages(ev, accomBookings) {
  var venue   = round2(parseMoney(ev.venueFee));
  var deposit = round2(parseMoney(ev.deposit));
  var stays   = eventAccomStays(ev, accomBookings);
  var extras  = eventAccomExtras(ev, accomBookings);
  var dates   = invoiceStageDates(ev);
  var label   = eventTypeLabel(ev);
  var evDate  = fmtDateLong(ev.date);
  var suffix  = label + (evDate ? " " + evDate : "");

  // Halves are computed once and the REMAINDER goes on stage 3, so the three
  // stages always sum back to venue + accom with no penny drift.
  var venueHalf = round2(venue / 2);
  var venueRest = round2(venue - venueHalf);

  var stage1Lines = [];
  if (deposit > 0) {
    stage1Lines.push({ desc: "Deposit — " + suffix, account: XERO_ACCOUNT_EVENTS, amount: deposit });
  }

  var stage2Lines = [], stage3Lines = [];
  if (venue > 0) {
    stage2Lines.push({ desc: "Venue fee (50%) — " + suffix, account: XERO_ACCOUNT_EVENTS, amount: venueHalf });
    stage3Lines.push({ desc: "Venue fee (50%) — " + suffix, account: XERO_ACCOUNT_EVENTS, amount: venueRest });
  }
  stays.forEach(function(s) {
    if (!(s.value > 0)) return;
    var half = round2(s.value / 2);
    var rest = round2(s.value - half);
    stage2Lines.push({ desc: accomLineDescription(s, 50), account: XERO_ACCOUNT_ACCOM, amount: half });
    stage3Lines.push({ desc: accomLineDescription(s, 50), account: XERO_ACCOUNT_ACCOM, amount: rest });
  });
  // Accommodation extras split 50:50 across stages 2 and 3, same as the stays.
  extras.forEach(function(x) {
    var half = round2(x.amount / 2);
    var rest = round2(x.amount - half);
    stage2Lines.push({ desc: x.desc + " (50%)", account: XERO_ACCOUNT_ACCOM, amount: half });
    stage3Lines.push({ desc: x.desc + " (50%)", account: XERO_ACCOUNT_ACCOM, amount: rest });
  });
  // Deposit already invoiced at stage 1 is credited back on stage 2. Negative
  // unit amount (quantity stays 1 — Xero rejects negative quantities).
  // The deposit is credited across BOTH remaining invoices rather than all
  // against the second, so stages 2 and 3 each come to half of the balance
  // owing: (venue + accom + extras − deposit) / 2. Taking it all off the second
  // invoice made that one noticeably smaller than the final one.
  // Any odd penny goes on stage 3 so the three stages still sum exactly to the
  // full amount.
  if (deposit > 0) {
    var depHalf = round2(deposit / 2);
    var depRest = round2(deposit - depHalf);
    stage2Lines.push({ desc: "Less deposit paid (50%) — " + suffix, account: XERO_ACCOUNT_EVENTS, amount: -depHalf });
    stage3Lines.push({ desc: "Less deposit paid (50%) — " + suffix, account: XERO_ACCOUNT_EVENTS, amount: -depRest });
  }

  function stage(n, lines) {
    var d = dates[n] || {};
    return {
      stage: n,
      label: INVOICE_STAGE_LABELS[n],
      invoiceDate: d.invoiceDate || null,
      readyFrom:   d.readyFrom || null,
      lines: lines,
      total: round2(lines.reduce(function(a, l) { return a + l.amount; }, 0))
    };
  }
  return [stage(1, stage1Lines), stage(2, stage2Lines), stage(3, stage3Lines)];
}

// Stable fingerprint of a stage's lines, stored when the invoice is pushed so
// later changes (guests commonly adjust accommodation once they see the
// invoice) can be detected and flagged against the pushed draft.
function invoiceLinesFingerprint(lines) {
  return (lines || []).map(function(l) {
    return l.account + "|" + l.desc + "|" + l.amount.toFixed(2);
  }).join("~");
}

// Xero's JSON API returns dates as "/Date(1234567890000+0000)/" on some
// endpoints and ISO on others (DateString). Normalise both to YYYY-MM-DD.
function xeroDateToIso(v) {
  if (!v) return null;
  var s = String(v);
  var m = s.match(/\/Date\((-?\d+)/);
  if (m) {
    var d = new Date(parseInt(m[1], 10));
    return isNaN(d) ? null : d.toISOString().slice(0, 10);
  }
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  return null;
}

function isoDayDiff(a, b) {
  if (!a || !b) return 99999;
  return Math.round((new Date(a + "T00:00:00") - new Date(b + "T00:00:00")) / 86400000);
}

// Match computed stages against invoices that already exist in Xero, so events
// invoiced before this feature existed aren't offered up for pushing again.
// A stage matches when an unclaimed, non-voided invoice has the same total to
// the penny; where several match, the one dated nearest the stage wins. Each
// Xero invoice can only be claimed once.
function matchStagesToXeroInvoices(stages, invoices, alreadyLinkedIds) {
  var used = {};
  (alreadyLinkedIds || []).forEach(function(id) { if (id) used[id] = true; });
  var live = (invoices || []).filter(function(inv) {
    var s = String(inv.Status || "").toUpperCase();
    return s !== "VOIDED" && s !== "DELETED";
  });
  var out = {};
  stages.forEach(function(st) {
    out[st.stage] = null;
    if (!(st.total > 0)) return;
    var cands = live.filter(function(inv) {
      return !used[inv.InvoiceID] && Math.abs(Number(inv.Total || 0) - st.total) <= 0.01;
    });
    if (!cands.length) return;
    cands.sort(function(a, b) {
      var da = Math.abs(isoDayDiff(xeroDateToIso(a.DateString || a.Date), st.invoiceDate));
      var db = Math.abs(isoDayDiff(xeroDateToIso(b.DateString || b.Date), st.invoiceDate));
      return da - db;
    });
    used[cands[0].InvoiceID] = true;
    out[st.stage] = cands[0];
  });
  return out;
}

// Only events that haven't happened yet are worth invoicing.
function isFutureEvent(ev, todayIso) {
  var end = eventEndDate(ev);
  return !!end && end >= todayIso;
}

// The stored record for a pushed invoice, keyed by event + stage.
function findPushedInvoice(records, eventId, stage) {
  return (records || []).find(function(r) {
    return String(r.eventId) === String(eventId) && Number(r.stage) === Number(stage);
  }) || null;
}

// Xero contact name, e.g. "26-09 Elizabeth Bradley & Ashley Williams".
// Zero-padded so contacts sort correctly in Xero's list.
function xeroContactName(ev) {
  if (!isValidEventDate(ev.date)) return (ev.couple || "").trim();
  return ev.date.slice(2, 4) + "-" + ev.date.slice(5, 7) + " " + (ev.couple || "").trim();
}
// Legacy unpadded variant ("26-9 …") — searched for as well so existing
// contacts are reused rather than duplicated.
function xeroContactNameLegacy(ev) {
  if (!isValidEventDate(ev.date)) return (ev.couple || "").trim();
  return ev.date.slice(2, 4) + "-" + String(parseInt(ev.date.slice(5, 7), 10)) + " " + (ev.couple || "").trim();
}

function parseInvoiceEmails(ev) {
  return String((ev && ev.invoiceEmails) || "")
    .split(",")
    .map(function(s) { return s.trim(); })
    .filter(function(s) { return s.indexOf("@") > 0; });
}

// Anything that would stop this event being invoiced.
function invoiceBlockers(ev, accomBookings) {
  var out = [];
  if (!ev.couple) out.push("No event name");
  if (!isValidEventDate(ev.date)) out.push("No valid event date");
  if (!parseInvoiceEmails(ev).length && !(ev.email || "").trim()) out.push("No invoice email");
  var venue = round2(parseMoney(ev.venueFee));
  if (!(venue > 0)) out.push("No venue fee");
  var deposit = round2(parseMoney(ev.deposit));
  if (deposit > venue) out.push("Deposit exceeds venue fee");
  return out;
}

// ─── STAFF CHIP ───────────────────────────────────────────────────────────────
function StaffChip({ initials, staff, size="sm" }) {
  const person = staff.find(s=>s.id===initials);
  const name = person ? person.name : initials;
  const idx = (initials||"").split("").reduce((a,c)=>a+c.charCodeAt(0),0) % T.chipBgs.length;
  return (
    <span title={name} style={{ display:"inline-flex", alignItems:"center", background:T.chipBgs[idx], color:T.chipTexts[idx], borderRadius:4, padding:size==="sm"?"2px 8px":"4px 12px", fontSize:size==="sm"?11:13, marginRight:4, marginBottom:3, whiteSpace:"nowrap", fontWeight:600 }}>
      {size==="sm" ? initials : name}
    </span>
  );
}


// ─── GMAIL LINK ───────────────────────────────────────────────────────────────
function GmailLink({ email }) {
  if (!email) return null;
  const url = `https://mail.google.com/mail/u/0/#search/${encodeURIComponent(email)}`;
  return (
    <a href={url} target="_blank" rel="noopener noreferrer"
      title={`Search Gmail for ${email}`}
      style={{ display:"inline-flex", alignItems:"center", gap:4, fontSize:11, fontWeight:600, color:"#db4437", background:"#fef2f2", border:"1px solid #fca5a5", borderRadius:4, padding:"2px 8px", textDecoration:"none", flexShrink:0, whiteSpace:"nowrap" }}
      onClick={e=>e.stopPropagation()}>
      <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor"><path d="M24 5.457v13.909c0 .904-.732 1.636-1.636 1.636h-3.819V11.73L12 16.64l-6.545-4.91v9.273H1.636A1.636 1.636 0 0 1 0 19.366V5.457c0-2.023 2.309-3.178 3.927-1.964L5.455 4.64 12 9.548l6.545-4.910 1.528-1.145C21.69 2.28 24 3.434 24 5.457z"/></svg>
      Gmail
    </a>
  );
}

// ─── STAFF PICKER ─────────────────────────────────────────────────────────────
function StaffPicker({ label, value=[], onChange, staff }) {
  const [open, setOpen] = useState(false);
  const toggle = id => onChange(value.includes(id) ? value.filter(v=>v!==id) : [...value, id]);
  const activeStaff = staff.filter(s=>s.active);
  return (
    <div style={{ position:"relative" }}>
      <label style={{ display:"block", fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, marginBottom:5, fontWeight:600 }}>{label}</label>
      <div onClick={()=>setOpen(!open)} style={{ minHeight:36, background:T.bgInput, border:`1.5px solid ${open?T.borderFocus:T.border}`, borderRadius:6, padding:"4px 10px", cursor:"pointer", display:"flex", flexWrap:"wrap", alignItems:"center", gap:2, boxShadow:open?"0 0 0 3px #dbeafe":"none", transition:"all .15s" }}>
        {value.length===0 && <span style={{ color:T.textLight, fontSize:13 }}>Select staff…</span>}
        {value.map(id=><StaffChip key={id} initials={id} staff={staff}/>)}
        <span style={{ marginLeft:"auto", color:T.textLight, fontSize:10 }}>▾</span>
      </div>
      {open && (
        <div style={{ position:"absolute", zIndex:200, top:"100%", left:0, right:0, background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:6, maxHeight:220, overflowY:"auto", boxShadow:"0 8px 24px rgba(0,0,0,.12)" }}>
          {activeStaff.map(s=>{
            const sel = value.includes(s.id);
            return (
              <div key={s.id} onClick={()=>toggle(s.id)} style={{ display:"flex", alignItems:"center", gap:10, padding:"8px 12px", cursor:"pointer", background:sel?T.accentLight:"none", borderBottom:`1px solid ${T.border}` }}
                onMouseEnter={e=>e.currentTarget.style.background=sel?T.accentLight:"#f0f6ff"}
                onMouseLeave={e=>e.currentTarget.style.background=sel?T.accentLight:"none"}>
                <span style={{ width:18, height:18, border:`2px solid ${sel?T.accent:T.border}`, borderRadius:4, background:sel?T.accent:"none", display:"flex", alignItems:"center", justifyContent:"center", fontSize:11, color:"#fff", flexShrink:0 }}>{sel?"✓":""}</span>
                <StaffChip initials={s.id} staff={staff}/>
                <span style={{ fontSize:13, color:T.text }}>{s.name}</span>
                <span style={{ marginLeft:"auto", fontSize:11, color:T.textLight }}>{s.role}</span>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

// ─── INPUT HELPERS ────────────────────────────────────────────────────────────
const IS = (f) => ({ width:"100%", background:T.bgInput, border:`1.5px solid ${f?T.borderFocus:T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:14, padding:"8px 11px", outline:"none", boxSizing:"border-box", boxShadow:f?"0 0 0 3px #dbeafe":"none", transition:"all .15s" });
// Static input style used in settings/editor components (no focus state needed)
const inpStyle = { background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:13, padding:"7px 10px", outline:"none", boxSizing:"border-box" };
function FLabel({ children, required }) {
  return <label style={{ display:"block", fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, marginBottom:5, fontWeight:600 }}>{children}{required&&<span style={{ color:T.red, marginLeft:4 }}>*</span>}</label>;
}
function FInput({ value, onChange, type="text", placeholder="" }) {
  const [f,setF] = useState(false);
  return <input type={type} value={value||""} onChange={e=>onChange(e.target.value)} placeholder={placeholder} onFocus={()=>setF(true)} onBlur={()=>setF(false)} style={IS(f)} />;
}
function FTextarea({ value, onChange, rows=3 }) {
  const [f,setF] = useState(false);
  return <textarea value={value||""} onChange={e=>onChange(e.target.value)} rows={rows} onFocus={()=>setF(true)} onBlur={()=>setF(false)} style={{ ...IS(f), resize:"vertical" }} />;
}
function FCheck({ checked, onChange, label, bold }) {
  return (
    <label style={{ display:"flex", alignItems:"center", gap:8, cursor:"pointer", userSelect:"none" }}>
      <span style={{ width:20, height:20, border:`2px solid ${checked?T.accent:T.border}`, borderRadius:4, background:checked?T.accent:"#fff", display:"flex", alignItems:"center", justifyContent:"center", fontSize:12, color:"#fff", flexShrink:0, transition:"all .15s" }}>{checked?"✓":""}</span>
      <span style={{ fontSize:bold?15:14, color:T.text, fontWeight:bold?600:400 }}>{label}</span>
    </label>
  );
}

// ─── ACCOMMODATION FIELD ──────────────────────────────────────────────────────
function AccomField({ bookedKey, feeKey, paid50Key, paid100Key, label, formData, update }) {
  const [f,setF] = useState(false);
  const val = formData[bookedKey] || "undecided";
  const isYes = val === "yes";
  const bgMap = { yes: T.accentLight, no: T.redBg, undecided: T.amberBg };
  const borderMap = { yes: T.accentMid, no: "#fca5a5", undecided: "#fcd34d" };
  return (
    <div style={{ background:bgMap[val]||T.bgInput, border:`1.5px solid ${borderMap[val]||T.border}`, borderRadius:8, padding:"14px 16px", transition:"all .2s" }}>
      <div style={{ display:"flex", alignItems:"center", flexWrap:"wrap", gap:12 }}>
        <span style={{ fontSize:15, fontWeight:600, color:T.text, minWidth:70 }}>{label}</span>
        <select value={val} onChange={e=>update(bookedKey,e.target.value)}
          style={{ background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:14, padding:"6px 10px", outline:"none", cursor:"pointer" }}>
          <option value="undecided">Undecided</option>
          <option value="yes">Yes</option>
          <option value="no">No</option>
        </select>
        {isYes && (
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            <span style={{ fontSize:13, color:T.textMid, fontWeight:500 }}>Fee: £</span>
            <input type="number" value={formData[feeKey]||""} onChange={e=>update(feeKey,e.target.value)} placeholder="0"
              onFocus={()=>setF(true)} onBlur={()=>setF(false)}
              style={{ width:90, background:"#fff", border:`1.5px solid ${f?T.borderFocus:T.border}`, borderRadius:6, color:T.text, fontSize:14, padding:"6px 10px", outline:"none", boxShadow:f?"0 0 0 3px #dbeafe":"none" }} />
          </div>
        )}
        {isYes && paid50Key && (
          <label style={{ display:"flex", alignItems:"center", gap:5, cursor:"pointer", fontSize:13, color:T.textMid, whiteSpace:"nowrap" }}>
            <input type="checkbox" checked={!!formData[paid50Key]} onChange={e=>update(paid50Key,e.target.checked)} style={{ width:14, height:14, accentColor:T.accent, cursor:"pointer" }}/>
            50% paid
          </label>
        )}
        {isYes && paid100Key && (
          <label style={{ display:"flex", alignItems:"center", gap:5, cursor:"pointer", fontSize:13, color:T.textMid, whiteSpace:"nowrap" }}>
            <input type="checkbox" checked={!!formData[paid100Key]} onChange={e=>update(paid100Key,e.target.checked)} style={{ width:14, height:14, accentColor:T.accent, cursor:"pointer" }}/>
            100% paid
          </label>
        )}
      </div>
    </div>
  );
}

// Find lettings bookings whose check-in falls within windowDays of an event date
function findLinkedAccom(eventDate, accomBookings, windowDays, eventEndDate) {
  if (!eventDate || !accomBookings) return [];
  var eStart = new Date(eventDate+"T00:00:00");
  var eEnd = (eventEndDate && eventEndDate > eventDate) ? new Date(eventEndDate+"T00:00:00") : eStart;
  var win = windowDays || 7;
  return accomBookings.filter(function(b) {
    if (b.status === "cancelled") return false;
    if (b.bookingType === "Blocked") return false; // not-available blocks aren't guest bookings
    var stays = (b.stays&&b.stays.length) ? b.stays : [b];
    return stays.some(function(s) {
      if (!s.checkIn) return false;
      var ci = new Date(s.checkIn+"T00:00:00");
      var co = s.checkOut ? new Date(s.checkOut+"T00:00:00") : ci;
      // Match if stay overlaps the event window
      return ci <= new Date(eEnd.getTime() + win*86400000) && co >= new Date(eStart.getTime() - win*86400000);
    });
  });
}

// Attribute a booking's flat schedule[] (Deposit/Balance entries) to the individual
// stays (properties) they belong to, so multi-property bookings can show each
// stay's Dep/Bal badges on that stay's own row instead of a separate combined row.
// Prefers an explicit sc.propertyId tag; falls back to splitting the schedule
// into equal-sized ordered chunks (one per stay) for older untagged data; if
// neither is possible, everything is returned as "leftover" so nothing is lost.
function attributeScheduleToStays(schedule, stays) {
  var sched = schedule || [];
  if (!stays || stays.length <= 1) return { byStay: [sched], leftover: [] };
  var hasTags = sched.some(function(sc) { return sc.propertyId; });
  if (hasTags) {
    var byStay = stays.map(function(s) {
      return sched.filter(function(sc) { return sc.propertyId === s.propertyId; });
    });
    var leftover = sched.filter(function(sc) { return !sc.propertyId; });
    return { byStay: byStay, leftover: leftover };
  }
  // Only attempt positional chunking when there's at least one full Deposit+
  // Balance pair per stay (2+ entries each) — this matches the shape of
  // older merged bookings from before per-property tagging existed. A single
  // combined Deposit/Balance pair for the whole multi-property booking (the
  // correct shape now that payments are per booking, not per property) is
  // shown as one unattributed row below instead of being incorrectly split
  // one entry per stay.
  var chunkSize = sched.length / stays.length;
  if (sched.length > 0 && Number.isInteger(chunkSize) && chunkSize >= 2) {
    var byStayChunks = stays.map(function(s, i) { return sched.slice(i * chunkSize, (i + 1) * chunkSize); });
    return { byStay: byStayChunks, leftover: [] };
  }
  return { byStay: stays.map(function() { return []; }), leftover: sched };
}

// Read-only panel: shows lettings bookings linked to a wedding event by date proximity
function AddAccomButton({ onAddAccom }) {
  if (!onAddAccom) return null;
  return (
    <button type="button" onClick={onAddAccom}
      style={{ background:T.accent, color:"#fff", border:"none", padding:"8px 16px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700, whiteSpace:"nowrap" }}>
      + Add accommodation
    </button>
  );
}

function LinkedAccomPanel({ eventDate, eventEndDate, eventId, accomBookings, accomProperties, onSaveAccomBooking, onOpenAccomBooking, onAddAccom }) {
  var [hideUnlinked, setHideUnlinked] = useState(true); // default: show linked only
  var nearby = findLinkedAccom(eventDate, accomBookings, 7, eventEndDate);
  var explicitlyLinked = (accomBookings||[]).filter(function(b) {
    return b.linkedEventId && String(b.linkedEventId) === String(eventId) && !nearby.find(function(n){ return n.id===b.id; });
  });
  var allBookings = nearby.concat(explicitlyLinked);
  var hasAnyLinked = allBookings.some(function(b){ return String(b.linkedEventId) === String(eventId); });
  // Only hide when there are linked entries — if nothing linked yet, show all so user can tick one
  var visibleBookings = (hideUnlinked && hasAnyLinked)
    ? allBookings.filter(function(b){ return String(b.linkedEventId) === String(eventId); })
    : allBookings;

  if (!allBookings.length) return (
    <div style={{ fontSize:12, color:T.textLight, background:T.bgInput, borderRadius:8, padding:"12px 14px", lineHeight:1.6 }}>
      No lettings bookings found within 7 days of this event.
      To link one, go to Lettings, add or edit a booking, and set its check-in near this event date.
      <div style={{ marginTop:10 }}><AddAccomButton onAddAccom={onAddAccom}/></div>
    </div>
  );

  var canLink = !!(eventId && onSaveAccomBooking);

  // Abbreviate common schedule labels
  function shortLabel(lbl) {
    var l = (lbl||"").toLowerCase();
    if (l.indexOf("deposit") !== -1 || l.indexOf("dep") === 0) return "Dep";
    if (l.indexOf("balance") !== -1 || l.indexOf("bal") === 0) return "Bal";
    return lbl;
  }

  return (
    <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:10, flexWrap:"wrap" }}>
        <AddAccomButton onAddAccom={onAddAccom}/>
        {canLink && !hasAnyLinked && (
          <div style={{ fontSize:11, color:T.textMid, background:T.bgInput, borderRadius:7, padding:"7px 12px" }}>
            Tick a booking to confirm it is attached to this event.
          </div>
        )}
        {canLink && (
          <label style={{ display:"flex", alignItems:"center", gap:7, cursor:"pointer", fontSize:12, color:T.text, fontWeight:600, padding:"6px 12px", background: hideUnlinked ? T.accentLight : T.bgInput, borderRadius:7, border:`1.5px solid ${hideUnlinked ? T.accent : T.border}`, marginLeft:"auto" }}>
            <input type="checkbox" checked={hideUnlinked} onChange={function(e){ setHideUnlinked(e.target.checked); }} style={{ width:14, height:14, accentColor:T.accent, cursor:"pointer" }} />
            Linked only
          </label>
        )}
      </div>
      {visibleBookings.map(function(b) {
        var stays = (b.stays&&b.stays.length) ? b.stays : [b];
        var paidAmt = (b.schedule||[]).filter(function(s){ return s.paid; }).reduce(function(sum,s){ return sum+(Number(s.amount)||0); }, 0);
        var outstanding = (Number(b.value)||0) - paidAmt;
        var isLinked = canLink && String(b.linkedEventId) === String(eventId);
        var canOpen = !!onOpenAccomBooking;
        return (
          <div key={b.id}
            onClick={canOpen ? function(){ onOpenAccomBooking(b.id); } : undefined}
            title={canOpen ? "Open this lettings booking" : undefined}
            style={{ border:`1.5px solid ${isLinked ? T.accent : T.border}`, borderRadius:9, padding:"12px 14px", background: isLinked ? T.accentLight : "#fff", cursor: canOpen ? "pointer" : "default" }}>
            {/* Header: checkbox + name + value */}
            <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:8 }}>
              <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                {canLink && (
                  <input type="checkbox" checked={isLinked}
                    onClick={function(e){ e.stopPropagation(); }}
                    onChange={function(e) {
                    var patch = { linkedEventId: e.target.checked ? eventId : null };
                    if (e.target.checked) patch.bookingType = "Wedding";
                    onSaveAccomBooking(b.id, patch);
                  }} style={{ width:16, height:16, accentColor:T.accent, cursor:"pointer", flexShrink:0 }} />
                )}
                <span style={{ fontWeight:700, color:T.text, fontSize:13, textDecoration: canOpen ? "underline" : "none", textDecorationStyle:"dotted", textDecorationColor:T.textLight }}>
                  {b.guestName || "(no name)"}
                  {b.bookingType && <span style={{ marginLeft:8, fontSize:11, fontWeight:600, color:T.accent, background:"#e0e7ff", padding:"1px 6px", borderRadius:6 }}>{b.bookingType}</span>}
                  {isLinked && <span style={{ marginLeft:8, fontSize:11, fontWeight:700, color:T.accent }}>Linked</span>}
                </span>
              </div>
              <span style={{ fontWeight:700, color:T.text, fontSize:13 }}>{fmtMoney(Number(b.value)||0)}</span>
            </div>
            {/* Stay rows — each with its own Dep/Bal badges inline */}
            {(function() {
              var attributed = attributeScheduleToStays(b.schedule, stays);
              return stays.map(function(s, i) {
                var prop = (accomProperties||[]).find(function(p){ return p.id===s.propertyId; });
                var staySchedule = stays.length === 1 ? (b.schedule||[]) : attributed.byStay[i];
                return (
                  <div key={i} style={{ display:"flex", alignItems:"center", gap:6, marginBottom:4, flexWrap:"wrap" }}>
                    {prop && <span style={{ width:8, height:8, borderRadius:"50%", background:prop.colour, display:"inline-block", flexShrink:0 }}/>}
                    <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>{s.propertyName || s.propertyId}</span>
                    <span style={{ fontSize:12, color:T.textMid }}>{fmtDate(s.checkIn)} – {fmtDate(s.checkOut)}</span>
                    {s.nights ? <span style={{ fontSize:11, color:T.textLight }}>({s.nights}n)</span> : null}
                    {staySchedule.map(function(sc, si) {
                      return (
                        <span key={si} style={{ fontSize:11, padding:"1px 7px", borderRadius:5, fontWeight:600,
                          background: sc.paid ? T.greenBg : T.amberBg,
                          color:      sc.paid ? T.green   : T.amber }}>
                          {shortLabel(sc.label)}: {fmtMoney(Number(sc.amount)||0)}{sc.paid ? " paid" : sc.dueDate ? " due "+fmtDate(sc.dueDate) : ""}
                        </span>
                      );
                    })}
                    {/* The agreed price for this property, pushed to the right
                        so a multi-property booking reads as a priced list
                        rather than one lump sum on the header row. */}
                    <span style={{ marginLeft:"auto", fontSize:12, fontWeight:700, color:T.text, whiteSpace:"nowrap" }}>
                      {Number(s.value) > 0 ? String(fmtMoney(s.value)) : <span style={{ color:T.textLight, fontWeight:400 }}>no price set</span>}
                    </span>
                  </div>
                );
              });
            })()}
            {/* Any schedule entries that couldn't be attributed to a specific stay */}
            {stays.length > 1 && attributeScheduleToStays(b.schedule, stays).leftover.length > 0 && (
              <div style={{ display:"flex", gap:5, flexWrap:"wrap", marginTop:4 }}>
                {attributeScheduleToStays(b.schedule, stays).leftover.map(function(sc, si) {
                  return (
                    <span key={si} style={{ fontSize:11, padding:"1px 7px", borderRadius:5, fontWeight:600,
                      background: sc.paid ? T.greenBg : T.amberBg,
                      color:      sc.paid ? T.green   : T.amber }}>
                      {shortLabel(sc.label)}: {fmtMoney(Number(sc.amount)||0)}{sc.paid ? " paid" : sc.dueDate ? " due "+fmtDate(sc.dueDate) : ""}
                    </span>
                  );
                })}
              </div>
            )}
            {(Number(b.value)||0) > 0 && (
              <div style={{ marginTop:5, fontSize:12 }}>
                {outstanding <= 0
                  ? <span style={{ color:T.green, fontWeight:600 }}>Fully paid</span>
                  : paidAmt > 0
                    ? <span style={{ color:T.amber, fontWeight:600 }}>Outstanding: {fmtMoney(outstanding)}</span>
                    : <span style={{ color:T.red, fontWeight:600 }}>Not yet paid</span>}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ─── LETTINGS (HOLIDAY LETS / ACCOMMODATION) ─────────────────────────────────
const PROPERTIES_STORAGE     = "hbf_properties_v1";
const ACCOM_STORAGE          = "hbf_accom_v1";
const ACCOM_GUESTS_STORAGE   = "hbf_accom_guests_v1";
const EMAIL_LOG_STORAGE      = "hbf_email_log_v1";
const DISCOUNT_CODES_STORAGE  = "hbf_discount_codes_v1";
const EMAIL_TEMPLATES_STORAGE = "hbf_email_templates_v1";
const SITE_URL = "https://hawthbushfarm.netlify.app";

// Read back a sent email in full.
//
// The body is only recorded for emails sent from build 2026-08-04s onward —
// earlier log rows hold the subject and recipient but no text, so say so
// plainly rather than reconstructing it from the current template (which may
// since have been edited, and whose tokens can no longer be filled).
function EmailViewerModal({ email, onClose }) {
  if (!email) return null;
  const when = email.sentAt
    ? new Date(email.sentAt).toLocaleString("en-GB", { weekday:"short", day:"numeric", month:"long", year:"numeric", hour:"2-digit", minute:"2-digit" })
    : "—";
  const text = email.body || "";
  const html = email.bodyHtml || "";

  return (
    <div onClick={onClose}
      style={{ position:"fixed", inset:0, background:"rgba(20,26,35,.55)", zIndex:2000, display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
      <div onClick={e=>e.stopPropagation()}
        style={{ background:"#fff", borderRadius:12, width:"min(720px, 100%)", maxHeight:"85vh", display:"flex", flexDirection:"column", boxShadow:"0 20px 60px rgba(0,0,0,.3)" }}>
        <div style={{ padding:"16px 22px", borderBottom:`1px solid ${T.border}` }}>
          <div style={{ display:"flex", alignItems:"flex-start", gap:12 }}>
            <h3 style={{ margin:0, fontSize:16, fontWeight:700, color:T.text, flex:1, lineHeight:1.4 }}>{email.subject || "(no subject)"}</h3>
            <button onClick={onClose}
              style={{ background:"none", border:"none", fontSize:22, lineHeight:1, color:T.textLight, cursor:"pointer", padding:0, fontFamily:"inherit" }}>×</button>
          </div>
          <div style={{ fontSize:12, color:T.textLight, marginTop:6, lineHeight:1.7 }}>
            <div><strong style={{ color:T.textMid, fontWeight:600 }}>To</strong> {email.to || "—"}</div>
            <div><strong style={{ color:T.textMid, fontWeight:600 }}>Sent</strong> {when}</div>
            {(email.template || email.type) && (
              <div><strong style={{ color:T.textMid, fontWeight:600 }}>Template</strong> {email.template || email.type}</div>
            )}
          </div>
        </div>
        <div style={{ padding:"18px 22px", overflowY:"auto", flex:1 }}>
          {html ? (
            <div style={{ fontSize:13.5, color:T.text, lineHeight:1.7 }} dangerouslySetInnerHTML={{ __html: html }}/>
          ) : text ? (
            <div style={{ fontFamily:"Georgia, serif", fontSize:14, color:T.text, lineHeight:1.75, whiteSpace:"pre-wrap" }}>{text}</div>
          ) : (
            <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:7, padding:"11px 14px", fontSize:12.5, color:"#92400e", lineHeight:1.65 }}>
              The text of this one wasn't recorded — only emails sent from 11 August 2026 onward store their full body.
              The subject, recipient and template above are everything that was kept.
            </div>
          )}
        </div>
        <div style={{ padding:"12px 22px", borderTop:`1px solid ${T.border}`, display:"flex", justifyContent:"flex-end" }}>
          <button onClick={onClose}
            style={{ padding:"8px 20px", border:`1px solid ${T.border}`, borderRadius:6, background:"#fff", color:T.textMid, fontFamily:"inherit", fontSize:13, cursor:"pointer" }}>
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

// Shows automated emails logged in hbf_email_log_v1 that relate to a specific
// lettings booking (matched by bookingId) or a specific person (matched by
// recipient email address — used for viewing confirm/decline emails, which
// are logged against the original viewing request rather than a booking id).
// Used on the accom booking page, and in the Contact sections of bookings/enquiries.
function EmailHistoryPanel({ title, emptyLabel, bookingId, emails, typeFilter }) {
  const [log, setLog] = useState(null);
  const [viewing, setViewing] = useState(null);

  useEffect(function() {
    let cancelled = false;
    (async function() {
      try { const l = await sbGet(EMAIL_LOG_STORAGE); if (!cancelled) setLog(l || []); }
      catch (e) { if (!cancelled) setLog([]); }
    })();
    return function() { cancelled = true; };
  }, []);

  if (log === null) return <div style={{ color:T.textLight, fontSize:12 }}>Loading…</div>;

  const emailSet = (emails || []).filter(Boolean).map(function(e) { return e.toLowerCase(); });
  const matches = log.filter(function(e) {
    const byBooking = bookingId && e.bookingId && String(e.bookingId) === String(bookingId);
    const byEmail = emailSet.length && e.to && emailSet.indexOf(String(e.to).toLowerCase()) !== -1;
    if (!byBooking && !byEmail) return false;
    if (typeFilter && !typeFilter(e.type || e.template || "")) return false;
    return true;
  }).sort(function(a, z) { return (z.sentAt || "") > (a.sentAt || "") ? 1 : -1; });

  return (
    <div>
      <h3 style={{ margin:"0 0 12px", color:T.midBlue, fontWeight:700, fontSize:15, borderBottom:`1px solid ${T.border}`, paddingBottom:10 }}>
        {title || "Emails Sent"} <span style={{ fontSize:12, color:T.textLight, fontWeight:400 }}>({matches.length})</span>
      </h3>
      {matches.length === 0
        ? <div style={{ color:T.textLight, fontSize:13 }}>{emptyLabel || "No emails sent yet."}</div>
        : (
          <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
            {matches.map(function(e) {
              const hasBody = !!(e.body || e.bodyHtml);
              return (
                <div key={e.id || (e.sentAt + e.subject)} onClick={function(){ setViewing(e); }}
                  title="Click to read the full email"
                  style={{ background:T.bgInput, border:`1px solid ${T.border}`, borderRadius:8, padding:"9px 12px", cursor:"pointer" }}>
                  <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:8 }}>
                    <span style={{ fontSize:13, fontWeight:600, color:T.text }}>{e.subject || "(no subject)"}</span>
                    <span style={{ fontSize:11, color:T.textLight, whiteSpace:"nowrap", flexShrink:0 }}>
                      {e.sentAt ? new Date(e.sentAt).toLocaleDateString("en-GB", { day:"numeric", month:"short", year:"numeric" }) : ""}
                    </span>
                  </div>
                  <div style={{ fontSize:11, color:T.textLight, marginTop:2, display:"flex", justifyContent:"space-between", gap:8 }}>
                    <span>To {e.to || "—"}</span>
                    <span style={{ color:T.accent, fontWeight:600, flexShrink:0 }}>{hasBody ? "Read →" : "Details →"}</span>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      <EmailViewerModal email={viewing} onClose={function(){ setViewing(null); }}/>
    </div>
  );
}

// Generic "Contact History" log (date + method + note entries), reusable
// anywhere a manual contact log is needed. Manages its own add/edit UI state
// and reports the updated contacts array back via onChange.
function ContactHistoryPanel({ contacts, onChange }) {
  const [newContact, setNewContact] = useState({ date: new Date().toISOString().slice(0,10), method:"email", note:"" });
  const [adding, setAdding] = useState(false);
  const [editingIdx, setEditingIdx] = useState(null);
  const [editForm, setEditForm] = useState(null);

  const list = contacts || [];
  const sorted = [...list].sort(function(a, b) {
    if (!a.date) return 1; if (!b.date) return -1;
    return b.date > a.date ? 1 : -1;
  });

  const addContact = function() {
    if (!newContact.note.trim()) return;
    onChange(list.concat([{ ...newContact }]));
    setNewContact({ date: new Date().toISOString().slice(0,10), method:"email", note:"" });
    setAdding(false);
  };

  const startEdit = function(i) {
    const actualIdx = list.indexOf(sorted[i]);
    setEditingIdx(actualIdx);
    setEditForm({ ...sorted[i] });
  };

  const saveEdit = function() {
    onChange(list.map(function(c, i) { return i === editingIdx ? editForm : c; }));
    setEditingIdx(null); setEditForm(null);
  };

  const deleteContact = function(i) {
    const actualIdx = list.indexOf(sorted[i]);
    onChange(list.filter(function(_, ii) { return ii !== actualIdx; }));
  };

  const methodLabel = function(m) { return m==="email" ? "Email" : m==="phone" ? "Phone" : m==="inperson" ? "In Person" : "Other"; };
  const iStyle = { width:"100%", background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:13, padding:"6px 9px", outline:"none", boxSizing:"border-box" };

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", borderBottom:`1px solid ${T.border}`, paddingBottom:10, marginBottom:14 }}>
        <h3 style={{ margin:0, color:T.midBlue, fontWeight:700, fontSize:15 }}>Contact History <span style={{ fontSize:12, color:T.textLight, fontWeight:400 }}>({list.length})</span></h3>
        {!adding && editingIdx===null && <button onClick={function(){ setAdding(true); }} style={{ background:T.accentLight, border:"none", color:T.accent, padding:"5px 14px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600 }}>+ Add Contact</button>}
      </div>

      {adding && (
        <div style={{ background:T.accentLight, border:`1.5px solid ${T.accentMid}`, borderRadius:8, padding:14, marginBottom:12 }}>
          <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:10 }}>
            <div>
              <label style={{ display:"block", fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, marginBottom:4, fontWeight:600 }}>Date</label>
              <input type="date" value={newContact.date} onChange={function(e){ setNewContact(function(n){ return { ...n, date:e.target.value }; }); }} style={iStyle}/>
            </div>
            <div>
              <label style={{ display:"block", fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, marginBottom:4, fontWeight:600 }}>Method</label>
              <select value={newContact.method} onChange={function(e){ setNewContact(function(n){ return { ...n, method:e.target.value }; }); }} style={iStyle}>
                <option value="email">Email</option>
                <option value="phone">Phone</option>
                <option value="inperson">In Person</option>
                <option value="other">Other</option>
              </select>
            </div>
          </div>
          <textarea value={newContact.note} onChange={function(e){ setNewContact(function(n){ return { ...n, note:e.target.value }; }); }} placeholder="Contact note…" rows={3}
            style={{ ...iStyle, resize:"vertical", marginBottom:10 }}/>
          <div style={{ display:"flex", gap:8 }}>
            <button onClick={addContact} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"7px 18px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>Add</button>
            <button onClick={function(){ setAdding(false); }} style={{ background:"none", color:T.textMid, border:`1px solid ${T.border}`, padding:"7px 14px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:13 }}>Cancel</button>
          </div>
        </div>
      )}

      {sorted.length === 0 && !adding && <div style={{ color:T.textLight, fontSize:13, textAlign:"center", padding:"12px 0" }}>No contact history yet.</div>}

      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {sorted.map(function(c, i) {
          const isEditing = editingIdx !== null && list.indexOf(c) === editingIdx;
          if (isEditing && editForm) {
            return (
              <div key={i} style={{ background:T.accentLight, border:`1.5px solid ${T.accentMid}`, borderRadius:8, padding:14 }}>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:10, marginBottom:10 }}>
                  <div>
                    <label style={{ display:"block", fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, marginBottom:4, fontWeight:600 }}>Date</label>
                    <input type="date" value={editForm.date||""} onChange={function(e){ setEditForm(function(f){ return { ...f, date:e.target.value }; }); }} style={iStyle}/>
                  </div>
                  <div>
                    <label style={{ display:"block", fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, marginBottom:4, fontWeight:600 }}>Method</label>
                    <select value={editForm.method||"email"} onChange={function(e){ setEditForm(function(f){ return { ...f, method:e.target.value }; }); }} style={iStyle}>
                      <option value="email">Email</option>
                      <option value="phone">Phone</option>
                      <option value="inperson">In Person</option>
                      <option value="other">Other</option>
                    </select>
                  </div>
                </div>
                <textarea value={editForm.note||""} onChange={function(e){ setEditForm(function(f){ return { ...f, note:e.target.value }; }); }} rows={3}
                  style={{ ...iStyle, resize:"vertical", marginBottom:10 }}/>
                <div style={{ display:"flex", gap:8 }}>
                  <button onClick={saveEdit} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"7px 18px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>Save</button>
                  <button onClick={function(){ setEditingIdx(null); setEditForm(null); }} style={{ background:"none", color:T.textMid, border:`1px solid ${T.border}`, padding:"7px 14px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:13 }}>Cancel</button>
                  <button onClick={function(){ deleteContact(i); setEditingIdx(null); setEditForm(null); }} style={{ marginLeft:"auto", background:T.redBg, border:"none", color:T.red, padding:"7px 12px", borderRadius:5, cursor:"pointer", fontSize:12, fontWeight:600 }}>Delete</button>
                </div>
              </div>
            );
          }
          return (
            <div key={i} style={{ background:T.bgInput, border:`1px solid ${T.border}`, borderRadius:8, padding:"10px 14px" }}>
              <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:6 }}>
                <span style={{ fontSize:11, fontWeight:700, color:T.midBlue, background:T.midBlueBg, padding:"2px 8px", borderRadius:6 }}>{methodLabel(c.method)}</span>
                <span style={{ fontSize:12, color:T.textLight }}>{c.date ? fmtDate(c.date) : "No date"}</span>
                {editingIdx===null && <button onClick={function(){ startEdit(i); }} style={{ marginLeft:"auto", background:T.midBlueBg, border:"none", color:T.midBlue, cursor:"pointer", fontSize:12, fontWeight:600, padding:"2px 10px", borderRadius:4 }}>Edit</button>}
              </div>
              {c.note && <p style={{ margin:0, fontSize:13, color:T.text, lineHeight:1.5 }}>{c.note}</p>}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const INITIAL_PROPERTIES = [{"id":"hamlet","name":"The Hamlet","bookaletName":"The Hamlet","sleeps":14,"depositPct":50,"balanceWeeks":4,"breakageDefault":0,"checkInFrom":"16:00","checkOutBy":"10:00","checkInFromWedding":"15:00","checkOutByWedding":"11:00","colour":"#2563eb","colourBg":"#dbeafe","blockedByFarmEvents":false,"minNights":2,"maxNights":28,"seasons":[],"baseRate":0,"longStayThreshold":0,"longStayDiscount":0},{"id":"amly","name":"Amly Barn","bookaletName":"Amly Barn","sleeps":6,"depositPct":50,"balanceWeeks":6,"breakageDefault":0,"checkInFrom":"16:00","checkOutBy":"10:00","checkInFromWedding":"15:00","checkOutByWedding":"11:00","colour":"#16a34a","colourBg":"#dcfce7","blockedByFarmEvents":true,"minNights":2,"maxNights":28,"seasons":[],"baseRate":0,"longStayThreshold":0,"longStayDiscount":0},{"id":"glamping","name":"Glamping","bookaletName":"Glamping","sleeps":20,"depositPct":20,"balanceWeeks":6,"breakageDefault":125,"checkInFrom":"16:00","checkOutBy":"10:00","checkInFromWedding":"15:00","checkOutByWedding":"11:00","colour":"#9333ea","colourBg":"#f3e8ff","blockedByFarmEvents":false,"minNights":2,"maxNights":28,"seasons":[],"baseRate":0,"longStayThreshold":0,"longStayDiscount":0}];

const ACCOM_STATUS_META = {
  confirmed: { label:"Confirmed", bg:T.greenBg,  text:T.green },
  pending:   { label:"Pending",   bg:T.amberBg,  text:T.amber },
  completed: { label:"Completed", bg:T.midBlueBg, text:T.midBlue },
  cancelled: { label:"Cancelled", bg:T.redBg,    text:T.red },
};

function fmtMoney(n) {
  const v = Number(n) || 0;
  return "£" + v.toLocaleString("en-GB", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

function daysInMonth(year, month) { return new Date(year, month + 1, 0).getDate(); }

function isoAddWeeks(iso, weeks) {
  if (!iso) return null;
  const d = new Date(iso + "T00:00:00");
  d.setDate(d.getDate() - weeks * 7);
  return d.toISOString().slice(0, 10);
}

function nightsBetween(ci, co) {
  if (!ci || !co) return null;
  const a = new Date(ci + "T00:00:00"), b = new Date(co + "T00:00:00");
  return Math.round((b - a) / 86400000);
}

// Wrap a legacy flat accom booking into the multi-stay model. No-op if stays[] already present.
function normalizeAccom(b) {
  if (b.stays && b.stays.length) return b;
  const stay = {
    propertyId:   b.propertyId   || "",
    propertyName: b.propertyName || "",
    checkIn:      b.checkIn      || "",
    checkOut:     b.checkOut     || "",
    nights:       b.nights       || null,
    value:        Number(b.value) || 0,
  };
  return Object.assign({}, b, { stays: [stay] });
}

// Long-stay discount, as a cash amount off the stay subtotal.
//
// The setting is a percentage. Properties configured before the change hold a
// £-per-night figure in the old longStayDiscount field instead, and that is
// still honoured until a percentage is entered — reading the old number as a
// percentage would quietly reprice every long stay.
// Mirrored in book-accom.html; the two must agree or the public quote and the
// office quote will differ.
function longStayDiscountAmount(prop, nights, subtotal) {
  if (!prop || !(prop.longStayThreshold > 0) || !(nights >= prop.longStayThreshold)) return 0;
  const pct = Number(prop.longStayDiscountPct) || 0;
  if (pct > 0) return Math.min(round2(subtotal), round2(subtotal * pct / 100));
  const legacyPerNight = Number(prop.longStayDiscount) || 0;
  return legacyPerNight > 0 ? Math.min(round2(subtotal), round2(legacyPerNight * nights)) : 0;
}
// Is this property still relying on the pre-percentage £/night figure?
function usesLegacyLongStay(prop) {
  return !!prop && !(Number(prop.longStayDiscountPct) > 0) && Number(prop.longStayDiscount) > 0;
}

// Airbnb list prices run above what we charge direct, because the guest is
// paying Airbnb's fees on top and the nightly rate is set to match. This is
// the uplift applied to our own calendar price to estimate what an imported
// booking was worth.
const AIRBNB_UPLIFT_PCT = 15;

// What an Airbnb-imported booking was probably worth, priced off our own
// calendar: every night at the rate we'd charge direct for that date —
// seasons, long-stay discount and all — then uplifted.
//
// Returns null when it can't be priced (no property, no rate configured, no
// usable dates) rather than guessing, so the caller can show nothing instead
// of a confident-looking zero.
function estimateLettingValue(b, properties) {
  const stays = (b.stays && b.stays.length) ? b.stays : [b];
  let total = 0;
  let priced = 0;

  stays.forEach(function(st) {
    if (!st || !st.checkIn || !st.checkOut) return;
    const prop = (properties || []).find(function(p) { return p.id === st.propertyId; });
    if (!prop || !(Number(prop.baseRate) > 0)) return;
    const q = quoteStay(prop, st.checkIn, st.checkOut);
    if (!q || !(q.total > 0)) return;
    total += q.total;
    priced += 1;
  });

  if (!priced) return null;
  return Math.round(total * (1 + AIRBNB_UPLIFT_PCT / 100) * 100) / 100;
}

// The figure to show for a booking, and whether it's an estimate.
//
// A value typed in by hand always wins — if someone has recorded what Airbnb
// actually paid, that is the truth and no estimate should override it. Only
// an Airbnb booking with no value of its own gets priced off the calendar.
function lettingValue(b, properties) {
  const entered = Number(b && b.value) || 0;
  if (entered > 0) return { value: entered, estimated: false };
  if (!b || b.source !== "airbnb") return { value: 0, estimated: false };
  const est = estimateLettingValue(b, properties);
  return est === null ? { value: 0, estimated: false } : { value: est, estimated: true };
}

// The season that applies on a given date.
//
// PRIORITY: seasons are held in priority order, highest first. Where two
// overlap, the one nearer the top of the list wins — so a narrow exception
// (bank holiday weekend, wedding weekend) sits above the broad season it
// carves out of. Scanning top-down and stopping at the first match gives
// exactly that. The ▲▼ buttons in Settings → Properties set the order, and
// book-accom.html applies the same rule so quotes match.
function seasonForDate(prop, dateStr) {
  if (!prop || !prop.seasons) return null;
  for (let i = 0; i < prop.seasons.length; i++) {
    const s = prop.seasons[i];
    if (s.startDate && s.endDate && dateStr >= s.startDate && dateStr < s.endDate) return s;
  }
  return null;
}

// Return nightly rate for a property on a given ISO date, checking seasons first.
function getPriceForNight(prop, dateStr) {
  if (!prop) return 0;
  const s = seasonForDate(prop, dateStr);
  if (s) return Number(s.ratePerNight) || 0;
  return Number(prop.baseRate) || 0;
}

// Stay-length limits for a check-in date. A season can override either, and
// the winning season is the one priority already picked — so where periods
// overlap, the higher of the two supplies the limits, same as the rate.
// A blank or zero override means "inherit the property's own figure".
function minNightsForDate(prop, dateStr) {
  const s = seasonForDate(prop, dateStr);
  const v = s && Number(s.minNights);
  return (v && v > 0) ? v : (Number(prop && prop.minNights) || 2);
}
function maxNightsForDate(prop, dateStr) {
  const s = seasonForDate(prop, dateStr);
  const v = s && Number(s.maxNights);
  return (v && v > 0) ? v : (Number(prop && prop.maxNights) || 28);
}

// Do two seasons cover any of the same nights? End dates are exclusive.
function seasonsOverlap(a, b) {
  if (!a || !b || !a.startDate || !a.endDate || !b.startDate || !b.endDate) return false;
  return a.startDate < b.endDate && b.startDate < a.endDate;
}

// Quote a stay: walk each night, sum rates, apply long-stay discount.
// Returns { nights, subtotal, discount, total } or null if invalid.
function quoteStay(prop, checkIn, checkOut) {
  if (!prop || !checkIn || !checkOut) return null;
  const ci = new Date(checkIn+"T00:00:00");
  const co = new Date(checkOut+"T00:00:00");
  const nights = Math.round((co - ci) / 86400000);
  if (nights <= 0) return null;
  let subtotal = 0;
  const d = new Date(ci);
  while (d < co) {
    subtotal += getPriceForNight(prop, d.toISOString().slice(0,10));
    d.setDate(d.getDate() + 1);
  }
  const discount = longStayDiscountAmount(prop, nights, subtotal);
  const total = Math.max(0, round2(subtotal - discount));
  return { nights, subtotal, discount, total };
}

// Return true if propertyId is free for [checkIn, checkOut), optionally ignoring excludeId.
function checkAvailability(bookings, propertyId, checkIn, checkOut, excludeId) {
  if (!checkIn || !checkOut || !propertyId) return true;
  const ci = new Date(checkIn+"T00:00:00");
  const co = new Date(checkOut+"T00:00:00");
  return !bookings.some(function(b) {
    if (b.id === excludeId || b.status === "cancelled") return false;
    const stays = (b.stays && b.stays.length) ? b.stays : [b];
    return stays.some(function(s) {
      if (s.propertyId !== propertyId) return false;
      if (!s.checkIn || !s.checkOut) return false;
      const sCI = new Date(s.checkIn+"T00:00:00");
      const sCO = new Date(s.checkOut+"T00:00:00");
      return ci < sCO && co > sCI;
    });
  });
}

// Every clash between a booking and what's already in the diary.
//
// Returns one entry per colliding stay: { other, otherStay, stay }. Dates are
// half-open — a stay ending on the 4th and another starting on the 4th is a
// changeover, not a clash, which is why the comparison is strictly < and >.
//
// Cancelled bookings don't count, and neither does the booking being edited
// (matched on id) — otherwise saving an unchanged booking would report it
// clashing with itself.
function findAccomClashes(bookings, rec) {
  const out = [];
  const mine = (rec.stays && rec.stays.length) ? rec.stays : [rec];

  // A booking overlapping *itself* — the same property listed twice on the
  // same nights. The clash check below only compares against other bookings,
  // so without this a record can quietly carry a duplicate stay, which then
  // appears twice in the channel feeds under one booking id.
  mine.forEach(function(s, i) {
    if (!s || !s.propertyId || !s.checkIn || !s.checkOut) return;
    mine.forEach(function(o, j) {
      if (j <= i || !o || o.propertyId !== s.propertyId) return;
      if (!o.checkIn || !o.checkOut) return;
      if (s.checkIn < o.checkOut && s.checkOut > o.checkIn) {
        out.push({ other: Object.assign({}, rec, { guestName: "this same booking" }), otherStay: o, stay: s });
      }
    });
  });

  mine.forEach(function(s) {
    if (!s || !s.propertyId || !s.checkIn || !s.checkOut) return;
    (bookings || []).forEach(function(b) {
      if (!b || String(b.id) === String(rec.id) || b.status === "cancelled") return;
      const theirs = (b.stays && b.stays.length) ? b.stays : [b];
      theirs.forEach(function(o) {
        if (!o || o.propertyId !== s.propertyId) return;
        if (!o.checkIn || !o.checkOut) return;
        if (s.checkIn < o.checkOut && s.checkOut > o.checkIn) {
          out.push({ other: b, otherStay: o, stay: s });
        }
      });
    });
  });
  return out;
}

// Arrival and departure times for a stay.
//
// Order of precedence: a time typed onto the stay itself, then the property's
// configured times, then the house rules below. Wedding parties get earlier
// access and a later checkout — driven by whether the booking is a wedding or
// is attached to a farm event, since an event-linked let is a wedding party
// whatever the booking type says.
const DEFAULT_CHECK_IN       = "16:00";
const DEFAULT_CHECK_OUT      = "10:00";
const WEDDING_CHECK_IN       = "15:00";
const WEDDING_CHECK_OUT      = "11:00";

function isWeddingStay(booking) {
  return !!(booking && (booking.bookingType === "Wedding" || booking.linkedEventId));
}

// The times that apply when nothing has been typed on the stay.
function defaultStayTimes(booking, prop) {
  if (isWeddingStay(booking)) {
    return {
      inTime:  (prop && prop.checkInFromWedding)  || WEDDING_CHECK_IN,
      outTime: (prop && prop.checkOutByWedding)   || WEDDING_CHECK_OUT
    };
  }
  return {
    inTime:  (prop && prop.checkInFrom) || DEFAULT_CHECK_IN,
    outTime: (prop && prop.checkOutBy)  || DEFAULT_CHECK_OUT
  };
}

// What to actually show for a stay, and whether it came from the rules or was
// set by hand — so the form can show an overridden time differently.
function stayTimes(booking, stay, prop) {
  const d = defaultStayTimes(booking, prop);
  return {
    inTime:  (stay && stay.checkInTime)  || d.inTime,
    outTime: (stay && stay.checkOutTime) || d.outTime,
    inOverridden:  !!(stay && stay.checkInTime  && stay.checkInTime  !== d.inTime),
    outOverridden: !!(stay && stay.checkOutTime && stay.checkOutTime !== d.outTime)
  };
}

// Log an automated email to Supabase. Called from send handlers (phase 2).
async function logEmail(entry) {
  try {
    const existing = await sbGet(EMAIL_LOG_STORAGE) || [];
    const rec = Object.assign({ id:"el"+Date.now(), sentAt:new Date().toISOString() }, entry);
    await sbSet(EMAIL_LOG_STORAGE, existing.concat([rec]).slice(-500));
  } catch(e) { console.error("Email log:", e); }
}

// Auto-build a deposit + balance schedule for a manual booking. Zero value -> no schedule.
function buildAccomSchedule(value, prop, checkIn) {
  const total = Number(value) || 0;
  if (total <= 0) return [];
  const pct = prop ? prop.depositPct : 50;
  const bweeks = prop ? prop.balanceWeeks : 4;
  const dep = Math.round(total * pct) / 100;
  const bal = Math.round((total - dep) * 100) / 100;
  return [
    { label:"Deposit", amount:dep, dueDate:null, requested:false, requestedDate:null, paid:false, paidDate:null, stripeId:"" },
    { label:"Balance", amount:bal, dueDate: isoAddWeeks(checkIn, bweeks), requested:false, requestedDate:null, paid:false, paidDate:null, stripeId:"" },
  ];
}

// Collapse a schedule array down to one entry per label (Deposit/Balance etc.)
// so a multi-property booking is always billed once per booking, never once
// per property. Used when merging previously-separate single-property
// bookings into one multi-property booking, where each side brought its own
// Deposit+Balance pair.
function consolidateSchedule(schedule) {
  var byLabel = {};
  var order = [];
  (schedule || []).forEach(function(sc) {
    var label = sc.label || "Other";
    if (!byLabel[label]) { byLabel[label] = []; order.push(label); }
    byLabel[label].push(sc);
  });
  return order.map(function(label) {
    var entries = byLabel[label];
    var amount = entries.reduce(function(s, e) { return s + (Number(e.amount) || 0); }, 0);
    var dueDates = entries.map(function(e) { return e.dueDate; }).filter(Boolean).sort();
    var allPaid = entries.every(function(e) { return e.paid; });
    var paidDates = entries.map(function(e) { return e.paidDate; }).filter(Boolean).sort();
    var stripeId = entries.map(function(e) { return e.stripeId; }).filter(Boolean)[0] || "";
    var anyRequested = entries.some(function(e) { return e.requested; });
    var requestedDates = entries.map(function(e) { return e.requestedDate; }).filter(Boolean).sort();
    return {
      label: label,
      amount: Math.round(amount * 100) / 100,
      dueDate: dueDates[0] || null,
      requested: anyRequested,
      requestedDate: requestedDates[0] || null,
      paid: allPaid,
      paidDate: allPaid ? (paidDates[paidDates.length - 1] || null) : null,
      stripeId: stripeId,
    };
  });
}

// A short booking reference: one letter and five digits, e.g. "A10432".
// Random rather than sequential, so two bookings created at the same moment
// can't be handed the same number, and checked against what already exists so
// a clash is impossible rather than merely unlikely — the reference is the
// primary key for the booking everywhere, including in Stripe's metadata.
// "A" is added here, "W" by the website; both are still a letter and five
// digits, and the letter says at a glance where the booking came from.
// Mirrored in create-accom-checkout.js — the two must agree.
function newBookingRef(existing, prefix) {
  var taken = {};
  (existing || []).forEach(function(b) { if (b && b.id) taken[String(b.id).toUpperCase()] = true; });
  var letter = prefix || "A";
  for (var i = 0; i < 200; i++) {
    var id = letter + String(Math.floor(10000 + Math.random() * 90000));
    if (!taken[id]) return id;
  }
  return letter + String(Date.now()).slice(-8);
}

function blankAccom(propId, existingBookings) {
  var pid = propId || "hamlet";
  return {
    id: newBookingRef(existingBookings, "A"),
    propertyId: pid, propertyName: "",
    propertyIds: [pid],
    guestName:"", email:"", phone:"",
    checkIn:"", checkOut:"", nights:null, guestCount:"",
    source:"manual", status:"confirmed", bookingType:"", linkedEventId:null,
    value:0, estimated:false,
    extras:[], breakage:0, breakageStripeId:"",
    discountCode:"", discountAmount:0,
    schedule:[], notes:"", createdAt: new Date().toISOString().slice(0,10),
    stays:[{ propertyId:pid, propertyName:"", checkIn:"", checkOut:"", nights:null, guestCount:"", value:0 }],
  };
}

// Small styled input used across the form
function LInput({ label, value, onChange, type="text", placeholder="", width, mono }) {
  const [f, setF] = useState(false);
  return (
    <label style={{ display:"flex", flexDirection:"column", gap:5, width: width || "auto" }}>
      {label && <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>{label}</span>}
      <input type={type} value={value} placeholder={placeholder}
        onChange={e=>onChange(e.target.value)} onFocus={()=>setF(true)} onBlur={()=>setF(false)}
        style={{ background:"#fff", border:`1.5px solid ${f?T.borderFocus:T.border}`, borderRadius:7, color:T.text,
          fontFamily: mono ? "ui-monospace,monospace" : "inherit", fontSize:14, padding:"9px 11px", outline:"none",
          boxShadow: f ? "0 0 0 3px #dbeafe" : "none" }} />
    </label>
  );
}

// Darken a hex colour by subtracting `amount` from each RGB channel (0-255 clamp)
function darkenHex(hex, amount) {
  var h = (hex || "#000000").replace("#", "");
  if (h.length === 3) h = h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
  var r = Math.max(0, parseInt(h.slice(0,2), 16) - amount);
  var g = Math.max(0, parseInt(h.slice(2,4), 16) - amount);
  var b = Math.max(0, parseInt(h.slice(4,6), 16) - amount);
  return "#" + [r,g,b].map(function(x){ return x.toString(16).padStart(2,"0"); }).join("");
}

// Append an alpha channel to a colour, normalising 3-digit hex first —
// "#abc" + "66" would otherwise produce the invalid "#abc66".
// Bumped whenever this file changes meaningfully, and shown on the Home page.
// Lets you tell at a glance whether the browser is running the build you just
// deployed, instead of guessing why a change "hasn't worked".
const APP_BUILD = "2026-08-21a";

// Year-calendar diagonals. A single pair of blues rather than per-property
// colours: the letter badges already identify the property, so colouring the
// diagonals as well just competed with them.
const CAL_LIGHT = "#bfdbfe";   // arrival / departure
const CAL_DARK  = "#1e40af";   // outgoing half of a changeover

// Grace period before an unpaid invoice is called overdue on the dashboard.
const OVERDUE_AFTER_DAYS = 3;

function hexWithAlpha(hex, alphaHex) {
  var h = String(hex || "#000000").replace("#", "");
  if (h.length === 3) h = h[0]+h[0]+h[1]+h[1]+h[2]+h[2];
  if (h.length !== 6) h = "000000";
  return "#" + h + alphaHex;
}

const DEFAULT_EMAIL_TEMPLATES = [
  {
    id: "booking_confirmed",
    name: "Booking Confirmed",
    triggerLabel: "Send on booking creation",
    triggerDays: null,
    subject: "Booking Confirmed – {{propertyName}} – Ref {{bookingRef}}",
    body: "Dear {{guestName}},\n\nThank you for booking with Hawthbush Farm! Your reservation is confirmed.\n\nBooking reference: {{bookingRef}}\n{{stayDetails}}\n\nTotal: £{{totalAmount}}\n\nA deposit of £{{depositAmount}} is due by {{depositDueDate}}.{{paymentLinkLine}}\n\nIf you have any questions, please don't hesitate to get in touch.\n\nWarm regards,\nHawthbush Farm",
    attachments: []
  },
  {
    id: "deposit_request",
    name: "Deposit Request",
    triggerLabel: "Days before deposit due date",
    triggerDays: 3,
    subject: "Deposit Due – {{propertyName}} – Ref {{bookingRef}}",
    body: "Dear {{guestName}},\n\nThis is a reminder that your deposit is due for your upcoming stay at Hawthbush Farm.\n\nBooking reference: {{bookingRef}}\n{{stayDetails}}\nDeposit due: £{{depositAmount}}\nDue date: {{depositDueDate}}\n\nYou can pay securely here: {{paymentLink}}\n\nWarm regards,\nHawthbush Farm",
    attachments: []
  },
  {
    id: "balance_request",
    name: "Balance Request",
    triggerLabel: "Days before balance due date",
    triggerDays: 28,
    subject: "Balance Due – {{propertyName}} – Ref {{bookingRef}}",
    body: "Dear {{guestName}},\n\nYour balance is now due ahead of your stay at Hawthbush Farm.\n\nBooking reference: {{bookingRef}}\n{{stayDetails}}\nBalance due: £{{balanceAmount}}\nDue date: {{balanceDueDate}}\n\nYou can pay securely here: {{paymentLink}}\n\nWe look forward to welcoming you!\n\nWarm regards,\nHawthbush Farm",
    attachments: []
  },
  {
    id: "payment_confirmation",
    name: "Payment Confirmation",
    triggerLabel: "Send on payment receipt",
    triggerDays: null,
    subject: "Payment Received – {{propertyName}} – Ref {{bookingRef}}",
    body: "Dear {{guestName}},\n\nThank you – we have received your payment of £{{amountPaid}} for your booking at Hawthbush Farm.\n\nBooking reference: {{bookingRef}}\n{{stayDetails}}\nAmount received: £{{amountPaid}}\n\nWarm regards,\nHawthbush Farm",
    attachments: []
  },
  {
    id: "arrival_general",
    name: "Arrival Info (General)",
    triggerLabel: "Days before check-in (1st reminder)",
    triggerDays: 28,
    triggerLabel2: "Days before check-in (2nd reminder)",
    triggerDays2: 3,
    triggerDays2Enabled: false,
    subject: "Your Arrival at Hawthbush Farm – {{checkIn}}",
    body: "Dear {{guestName}},\n\nWe're looking forward to welcoming you to {{propertyName}}!\n\nBooking reference: {{bookingRef}}\n{{stayDetails}}\nCheck-in from {{checkInTime}} · Check-out by {{checkOutTime}}\n\nDirections and access information are attached. Please don't hesitate to contact us if you have any questions before your arrival.\n\nWarm regards,\nHawthbush Farm",
    attachments: []
  },
  {
    id: "arrival_event",
    name: "Arrival Info (Wedding/Event)",
    triggerLabel: "Days before check-in (1st reminder)",
    triggerDays: 28,
    triggerLabel2: "Days before check-in (2nd reminder)",
    triggerDays2: 3,
    triggerDays2Enabled: false,
    subject: "Your Wedding Weekend at Hawthbush Farm – {{checkIn}}",
    body: "Dear {{guestName}},\n\nWe are so excited to be part of your special day at Hawthbush Farm!\n\nBooking reference: {{bookingRef}}\n{{stayDetails}}\nCheck-in from {{checkInTime}} · Check-out by {{checkOutTime}}\n\nYour event information pack and site map are attached. Please do reach out if there is anything you need ahead of your celebration.\n\nWith warmest wishes,\nHawthbush Farm",
    attachments: []
  }
];

const EMAIL_TOKENS = [
  "{{guestName}}", "{{guestEmail}}", "{{guestPhone}}",
  "{{bookingRef}}", "{{propertyName}}", "{{stayDetails}}",
  "{{checkIn}}", "{{checkOut}}", "{{nights}}",
  "{{checkInTime}}", "{{checkOutTime}}",
  "{{totalAmount}}", "{{depositAmount}}", "{{balanceAmount}}",
  "{{depositDueDate}}", "{{balanceDueDate}}", "{{amountPaid}}", "{{paymentLink}}", "{{paymentLinkLine}}", "{{receiptUrl}}"
];

// ── Month timeline: one lane per property ────────────────────────────────────
function AccomCalendar({ properties, bookings, events, cursor, setCursor, onOpen, onViewEventsCalendar }) {
  const [mode, setMode] = useState("year");
  const [tooltip, setTooltip] = useState(null);
  // Year-calendar filter: "all", "events", or a property id.
  const [calFilter, setCalFilter] = useState("all");

  const year  = cursor.getFullYear();
  const month = cursor.getMonth();

  const MONTHS = ["January","February","March","April","May","June","July","August","September","October","November","December"];
  const DOW    = ["M","T","W","T","F","S","S"];
  const todayD = new Date();
  const today  = todayD.getFullYear() + "-" + String(todayD.getMonth()+1).padStart(2,"0") + "-" + String(todayD.getDate()).padStart(2,"0");

  // Helper: local-time ISO date string from a Date object (avoids UTC-shift bug)
  function localDs(d) {
    return d.getFullYear() + "-" + String(d.getMonth()+1).padStart(2,"0") + "-" + String(d.getDate()).padStart(2,"0");
  }

  // Occupancy map: dateStr -> [property, ...]
  // Booking map:   dateStr -> [{booking, stay, prop}]  (for hover tooltip)
  // Blocked set:   "dateStr:propId" -> true, for manually blocked "not available" ranges
  const occMap = {}, bookingMap = {}, blockedSet = new Set();
  bookings.forEach(b => {
    if (b.status === "cancelled") return;
    const isBlocked = b.bookingType === "Blocked";
    const stays = (b.stays && b.stays.length) ? b.stays : [b];
    stays.forEach(s => {
      if (!s.checkIn || !s.checkOut || !s.propertyId) return;
      const prop = properties.find(p => p.id === s.propertyId);
      if (!prop) return;
      const ci  = new Date(s.checkIn+"T00:00:00");
      const co  = new Date(s.checkOut+"T00:00:00");
      const st  = new Date(Math.max(ci.getTime(), new Date(year,0,1).getTime()));
      const en  = new Date(Math.min(co.getTime(), new Date(year+1,0,1).getTime()));
      let d = new Date(st);
      while (d < en) {
        const ds = localDs(d);
        if (!occMap[ds]) occMap[ds] = [];
        if (!occMap[ds].find(x=>x.id===prop.id)) occMap[ds].push(prop);
        if (!bookingMap[ds]) bookingMap[ds] = [];
        if (!bookingMap[ds].find(e=>e.booking.id===b.id&&e.prop.id===prop.id)) bookingMap[ds].push({ booking:b, stay:s, prop:prop });
        if (isBlocked) blockedSet.add(ds + ":" + prop.id);
        d.setDate(d.getDate()+1);
      }
    });
  });

  // Event dates set + map: any wedding/event that falls in the year
  const eventDates = new Set();
  const eventByDate = {};
  (events || []).forEach(function(e) {
    if (!e.date) return;
    var start = e.date;
    var end = (e.endDate && e.endDate > start) ? e.endDate : start;
    var cur = new Date(start + "T00:00:00");
    var endD = new Date(end + "T00:00:00");
    while (cur <= endD) {
      var ds = cur.getFullYear() + "-" + String(cur.getMonth()+1).padStart(2,"0") + "-" + String(cur.getDate()).padStart(2,"0");
      if (ds.startsWith(String(year))) {
        eventDates.add(ds);
        if (!eventByDate[ds]) eventByDate[ds] = [];
        if (!eventByDate[ds].find(function(x){ return x.id===e.id; })) eventByDate[ds].push(e);
      }
      cur.setDate(cur.getDate() + 1);
    }
  });

  // Changeover set: "dateStr:propId" for days where same property has both a checkOut AND checkIn
  const coByProp = {}, ciByProp = {};
  bookings.forEach(function(b) {
    if (b.status === "cancelled") return;
    var bstays = (b.stays && b.stays.length) ? b.stays : [b];
    bstays.forEach(function(s) {
      if (!s.checkIn || !s.checkOut || !s.propertyId) return;
      if (!coByProp[s.propertyId]) coByProp[s.propertyId] = new Set();
      if (!ciByProp[s.propertyId]) ciByProp[s.propertyId] = new Set();
      coByProp[s.propertyId].add(s.checkOut);
      ciByProp[s.propertyId].add(s.checkIn);
    });
  });
  const changeoverSet = new Set();
  properties.forEach(function(p) {
    var coSet = coByProp[p.id] || new Set();
    var ciSet = ciByProp[p.id] || new Set();
    coSet.forEach(function(d) { if (ciSet.has(d)) changeoverSet.add(d + ":" + p.id); });
  });

  // Date-keyed arrivals/departures, so the year grid can draw a diagonal on
  // check-in and check-out days. A checkout day isn't "occupied" (occupancy is
  // [checkIn, checkOut) exclusive), so without this those days would look
  // completely free even though the property is being turned around.
  const ciByDate = {}, coByDate = {};
  properties.forEach(function(p) {
    (ciByProp[p.id] || new Set()).forEach(function(d) {
      if (!ciByDate[d]) ciByDate[d] = [];
      ciByDate[d].push(p);
    });
    (coByProp[p.id] || new Set()).forEach(function(d) {
      if (!coByDate[d]) coByDate[d] = [];
      coByDate[d].push(p);
    });
  });

  // ── YEAR VIEW ──────────────────────────────────────────────────────────────
  if (mode === "year") {
    // Filter state resolved once: which property (if any), and whether
    // accommodation / farm events are shown at all.
    const propFilter  = (calFilter !== "all" && calFilter !== "events") ? calFilter : null;
    const showAccom   = calFilter !== "events";
    const showEvents  = calFilter === "all" || calFilter === "events";
    const keepProp    = function(p) { return !propFilter || p.id === propFilter; };
    const filterBtn   = function(id, label, colour) {
      const on = calFilter === id;
      return (
        <button key={id} onClick={function(){ setCalFilter(id); }}
          style={{ padding:"6px 13px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:12.5, fontWeight: on?700:500,
            background: on ? (colour || T.midBlue) : "#fff",
            color: on ? "#fff" : T.textMid,
            border: `1.5px solid ${on ? (colour || T.midBlue) : T.border}`,
            display:"flex", alignItems:"center", gap:6, whiteSpace:"nowrap" }}>
          {colour && !on && <span style={{ width:9, height:9, borderRadius:2, background:colour, display:"inline-block" }}/>}
          {label}
        </button>
      );
    };
    return (
      <div>
        <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:18 }}>
          <button onClick={()=>setCursor(new Date(year-1,0,1))} style={navBtn}>&#8249;</button>
          <div style={{ fontSize:20, fontWeight:800, color:T.text, minWidth:70, textAlign:"center" }}>{year}</div>
          <button onClick={()=>setCursor(new Date(year+1,0,1))} style={navBtn}>&#8250;</button>
          <button onClick={()=>{ setCursor(new Date()); setMode("month"); }} style={{ ...navBtn, width:"auto", padding:"0 14px", fontSize:13, fontWeight:600 }}>This month</button>
          {onViewEventsCalendar && (
            <button onClick={onViewEventsCalendar} style={{ ...navBtn, width:"auto", padding:"0 14px", fontSize:13, fontWeight:600, marginLeft:"auto", background:T.accentLight, color:T.accent, border:`1.5px solid ${T.accent}` }}>Events calendar</button>
          )}
        </div>

        {/* Filter the year grid to one property, to farm events, or show all */}
        <div style={{ display:"flex", gap:7, marginBottom:16, flexWrap:"wrap", alignItems:"center" }}>
          {properties.map(function(p) { return filterBtn(p.id, shortPropLabel(p), p.colour); })}
          {filterBtn("events", "Events", "#ef4444")}
          {filterBtn("all", "All", null)}
        </div>

        <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:16, marginBottom:16 }}>
          {MONTHS.map((mName, mIdx) => {
            const nD = daysInMonth(year, mIdx);
            const firstDow = (new Date(year, mIdx, 1).getDay()+6)%7;
            // Single flat array: 7 DOW headers + blank pads + date cells
            const allCells = [];
            DOW.forEach((d,i) => allCells.push({ type:"dow", label:d, key:"h"+i }));
            for (let i=0; i<firstDow; i++) allCells.push({ type:"pad", key:"p"+i });
            for (let d=1; d<=nD; d++) allCells.push({ type:"day", day:d });
            return (
              <div key={mName} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
                <div onClick={()=>{ setCursor(new Date(year,mIdx,1)); setMode("month"); }}
                  style={{ padding:"8px 12px", background:"#eef4fd", borderBottom:`1px solid ${T.border}`, cursor:"pointer", display:"flex", justifyContent:"space-between", alignItems:"center" }}>
                  <span style={{ fontSize:15, fontWeight:700, color:T.midBlue }}>{mName}</span>
                  <span style={{ fontSize:11, color:T.accent, fontWeight:600 }}>View &#8594;</span>
                </div>
                <div style={{ padding:"8px 8px 10px" }}>
                  <div style={{ display:"grid", gridTemplateColumns:"repeat(7,1fr)", gap:2 }}>
                    {allCells.map((cell, ci) => {
                      if (cell.type === "dow") return (
                        <div key={cell.key} style={{ textAlign:"center", fontSize:11, color:T.textLight, fontWeight:700, paddingBottom:3 }}>{cell.label}</div>
                      );
                      if (cell.type === "pad") return <div key={cell.key}/>;
                      // day cell
                      const day = cell.day;
                      const ds = `${year}-${String(mIdx+1).padStart(2,"0")}-${String(day).padStart(2,"0")}`;
                      const propsOn = showAccom ? (occMap[ds] || []).filter(keepProp) : [];
                      const hasEvent = showEvents && eventDates.has(ds);
                      const isToday  = ds === today;
                      const colInRow = (ci - 7) % 7; // offset by 7 header cells
                      const isSat = colInRow === 5, isSun = colInRow === 6;
                      const allBlocked = propsOn.length > 0 && propsOn.every(p => blockedSet.has(ds + ":" + p.id));
                      // A property arriving today shouldn't also tint the whole
                      // cell — the tint would swallow the arrival diagonal and
                      // the day would read as fully occupied. Only properties
                      // that are mid-stay (already in, not leaving) fill the
                      // cell. Departure days are excluded automatically because
                      // occupancy runs [check-in, check-out).
                      // Arrivals and departures, drawn as directional gradients.
                      // Left of the cell reads as the start of the day and right
                      // as the end, so occupancy visibly flows across the day:
                      //   check-in    clear (bottom-left) → colour (top-right)
                      //   check-out   colour (top-left)   → clear (bottom-right)
                      //   changeover  dark (left)         → light (right)
                      const ciProps = showAccom ? (ciByDate[ds] || []).filter(keepProp) : [];
                      const coProps = showAccom ? (coByDate[ds] || []).filter(keepProp) : [];
                      // Declared AFTER ciProps — referencing it earlier is a
                      // temporal-dead-zone ReferenceError that blanks the page.
                      const arrivingIds = ciProps.map(function(p){ return p.id; });
                      const midStayProps = propsOn.filter(function(p) { return arrivingIds.indexOf(p.id) === -1; });
                      // A changeover is the SAME property leaving and arriving on
                      // one day. Treating "any check-in plus any check-out" as a
                      // changeover wrongly darkened ordinary arrival days whenever
                      // an unrelated property happened to depart that day.
                      const isChgDay = ciProps.some(function(p) { return changeoverSet.has(ds + ":" + p.id); });
                      const hasCI = ciProps.length > 0, hasCO = coProps.length > 0;
                      // One colour for occupancy shading regardless of property —
                      // the letter badges already say which property it is, so
                      // green/purple cells only made the grid harder to read.
                      const bg = allBlocked
                        ? "repeating-linear-gradient(135deg, #e2e8f0, #e2e8f0 4px, #eef2f7 4px, #eef2f7 8px)"
                        : midStayProps.length ? CAL_LIGHT
                        : "transparent";
                      const dayEntries = showAccom ? (bookingMap[ds] || []).filter(function(e){ return keepProp(e.prop); }) : [];
                      const dateEvts = showEvents ? (eventByDate[ds] || []) : [];
                      return (
                        <div key={day}
                          style={{ textAlign:"center", padding:"3px 0 5px", borderRadius:3, background:bg,
                            outline: isToday ? `1.5px solid ${T.accent}` : "none",
                            cursor: (dayEntries.length||dateEvts.length) ? "pointer" : "default", position:"relative", overflow:"hidden" }}
                          onMouseEnter={function(e) {
                            if (!dayEntries.length && !dateEvts.length) return;
                            var rect = e.currentTarget.getBoundingClientRect();
                            setTooltip({ ds:ds, dayEntries:dayEntries, dateEvts:dateEvts, x:rect.left, y:rect.bottom+4 });
                          }}
                          onMouseLeave={function() { setTooltip(null); }}>
                          {/* Hard-edged diagonals. One colour throughout — the
                              letter badges already say which property it is, so
                              per-property hues here only added noise. Dark blue
                              is reserved for the outgoing half of a changeover. */}
                          {isChgDay ? (
                            <>
                              <div style={{ position:"absolute", inset:0, pointerEvents:"none", background:CAL_DARK,
                                clipPath:"polygon(0 0, 0 100%, 100% 100%)" }}/>
                              <div style={{ position:"absolute", inset:0, pointerEvents:"none", background:CAL_LIGHT,
                                clipPath:"polygon(0 0, 100% 0, 100% 100%)" }}/>
                            </>
                          ) : (
                            <>
                              {hasCO && (
                                <div style={{ position:"absolute", inset:0, pointerEvents:"none", background:CAL_LIGHT,
                                  clipPath:"polygon(0 0, 0 100%, 100% 100%)" }}/>
                              )}
                              {hasCI && (
                                <div style={{ position:"absolute", inset:0, pointerEvents:"none", background:CAL_LIGHT,
                                  clipPath:"polygon(0 100%, 100% 0, 100% 100%)" }}/>
                              )}
                            </>
                          )}
                          <div style={{ position:"relative", fontSize:12, fontWeight:propsOn.length||hasEvent?700:400,
                            color: isSat||isSun ? T.accent : T.text, lineHeight:"1.3" }}>{day}</div>
                          {(propsOn.length > 0 || hasEvent) && (
                            <div style={{ position:"relative", display:"flex", justifyContent:"center", gap:2, marginTop:2, flexWrap:"wrap" }}>
                              {propsOn.slice(0,3).map(function(p){
                                const isPropBlocked = blockedSet.has(ds + ":" + p.id);
                                return (
                                  <span key={p.id} title={isPropBlocked ? p.name + " — not available" : p.name} style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", width:11, height:11, borderRadius:2, background: isPropBlocked ? "#94a3b8" : p.colour, color:"#fff", fontSize:8, fontWeight:800, lineHeight:1 }}>
                                    {(p.id||p.name||"?")[0].toUpperCase()}
                                  </span>
                                );
                              })}
                              {hasEvent && (
                                <span style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", width:11, height:11, borderRadius:2, background:"#ef4444", color:"#fff", fontSize:8, fontWeight:800, lineHeight:1 }}>E</span>
                              )}
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Hover tooltip */}
        {tooltip && (function() {
          var vw = typeof window !== "undefined" ? window.innerWidth : 800;
          var tLeft = Math.max(8, Math.min(tooltip.x - 130, vw - 280));
          var dispDate = new Date(tooltip.ds+"T00:00:00").toLocaleDateString("en-GB", { weekday:"long", day:"numeric", month:"long" });
          return (
            <div style={{ position:"fixed", left:tLeft, top:tooltip.y, zIndex:9999, background:"#1e293b", color:"#f8fafc",
              borderRadius:9, boxShadow:"0 8px 28px rgba(0,0,0,.35)", padding:"10px 14px", minWidth:220, maxWidth:280, pointerEvents:"none", fontSize:12, lineHeight:"1.55" }}>
              <div style={{ fontWeight:700, marginBottom:6, borderBottom:"1px solid rgba(255,255,255,.18)", paddingBottom:4, fontSize:13 }}>{dispDate}</div>
              {tooltip.dayEntries.map(function(entry, i) {
                return (
                  <div key={i} style={{ marginBottom: i < tooltip.dayEntries.length-1 ? 8 : 0 }}>
                    <div style={{ display:"flex", alignItems:"center", gap:6 }}>
                      <span style={{ width:8, height:8, borderRadius:"50%", background:entry.prop.colour, display:"inline-block", flexShrink:0 }}/>
                      <span style={{ fontWeight:700, color:"#cbd5e1" }}>{entry.prop.name}</span>
                    </div>
                    <div style={{ paddingLeft:14, color:"#e2e8f0" }}>
                      {entry.booking.guestName || entry.booking.name || "Guest"}
                    </div>
                    {entry.stay.checkIn && (
                      <div style={{ paddingLeft:14, color:"#94a3b8", fontSize:11 }}>
                        {new Date(entry.stay.checkIn+"T00:00:00").toLocaleDateString("en-GB",{day:"numeric",month:"short"})}
                        {" - "}
                        {new Date(entry.stay.checkOut+"T00:00:00").toLocaleDateString("en-GB",{day:"numeric",month:"short"})}
                      </div>
                    )}
                  </div>
                );
              })}
              {(tooltip.dateEvts||[]).map(function(ev, i) {
                return (
                  <div key={i} style={{ marginTop: (i===0&&tooltip.dayEntries.length) ? 6 : i===0 ? 0 : 4, display:"flex", alignItems:"center", gap:6 }}>
                    <span style={{ width:8, height:8, borderRadius:"50%", background:"#ef4444", display:"inline-block", flexShrink:0 }}/>
                    <span style={{ color:"#fca5a5", fontWeight:600 }}>
                      {ev.eventType || "Wedding"}{ev.couple ? " — " + ev.couple : ""}
                    </span>
                  </div>
                );
              })}
            </div>
          );
        })()}

        {/* Legend */}
        <div style={{ display:"flex", gap:18, flexWrap:"wrap", alignItems:"center", padding:"10px 14px", background:"#fff", border:`1px solid ${T.border}`, borderRadius:9, fontSize:12, color:T.textMid }}>
          <span style={{ fontWeight:700, color:T.text, fontSize:11, textTransform:"uppercase", letterSpacing:.4 }}>Key:</span>
          {properties.filter(function(p){ return showAccom && keepProp(p); }).map(function(p){
            return (
              <span key={p.id} style={{ display:"flex", alignItems:"center", gap:5 }}>
                <span style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", width:11, height:11, borderRadius:2, background:p.colour, color:"#fff", fontSize:8, fontWeight:800 }}>{(p.id||p.name||"?")[0].toUpperCase()}</span>
                {p.name}
              </span>
            );
          })}
          {showEvents && (
            <span style={{ display:"flex", alignItems:"center", gap:5 }}>
              <span style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", width:11, height:11, borderRadius:2, background:"#ef4444", color:"#fff", fontSize:8, fontWeight:800 }}>E</span>
              Farm event
            </span>
          )}
          <span style={{ display:"flex", alignItems:"center", gap:5 }}>
            <span style={{ display:"inline-flex", alignItems:"center", justifyContent:"center", width:11, height:11, borderRadius:2, background:"#94a3b8", color:"#fff", fontSize:8, fontWeight:800 }}>×</span>
            Blocked / not available
          </span>
          <span style={{ display:"flex", alignItems:"center", gap:5 }}>
            <span style={{ display:"inline-block", width:14, height:14, borderRadius:2, border:`1px solid ${T.border}`, background:CAL_LIGHT }}/>
            Occupied
          </span>
          <span style={{ display:"flex", alignItems:"center", gap:5 }}>
            <span style={{ position:"relative", display:"inline-block", width:14, height:14, borderRadius:2, border:`1px solid ${T.border}`, overflow:"hidden" }}>
              <span style={{ position:"absolute", inset:0, background:CAL_LIGHT, clipPath:"polygon(0 100%, 100% 0, 100% 100%)" }}/>
            </span>
            Check-in
          </span>
          <span style={{ display:"flex", alignItems:"center", gap:5 }}>
            <span style={{ position:"relative", display:"inline-block", width:14, height:14, borderRadius:2, border:`1px solid ${T.border}`, overflow:"hidden" }}>
              <span style={{ position:"absolute", inset:0, background:CAL_LIGHT, clipPath:"polygon(0 0, 0 100%, 100% 100%)" }}/>
            </span>
            Check-out
          </span>
          <span style={{ display:"flex", alignItems:"center", gap:5 }}>
            <span style={{ position:"relative", display:"inline-block", width:14, height:14, borderRadius:2, border:`1px solid ${T.border}`, overflow:"hidden" }}>
              <span style={{ position:"absolute", inset:0, background:CAL_DARK, clipPath:"polygon(0 0, 0 100%, 100% 100%)" }}/>
              <span style={{ position:"absolute", inset:0, background:CAL_LIGHT, clipPath:"polygon(0 0, 100% 0, 100% 100%)" }}/>
            </span>
            Changeover
          </span>
          <span style={{ display:"flex", alignItems:"center", gap:5 }}>
            <span style={{ width:12, height:12, borderRadius:2, outline:`1.5px solid ${T.accent}`, display:"inline-block" }}/>
            Today
          </span>
          <span style={{ display:"flex", alignItems:"center", gap:5, color:T.textLight, fontStyle:"italic" }}>
            Hover a date to see booking details
          </span>
        </div>
      </div>
    );
  }

  // ── MONTH TIMELINE VIEW ────────────────────────────────────────────────────
  const nDays = daysInMonth(year, month);
  const dayW = 34;
  const monthStart = new Date(year, month, 1);
  const monthEnd   = new Date(year, month+1, 1);
  const monthLabel = cursor.toLocaleDateString("en-GB", { month:"long", year:"numeric" });

  const laneFor = (pid) => {
    const entries = [];
    bookings.forEach(b => {
      if (b.status === "cancelled") return;
      const stays = (b.stays && b.stays.length) ? b.stays : [b];
      stays.forEach(s => {
        if (s.propertyId !== pid) return;
        if (!s.checkIn || !s.checkOut) return;
        if (new Date(s.checkOut+"T00:00:00") <= monthStart) return;
        if (new Date(s.checkIn+"T00:00:00") >= monthEnd) return;
        entries.push({ booking:b, checkIn:s.checkIn, checkOut:s.checkOut });
      });
    });
    return entries;
  };

  const barGeom = (checkIn, checkOut) => {
    const ci = new Date(checkIn+"T00:00:00"), co = new Date(checkOut+"T00:00:00");
    const startDay = ci < monthStart ? 0 : (ci.getDate() - 1);
    const endDay   = co > monthEnd   ? nDays : (co.getDate() - 1);
    const span = Math.max(1, endDay - startDay);
    return { left: startDay * dayW, width: span * dayW - 3 };
  };

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:14, flexWrap:"wrap" }}>
        <button onClick={()=>setMode("year")} style={{ ...navBtn, width:"auto", padding:"0 14px", fontSize:13, fontWeight:600, color:T.accent, border:`1.5px solid ${T.accent}` }}>&#8592; Year</button>
        <button onClick={()=>setCursor(new Date(year, month-1, 1))} style={navBtn}>&#8249;</button>
        <div style={{ fontSize:17, fontWeight:700, color:T.text, minWidth:180, textAlign:"center" }}>{monthLabel}</div>
        <button onClick={()=>setCursor(new Date(year, month+1, 1))} style={navBtn}>&#8250;</button>
        <button onClick={()=>setCursor(new Date())} style={{ ...navBtn, width:"auto", padding:"0 14px", fontSize:13, fontWeight:600 }}>Today</button>
      </div>

      <div style={{ overflowX:"auto", border:`1px solid ${T.border}`, borderRadius:10, background:"#fff" }}>
        <div style={{ minWidth: 130 + nDays*dayW }}>
          <div style={{ display:"flex", borderBottom:`1px solid ${T.border}`, background:T.bgInput }}>
            <div style={{ width:130, flexShrink:0, padding:"8px 10px", fontSize:12, fontWeight:700, color:T.textMid }}>Property</div>
            {Array.from({length:nDays}, (_,i)=>{
              const d = new Date(year, month, i+1);
              const wknd = d.getDay()===0 || d.getDay()===6;
              return (
                <div key={i} style={{ width:dayW, flexShrink:0, textAlign:"center", padding:"6px 0", fontSize:11,
                  color: wknd ? T.accent : T.textLight, fontWeight: wknd?700:500, background: wknd ? "#f0f6ff" : "transparent" }}>
                  <div>{"SMTWTFS".charAt(d.getDay())}</div>
                  <div style={{ fontSize:12, color:T.text }}>{i+1}</div>
                </div>
              );
            })}
          </div>
          {properties.map(p => {
            const lane = laneFor(p.id);
            const checkInDays = new Set(
              lane.filter(e => { const ci=new Date(e.checkIn+"T00:00:00"); return ci.getFullYear()===year&&ci.getMonth()===month; })
                  .map(e => new Date(e.checkIn+"T00:00:00").getDate())
            );
            const checkOutDays = new Set(
              lane.filter(e => { const co=new Date(e.checkOut+"T00:00:00"); return co.getFullYear()===year&&co.getMonth()===month; })
                  .map(e => new Date(e.checkOut+"T00:00:00").getDate())
            );
            return (
              <div key={p.id} style={{ display:"flex", borderBottom:`1px solid ${T.border}` }}>
                <div style={{ width:130, flexShrink:0, padding:"12px 10px", fontSize:13, fontWeight:700, color:T.text,
                  display:"flex", alignItems:"center", gap:7, borderRight:`1px solid ${T.border}` }}>
                  <span style={{ width:11, height:11, borderRadius:3, background:p.colour, flexShrink:0 }}/>{p.name}
                </div>
                <div style={{ position:"relative", height:44, flex:1 }}>
                  {Array.from({length:nDays}, (_,i)=>{
                    const d = new Date(year, month, i+1);
                    const wknd = d.getDay()===0||d.getDay()===6;
                    const dayNum = i+1;
                    const isCI = checkInDays.has(dayNum);
                    const isCO = checkOutDays.has(dayNum);
                    const isChgDay = isCI && isCO;
                    return (
                      <div key={i} style={{ position:"absolute", left:i*dayW, top:0, width:dayW, height:"100%",
                        background: wknd ? "#f6faff" : "transparent", borderRight:`1px solid #eef3fa`, overflow:"hidden" }}>
                        {isCO && <div style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%",
                          background: isChgDay ? darkenHex(p.colour, 55) : p.colour,
                          opacity: isChgDay ? 0.75 : 0.28,
                          clipPath:"polygon(0 0, 0% 100%, 100% 100%)" }}/>}
                        {isCI && <div style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%",
                          background: p.colour,
                          opacity: isChgDay ? 0.35 : 0.28,
                          clipPath:"polygon(100% 0, 0 0, 100% 100%)" }}/>}
                      </div>
                    );
                  })}
                  {lane.map((e,i) => {
                    const g = barGeom(e.checkIn, e.checkOut);
                    const b = e.booking;
                    const airbnb = b.source==="airbnb";
                    const blocked = b.bookingType==="Blocked";
                    return (
                      <div key={b.id+"-"+i} onClick={()=>onOpen(b)}
                        title={`${blocked ? "Not available" : (b.guestName||"(no name)")} - ${fmtDate(e.checkIn)} to ${fmtDate(e.checkOut)}`}
                        style={{ position:"absolute", left:g.left+2, top:8, width:g.width, height:28, borderRadius:6,
                          background: blocked ? "repeating-linear-gradient(135deg, #e2e8f0, #e2e8f0 4px, #eef2f7 4px, #eef2f7 8px)" : airbnb ? "#fff" : p.colourBg,
                          border: blocked ? "1.5px solid #94a3b8" : `1.5px ${airbnb?"dashed":"solid"} ${p.colour}`,
                          color: blocked ? "#64748b" : p.colour, fontSize:11, fontWeight:600, padding:"0 6px", display:"flex", alignItems:"center",
                          overflow:"hidden", whiteSpace:"nowrap", cursor:"pointer", opacity: b.status==="pending"?0.75:1 }}>
                        {blocked ? "Not available" : airbnb ? "Airbnb" : (b.guestName || "Booking")}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
      <div style={{ display:"flex", gap:16, marginTop:10, fontSize:12, color:T.textMid, flexWrap:"wrap", alignItems:"center" }}>
        <span><span style={{ display:"inline-block", width:20, height:10, background:T.accentLight, border:`1.5px solid ${T.accent}`, borderRadius:3, verticalAlign:"middle", marginRight:5 }}/>Direct / manual</span>
        <span><span style={{ display:"inline-block", width:20, height:10, background:"#fff", border:`1.5px dashed ${T.accent}`, borderRadius:3, verticalAlign:"middle", marginRight:5 }}/>Airbnb block</span>
        <span style={{ display:"inline-flex", alignItems:"center", gap:5 }}>
          <span style={{ display:"inline-block", width:14, height:14, background:"#2563eb", opacity:.3, clipPath:"polygon(0 0, 0% 100%, 100% 100%)", verticalAlign:"middle" }}/>
          <span>Checkout day</span>
        </span>
        <span style={{ display:"inline-flex", alignItems:"center", gap:5 }}>
          <span style={{ display:"inline-block", width:14, height:14, background:"#2563eb", opacity:.3, clipPath:"polygon(100% 0, 0 0, 100% 100%)", verticalAlign:"middle" }}/>
          <span>Checkin day</span>
        </span>
        <span style={{ display:"inline-flex", alignItems:"center", gap:5 }}>
          <span style={{ display:"inline-flex", width:14, height:14, verticalAlign:"middle", overflow:"hidden" }}>
            <span style={{ display:"inline-block", width:"100%", height:"100%", background:"#1040a0", opacity:.8, clipPath:"polygon(0 0, 0% 100%, 100% 100%)" }}/>
          </span>
          <span>+</span>
          <span style={{ display:"inline-flex", width:14, height:14, verticalAlign:"middle", overflow:"hidden" }}>
            <span style={{ display:"inline-block", width:"100%", height:"100%", background:"#2563eb", opacity:.35, clipPath:"polygon(100% 0, 0 0, 100% 100%)" }}/>
          </span>
          <span>Changeover day</span>
        </span>
        <span style={{ opacity:.7 }}>Faded = pending</span>
      </div>
    </div>
  );
}

const navBtn = { width:36, height:36, borderRadius:8, border:`1.5px solid ${T.border}`, background:"#fff", color:T.text, fontSize:18, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center" };

// ── Booking list ─────────────────────────────────────────────────────────────
// Short display label for a property (used in table headers / badges)
function shortPropLabel(p) {
  var n = (p && (p.name || p.id)) || "";
  if (/hamlet/i.test(n)) return "Hamlet";
  if (/amly/i.test(n)) return "Amly";
  if (/glamp/i.test(n) || /camping/i.test(n)) return "Glamping";
  return n.split(" ")[0] || n;
}

// Source label for a lettings booking: Manual / Website / Airbnb / Blocked
function accomSourceLabel(b) {
  if (b.bookingType === "Blocked") return "Blocked";
  if (b.source === "airbnb") return "Airbnb";
  if (b.source === "direct" || b.source === "website") return "Website";
  return "Manual";
}
const ACCOM_SOURCE_META = {
  Manual:  { bg:"#e0e7ff", text:"#4338ca" },
  Website: { bg:"#dcfce7", text:"#15803d" },
  Airbnb:  { bg:"#fee2e2", text:"#b91c1c" },
  Blocked: { bg:"#f1f5f9", text:"#64748b" },
};

function AccomList({ properties, bookings, filterProp, setFilterProp, filterStatus, setFilterStatus, onOpen }) {
  const [showPast, setShowPast] = useState(false);
  const today = new Date().toISOString().slice(0,10);

  const propName = (id) => (properties.find(p=>p.id===id)||{}).name || id;

  const withPrimary = bookings.map(b => {
    const primary = (b.stays && b.stays[0]) || b;
    return { b, primary };
  });

  const isCurrent = ({ primary }) => {
    // A booking is "current/future" if its latest checkout is today or later
    return (primary.checkOut || "") >= today;
  };

  const filtered = withPrimary
    .filter(({ b, primary }) => filterProp==="all" || (b.stays||[]).some(s=>s.propertyId===filterProp) || b.propertyId===filterProp)
    .filter(({ b }) => filterStatus==="all" || b.status===filterStatus);

  const currentRows = filtered.filter(x => isCurrent(x))
    .sort((a,z)=> (a.primary.checkIn||"").localeCompare(z.primary.checkIn||""));

  const pastRows = filtered.filter(x => !isCurrent(x))
    .sort((a,z)=> (z.primary.checkIn||"").localeCompare(a.primary.checkIn||"")); // most recent first

  const paidState = (b) => {
    if (!b.schedule || !b.schedule.length) return b.value>0 ? "—" : "n/a";
    const paid = b.schedule.filter(s=>s.paid).length;
    return paid===b.schedule.length ? "Paid" : String(paid)+"/"+String(b.schedule.length);
  };

  // Which property IDs are booked in this booking
  const bookedPropIds = (b) => {
    var ids = new Set();
    if (b.stays && b.stays.length) {
      b.stays.forEach(function(s){ if (s.propertyId) ids.add(s.propertyId); });
    } else if (b.propertyId) {
      ids.add(b.propertyId);
    }
    return ids;
  };

  // Build dynamic grid: Guest | per-property | Dates | Source | Event | Status | Value | Paid
  const propCols = properties.map(function(){ return "0.55fr"; }).join(" ");
  const gridTemplate = "1.5fr " + propCols + " 1.1fr 0.7fr 0.75fr 0.75fr 0.75fr 0.75fr";

  const TableHeader = () => (
    <div style={{ display:"grid", gridTemplateColumns:gridTemplate, background:T.bgInput, borderBottom:`1px solid ${T.border}`, fontSize:12, fontWeight:700, color:T.textMid }}>
      <div style={{ padding:"10px 12px" }}>Guest</div>
      {properties.map(p=>(
        <div key={p.id} style={{ padding:"10px 4px", textAlign:"center" }}>
          <span title={p.name} style={{ display:"inline-flex", alignItems:"center", gap:3, fontSize:11 }}>
            <span style={{ width:8, height:8, borderRadius:"50%", background:p.colour, display:"inline-block" }}/>
            {shortPropLabel(p)}
          </span>
        </div>
      ))}
      <div style={{ padding:"10px 12px" }}>Dates</div>
      <div style={{ padding:"10px 12px" }}>Source</div>
      <div style={{ padding:"10px 12px" }}>Type</div>
      <div style={{ padding:"10px 12px" }}>Status</div>
      <div style={{ padding:"10px 12px" }}>Value</div>
      <div style={{ padding:"10px 12px" }}>Paid</div>
    </div>
  );

  const Row = ({ b, primary }) => {
    const meta = ACCOM_STATUS_META[b.status] || ACCOM_STATUS_META.confirmed;
    const bProps = bookedPropIds(b);
    const srcLabel = accomSourceLabel(b);
    const srcMeta = ACCOM_SOURCE_META[srcLabel] || ACCOM_SOURCE_META.Manual;
    return (
      <div onClick={()=>onOpen(b)} style={{ display:"grid", gridTemplateColumns:gridTemplate, borderBottom:`1px solid #eef3fa`, cursor:"pointer", fontSize:13, color:T.text, alignItems:"center" }}>
        <div style={{ padding:"11px 12px", fontWeight:600 }}>
          {b.guestName || (b.bookingType==="Blocked" ? "Not available" : b.source==="airbnb" ? "Airbnb block" : "(no name)")}
          {b.estimated && b.value>0 && <span style={{ marginLeft:6, fontSize:10, color:T.amber, fontWeight:600 }}>est.</span>}
        </div>
        {properties.map(p=>(
          <div key={p.id} style={{ padding:"8px 4px", textAlign:"center" }}>
            {bProps.has(p.id)
              ? <span style={{ width:14, height:14, borderRadius:3, background: b.bookingType==="Blocked" ? "#94a3b8" : p.colour, display:"inline-block", boxShadow:"0 1px 3px "+(b.bookingType==="Blocked"?"#94a3b8":p.colour)+"66" }} title={p.name}/>
              : <span style={{ width:14, height:14, borderRadius:3, border:`1.5px solid #e2e8f0`, display:"inline-block", background:"transparent" }}/>
            }
          </div>
        ))}
        <div style={{ padding:"11px 12px", fontSize:12 }}>{fmtDate(primary.checkIn)} – {fmtDate(primary.checkOut)}</div>
        <div style={{ padding:"11px 12px" }}>
          <span style={{ fontSize:11, fontWeight:700, color:srcMeta.text, background:srcMeta.bg, padding:"2px 7px", borderRadius:8 }}>{srcLabel}</span>
        </div>
        <div style={{ padding:"11px 12px" }}>
          {b.bookingType
            ? <span style={{ fontSize:11, fontWeight:700, color: b.bookingType==="Blocked" ? "#64748b" : T.accent, background: b.bookingType==="Blocked" ? "#f1f5f9" : T.accentLight, padding:"2px 7px", borderRadius:8 }}>{b.bookingType}</span>
            : <span style={{ color:T.textLight, fontSize:11 }}>Let</span>}
        </div>
        <div style={{ padding:"11px 12px" }}><span style={{ fontSize:11, fontWeight:700, color:meta.text, background:meta.bg, padding:"2px 8px", borderRadius:8 }}>{meta.label}</span></div>
        <div style={{ padding:"11px 12px" }}>
          {(function() {
            const v = lettingValue(b, properties);
            if (!(v.value > 0)) return "—";
            return (
              <span title={v.estimated ? "Estimated from our own calendar rate for these dates, plus " + AIRBNB_UPLIFT_PCT + "%" : ""}>
                {String(fmtMoney(v.value))}
                {v.estimated && <span style={{ marginLeft:5, fontSize:10, color:T.amber, fontWeight:700 }}>(est)</span>}
              </span>
            );
          })()}
        </div>
        <div style={{ padding:"11px 12px" }}>{paidState(b)}</div>
      </div>
    );
  };

  return (
    <div>
      <div style={{ display:"flex", gap:10, marginBottom:14, flexWrap:"wrap", alignItems:"center" }}>
        <select value={filterProp} onChange={e=>setFilterProp(e.target.value)} style={selStyle}>
          <option value="all">All properties</option>
          {properties.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}
        </select>
        <select value={filterStatus} onChange={e=>setFilterStatus(e.target.value)} style={selStyle}>
          <option value="all">All statuses</option>
          <option value="confirmed">Confirmed</option>
          <option value="pending">Pending</option>
          <option value="completed">Completed</option>
          <option value="cancelled">Cancelled</option>
        </select>
        <span style={{ alignSelf:"center", fontSize:13, color:T.textMid }}>{currentRows.length} upcoming · {pastRows.length} past</span>
      </div>

      <div style={{ border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", background:"#fff" }}>
        <TableHeader/>
        {currentRows.map(({ b, primary }) => <Row key={b.id} b={b} primary={primary}/>)}
        {!currentRows.length && <div style={{ padding:"22px", textAlign:"center", color:T.textLight, fontSize:13 }}>No upcoming bookings match.</div>}
      </div>

      <div style={{ marginTop:14, textAlign:"center" }}>
        <button onClick={()=>setShowPast(v=>!v)}
          style={{ background:"none", border:`1.5px solid ${T.border}`, color:T.textMid, borderRadius:8, padding:"8px 20px", cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>
          {showPast ? "Hide past bookings" : "Show past bookings (" + pastRows.length + ")"}
        </button>
      </div>

      {showPast && pastRows.length > 0 && (
        <div style={{ border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", background:"#fff", marginTop:10, opacity:.85 }}>
          <div style={{ padding:"8px 14px", background:T.bgInput, borderBottom:`1px solid ${T.border}`, fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4 }}>
            Past bookings (most recent first)
          </div>
          <TableHeader/>
          {pastRows.map(({ b, primary }) => <Row key={b.id} b={b} primary={primary}/>)}
        </div>
      )}
    </div>
  );
}

const selStyle = { background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text, fontFamily:"inherit", fontSize:13, padding:"8px 11px", outline:"none", cursor:"pointer" };

// ── Add / edit form ──────────────────────────────────────────────────────────
// The clock beside a date. Shows the time that applies — from the rules
// unless someone has set one — and opens a time picker when clicked. An
// overridden time is shown in amber so it's obvious it isn't the default;
// "reset" puts it back to the rule rather than to blank, which is what people
// actually mean when they undo one of these.
function StayTimeField({ booking, stay, prop, which, onChange }) {
  const [open, setOpen] = useState(false);
  const t = stayTimes(booking, stay, prop);
  const value = which === "in" ? t.inTime : t.outTime;
  const overridden = which === "in" ? t.inOverridden : t.outOverridden;

  if (!open) {
    return (
      <button type="button" onClick={function(){ setOpen(true); }}
        title={overridden ? "Set by hand — click to change" : "Default for this booking — click to change"}
        style={{ background:"none", border:"none", padding:"3px 0 0", cursor:"pointer", fontFamily:"inherit",
          fontSize:11, color: overridden ? T.amber : T.textLight, fontWeight: overridden ? 700 : 500,
          display:"flex", alignItems:"center", gap:4 }}>
        <span aria-hidden="true">🕑</span>{value}
      </button>
    );
  }

  return (
    <div style={{ display:"flex", alignItems:"center", gap:4, paddingTop:3 }}>
      <input type="time" value={value} step="900" autoFocus
        onChange={function(e){ onChange(e.target.value); }}
        onBlur={function(){ setOpen(false); }}
        style={{ ...inlineInput, padding:"3px 5px", fontSize:11, width:78 }}/>
      {overridden && (
        <button type="button" onMouseDown={function(e){ e.preventDefault(); onChange(""); setOpen(false); }}
          title="Back to the default time"
          style={{ background:"none", border:"none", color:T.textLight, cursor:"pointer", fontSize:10, fontFamily:"inherit", padding:0 }}>
          reset
        </button>
      )}
    </div>
  );
}

function AccomForm({ properties, discountCodes, events, form, setForm, onSave, onExit, onDelete, onOpenEvent }) {
  var formStays = (form.stays && form.stays.length) ? form.stays : [{ propertyId:form.propertyId||"hamlet", propertyName:"", checkIn:form.checkIn||"", checkOut:form.checkOut||"", nights:null, guestCount:form.guestCount||"", value:Number(form.value)||0 }];
  var selPropIds = formStays.map(function(s){ return s.propertyId; });
  var totalValue = formStays.reduce(function(s,st){ return s+(Number(st.value)||0); }, 0);
  var primaryProp = properties.find(function(p){ return p.id===selPropIds[0]; });
  const upd = (k,v)=> setForm(f=>({ ...f, [k]:v }));
  const zeroValue = totalValue <= 0;

  const toggleProp = (pid, checked) => setForm(function(f) {
    var cur = (f.stays&&f.stays.length) ? f.stays : [{ propertyId:f.propertyId||"hamlet", propertyName:"", checkIn:"", checkOut:"", nights:null, guestCount:"", value:0 }];
    var next;
    if (checked) {
      var ref = cur[0] || {};
      next = cur.concat([{ propertyId:pid, propertyName:"", checkIn:ref.checkIn||"", checkOut:ref.checkOut||"", nights:ref.nights||null, guestCount:"", value:0 }]);
    } else {
      next = cur.filter(function(s){ return s.propertyId !== pid; });
      if (!next.length) next = cur;
    }
    var pIds = next.map(function(s){ return s.propertyId; });
    var tot = next.reduce(function(s,st){ return s+(Number(st.value)||0); }, 0);
    return Object.assign({}, f, { stays:next, propertyIds:pIds, propertyId:pIds[0], value:tot });
  });

  const updStay = (idx, key, val) => setForm(function(f) {
    var cur = (f.stays&&f.stays.length) ? f.stays : [];
    var next = cur.map(function(s,i){
      if (i !== idx) return s;
      var patch = { [key]: val };
      // When a check-in date is picked and there's no check-out yet, seed the
      // check-out field with a date in the same month — the browser's native
      // date picker opens to whatever month the field's current value is in,
      // so this makes choosing the check-out date land on the right month.
      if (key === "checkIn" && val && !s.checkOut) {
        var d = new Date(val + "T00:00:00");
        d.setDate(d.getDate() + 1);
        patch.checkOut = d.toISOString().slice(0,10);
      }
      return Object.assign({}, s, patch);
    });
    var tot = next.reduce(function(s,st){ return s+(Number(st.value)||0); }, 0);
    return Object.assign({}, f, { stays:next, value:tot });
  });

  // Copy the check-in/check-out dates from the stay row directly above this
  // one — used by the small "copy" button shown on every property row after
  // the first, so multi-property bookings can be dated in one click.
  const copyDatesFromAbove = (idx) => setForm(function(f) {
    var cur = (f.stays&&f.stays.length) ? f.stays : [];
    if (idx <= 0 || !cur[idx-1]) return f;
    var above = cur[idx-1];
    var next = cur.map(function(s,i){ return i===idx ? Object.assign({}, s, { checkIn: above.checkIn||"", checkOut: above.checkOut||"" }) : s; });
    var tot = next.reduce(function(s,st){ return s+(Number(st.value)||0); }, 0);
    return Object.assign({}, f, { stays:next, value:tot });
  });

  const regenSchedule = () => {
    var firstStay = formStays[0] || {};
    const sched = buildAccomSchedule(totalValue, primaryProp, firstStay.checkIn);
    setForm(f=>({ ...f, schedule: sched, value: totalValue }));
  };
  const updSched = (i, k, v) => setForm(f=>{
    const s = f.schedule.map((row,idx)=> idx===i ? { ...row, [k]:v } : row);
    return { ...f, schedule: s };
  });
  const addExtra = () => setForm(f=>({ ...f, extras: f.extras.concat([{ desc:"", amount:0 }]) }));
  const updExtra = (i,k,v)=> setForm(f=>({ ...f, extras: f.extras.map((e,idx)=> idx===i ? { ...e, [k]:v } : e) }));
  const rmExtra = (i)=> setForm(f=>({ ...f, extras: f.extras.filter((_,idx)=> idx!==i) }));

  return (
    <div style={{ maxWidth:1020 }}>
      {form.bookingType === "Blocked" && (
        <div style={{ marginBottom:16, padding:"10px 14px", background:"#f1f5f9", border:`1.5px solid #cbd5e1`, borderRadius:8, fontSize:12, color:T.textMid, lineHeight:1.5 }}>
          This marks the property as unavailable for the selected dates. It won't be treated as a guest booking, and will sync out to Airbnb as blocked.
        </div>
      )}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:14, marginBottom:16 }}>
        <div style={{ display:"flex", flexDirection:"column", gap:5 }}>
          <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Properties</span>
          <div style={{ display:"flex", gap:14, flexWrap:"wrap", padding:"10px 12px", background:T.bgInput, borderRadius:8, border:`1.5px solid ${T.border}` }}>
            {properties.map(function(p) {
              var checked = selPropIds.includes(p.id);
              return (
                <label key={p.id} style={{ display:"flex", alignItems:"center", gap:7, cursor:"pointer", fontSize:13, fontWeight:checked?700:500, color:checked?T.text:T.textMid }}>
                  <input type="checkbox" checked={checked}
                    onChange={function(e){ toggleProp(p.id, e.target.checked); }}
                    style={{ width:15, height:15, accentColor:p.colour, cursor:"pointer" }} />
                  <span style={{ width:10, height:10, borderRadius:"50%", background:p.colour, display:"inline-block" }}/>
                  {p.name}
                </label>
              );
            })}
          </div>
        </div>
        <label style={{ display:"flex", flexDirection:"column", gap:5 }}>
          <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Booking type</span>
          <select value={form.bookingType} onChange={function(e){
            var v = e.target.value;
            upd("bookingType", v);
            if (v === "Blocked" && !form.guestName) upd("guestName", "Not available");
          }} style={{ ...selStyle, padding:"9px 11px" }}>
            <option value="">Standard let</option>
            <option value="Wedding">Wedding</option>
            <option value="Owner">Owner / comp</option>
            <option value="Blocked">Blocked (not available)</option>
          </select>
        </label>
        {(events && events.length > 0) && (
          <label style={{ display:"flex", flexDirection:"column", gap:5 }}>
            <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Link to farm event</span>
            <select value={form.linkedEventId || ""} onChange={function(e){ upd("linkedEventId", e.target.value ? Number(e.target.value) : null); }} style={{ ...selStyle, padding:"9px 11px" }}>
              <option value="">No event link</option>
              {(events||[]).slice().sort(function(a,b){ return a.date>b.date?1:-1; }).map(function(ev) {
                return (
                  <option key={ev.id} value={ev.id}>
                    {ev.date} — {ev.couple || ev.bookingType || "Event"}{ev.eventType ? " (" + ev.eventType + ")" : ""}
                  </option>
                );
              })}
            </select>
            {form.linkedEventId && (
              <span style={{ fontSize:11, color:T.accent, fontWeight:600 }}>
                {onOpenEvent ? (
                  <button type="button" onClick={function(){ onOpenEvent(form.linkedEventId); }}
                    title="Open this event"
                    style={{ background:"none", border:"none", padding:0, color:T.accent, fontFamily:"inherit",
                      fontSize:11, fontWeight:700, cursor:"pointer", textDecoration:"underline" }}>
                    {(function() {
                      const ev = (events || []).find(function(e) { return String(e.id) === String(form.linkedEventId); });
                      return ev ? (ev.couple || "Event #" + form.linkedEventId) + " →" : "Open event #" + form.linkedEventId + " →";
                    })()}
                  </button>
                ) : ("Linked to event #" + form.linkedEventId)}
              </span>
            )}
          </label>
        )}
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:14, marginBottom:16 }}>
        <LInput label="Guest name" value={form.guestName} onChange={v=>upd("guestName",v)} />
        <LInput label="Email" value={form.email} onChange={v=>upd("email",v)} />
        <LInput label="Phone" value={form.phone} onChange={v=>upd("phone",v)} />
        <label style={{ display:"flex", flexDirection:"column", gap:5 }}>
          <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Status</span>
          <select value={form.status} onChange={e=>upd("status", e.target.value)} style={{ ...selStyle, padding:"9px 11px" }}>
            <option value="confirmed">Confirmed</option>
            <option value="pending">Pending</option>
            <option value="completed">Completed</option>
            <option value="cancelled">Cancelled</option>
          </select>
        </label>
      </div>

      {/* Per-property stays grid */}
      <div style={{ border:`1px solid ${T.border}`, borderRadius:9, overflow:"hidden", marginBottom:16 }}>
        <div style={{ display:"grid", gridTemplateColumns:"1.7fr 52px 1fr 1fr 44px 54px 1.4fr", background:T.bgInput, borderBottom:`1px solid ${T.border}`, fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.5 }}>
          {["Property","Maybe","Check-in","Check-out","Nights","Guests","Price (£)"].map(function(h){ return <div key={h} style={{ padding:"9px 12px" }}>{h}</div>; })}
        </div>
        {formStays.map(function(s, idx) {
          var p = properties.find(function(pp){ return pp.id===s.propertyId; });
          var nights = nightsBetween(s.checkIn, s.checkOut);
          var q = (p && p.baseRate && s.checkIn && s.checkOut) ? quoteStay(p, s.checkIn, s.checkOut) : null;
          return (
            <div key={s.propertyId} style={{ display:"grid", gridTemplateColumns:"1.7fr 52px 1fr 1fr 44px 54px 1.4fr", borderBottom: idx < formStays.length-1 ? `1px solid ${T.border}` : "none", background:"#fff", alignItems:"center" }}>
              <div style={{ padding:"10px 12px", display:"flex", alignItems:"center", gap:7, fontSize:13, fontWeight:600 }}>
                {p && <span style={{ width:10, height:10, borderRadius:"50%", background:p.colour, display:"inline-block", flexShrink:0 }}/>}
                <span style={{ overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p ? p.name : s.propertyId}</span>
                {idx > 0 && (
                  <button type="button" onClick={function(){ copyDatesFromAbove(idx); }}
                    title="Copy check-in/check-out dates from the property above"
                    style={{ ...smallBtn, padding:"3px 7px", fontSize:11, whiteSpace:"nowrap", flexShrink:0, marginLeft:"auto" }}>
                    ⧉ Copy
                  </button>
                )}
              </div>
              {/* Provisional marker — recorded on the stay for later use; it
                  changes nothing else today. */}
              <div style={{ padding:"10px 8px", display:"flex", justifyContent:"center" }}>
                <input type="checkbox" checked={!!s.maybe} onChange={function(e){ updStay(idx,"maybe",e.target.checked); }}
                  title="Provisional — not confirmed"
                  style={{ width:16, height:16, accentColor:T.amber, cursor:"pointer" }}/>
              </div>
              <div style={{ padding:"6px 8px" }}>
                <input type="date" value={s.checkIn||""} onChange={function(e){ updStay(idx,"checkIn",e.target.value); }} style={{ ...inlineInput, width:"100%" }}/>
                <StayTimeField booking={form} stay={s} prop={p} which="in"
                  onChange={function(v){ updStay(idx,"checkInTime",v); }}/>
              </div>
              <div style={{ padding:"6px 8px" }}>
                <input type="date" value={s.checkOut||""} onChange={function(e){ updStay(idx,"checkOut",e.target.value); }} style={{ ...inlineInput, width:"100%" }}/>
                <StayTimeField booking={form} stay={s} prop={p} which="out"
                  onChange={function(v){ updStay(idx,"checkOutTime",v); }}/>
              </div>
              <div style={{ padding:"10px 8px", fontSize:13, color:T.textMid, textAlign:"center" }}>{nights||"—"}</div>
              <div style={{ padding:"6px 8px" }}>
                <input type="number" value={s.guestCount||""} placeholder="—" onChange={function(e){ updStay(idx,"guestCount",e.target.value); }} style={{ ...inlineInput, width:"100%" }}/>
              </div>
              <div style={{ padding:"6px 8px", display:"flex", gap:6, alignItems:"center" }}>
                <input type="number" value={s.value||""} placeholder="0" onChange={function(e){ updStay(idx,"value",e.target.value); }} style={{ ...inlineInput, flex:1, minWidth:62 }}/>
                {q && (
                  <button type="button" onClick={function(){ updStay(idx,"value",q.total); }}
                    title={"Pricing estimate: "+fmtMoney(q.total)}
                    style={{ ...smallBtn, padding:"5px 9px", fontSize:11, whiteSpace:"nowrap", flexShrink:0 }}>
                    {fmtMoney(q.total)}
                  </button>
                )}
              </div>
            </div>
          );
        })}
        {formStays.length > 1 && (
          <div style={{ display:"flex", justifyContent:"flex-end", alignItems:"center", padding:"10px 16px", background:T.accentLight, borderTop:`1px solid ${T.accent}30`, gap:16 }}>
            <span style={{ fontSize:12, color:T.midBlue }}>Total billed to guest</span>
            <span style={{ fontSize:16, fontWeight:800, color:T.text }}>{fmtMoney(totalValue)}</span>
          </div>
        )}
      </div>

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14, marginBottom:8 }}>
        <label style={{ display:"flex", flexDirection:"column", gap:5 }}>
          <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Discount code</span>
          <input value={form.discountCode || ""} onChange={e => {
            const code = e.target.value.toUpperCase();
            upd("discountCode", code);
            const today = new Date().toISOString().slice(0,10);
            const match = (discountCodes || []).find(c => c.active && c.code === code && (!c.expiresAt || c.expiresAt >= today));
            if (match) {
              const disc = match.type === "pct" ? Math.round((Number(form.value)||0) * match.value / 100 * 100) / 100 : match.value;
              upd("discountAmount", disc);
            } else {
              upd("discountAmount", 0);
            }
          }} style={inpStyle} placeholder="e.g. SUMMER10" />
          {(function() {
            const today = new Date().toISOString().slice(0,10);
            const match = (discountCodes || []).find(c => c.code === (form.discountCode || "").toUpperCase());
            if (!form.discountCode) return null;
            if (!match) return <span style={{ fontSize:11, color:T.red }}>Code not found</span>;
            if (!match.active) return <span style={{ fontSize:11, color:T.red }}>Code inactive</span>;
            if (match.expiresAt && match.expiresAt < today) return <span style={{ fontSize:11, color:T.red }}>Code expired</span>;
            return <span style={{ fontSize:11, color:T.green, fontWeight:600 }}>Valid — {match.type === "pct" ? match.value+"% off" : fmtMoney(match.value)+" off"}</span>;
          })()}
        </label>
        <label style={{ display:"flex", flexDirection:"column", gap:5 }}>
          <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Source</span>
          <select value={form.source} onChange={e=>upd("source", e.target.value)} style={{ ...selStyle, padding:"9px 11px" }}>
            <option value="manual">Manual</option>
            <option value="direct">Direct (online)</option>
            <option value="airbnb">Airbnb</option>
            <option value="wedding">Wedding-linked</option>
          </select>
        </label>
      </div>
      {zeroValue && <div style={{ fontSize:12, color:T.textMid, background:T.amberBg, border:`1px solid #fcd34d`, borderRadius:7, padding:"8px 11px", marginBottom:16 }}>Zero value — this booking blocks the calendar but generates no payment schedule and is never chased.</div>}

      {/* Extras */}
      <div style={{ border:`1px solid ${T.border}`, borderRadius:9, padding:"14px 16px", marginBottom:16, background:T.bgInput }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom: form.extras.length?10:0 }}>
          <span style={{ fontSize:13, fontWeight:700, color:T.text }}>Extras</span>
          <button onClick={addExtra} style={smallBtn}>+ Add extra</button>
        </div>
        {form.extras.map((e,i)=>(
          <div key={i} style={{ display:"flex", gap:10, marginBottom:8 }}>
            <input value={e.desc} placeholder="Description" onChange={ev=>updExtra(i,"desc",ev.target.value)} style={{ flex:1, ...inlineInput }} />
            <input type="number" value={e.amount} placeholder="£" onChange={ev=>updExtra(i,"amount",ev.target.value)} style={{ width:110, ...inlineInput }} />
            <button onClick={()=>rmExtra(i)} style={{ ...smallBtn, color:T.red, borderColor:"#fca5a5" }}>Remove</button>
          </div>
        ))}
      </div>

      {/* Breakage */}
      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:14, marginBottom:16, alignItems:"end" }}>
        <LInput label="Breakage deposit (£, refundable)" type="number" value={form.breakage} onChange={v=>upd("breakage",v)} />
        {Number(form.breakage)>0 && (
          <button onClick={()=>alert("Refund breakage via Stripe — wired to the Stripe refund function in phase 2 (uses the stored charge ID).")}
            style={{ ...smallBtn, padding:"9px 14px", fontSize:13 }}>Refund breakage from Stripe</button>
        )}
      </div>

      {/* Payment schedule — suppressed when the booking is billed via an event.
          Event-linked accommodation is invoiced through the event's Xero
          invoices (50% on the 1 Dec invoice, 50% on the final one), so it must
          not also have its own deposit/balance requests or payment links. */}
      {form.linkedEventId ? (
        <div style={{ border:"1px solid #bfdbfe", background:"#eff6ff", borderRadius:9, padding:"12px 16px", marginBottom:16 }}>
          <div style={{ fontSize:13, fontWeight:700, color:"#1d4ed8", marginBottom:4 }}>Billed through the linked event</div>
          <div style={{ fontSize:12, color:"#1d4ed8", lineHeight:1.6 }}>
            This accommodation is invoiced with{" "}
            {onOpenEvent ? (
              <button type="button" onClick={function(){ onOpenEvent(form.linkedEventId); }}
                style={{ background:"none", border:"none", padding:0, color:"#1d4ed8", fontFamily:"inherit",
                  fontSize:12, fontWeight:700, cursor:"pointer", textDecoration:"underline" }}>
                event #{form.linkedEventId}
              </button>
            ) : ("event #" + form.linkedEventId)} — split 50% on the 1&nbsp;December invoice and 50% on the final invoice,
            along with any extras below. No deposit or balance requests are sent for it, and no payment schedule applies.
            Unlink the event above if this should be billed as a standard let instead.
          </div>
        </div>
      ) : (
      <div style={{ border:`1px solid ${T.border}`, borderRadius:9, padding:"14px 16px", marginBottom:16 }}>
        <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:10 }}>
          <span style={{ fontSize:13, fontWeight:700, color:T.text }}>Payment schedule</span>
          <button onClick={regenSchedule} style={smallBtn} disabled={zeroValue}>Auto-build deposit + balance</button>
        </div>
        {!form.schedule.length && <div style={{ fontSize:12, color:T.textLight }}>No schedule. {zeroValue ? "Zero-value booking." : "Use auto-build, or leave blank if paid."}</div>}
        {form.schedule.map((s,i)=>(
          <div key={i} style={{ marginBottom:8 }}>
            <div style={{ display:"grid", gridTemplateColumns:"1fr 0.9fr 1.1fr auto", gap:10, alignItems:"center" }}>
              <input value={s.label} onChange={e=>updSched(i,"label",e.target.value)} style={inlineInput} />
              <input type="number" value={s.amount} onChange={e=>updSched(i,"amount",e.target.value)} style={inlineInput} />
              <input type="date" value={s.dueDate||""} onChange={e=>updSched(i,"dueDate",e.target.value)} style={inlineInput} />
              <label style={{ display:"flex", alignItems:"center", gap:6, fontSize:12, color:T.textMid, whiteSpace:"nowrap" }}>
                <input type="checkbox" checked={!!s.paid} onChange={e=>updSched(i,"paid",e.target.checked)} style={{ width:15, height:15, accentColor:T.accent }} />paid
              </label>
            </div>
            {/* Stripe ticks "paid" itself when the webhook fires; this line
                shows what it recorded, so a tick that came from a real payment
                is distinguishable from one someone ticked by hand. */}
            {s.paid && (s.paidDate || s.receiptUrl) && (
              <div style={{ display:"flex", alignItems:"center", gap:9, flexWrap:"wrap",
                fontSize:11, color:T.green, marginTop:4, paddingLeft:2 }}>
                <span>
                  {s.receiptUrl ? "Paid via Stripe" : "Marked paid"}
                  {s.paidDate ? " " + fmtDate(s.paidDate) : ""}
                  {Number(s.paidAmount) > 0 ? " · " + String(fmtMoney(s.paidAmount)) : ""}
                  {Number(s.paidAmount) > 0 && Math.abs(Number(s.paidAmount) - Number(s.amount)) > 0.005
                    ? " (scheduled " + String(fmtMoney(s.amount)) + ")" : ""}
                </span>
                {s.receiptUrl && (
                  <a href={s.receiptUrl} target="_blank" rel="noreferrer"
                    style={{ color:T.accent, fontWeight:600, textDecoration:"none" }}>
                    Stripe receipt ↗
                  </a>
                )}
                {s.paymentIntentId && (
                  <a href={"https://dashboard.stripe.com/payments/" + s.paymentIntentId} target="_blank" rel="noreferrer"
                    style={{ color:T.textLight, textDecoration:"none" }}>
                    open in Stripe ↗
                  </a>
                )}
              </div>
            )}
          </div>
        ))}
      </div>
      )}

      <label style={{ display:"flex", flexDirection:"column", gap:5, marginBottom:18 }}>
        <span style={{ fontSize:12, fontWeight:600, color:T.textMid }}>Notes</span>
        <textarea value={form.notes} onChange={e=>upd("notes",e.target.value)} rows={3}
          style={{ background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text, fontFamily:"inherit", fontSize:14, padding:"10px 11px", outline:"none", resize:"vertical" }} />
      </label>

      {form.termsAcceptedAt && (
        <div style={{ fontSize:12, color:T.green, background:T.greenBg, border:"1px solid #bbf7d0", borderRadius:7,
          padding:"8px 12px", marginBottom:14 }}>
          Terms &amp; Conditions accepted at checkout on{" "}
          {new Date(form.termsAcceptedAt).toLocaleString("en-GB", { day:"numeric", month:"long", year:"numeric", hour:"2-digit", minute:"2-digit" })}
        </div>
      )}

      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:9, padding:"16px 18px", marginBottom:18 }}>
        <ManualEmailSenders booking={form} onBuildSchedule={form.linkedEventId ? null : regenSchedule}/>
        <EmailHistoryPanel bookingId={form.id} title="Emails Sent" emptyLabel="No emails sent for this booking yet."/>
      </div>

      {/* Save keeps the booking open so the schedule can be built, emails sent
          and figures adjusted in one sitting. Exit is deliberately separate. */}
      <div style={{ display:"flex", gap:10, alignItems:"center", flexWrap:"wrap" }}>
        <button onClick={function(){ onSave(true); }}
          style={{ background:T.accent, color:"#fff", border:"none", padding:"11px 22px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:700 }}>
          Save booking
        </button>
        <button onClick={function(){ onSave(false); }}
          style={{ background:"#fff", color:T.accent, border:`1.5px solid ${T.accent}`, padding:"11px 22px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:700 }}>
          Save &amp; exit
        </button>
        <button onClick={onExit}
          style={{ background:"#fff", color:T.textMid, border:`1.5px solid ${T.border}`, padding:"11px 22px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:600 }}>
          Exit
        </button>
        {onDelete && <button onClick={onDelete} style={{ marginLeft:"auto", background:"#fff", color:T.red, border:`1.5px solid #fca5a5`, padding:"11px 22px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:600 }}>Delete</button>}
      </div>
      <div style={{ fontSize:11, color:T.textLight, marginTop:8 }}>
        Exit leaves without saving anything changed since the last save.
      </div>
    </div>
  );
}

// ─── MANUAL EMAIL TRIGGERS ────────────────────────────────────────────────────
// Fire any stage email on demand, ignoring the schedule entirely — for testing
// the templates, and for resending when a guest says nothing arrived.
// These bypass the automatic rules on purpose, including the suppression of
// lettings emails for event-linked bookings, so a one-off can always be sent.
// They do not bypass the £0 guards: the server refuses those, because a
// request for nothing is a fault however it was triggered.
const MANUAL_EMAILS = [
  { id:"booking_confirmed",    label:"Booking confirmed" },
  { id:"deposit_request",      label:"Deposit request" },
  { id:"balance_request",      label:"Balance request" },
  { id:"payment_confirmation", label:"Payment received" },
  { id:"arrival",              label:"Arrival info" }
];

function ManualEmailSenders({ booking, onBuildSchedule }) {
  const [busy, setBusy] = useState(null);
  const [note, setNote] = useState(null);
  const [confirmId, setConfirmId] = useState(null);

  if (!booking || !booking.id) {
    return (
      <div style={{ fontSize:12, color:T.textLight, marginBottom:16 }}>
        Save the booking before sending any emails.
      </div>
    );
  }

  const to = (booking.email || "").trim();
  const schedule = booking.schedule || [];
  const amountOf = function(label) {
    const e = schedule.find(function(s){ return s.label === label; });
    return Number(e && e.amount) || 0;
  };
  const paidSoFar = schedule.reduce(function(a,s){ return a + (s.paid ? Number(s.amount)||0 : 0); }, 0);

  // Arrival comes in two flavours; the server picks by booking type, so mirror
  // that here rather than making the user choose.
  const resolveId = function(id) {
    if (id !== "arrival") return id;
    return booking.bookingType === "Wedding" ? "arrival_event" : "arrival_general";
  };

  // Entering a value doesn't create a payment schedule — that only happens when
  // "Auto-build deposit + balance" is pressed. Without it there is no Deposit or
  // Balance row to price the email from, so say that rather than reporting £0,
  // which reads as though the figures are wrong.
  const total = Number(booking.value) || 0;
  const noSchedule = !schedule.length;

  const blockedReason = function(id) {
    if (!to) return "No guest email on this booking";
    if (id === "deposit_request" || id === "balance_request") {
      if (noSchedule) {
        return total > 0
          ? "No payment schedule yet — build one first"
          : "No payment schedule, and the booking value is £0";
      }
      const label = id === "deposit_request" ? "Deposit" : "Balance";
      if (!(amountOf(label) > 0)) return "The " + label + " row is £0";
    }
    if (id === "payment_confirmation" && !(paidSoFar > 0)) {
      return noSchedule ? "No payment schedule, so nothing can be marked paid" : "Nothing ticked as paid yet";
    }
    if (id === "arrival" && !booking.checkIn) return "No check-in date";
    return null;
  };

  async function send(id) {
    setBusy(id); setNote(null); setConfirmId(null);
    try {
      const res = await fetch("/.netlify/functions/send-accom-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bookingId: booking.id, emailType: resolveId(id) })
      });
      const data = await res.json().catch(function(){ return {}; });
      if (!res.ok || data.error) throw new Error(data.error || ("Send failed (" + res.status + ")"));
      // data.fn is the version of the Netlify function that answered. If it's
      // missing, an older copy is still deployed — which is the usual reason a
      // payment link fails to appear even though everything looks right here.
      setNote({
        kind: data.fn ? "ok" : "warn",
        text: data.fn
          ? "Sent to " + to + "." + (data.paymentLink ? " Payment link included." : "")
          : "Sent to " + to + ", but the server is running an older version of the email function — payment links won't be included until the Netlify functions are redeployed."
      });
    } catch (e) {
      setNote({ kind:"error", text: String(e.message || e) });
    }
    setBusy(null);
  }

  return (
    <div style={{ marginBottom:18, paddingBottom:16, borderBottom:`1px solid ${T.border}` }}>
      <div style={{ display:"flex", alignItems:"baseline", gap:8, marginBottom:8, flexWrap:"wrap" }}>
        <h3 style={{ margin:0, color:T.midBlue, fontWeight:700, fontSize:15 }}>Send an email now</h3>
        <span style={{ fontSize:11, color:T.textLight }}>
          ignores the due dates — for testing, or resending{to ? " to " + to : ""}
        </span>
      </div>
      {/* The email is built server-side from the stored booking, so anything
          still sitting unsaved on this form won't appear in it. */}
      <div style={{ fontSize:11, color:T.textLight, marginBottom:9, lineHeight:1.6 }}>
        Sent from the saved booking — save first if you've just changed the figures.
      </div>
      {booking.linkedEventId && (
        <div style={{ fontSize:11.5, color:"#92400e", background:"#fffbeb", border:"1px solid #fde68a",
          borderRadius:6, padding:"7px 10px", marginBottom:9, lineHeight:1.6 }}>
          Attached to a farm event — only arrival info is sent automatically. These buttons still work if you want to send something by hand.
        </div>
      )}
      {noSchedule && total > 0 && !booking.linkedEventId && (
        <div style={{ fontSize:11.5, color:"#92400e", background:"#fffbeb", border:"1px solid #fde68a",
          borderRadius:6, padding:"7px 10px", marginBottom:9, lineHeight:1.6, display:"flex",
          alignItems:"center", gap:9, flexWrap:"wrap" }}>
          <span style={{ flex:1, minWidth:200 }}>
            This booking is {String(fmtMoney(total))} but has no payment schedule, so there's no deposit or balance to email about.
          </span>
          {onBuildSchedule && (
            <button type="button" onClick={onBuildSchedule}
              style={{ background:"none", border:"1px solid #fdba74", color:"#92400e", borderRadius:5,
                padding:"4px 10px", fontFamily:"inherit", fontSize:11, fontWeight:700, cursor:"pointer", flexShrink:0 }}>
              Build deposit + balance
            </button>
          )}
        </div>
      )}
      <div style={{ display:"flex", gap:7, flexWrap:"wrap" }}>
        {MANUAL_EMAILS.map(function(m) {
          const reason = blockedReason(m.id);
          const armed = confirmId === m.id;
          return (
            <button key={m.id} type="button"
              disabled={!!reason || busy !== null}
              onClick={function(){ armed ? send(m.id) : setConfirmId(m.id); }}
              onBlur={function(){ if (armed) setConfirmId(null); }}
              title={reason || ("Send the " + m.label.toLowerCase() + " email to " + to)}
              style={{ background: armed ? T.green : "#fff", color: armed ? "#fff" : (reason ? T.textLight : T.text),
                border:`1.5px solid ${armed ? T.green : T.border}`, borderRadius:7, padding:"6px 12px",
                fontFamily:"inherit", fontSize:12, fontWeight:600,
                cursor: reason ? "not-allowed" : "pointer", opacity: reason ? .55 : 1 }}>
              {busy === m.id ? "Sending…" : armed ? "Send now?" : m.label}
            </button>
          );
        })}
      </div>
      {note && (
        <div style={{ marginTop:9, fontSize:12, lineHeight:1.55,
          color: note.kind==="ok" ? T.green : note.kind==="warn" ? "#92400e" : T.red }}>{note.text}</div>
      )}
    </div>
  );
}

const smallBtn = { background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text, fontFamily:"inherit", fontSize:12, fontWeight:600, padding:"6px 12px", cursor:"pointer" };
const inlineInput = { background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text, fontFamily:"inherit", fontSize:13, padding:"8px 10px", outline:"none" };

// ── One-off Bookalet importer (file upload) ──────────────────────────────────
function AccomImport({ onImported, saveBookings, bookings }) {
  const [status, setStatus] = useState("");
  const [mergeStatus, setMergeStatus] = useState("");
  const [mergePreview, setMergePreview] = useState(null);

  const handleFile = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async () => {
      try {
        const data = JSON.parse(reader.result);
        const props = Array.isArray(data.properties) && data.properties.length ? data.properties : INITIAL_PROPERTIES;
        const guests = Array.isArray(data.guests) ? data.guests : [];
        const imported = Array.isArray(data.bookings) ? data.bookings : [];
        setStatus("Saving " + imported.length + " bookings and " + guests.length + " guests…");
        await sbSet(PROPERTIES_STORAGE, props);
        await sbSet(ACCOM_GUESTS_STORAGE, guests);
        await sbSet(ACCOM_STORAGE, imported);
        setStatus("Imported " + imported.length + " bookings and " + guests.length + " guests.");
        onImported(props, guests, imported);
      } catch (err) {
        setStatus("Import failed: " + err.message);
      }
    };
    reader.readAsText(file);
  };

  // Find pairs: any two single-property bookings with the same guest name (case-insensitive)
  // that have different properties and check-in dates within 7 days of each other.
  const findMergePairs = () => {
    var singles = (bookings||[]).filter(function(b) {
      if (b.status === "cancelled") return false;
      var stays = (b.stays&&b.stays.length) ? b.stays : [b];
      return stays.length === 1;
    });
    var pairs = [];
    var used = new Set();
    singles.forEach(function(b1, i) {
      if (used.has(b1.id)) return;
      var s1 = ((b1.stays&&b1.stays.length)?b1.stays:[b1])[0];
      if (!s1||!s1.propertyId||!s1.checkIn) return;
      var name1 = (b1.guestName||"").toLowerCase().trim();
      if (!name1) return;
      var ci1 = new Date(s1.checkIn+"T00:00:00");
      singles.forEach(function(b2, j) {
        if (j <= i) return;
        if (used.has(b1.id)||used.has(b2.id)) return;
        var s2 = ((b2.stays&&b2.stays.length)?b2.stays:[b2])[0];
        if (!s2||!s2.propertyId||!s2.checkIn) return;
        if (s2.propertyId === s1.propertyId) return;
        var name2 = (b2.guestName||"").toLowerCase().trim();
        if (!name2 || name2 !== name1) return;
        var ci2 = new Date(s2.checkIn+"T00:00:00");
        if (Math.abs((ci1-ci2)/86400000) > 7) return;
        pairs.push({ b1:b1, b2:b2, s1:s1, s2:s2 });
        used.add(b1.id); used.add(b2.id);
      });
    });
    return pairs;
  };

  const previewMerge = () => {
    var pairs = findMergePairs();
    setMergePreview(pairs);
  };

  const runMerge = async () => {
    if (!mergePreview || !mergePreview.length) return;
    setMergeStatus("Merging…");
    var removeIds = new Set();
    var newBookings = [];
    mergePreview.forEach(function(pair) {
      var b1 = pair.b1, b2 = pair.b2, s1 = pair.s1, s2 = pair.s2;
      var merged = Object.assign({}, b1, {
        guestName: b1.guestName || b2.guestName,
        value: (Number(b1.value)||0) + (Number(b2.value)||0),
        propertyIds: [s1.propertyId, s2.propertyId],
        stays: [
          Object.assign({}, s1, { value:0 }),
          Object.assign({}, s2, { value:0 }),
        ],
      });
      // Payments are per booking, not per property — merging two previously
      // separate single-property bookings must not leave two Deposit/Balance
      // pairs. Consolidate down to one Deposit + one Balance covering the
      // combined total.
      var combinedSched = consolidateSchedule((b1.schedule||[]).concat(b2.schedule||[]));
      if (combinedSched.length) merged.schedule = combinedSched;
      newBookings.push(merged);
      removeIds.add(b1.id); removeIds.add(b2.id);
    });
    var updated = (bookings||[]).filter(function(b){ return !removeIds.has(b.id); }).concat(newBookings);
    await saveBookings(updated);
    setMergeStatus("Merged " + mergePreview.length + " pair" + (mergePreview.length===1?"":"s") + " — " + newBookings.length + " multi-property booking" + (newBookings.length===1?"":"s") + " created.");
    setMergePreview(null);
  };

  return (
    <div style={{ maxWidth:620, display:"flex", flexDirection:"column", gap:18 }}>
      <div style={{ border:`1px solid ${T.border}`, borderRadius:10, padding:"20px 22px", background:"#fff" }}>
        <div style={{ fontSize:15, fontWeight:700, color:T.text, marginBottom:6 }}>Import from Bookalet</div>
        <div style={{ fontSize:13, color:T.textMid, lineHeight:1.55, marginBottom:16 }}>
          Load the one-off seed file (guests + bookings exported from Bookalet). This overwrites the Lettings data in Supabase, so it is safe to re-run. Running read-only alongside Bookalet — nothing is sent to Airbnb or Stripe.
        </div>
        <input type="file" accept="application/json,.json" onChange={handleFile}
          style={{ fontSize:13, color:T.textMid }} />
        {status && <div style={{ marginTop:14, fontSize:13, fontWeight:600, color: status.startsWith("Import failed") ? T.red : T.green }}>{status}</div>}
      </div>

      {/* Multi-property merge tool */}
      <div style={{ border:`1px solid ${T.border}`, borderRadius:10, padding:"20px 22px", background:"#fff" }}>
        <div style={{ fontSize:15, fontWeight:700, color:T.text, marginBottom:4 }}>Merge Split Bookings</div>
        <div style={{ fontSize:13, color:T.textMid, lineHeight:1.55, marginBottom:14 }}>
          Finds pairs of single-property bookings with the same guest name and close dates — these should be one multi-property booking. Preview first before committing.
        </div>
        {!mergePreview && (
          <button onClick={previewMerge} style={{ background:"#fff", border:`1.5px solid ${T.border}`, color:T.text, fontFamily:"inherit", fontSize:13, fontWeight:600, padding:"9px 18px", borderRadius:8, cursor:"pointer" }}>Preview pairs</button>
        )}
        {mergePreview && mergePreview.length===0 && (
          <div style={{ fontSize:13, color:T.green, fontWeight:600 }}>No mergeable pairs found — all bookings look correct.</div>
        )}
        {mergePreview && mergePreview.length>0 && (
          <div>
            <div style={{ fontSize:13, fontWeight:600, color:T.text, marginBottom:10 }}>Found {mergePreview.length} pair{mergePreview.length===1?"":"s"} to merge:</div>
            {mergePreview.map(function(pair, i) {
              var b1=pair.b1, b2=pair.b2, s1=pair.s1, s2=pair.s2;
              return (
                <div key={i} style={{ background:T.bgInput, border:`1px solid ${T.border}`, borderRadius:7, padding:"10px 14px", marginBottom:8, fontSize:12, color:T.textMid }}>
                  <div style={{ fontWeight:700, color:T.text, marginBottom:4 }}>{b1.guestName || "(no name)"}</div>
                  <div style={{ display:"flex", gap:12, flexWrap:"wrap" }}>
                    <span style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:5, padding:"3px 8px" }}>
                      {s1.propertyId} · {fmtDate(s1.checkIn)}–{fmtDate(s1.checkOut)} · {fmtMoney(Number(b1.value)||0)}
                    </span>
                    <span style={{ color:T.textLight, alignSelf:"center" }}>+</span>
                    <span style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:5, padding:"3px 8px" }}>
                      {s2.propertyId} · {fmtDate(s2.checkIn)}–{fmtDate(s2.checkOut)} · {fmtMoney(Number(b2.value)||0)}
                    </span>
                    <span style={{ color:T.green, fontWeight:700, alignSelf:"center" }}>= {fmtMoney((Number(b1.value)||0)+(Number(b2.value)||0))}</span>
                  </div>
                </div>
              );
            })}
            <div style={{ display:"flex", gap:10, marginTop:14 }}>
              <button onClick={runMerge} style={{ background:T.accent, color:"#fff", border:"none", fontFamily:"inherit", fontSize:13, fontWeight:700, padding:"9px 20px", borderRadius:8, cursor:"pointer" }}>Merge {mergePreview.length} pair{mergePreview.length===1?"":"s"}</button>
              <button onClick={()=>setMergePreview(null)} style={{ background:"#fff", border:`1.5px solid ${T.border}`, color:T.textMid, fontFamily:"inherit", fontSize:13, fontWeight:600, padding:"9px 16px", borderRadius:8, cursor:"pointer" }}>Cancel</button>
            </div>
          </div>
        )}
        {mergeStatus && <div style={{ marginTop:12, fontSize:13, fontWeight:600, color:T.green }}>{mergeStatus}</div>}
      </div>
    </div>
  );
}

// ── Lettings Revenue Report ───────────────────────────────────────────────────
function AccomReport({ properties, bookings }) {
  const allYears = [...new Set(
    bookings.flatMap(b => {
      const stays = (b.stays && b.stays.length) ? b.stays : [b];
      return stays.map(s => s.checkIn ? s.checkIn.slice(0,4) : null).filter(Boolean);
    })
  )].sort();
  const currentYear = new Date().getFullYear().toString();
  const [year, setYear] = useState(allYears.includes(currentYear) ? currentYear : (allYears[allYears.length-1]||currentYear));

  const propName = (id) => (properties.find(p=>p.id===id)||{}).name || id;

  // Filter to bookings with at least one stay in the selected year, not cancelled
  const yearBookings = bookings.filter(b => {
    if (b.status==="cancelled") return false;
    const stays = (b.stays && b.stays.length) ? b.stays : [b];
    return stays.some(s => s.checkIn && s.checkIn.startsWith(year));
  });

  // Value each booking once, using the recorded figure where there is one and
  // a calendar-based estimate for Airbnb bookings that have none.
  const valued = yearBookings.map(function(b) {
    const v = lettingValue(b, properties);
    return { b: b, value: v.value, estimated: v.estimated };
  }).filter(function(r) { return r.value > 0; });

  // Buckets are mutually exclusive — a wedding-linked booking used to land in
  // both "direct" and "wedding", which inflated the year total by its whole
  // value a second time.
  const bucketOf = function(b) {
    return b.source === "airbnb" ? "airbnb" : b.bookingType === "Wedding" ? "wedding" : "direct";
  };
  const direct    = valued.filter(function(r) { return bucketOf(r.b) === "direct"; });
  const airbnbEst = valued.filter(function(r) { return bucketOf(r.b) === "airbnb"; });
  const wedding   = valued.filter(function(r) { return bucketOf(r.b) === "wedding"; });

  const sumVal = (arr) => arr.reduce((s, r) => s + (Number(r.value) || 0), 0);
  const estCount = valued.filter(function(r) { return r.estimated; }).length;

  // Revenue by property (across all sources)
  const byProp = {};
  properties.forEach(p => { byProp[p.id] = { direct:0, airbnb:0, wedding:0, total:0 }; });
  valued.forEach(r => {
    const b = r.b;
    const stays = (b.stays && b.stays.length) ? b.stays : [b];
    // Distribute value equally across stays of this booking (simple split)
    const perStay = r.value / stays.length;
    stays.forEach(s => {
      if (!s.checkIn || !s.checkIn.startsWith(year)) return;
      if (!byProp[s.propertyId]) byProp[s.propertyId] = { direct:0, airbnb:0, wedding:0, total:0 };
      const bucket = bucketOf(b);
      byProp[s.propertyId][bucket] = (byProp[s.propertyId][bucket]||0) + perStay;
      byProp[s.propertyId].total   = (byProp[s.propertyId].total||0)   + perStay;
    });
  });

  const totalAll = sumVal(direct) + sumVal(airbnbEst) + sumVal(wedding);

  const prevYear = allYears[allYears.indexOf(year)-1];
  const nextYear = allYears[allYears.indexOf(year)+1];

  const srcRow = (label, arr, colour) => {
    const val = sumVal(arr);
    return (
      <div key={label} style={{ display:"flex", alignItems:"center", gap:12, marginBottom:10 }}>
        <span style={{ width:160, color:T.textMid, fontSize:13 }}>{label}</span>
        <div style={{ flex:1, background:"#f0f6ff", borderRadius:4, height:24, overflow:"hidden" }}>
          <div style={{ width:totalAll>0?`${Math.min(100,(val/totalAll)*100)}%`:"0%", minWidth:val>0?40:0, height:"100%",
            background:colour, borderRadius:4, display:"flex", alignItems:"center", paddingLeft:8 }}>
            {val>0 && <span style={{ color:"#fff", fontSize:11, fontWeight:700 }}>{fmtMoney(val)}</span>}
          </div>
        </div>
        <span style={{ fontSize:13, fontWeight:600, color:T.text, minWidth:80, textAlign:"right" }}>{fmtMoney(val)}</span>
        <span style={{ fontSize:12, color:T.textLight, minWidth:40, textAlign:"right" }}>{arr.length} bkg{arr.length===1?"":"s"}</span>
      </div>
    );
  };

  return (
    <div>
      {/* Year navigator */}
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:22 }}>
        <button onClick={()=>setYear(prevYear)} disabled={!prevYear} style={{ ...navBtn, opacity:prevYear?1:.4 }}>&#8249;</button>
        <div style={{ display:"flex", gap:6 }}>
          {allYears.map(y=>(
            <button key={y} onClick={()=>setYear(y)} style={{ background:y===year?T.midBlue:"#fff", color:y===year?"#fff":T.textMid, border:`1.5px solid ${y===year?T.midBlue:T.border}`, padding:"6px 16px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:y===year?700:400 }}>{y}</button>
          ))}
        </div>
        <button onClick={()=>setYear(nextYear)} disabled={!nextYear} style={{ ...navBtn, opacity:nextYear?1:.4 }}>&#8250;</button>
      </div>

      {/* Summary cards */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:14, marginBottom:24 }}>
        <StatCard label="Direct lettings" value={fmtMoney(sumVal(direct))} sub={`${direct.length} booking${direct.length===1?"":"s"}`}/>
        <StatCard label="Airbnb lettings" value={fmtMoney(sumVal(airbnbEst))}
          sub={`${airbnbEst.length} booking${airbnbEst.length===1?"":"s"}` + (estCount ? ` — ${estCount} estimated` : "")}/>
        <StatCard label="Wedding-linked" value={fmtMoney(sumVal(wedding))} sub={`${wedding.length} bookings`}/>
      </div>

      {/* Revenue by source bar chart */}
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"20px 22px", marginBottom:20, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <h3 style={{ margin:"0 0 16px", color:T.midBlue, fontWeight:700, fontSize:15 }}>Revenue by source — {year}</h3>
        {srcRow("Direct lettings", direct, T.accent)}
        {srcRow("Airbnb lettings", airbnbEst, T.amber)}
        {srcRow("Wedding-linked", wedding, T.green)}
        <div style={{ borderTop:`1px solid ${T.border}`, marginTop:12, paddingTop:10, display:"flex", justifyContent:"flex-end", fontSize:14, fontWeight:700, color:T.midBlue }}>
          Total: {fmtMoney(totalAll)}
        </div>
      </div>

      {/* Revenue by property */}
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"20px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <h3 style={{ margin:"0 0 16px", color:T.midBlue, fontWeight:700, fontSize:15 }}>Revenue by property — {year}</h3>
        <div style={{ overflowX:"auto" }}>
          <table style={{ width:"100%", borderCollapse:"collapse", fontSize:13 }}>
            <thead>
              <tr style={{ background:T.bgInput }}>
                {["Property","Direct","Airbnb est.","Wedding","Total"].map(h=>(
                  <th key={h} style={{ padding:"9px 12px", textAlign:"left", color:T.textMid, fontSize:11, letterSpacing:1, textTransform:"uppercase", fontWeight:700 }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {properties.map((p,i) => {
                const d = byProp[p.id] || { direct:0, airbnb:0, wedding:0, total:0 };
                return (
                  <tr key={p.id} style={{ borderTop:`1px solid ${T.border}` }}>
                    <td style={{ padding:"10px 12px", fontWeight:600 }}>
                      <span style={{ display:"inline-block", width:10, height:10, borderRadius:2, background:p.colour, marginRight:6, verticalAlign:"middle" }}/>
                      {p.name}
                    </td>
                    <td style={{ padding:"10px 12px", color:d.direct>0?T.text:T.textLight }}>{d.direct>0?fmtMoney(Math.round(d.direct)):"—"}</td>
                    <td style={{ padding:"10px 12px", color:d.airbnb>0?T.amber:T.textLight }}>{d.airbnb>0?fmtMoney(Math.round(d.airbnb))+" *":"—"}</td>
                    <td style={{ padding:"10px 12px", color:d.wedding>0?T.green:T.textLight }}>{d.wedding>0?fmtMoney(Math.round(d.wedding)):"—"}</td>
                    <td style={{ padding:"10px 12px", fontWeight:700, color:T.midBlue }}>{d.total>0?fmtMoney(Math.round(d.total)):"—"}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
        <div style={{ marginTop:10, fontSize:11, color:T.textLight, lineHeight:1.6 }}>
          * Where an Airbnb booking has no recorded value, it is priced from our own calendar for those dates —
          seasonal rate and long-stay discount included — plus {AIRBNB_UPLIFT_PCT}%, since Airbnb rates are set above
          our direct prices. A value entered by hand always takes precedence over the estimate.
        </div>
      </div>
    </div>
  );
}

// ── Property settings editor ─────────────────────────────────────────────────
// Weekday toggle row — used for allowed check-in / check-out days, at property
// level and as an optional per-season override. Days are stored as an array of
// 0=Mon..6=Sun indices; empty/undefined array means "no restriction, any day".
const DOW_SHORT = ["Mon","Tue","Wed","Thu","Fri","Sat","Sun"];
function DayToggles({ label, hint, value, onChange, compact }) {
  const days = value || [];
  const toggle = (i) => {
    const next = days.includes(i) ? days.filter(d => d !== i) : days.concat([i]).sort();
    onChange(next);
  };
  return (
    <div style={{ display:"flex", flexDirection:"column", gap:compact?3:4 }}>
      {label && <span style={{ fontSize:compact?10:11, color:T.textMid, fontWeight:600 }}>{label}</span>}
      <div style={{ display:"flex", gap:4 }}>
        {DOW_SHORT.map((d,i) => {
          const on = days.includes(i);
          return (
            <button key={i} type="button" onClick={()=>toggle(i)}
              title={d}
              style={{ width:compact?24:28, height:compact?24:28, borderRadius:6, border:`1.5px solid ${on?T.accent:T.border}`,
                background: on ? T.accent : "#fff", color: on ? "#fff" : T.textMid, fontSize:compact?10:11, fontWeight:700,
                cursor:"pointer", fontFamily:"inherit", padding:0 }}>
              {d[0]}
            </button>
          );
        })}
      </div>
      {hint && <span style={{ fontSize:10, color:T.textLight }}>{days.length ? hint : "No restriction — any day allowed"}</span>}
    </div>
  );
}

function PropertyEditor({ properties, setProperties, onSave }) {
  const [openId, setOpenId] = useState(null);
  const [flash,  setFlash]  = useState("");

  const updProp = (pid, key, val) =>
    setProperties(ps => ps.map(p => p.id === pid ? Object.assign({}, p, { [key]: val }) : p));

  const addSeason = (pid) =>
    setProperties(ps => ps.map(p =>
      p.id !== pid ? p : Object.assign({}, p, {
        seasons: p.seasons.concat([{ label:"", startDate:"", endDate:"", ratePerNight:0 }])
      })
    ));

  const updSeason = (pid, si, key, val) =>
    setProperties(ps => ps.map(p =>
      p.id !== pid ? p : Object.assign({}, p, {
        seasons: p.seasons.map((s, idx) => idx === si ? Object.assign({}, s, { [key]: val }) : s)
      })
    ));

  // Reorder: index 0 is the highest priority, so "up" means "wins over more".
  const moveSeason = (pid, si, dir) =>
    setProperties(ps => ps.map(p => {
      if (p.id !== pid) return p;
      const list = (p.seasons || []).slice();
      const to = si + dir;
      if (to < 0 || to >= list.length) return p;
      const moved = list[si];
      list[si] = list[to];
      list[to] = moved;
      return Object.assign({}, p, { seasons: list });
    }));

  const rmSeason = (pid, si) =>
    setProperties(ps => ps.map(p =>
      p.id !== pid ? p : Object.assign({}, p, {
        seasons: p.seasons.filter((_, idx) => idx !== si)
      })
    ));

  const handleSave = async () => {
    await onSave();
    setFlash("Saved");
    setTimeout(() => setFlash(""), 2500);
  };

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:18 }}>
        <div>
          <div style={{ fontSize:15, fontWeight:700, color:T.text }}>Property settings</div>
          <div style={{ fontSize:12, color:T.textMid, marginTop:2 }}>Pricing, seasons, booking rules — used by the public booking page</div>
        </div>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          {flash && <span style={{ fontSize:12, color:T.green, fontWeight:600 }}>{flash}</span>}
          <button onClick={handleSave} style={{ background:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>Save all</button>
        </div>
      </div>

      {properties.map(p => {
        const open = openId === p.id;
        return (
          <div key={p.id} style={{ border:`1px solid ${T.border}`, borderRadius:10, marginBottom:12, overflow:"hidden", boxShadow:"0 2px 6px rgba(37,99,235,.05)" }}>
            <div onClick={() => setOpenId(open ? null : p.id)}
              style={{ display:"flex", alignItems:"center", gap:10, padding:"13px 16px", background:T.bgInput, cursor:"pointer", userSelect:"none" }}>
              <span style={{ width:13, height:13, borderRadius:3, background:p.colour, flexShrink:0 }}/>
              <span style={{ fontSize:14, fontWeight:700, color:T.text }}>{p.name}</span>
              <span style={{ flex:1 }}>
                {p.publicBookable === false && (
                  <span style={{ fontSize:10, fontWeight:700, padding:"2px 8px", borderRadius:9, background:"#fffbeb", color:"#92400e", border:"1px solid #fde68a" }}>
                    Not on website
                  </span>
                )}
              </span>
              <span style={{ fontSize:12, color:T.textMid }}>
                {p.baseRate ? "Base: " + String(fmtMoney(p.baseRate)) + "/night" : "No base rate"} ·{" "}
                {p.seasons && p.seasons.length ? p.seasons.length + " season" + (p.seasons.length > 1 ? "s" : "") : "No seasons"}
              </span>
              <span style={{ fontSize:11, color:T.textLight, marginLeft:8 }}>{open ? "▲" : "▼"}</span>
            </div>

            {open && (
              <div style={{ padding:"18px 18px 20px" }}>

                {/* ── Public visibility ── */}
                {/* Stored as publicBookable. Properties saved before this
                    setting existed have no flag, and undefined is treated as
                    visible by the booking page, so the default is "shown". */}
                <label style={{ display:"flex", alignItems:"flex-start", gap:9, cursor:"pointer",
                  background: p.publicBookable === false ? "#fffbeb" : T.greenBg,
                  border:`1px solid ${p.publicBookable === false ? "#fde68a" : "#bbf7d0"}`,
                  borderRadius:8, padding:"10px 13px", marginBottom:18 }}>
                  <input type="checkbox" checked={p.publicBookable !== false}
                    onChange={e => updProp(p.id, "publicBookable", e.target.checked)}
                    style={{ width:15, height:15, marginTop:1, accentColor:T.green, cursor:"pointer", flexShrink:0 }}/>
                  <span>
                    <span style={{ fontSize:13, fontWeight:700, color: p.publicBookable === false ? "#92400e" : T.green }}>
                      Bookable on the public website
                    </span>
                    <span style={{ display:"block", fontSize:11, color:T.textMid, marginTop:2, lineHeight:1.6 }}>
                      {p.publicBookable === false
                        ? "Hidden from book-accom — no card, and no availability letter on the calendar. You can still take bookings for it in here."
                        : "Shown on book-accom with its availability letter on the calendar."}
                    </span>
                  </span>
                </label>

                {/* ── Pricing ── */}
                <div style={{ fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.5, marginBottom:10 }}>Pricing</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12, marginBottom:18 }}>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Base rate (£/night)</span>
                    <input type="number" value={p.baseRate || ""} onChange={e => updProp(p.id, "baseRate", Number(e.target.value))} style={inpStyle} placeholder="e.g. 250" min="0" />
                  </label>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Long-stay from (nights)</span>
                    <input type="number" value={p.longStayThreshold || ""} onChange={e => updProp(p.id, "longStayThreshold", Number(e.target.value))} style={inpStyle} placeholder="e.g. 7" min="0" />
                  </label>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Long-stay discount (%)</span>
                    <input type="number" value={p.longStayDiscountPct || ""}
                      onChange={e => updProp(p.id, "longStayDiscountPct", Number(e.target.value))}
                      style={inpStyle} placeholder="e.g. 10" min="0" max="100" step="0.5" />
                  </label>
                </div>
                {/* Setting a percentage retires the old £/night figure. Until
                    then it keeps applying, so pricing doesn't change silently. */}
                {usesLegacyLongStay(p) && (
                  <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:7, padding:"9px 12px",
                    marginTop:-8, marginBottom:18, fontSize:11.5, color:"#92400e", lineHeight:1.6 }}>
                    Still using the old fixed discount of <strong>{String(fmtMoney(p.longStayDiscount))} per night</strong>.
                    Enter a percentage above to replace it — that figure is <em>not</em> being read as {p.longStayDiscount}%.
                    <button onClick={() => updProp(p.id, "longStayDiscount", 0)}
                      style={{ background:"none", border:"1px solid #fdba74", color:"#92400e", borderRadius:5, padding:"3px 9px",
                        marginLeft:8, fontFamily:"inherit", fontSize:11, fontWeight:600, cursor:"pointer" }}>
                      Remove it
                    </button>
                  </div>
                )}
                {p.longStayThreshold > 0 && Number(p.longStayDiscountPct) > 0 && p.baseRate > 0 && (
                  <div style={{ fontSize:11, color:T.textLight, marginTop:-8, marginBottom:18, lineHeight:1.6 }}>
                    A {p.longStayThreshold}-night stay at the base rate would be{" "}
                    {String(fmtMoney(round2(p.baseRate * p.longStayThreshold)))} less{" "}
                    {String(fmtMoney(round2(p.baseRate * p.longStayThreshold * p.longStayDiscountPct / 100)))} ={" "}
                    <strong style={{ color:T.textMid }}>
                      {String(fmtMoney(round2(p.baseRate * p.longStayThreshold * (1 - p.longStayDiscountPct / 100))))}
                    </strong>.
                  </div>
                )}

                {/* ── Seasons ── */}
                <div style={{ fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.5, marginBottom:4 }}>Seasons (override base rate for date ranges)</div>
                {p.seasons && p.seasons.length > 1 && (
                  <div style={{ fontSize:11, color:T.textMid, background:"#f4f8fd", border:`1px solid ${T.border}`,
                    borderRadius:6, padding:"6px 10px", marginBottom:10, lineHeight:1.6 }}>
                    Listed in priority order. Where two seasons cover the same night, <strong>the one nearer the top wins</strong> —
                    so put narrow exceptions (a bank holiday, a wedding weekend) above the broad season they sit inside.
                    Use ▲▼ to reorder.
                  </div>
                )}
                {p.seasons && p.seasons.map((s, si) => {
                  const clashes = (p.seasons || []).filter((o, oi) => oi !== si && seasonsOverlap(s, o));
                  const beaten  = (p.seasons || []).filter((o, oi) => oi < si && seasonsOverlap(s, o));
                  return (
                  <div key={si} style={{ marginBottom:12, paddingBottom:12, borderBottom: si < p.seasons.length-1 ? `1px dashed ${T.border}` : "none" }}>
                    <div style={{ display:"grid", gridTemplateColumns:"auto 2fr 1fr 1fr 1fr auto", gap:8, alignItems:"end" }}>
                      <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:2 }}>
                        {si === 0 && <span style={{ fontSize:10, color:T.textLight, fontWeight:600 }}>Order</span>}
                        <div style={{ display:"flex", alignItems:"center", gap:3, height:36 }}>
                          <span title="Priority — 1 is applied first and beats the rest"
                            style={{ fontSize:11, fontWeight:700, color:T.textLight, width:12, textAlign:"right" }}>{si+1}</span>
                          <div style={{ display:"flex", flexDirection:"column", gap:2 }}>
                            <button onClick={() => moveSeason(p.id, si, -1)} disabled={si === 0} title="Move up — wins over more seasons"
                              style={{ background:"none", border:`1px solid ${T.border}`, borderRadius:4, width:20, height:16, lineHeight:1,
                                fontSize:9, color: si === 0 ? "#cfcabf" : T.textMid, cursor: si === 0 ? "default" : "pointer", padding:0, fontFamily:"inherit" }}>▲</button>
                            <button onClick={() => moveSeason(p.id, si, 1)} disabled={si === p.seasons.length-1} title="Move down — beaten by more seasons"
                              style={{ background:"none", border:`1px solid ${T.border}`, borderRadius:4, width:20, height:16, lineHeight:1,
                                fontSize:9, color: si === p.seasons.length-1 ? "#cfcabf" : T.textMid, cursor: si === p.seasons.length-1 ? "default" : "pointer", padding:0, fontFamily:"inherit" }}>▼</button>
                          </div>
                        </div>
                      </div>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        {si === 0 && <span style={{ fontSize:10, color:T.textLight, fontWeight:600 }}>Label</span>}
                        <input value={s.label || ""} onChange={e => updSeason(p.id, si, "label", e.target.value)} style={inpStyle} placeholder="e.g. Peak summer" />
                      </label>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        {si === 0 && <span style={{ fontSize:10, color:T.textLight, fontWeight:600 }}>From</span>}
                        <input type="date" value={s.startDate || ""} onChange={e => updSeason(p.id, si, "startDate", e.target.value)} style={inpStyle} />
                      </label>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        {si === 0 && <span style={{ fontSize:10, color:T.textLight, fontWeight:600 }}>To (exclusive)</span>}
                        <input type="date" value={s.endDate || ""} onChange={e => updSeason(p.id, si, "endDate", e.target.value)} style={inpStyle} />
                      </label>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        {si === 0 && <span style={{ fontSize:10, color:T.textLight, fontWeight:600 }}>£/night</span>}
                        <input type="number" value={s.ratePerNight || ""} onChange={e => updSeason(p.id, si, "ratePerNight", Number(e.target.value))} style={inpStyle} placeholder="0" min="0" />
                      </label>
                      <button onClick={() => rmSeason(p.id, si)}
                        style={{ background:T.redBg, color:T.red, border:"1px solid #fca5a5", borderRadius:6, padding:"0 12px", cursor:"pointer", fontFamily:"inherit", fontSize:12, height:36, alignSelf:"end" }}>
                        Remove
                      </button>
                    </div>
                    {clashes.length > 0 && (
                      <div style={{ fontSize:11, marginTop:6, paddingLeft:2, lineHeight:1.6,
                        color: beaten.length ? "#92400e" : T.textLight }}>
                        {beaten.length
                          ? "Overlaps " + beaten.map(o => "“" + (o.label || "unnamed") + "”").join(", ") + " above it — those rates win on the shared nights."
                          : "Overlaps " + clashes.map(o => "“" + (o.label || "unnamed") + "”").join(", ") + " below it — this rate wins on the shared nights."}
                      </div>
                    )}
                    <div style={{ display:"flex", gap:24, marginTop:8, paddingLeft:2, flexWrap:"wrap", alignItems:"flex-start" }}>
                      <DayToggles compact label="Check-in days override" value={s.checkInDays}
                        onChange={(v)=>updSeason(p.id, si, "checkInDays", v)} />
                      <DayToggles compact label="Check-out days override" value={s.checkOutDays}
                        onChange={(v)=>updSeason(p.id, si, "checkOutDays", v)} />
                      {/* Blank means "use the property's own rule" — 0 is not a
                          valid stay length, so an empty box can safely mean
                          inherit rather than needing a separate flag. */}
                      <div style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        <span style={{ fontSize:10, color:T.textLight, fontWeight:600 }}>Nights override</span>
                        <div style={{ display:"flex", gap:6, alignItems:"center" }}>
                          <input type="number" min="1" value={s.minNights || ""}
                            onChange={e => updSeason(p.id, si, "minNights", e.target.value === "" ? "" : Number(e.target.value))}
                            placeholder={"min " + (p.minNights || 2)}
                            style={Object.assign({}, inpStyle, { width:78, padding:"5px 7px", fontSize:12 })} />
                          <span style={{ fontSize:11, color:T.textLight }}>to</span>
                          <input type="number" min="1" value={s.maxNights || ""}
                            onChange={e => updSeason(p.id, si, "maxNights", e.target.value === "" ? "" : Number(e.target.value))}
                            placeholder={"max " + (p.maxNights || 28)}
                            style={Object.assign({}, inpStyle, { width:78, padding:"5px 7px", fontSize:12 })} />
                        </div>
                        <span style={{ fontSize:10, color:T.textLight }}>Blank = use the property default</span>
                      </div>
                    </div>
                  </div>
                  );
                })}
                <button onClick={() => addSeason(p.id)}
                  style={{ background:"none", border:`1.5px dashed ${T.border}`, color:T.accent, borderRadius:7, padding:"6px 16px", cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600, marginBottom:20 }}>
                  + Add season
                </button>

                {/* ── Booking rules ── */}
                <div style={{ fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.5, marginBottom:10 }}>Booking rules</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12, marginBottom:16 }}>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Min nights</span>
                    <input type="number" value={p.minNights || ""} onChange={e => updProp(p.id, "minNights", Number(e.target.value))} style={inpStyle} min="1" />
                  </label>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Max nights</span>
                    <input type="number" value={p.maxNights || ""} onChange={e => updProp(p.id, "maxNights", Number(e.target.value))} style={inpStyle} min="1" />
                  </label>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Booking window (months ahead)</span>
                    <input type="number" value={p.bookingHorizonMonths || ""} onChange={e => updProp(p.id, "bookingHorizonMonths", Number(e.target.value))} style={inpStyle} placeholder="e.g. 6 — blank = no limit" min="0" />
                  </label>
                </div>

                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:20, marginBottom:18, padding:"12px 14px", background:T.bgInput, borderRadius:8, border:`1px solid ${T.border}` }}>
                  <DayToggles label="Allowed check-in days" hint="Only these days can be selected as an arrival day on the public calendar"
                    value={p.checkInDays} onChange={(v)=>updProp(p.id, "checkInDays", v)} />
                  <DayToggles label="Allowed check-out days" hint="Stay lengths that would land checkout on another day are hidden"
                    value={p.checkOutDays} onChange={(v)=>updProp(p.id, "checkOutDays", v)} />
                </div>

                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:12, marginBottom:6 }}>
                  <div style={{ background:T.accentLight, borderRadius:8, padding:"10px 14px" }}>
                    <div style={{ fontSize:10, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4, marginBottom:8 }}>General bookings</div>
                    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Check-in from</span>
                        <input value={p.checkInFrom || ""} onChange={e => updProp(p.id, "checkInFrom", e.target.value)} style={inpStyle} placeholder="16:00" />
                      </label>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Check-out by</span>
                        <input value={p.checkOutBy || ""} onChange={e => updProp(p.id, "checkOutBy", e.target.value)} style={inpStyle} placeholder="10:00" />
                      </label>
                    </div>
                  </div>
                  <div style={{ background:"#fef3c7", borderRadius:8, padding:"10px 14px" }}>
                    <div style={{ fontSize:10, fontWeight:700, color:"#92400e", textTransform:"uppercase", letterSpacing:.4, marginBottom:8 }}>Weekend weddings</div>
                    <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:8 }}>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Check-in from</span>
                        <input value={p.checkInFromWedding || ""} onChange={e => updProp(p.id, "checkInFromWedding", e.target.value)} style={inpStyle} placeholder="15:00" />
                      </label>
                      <label style={{ display:"flex", flexDirection:"column", gap:3 }}>
                        <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Check-out by</span>
                        <input value={p.checkOutByWedding || ""} onChange={e => updProp(p.id, "checkOutByWedding", e.target.value)} style={inpStyle} placeholder="11:00" />
                      </label>
                    </div>
                  </div>
                </div>
                <div style={{ fontSize:11, color:T.textLight, marginBottom:18 }}>{"Email tokens {{checkInTime}} and {{checkOutTime}} resolve to these times based on booking type."}</div>

                {/* ── Payment ── */}
                <div style={{ fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.5, marginBottom:10 }}>Payment</div>
                <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr 1fr", gap:12 }}>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Deposit %</span>
                    <input type="number" value={p.depositPct || ""} onChange={e => updProp(p.id, "depositPct", Number(e.target.value))} style={inpStyle} min="0" max="100" />
                  </label>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Balance due (weeks before check-in)</span>
                    <input type="number" value={p.balanceWeeks || ""} onChange={e => updProp(p.id, "balanceWeeks", Number(e.target.value))} style={inpStyle} min="0" />
                  </label>
                  <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
                    <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Breakage deposit (£)</span>
                    <input type="number" value={p.breakageDefault || ""} onChange={e => updProp(p.id, "breakageDefault", Number(e.target.value))} style={inpStyle} min="0" />
                  </label>
                </div>

              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ── Discount codes editor ────────────────────────────────────────────────────
function DiscountCodesEditor({ codes, setCodes, onSave }) {
  const [flash, setFlash] = useState("");
  const [newCode, setNewCode] = useState({ code:"", type:"pct", value:"", description:"", expiresAt:"" });

  const updNew = (k, v) => setNewCode(c => Object.assign({}, c, { [k]: v }));

  const addCode = () => {
    if (!newCode.code.trim() || !newCode.value) return;
    const rec = {
      id:          "dc-" + Date.now(),
      code:        newCode.code.trim().toUpperCase(),
      type:        newCode.type,
      value:       Number(newCode.value),
      description: newCode.description.trim(),
      active:      true,
      expiresAt:   newCode.expiresAt || null,
    };
    setCodes(cs => cs.concat([rec]));
    setNewCode({ code:"", type:"pct", value:"", description:"", expiresAt:"" });
  };

  const toggleActive = (id) =>
    setCodes(cs => cs.map(c => c.id === id ? Object.assign({}, c, { active: !c.active }) : c));

  const removeCode = (id) => setCodes(cs => cs.filter(c => c.id !== id));

  const handleSave = async () => {
    await onSave();
    setFlash("Saved");
    setTimeout(() => setFlash(""), 2000);
  };

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:16 }}>
        <div>
          <div style={{ fontSize:15, fontWeight:700, color:T.text }}>Discount codes</div>
          <div style={{ fontSize:12, color:T.textMid, marginTop:2 }}>Applied at booking — fixed £ off or percentage off the total</div>
        </div>
        <div style={{ display:"flex", gap:10, alignItems:"center" }}>
          {flash && <span style={{ fontSize:12, color:T.green, fontWeight:600 }}>{flash}</span>}
          <button onClick={handleSave} style={{ background:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>Save</button>
        </div>
      </div>

      {/* Existing codes */}
      {codes.length > 0 && (
        <div style={{ border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", background:"#fff", marginBottom:18 }}>
          <div style={{ display:"grid", gridTemplateColumns:"1.2fr 0.8fr 0.8fr 1.5fr 1fr 0.7fr 0.6fr", background:T.bgInput, borderBottom:`1px solid ${T.border}`, fontSize:11, fontWeight:700, color:T.textMid }}>
            {["Code","Type","Value","Description","Expires","Active",""].map(h => (
              <div key={h} style={{ padding:"9px 12px" }}>{h}</div>
            ))}
          </div>
          {codes.map(c => (
            <div key={c.id} style={{ display:"grid", gridTemplateColumns:"1.2fr 0.8fr 0.8fr 1.5fr 1fr 0.7fr 0.6fr", borderBottom:`1px solid #eef3fa`, fontSize:13, color:T.text, alignItems:"center", opacity: c.active ? 1 : .55 }}>
              <div style={{ padding:"10px 12px", fontWeight:700, letterSpacing:.5, color:T.midBlue }}>{c.code}</div>
              <div style={{ padding:"10px 12px" }}>{c.type === "pct" ? "% off" : "£ off"}</div>
              <div style={{ padding:"10px 12px" }}>{c.type === "pct" ? c.value + "%" : fmtMoney(c.value)}</div>
              <div style={{ padding:"10px 12px", fontSize:12, color:T.textMid }}>{c.description || "—"}</div>
              <div style={{ padding:"10px 12px", fontSize:12 }}>{c.expiresAt ? fmtDate(c.expiresAt) : "No expiry"}</div>
              <div style={{ padding:"10px 12px" }}>
                <button onClick={() => toggleActive(c.id)}
                  style={{ fontSize:11, fontWeight:700, padding:"3px 10px", borderRadius:8, border:"none", cursor:"pointer", fontFamily:"inherit",
                    background: c.active ? T.greenBg : T.redBg, color: c.active ? T.green : T.red }}>
                  {c.active ? "Active" : "Off"}
                </button>
              </div>
              <div style={{ padding:"10px 12px" }}>
                <button onClick={() => removeCode(c.id)}
                  style={{ fontSize:11, color:T.red, background:T.redBg, border:"none", borderRadius:6, padding:"3px 10px", cursor:"pointer", fontFamily:"inherit" }}>
                  Delete
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Add new code */}
      <div style={{ border:`1px solid ${T.border}`, borderRadius:10, padding:"16px 18px", background:"#fff" }}>
        <div style={{ fontSize:12, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4, marginBottom:12 }}>Add new code</div>
        <div style={{ display:"grid", gridTemplateColumns:"1fr 0.7fr 0.7fr 1.5fr 1fr auto", gap:10, alignItems:"end" }}>
          <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
            <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Code</span>
            <input value={newCode.code} onChange={e => updNew("code", e.target.value.toUpperCase())}
              style={inpStyle} placeholder="e.g. SUMMER10" />
          </label>
          <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
            <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Type</span>
            <select value={newCode.type} onChange={e => updNew("type", e.target.value)} style={{ ...inpStyle }}>
              <option value="pct">% off</option>
              <option value="fixed">£ off</option>
            </select>
          </label>
          <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
            <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>{newCode.type === "pct" ? "%" : "£"} value</span>
            <input type="number" value={newCode.value} onChange={e => updNew("value", e.target.value)}
              style={inpStyle} placeholder={newCode.type === "pct" ? "10" : "50"} min="0" />
          </label>
          <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
            <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Description (optional)</span>
            <input value={newCode.description} onChange={e => updNew("description", e.target.value)}
              style={inpStyle} placeholder="e.g. Summer 2026 discount" />
          </label>
          <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
            <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Expires (optional)</span>
            <input type="date" value={newCode.expiresAt} onChange={e => updNew("expiresAt", e.target.value)}
              style={inpStyle} />
          </label>
          <button onClick={addCode}
            style={{ background:T.accent, color:"#fff", border:"none", borderRadius:8, padding:"9px 18px", cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700, height:38, alignSelf:"end" }}>
            Add
          </button>
        </div>
      </div>
    </div>
  );
}

// ── iCal / Airbnb sync settings ───────────────────────────────────────────────
function ICalSettings({ properties, setProperties, onSave }) {
  const [syncState, setSyncState] = useState({});
  const [flash, setFlash] = useState("");

  const updProp = (pid, key, val) =>
    setProperties(ps => ps.map(p => p.id === pid ? Object.assign({}, p, { [key]: val }) : p));

  const handleSave = async () => {
    await onSave();
    setFlash("Saved");
    setTimeout(() => setFlash(""), 2000);
  };

  const syncNow = async (pid) => {
    setSyncState(s => Object.assign({}, s, { [pid]: { loading: true, result: null } }));
    try {
      const res = await fetch("/.netlify/functions/sync-property-ical", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ propertyId: pid })
      });
      const data = await res.json();
      if (data.error) {
        setSyncState(s => Object.assign({}, s, { [pid]: { loading: false, result: "Error: " + data.error } }));
      } else {
        const msg = "Synced — " + data.imported + " new block" + (data.imported === 1 ? "" : "s") + " from " + data.total + " in feed";
        setSyncState(s => Object.assign({}, s, { [pid]: { loading: false, result: msg } }));
        // Update lastSyncedAt in local property state
        setProperties(ps => ps.map(p => p.id === pid ? Object.assign({}, p, { lastSyncedAt: new Date().toISOString() }) : p));
      }
    } catch (e) {
      setSyncState(s => Object.assign({}, s, { [pid]: { loading: false, result: "Network error — check console" } }));
    }
  };

  const copyUrl = (url) => {
    if (navigator.clipboard) navigator.clipboard.writeText(url);
  };

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"center", marginBottom:6 }}>
        <div>
          <div style={{ fontSize:15, fontWeight:700, color:T.text }}>Airbnb / iCal sync</div>
          <div style={{ fontSize:12, color:T.textMid, marginTop:2 }}>Export your availability to Airbnb; import Airbnb blocks back in</div>
        </div>
        <div style={{ display:"flex", gap:10, alignItems:"center" }}>
          {flash && <span style={{ fontSize:12, color:T.green, fontWeight:600 }}>{flash}</span>}
          <button onClick={handleSave} style={{ background:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>Save URLs</button>
        </div>
      </div>
      <div style={{ fontSize:12, color:T.textMid, background:T.accentLight, borderRadius:8, padding:"10px 14px", marginBottom:20, lineHeight:1.6 }}>
        <strong>Setup:</strong> For each property, (1) copy the Export URL and paste it into Airbnb as your availability calendar URL,
        then (2) paste Airbnb's iCal import URL here and click Sync. Airbnb's URL is found in your Airbnb listing under Calendar settings.
      </div>

      {properties.map(p => {
        // Airbnb validates that the URL looks like a calendar file, so the
        // tidy /ical/<id>.ics form is what's offered rather than the raw
        // function path. Both work; only this one is accepted by Airbnb.
        const exportUrl = SITE_URL + "/ical/" + p.id + ".ics";
        const ss = syncState[p.id] || {};
        return (
          <div key={p.id} style={{ border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 20px", marginBottom:14, background:"#fff", boxShadow:"0 2px 6px rgba(37,99,235,.04)" }}>
            <div style={{ display:"flex", alignItems:"center", gap:10, marginBottom:16 }}>
              <span style={{ width:13, height:13, borderRadius:3, background:p.colour, flexShrink:0 }}/>
              <span style={{ fontSize:14, fontWeight:700, color:T.text }}>{p.name}</span>
              {p.lastSyncedAt && (
                <span style={{ fontSize:11, color:T.textLight, marginLeft:"auto" }}>
                  Last synced: {new Date(p.lastSyncedAt).toLocaleString("en-GB", { day:"numeric", month:"short", hour:"2-digit", minute:"2-digit" })}
                </span>
              )}
            </div>

            <div style={{ marginBottom:14 }}>
              <div style={{ fontSize:11, fontWeight:600, color:T.textMid, marginBottom:6, textTransform:"uppercase", letterSpacing:.4 }}>
                1. Export URL — paste this into Airbnb
              </div>
              <div style={{ display:"flex", gap:8, alignItems:"center" }}>
                <input readOnly value={exportUrl} style={{ ...inpStyle, flex:1, fontSize:11, background:"#f7f9fc", color:T.textMid }} />
                <button onClick={() => copyUrl(exportUrl)}
                  style={{ background:T.accentLight, color:T.accent, border:`1.5px solid ${T.accent}30`, borderRadius:7, padding:"8px 16px", cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:700, whiteSpace:"nowrap" }}>
                  Copy
                </button>
              </div>
              <div style={{ fontSize:11, color:T.textLight, marginTop:5, lineHeight:1.6 }}>
                Dates only — every booking reads "Booked". This URL is public and guessable, so it carries no guest names;
                Airbnb ignores the labels in any case. For the full picture with names, subscribe to the calendar feed in Settings.
              </div>
            </div>

            <div style={{ marginBottom:10 }}>
              <div style={{ fontSize:11, fontWeight:600, color:T.textMid, marginBottom:6, textTransform:"uppercase", letterSpacing:.4 }}>
                2. Import URL — from Airbnb
              </div>
              <div style={{ display:"flex", gap:8, alignItems:"center" }}>
                <input value={p.airbnbImportUrl || ""}
                  onChange={e => updProp(p.id, "airbnbImportUrl", e.target.value)}
                  style={{ ...inpStyle, flex:1, fontSize:12 }}
                  placeholder="https://www.airbnb.co.uk/calendar/ical/..." />
                <button onClick={() => syncNow(p.id)} disabled={!p.airbnbImportUrl || ss.loading}
                  style={{ background: ss.loading ? T.bgInput : T.green, color: ss.loading ? T.textLight : "#fff", border:"none", borderRadius:7, padding:"8px 16px", cursor: p.airbnbImportUrl && !ss.loading ? "pointer" : "not-allowed", fontFamily:"inherit", fontSize:12, fontWeight:700, whiteSpace:"nowrap" }}>
                  {ss.loading ? "Syncing…" : "Sync now"}
                </button>
              </div>
              {ss.result && (
                <div style={{ marginTop:6, fontSize:12, color: ss.result.startsWith("Error") ? T.red : T.green, fontWeight:600 }}>
                  {ss.result}
                </div>
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ── Email Templates Editor ────────────────────────────────────────────────────
// ─── TERMS & CONDITIONS ───────────────────────────────────────────────────────
// Held as one block of text in Supabase and published at /terms.html, so it is
// edited in exactly one place. Emails and the booking flow link to that page
// rather than carrying the wording, which keeps them short and means a change
// applies to everything already sent as well as everything to come.
const TERMS_STORAGE = "hbf_terms_v1";
const TERMS_URL = SITE_URL + "/terms.html";

function TermsEditor() {
  const [text, setText] = useState(null);
  const [updatedAt, setUpdatedAt] = useState(null);
  const [saving, setSaving] = useState(false);
  const [flash, setFlash] = useState("");

  useEffect(function() {
    let cancelled = false;
    (async function() {
      try {
        const t = await sbGet(TERMS_STORAGE);
        if (cancelled) return;
        setText((t && t.text) || "");
        setUpdatedAt((t && t.updatedAt) || null);
      } catch (e) { if (!cancelled) setText(""); }
    })();
    return function() { cancelled = true; };
  }, []);

  if (text === null) return <div style={{ fontSize:13, color:T.textLight }}>Loading…</div>;

  const save = async function() {
    setSaving(true);
    try {
      const stamp = new Date().toISOString();
      await sbSet(TERMS_STORAGE, { text: text, updatedAt: stamp });
      setUpdatedAt(stamp);
      setFlash("Saved — live on the website immediately");
      setTimeout(function(){ setFlash(""); }, 3000);
    } catch (e) {
      setFlash("Save failed: " + (e.message || e));
      setTimeout(function(){ setFlash(""); }, 4000);
    }
    setSaving(false);
  };

  const written = !!String(text).trim();

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", gap:12, marginBottom:6, flexWrap:"wrap" }}>
        <div>
          <div style={{ fontSize:15, fontWeight:700, color:T.text }}>Terms &amp; Conditions</div>
          <div style={{ fontSize:12, color:T.textMid, marginTop:2 }}>
            Published at <a href={TERMS_URL} target="_blank" rel="noreferrer" style={{ color:T.accent }}>{TERMS_URL}</a> and linked from every email and the booking page
          </div>
        </div>
        <div style={{ display:"flex", alignItems:"center", gap:10 }}>
          {flash && <span style={{ fontSize:12, color:T.green, fontWeight:600 }}>{flash}</span>}
          <button onClick={save} disabled={saving}
            style={{ background:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:8,
              cursor: saving ? "default" : "pointer", fontFamily:"inherit", fontSize:13, fontWeight:700, opacity: saving ? .6 : 1 }}>
            {saving ? "Saving…" : "Save terms"}
          </button>
        </div>
      </div>
      {!written && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:7, padding:"9px 12px",
          margin:"8px 0 10px", fontSize:12, color:"#92400e", lineHeight:1.6 }}>
          Nothing written yet, so no T&amp;C link appears in emails or at checkout. Paste your terms below and save to turn it on everywhere.
        </div>
      )}
      <textarea value={text} onChange={function(e){ setText(e.target.value); }} rows={22}
        placeholder={"Paste your terms and conditions here.\n\nLeave a blank line between paragraphs. A line on its own that ends without a full stop is treated as a heading."}
        style={{ width:"100%", background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:8, color:T.text,
          fontFamily:"inherit", fontSize:13, lineHeight:1.7, padding:"12px 14px", outline:"none", resize:"vertical" }}/>
      <div style={{ fontSize:11, color:T.textLight, marginTop:6 }}>
        {updatedAt ? "Last updated " + new Date(updatedAt).toLocaleString("en-GB", { day:"numeric", month:"long", year:"numeric", hour:"2-digit", minute:"2-digit" }) : "Not yet saved."}
        {written ? " · " + String(text).trim().split(/\s+/).length + " words" : ""}
      </div>
    </div>
  );
}

function EmailTemplatesEditor({ templates, setTemplates, onSave }) {
  const [sel, setSel] = useState(0);
  const [flash, setFlash] = useState("");
  const [copying, setCopying] = useState(null);
  const fileRef = useRef(null);

  const upd = function(key, val) {
    setTemplates(function(ts) {
      return ts.map(function(t, i) { return i === sel ? Object.assign({}, t, { [key]: val }) : t; });
    });
  };

  const handleSave = async function() {
    await onSave();
    setFlash("Saved");
    setTimeout(function() { setFlash(""); }, 2000);
  };

  const handleFile = function(e) {
    var file = e.target.files[0];
    if (!file) return;
    if (file.size > 2 * 1024 * 1024) {
      alert("File is over 2 MB — please compress it before attaching.");
      e.target.value = "";
      return;
    }
    var reader = new FileReader();
    reader.onload = function(ev) {
      var att = { name: file.name, size: file.size, type: file.type, dataUrl: ev.target.result };
      var curr = templates[sel];
      upd("attachments", (curr.attachments || []).concat([att]));
    };
    reader.readAsDataURL(file);
    e.target.value = "";
  };

  const removeAtt = function(idx) {
    upd("attachments", (templates[sel].attachments || []).filter(function(_, i) { return i !== idx; }));
  };

  const copyToken = function(token, idx) {
    if (navigator.clipboard) navigator.clipboard.writeText(token);
    setCopying(idx);
    setTimeout(function() { setCopying(null); }, 1200);
  };

  var tmpl = templates[sel] || {};
  var TEMPLATE_NAMES = templates.map(function(t) { return t.name; });

  const taStyle = {
    width:"100%", boxSizing:"border-box", fontFamily:"monospace", fontSize:13, lineHeight:1.65,
    border:`1.5px solid ${T.border}`, borderRadius:8, padding:"12px 14px", resize:"vertical",
    color:T.text, background:"#fafbff", minHeight:260, outline:"none"
  };

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:14 }}>
        <div>
          <div style={{ fontSize:15, fontWeight:700, color:T.text }}>Email templates</div>
          <div style={{ fontSize:12, color:T.textMid, marginTop:3 }}>Edit subject and body for each email type. Use tokens (click to copy) where guest/booking details should appear.</div>
        </div>
        <div style={{ display:"flex", gap:10, alignItems:"center", flexShrink:0, marginLeft:16 }}>
          {flash && <span style={{ fontSize:12, color:T.green, fontWeight:600 }}>{flash}</span>}
          <button onClick={handleSave} style={{ background:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>Save templates</button>
        </div>
      </div>

      <div style={{ display:"flex", gap:14 }}>
        {/* Left: template list */}
        <div style={{ width:190, flexShrink:0 }}>
          {TEMPLATE_NAMES.map(function(name, i) {
            return (
              <button key={i} onClick={function() { setSel(i); }}
                style={{ display:"block", width:"100%", textAlign:"left", background: sel===i ? T.accentLight : "transparent",
                  border: `1.5px solid ${sel===i ? T.accent : T.border}`, borderRadius:8, padding:"9px 12px", marginBottom:6,
                  cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight: sel===i ? 700 : 500,
                  color: sel===i ? T.accent : T.text }}>
                {name}
                {templates[i].triggerDays !== null && (
                  <div style={{ fontSize:10, color:T.textLight, marginTop:2, fontWeight:400 }}>{templates[i].triggerLabel}</div>
                )}
              </button>
            );
          })}
        </div>

        {/* Right: editor */}
        <div style={{ flex:1, minWidth:0 }}>
          <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"20px 22px" }}>
            {/* Trigger days row (for timed templates) */}
            {tmpl.triggerDays !== null && (
              <div style={{ display:"flex", flexDirection:"column", gap:8, marginBottom:16, padding:"10px 14px", background:T.accentLight, borderRadius:8, border:`1px solid ${T.accent}30` }}>
                <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                  <span style={{ fontSize:12, color:T.textMid, fontWeight:600 }}>{tmpl.triggerLabel}:</span>
                  <input type="number" min="0" max="365" value={tmpl.triggerDays || 0}
                    onChange={function(e) { upd("triggerDays", parseInt(e.target.value) || 0); }}
                    style={{ width:60, border:`1.5px solid ${T.border}`, borderRadius:6, padding:"5px 8px", fontFamily:"inherit", fontSize:13, textAlign:"center" }} />
                  <span style={{ fontSize:12, color:T.textLight }}>days before (set to 0 to disable)</span>
                </div>
                {tmpl.triggerDays2 !== undefined && (
                  <div style={{ display:"flex", alignItems:"center", gap:10 }}>
                    <label style={{ display:"flex", alignItems:"center", gap:6, cursor:"pointer", fontSize:12, color:T.textMid, fontWeight:600 }}>
                      <input type="checkbox" checked={!!tmpl.triggerDays2Enabled}
                        onChange={function(e) { upd("triggerDays2Enabled", e.target.checked); }}
                        style={{ width:14, height:14, accentColor:T.accent, cursor:"pointer" }} />
                      Send a second email — {tmpl.triggerLabel2 || "2nd reminder"}:
                    </label>
                    <input type="number" min="0" max="365" value={tmpl.triggerDays2 || 0} disabled={!tmpl.triggerDays2Enabled}
                      onChange={function(e) { upd("triggerDays2", parseInt(e.target.value) || 0); }}
                      style={{ width:60, border:`1.5px solid ${T.border}`, borderRadius:6, padding:"5px 8px", fontFamily:"inherit", fontSize:13, textAlign:"center", opacity: tmpl.triggerDays2Enabled ? 1 : .5 }} />
                    <span style={{ fontSize:12, color:T.textLight }}>days before</span>
                  </div>
                )}
              </div>
            )}

            {/* Subject */}
            <div style={{ marginBottom:14 }}>
              <label style={{ display:"block", fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4, marginBottom:5 }}>Subject</label>
              <input value={tmpl.subject || ""} onChange={function(e) { upd("subject", e.target.value); }}
                style={{ ...inpStyle, width:"100%", boxSizing:"border-box", fontSize:13 }} />
            </div>

            {/* Body */}
            <div style={{ marginBottom:16 }}>
              <label style={{ display:"block", fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4, marginBottom:5 }}>Body</label>
              <textarea value={tmpl.body || ""} onChange={function(e) { upd("body", e.target.value); }} style={taStyle} />
            </div>

            {/* Tokens reference */}
            <div style={{ marginBottom:18 }}>
              <div style={{ fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4, marginBottom:7 }}>Available tokens — click to copy</div>
              <div style={{ display:"flex", flexWrap:"wrap", gap:5 }}>
                {EMAIL_TOKENS.map(function(token, i) {
                  return (
                    <button key={token} onClick={function() { copyToken(token, i); }}
                      style={{ background: copying===i ? T.green : T.bgInput, color: copying===i ? "#fff" : T.textMid,
                        border:`1px solid ${T.border}`, borderRadius:5, padding:"3px 8px", cursor:"pointer",
                        fontFamily:"monospace", fontSize:11, transition:"background .15s" }}>
                      {copying===i ? "Copied!" : token}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* A payment email whose body never mentions the link still gets a
                Pay button added automatically, but the guest reads the text
                first — so flag it rather than relying on the fallback. */}
            {["booking_confirmed","deposit_request","balance_request"].indexOf(tmpl.id) !== -1
              && String(tmpl.body || "").indexOf("{{payment") === -1 && (
              <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:7, padding:"9px 12px",
                marginBottom:16, fontSize:11.5, color:"#92400e", lineHeight:1.6 }}>
                This email asks for money but the body has no <code>{"{{paymentLink}}"}</code> token, so no link appears in the text.
                A <strong>Pay now</strong> button is added to the email automatically, but it reads better if you put the link in yourself —
                paste <code>{"{{paymentLink}}"}</code> where the URL should go.
              </div>
            )}

            {/* Attachments */}
            <div>
              <div style={{ fontSize:11, fontWeight:700, color:T.textMid, textTransform:"uppercase", letterSpacing:.4, marginBottom:7 }}>Attachments (max 2 MB each)</div>
              {(tmpl.attachments || []).length === 0 && (
                <div style={{ fontSize:12, color:T.textLight, marginBottom:8 }}>No files attached to this template.</div>
              )}
              {(tmpl.attachments || []).map(function(att, i) {
                return (
                  <div key={i} style={{ display:"flex", alignItems:"center", gap:10, padding:"7px 10px", background:T.bgInput, borderRadius:7, marginBottom:5, border:`1px solid ${T.border}` }}>
                    <span style={{ fontSize:12, color:T.text, flex:1, overflow:"hidden", whiteSpace:"nowrap", textOverflow:"ellipsis" }}>{att.name}</span>
                    <span style={{ fontSize:11, color:T.textLight, flexShrink:0 }}>{Math.round(att.size/1024)} KB</span>
                    <button onClick={function() { removeAtt(i); }}
                      style={{ background:"none", border:"none", color:T.red, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700, padding:"0 4px" }}>
                      Remove
                    </button>
                  </div>
                );
              })}
              <input ref={fileRef} type="file" onChange={handleFile} style={{ display:"none" }} />
              <button onClick={function() { if (fileRef.current) fileRef.current.click(); }}
                style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:7, padding:"8px 16px", cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600, color:T.text, marginTop:4 }}>
                + Attach file
              </button>
              <div style={{ fontSize:11, color:T.textLight, marginTop:5 }}>
                Files are stored with the template. For large files (brochures, maps) consider linking to a URL in the body instead.
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

// ── Setup wrapper (sub-tabs: Pricing | Discount Codes | Airbnb Sync) ──────────
function LettingsSetup({ properties, setProperties, onSaveProperties, discountCodes, setDiscountCodes, onSaveDiscountCodes, emailTemplates, setEmailTemplates, onSaveEmailTemplates }) {
  const [setupTab, setSetupTab] = useState("pricing");
  const tabs = [["pricing","Pricing & Rules"],["codes","Discount Codes"],["ical","Airbnb Sync"],["emails","Email Templates"],["terms","Terms & Conditions"]];
  return (
    <div>
      <div style={{ display:"flex", gap:2, marginBottom:22, borderBottom:`1px solid ${T.border}` }}>
        {tabs.map(function([id, label]) {
          return (
            <button key={id} onClick={function() { setSetupTab(id); }}
              style={{ background:"none", border:"none", borderBottom: setupTab===id ? `3px solid ${T.midBlue}` : "3px solid transparent",
                color: setupTab===id ? T.midBlue : T.navInactive, fontFamily:"inherit", fontSize:13, fontWeight: setupTab===id ? 700 : 500,
                padding:"6px 16px 10px", cursor:"pointer" }}>
              {label}
            </button>
          );
        })}
      </div>
      {setupTab === "pricing" && <PropertyEditor properties={properties} setProperties={setProperties} onSave={onSaveProperties}/>}
      {setupTab === "codes"   && <DiscountCodesEditor codes={discountCodes} setCodes={setDiscountCodes} onSave={onSaveDiscountCodes}/>}
      {setupTab === "ical"    && <ICalSettings properties={properties} setProperties={setProperties} onSave={onSaveProperties}/>}
      {setupTab === "emails"  && <EmailTemplatesEditor templates={emailTemplates} setTemplates={setEmailTemplates} onSave={onSaveEmailTemplates}/>}
      {setupTab === "terms"   && <TermsEditor/>}
    </div>
  );
}

// ── Todoist ──────────────────────────────────────────────────────────────────
const TODOIST_ICS_KEY = "hbf_todoist_ics_v1";

function TodoistSettings() {
  const [url, setUrl]     = useState("");
  const [saved, setSaved] = useState(false);
  const [test, setTest]   = useState(null);
  const [busy, setBusy]   = useState(false);

  useEffect(function() {
    (async function() {
      try { setUrl((await sbGet(TODOIST_ICS_KEY)) || ""); } catch (e) { setUrl(""); }
    })();
  }, []);

  async function save() {
    setBusy(true); setTest(null);
    try {
      await sbSet(TODOIST_ICS_KEY, url.trim());
      setSaved(true); setTimeout(function(){ setSaved(false); }, 2000);
      if (url.trim()) {
        const res = await fetch("/.netlify/functions/todoist-feed", {
          method:"POST", headers:{ "Content-Type":"application/json" },
          body: JSON.stringify({ url: url.trim(), force: true })
        });
        const d = await res.json();
        if (!res.ok || d.error) setTest({ ok:false, text:d.error || "Could not read the feed" });
        else setTest({ ok:true, text:"Found " + d.tasks.length + " task" + (d.tasks.length!==1?"s":"") + "." });
      }
    } catch (e) { setTest({ ok:false, text:String(e.message||e) }); }
    setBusy(false);
  }

  return (
    <div>
      <p style={{ fontSize:13, color:T.textMid, margin:"0 0 12px", lineHeight:1.6 }}>
        Shows outstanding Todoist tasks on the Home page. Get the URL from Todoist: Settings &rarr; Integrations &rarr; Calendar feed.
        Better still, set it as <code>TODOIST_ICS_URL</code> in Netlify instead of here &mdash; the URL contains a token granting read
        access to your tasks, and anything saved on this page is readable by anyone who can load the app.
      </p>
      <div style={{ display:"flex", gap:10, flexWrap:"wrap", alignItems:"center" }}>
        <input value={url} onChange={function(e){ setUrl(e.target.value); }}
          placeholder="https://ics.todoist.com/..."
          style={{ flex:1, minWidth:240, background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text, fontFamily:"inherit", fontSize:13, padding:"9px 12px", outline:"none" }}/>
        <button onClick={save} disabled={busy}
          style={{ background:saved?T.green:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:7, cursor:busy?"wait":"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>
          {busy ? "Checking..." : saved ? "Saved" : "Save & test"}
        </button>
      </div>
      {test && (
        <div style={{ marginTop:10, fontSize:12, color: test.ok ? T.green : T.red, lineHeight:1.6 }}>{test.text}</div>
      )}
      <p style={{ fontSize:11, color:T.textLight, margin:"10px 0 0", lineHeight:1.6 }}>
        The feed URL acts like a password &mdash; anyone holding it can read your task list. Regenerate it in Todoist if it is ever shared by mistake.
      </p>
    </div>
  );
}

function TodoBox() {
  const [tasks, setTasks] = useState(null);
  const [err, setErr]     = useState(null);
  const [configured, setConfigured] = useState(null);

  async function load() {
    try {
      // The URL may live only in Netlify (TODOIST_ICS_URL), in which case
      // there is nothing stored here — ask the function anyway and hide the
      // box only if it reports nothing is configured at either end.
      let url = "";
      try { url = (await sbGet(TODOIST_ICS_KEY)) || ""; } catch (e) { url = ""; }
      const res = await fetch("/.netlify/functions/todoist-feed", {
        method:"POST", headers:{ "Content-Type":"application/json" },
        body: JSON.stringify({ url: url })
      });
      const d = await res.json();
      if (d && d.error === "No feed URL set") { setConfigured(false); return; }
      setConfigured(true);
      if (!res.ok || d.error) throw new Error(d.error || "Could not read Todoist");
      setTasks(d.tasks || []); setErr(null);
    } catch (e) { setErr(String(e.message||e)); }
  }
  useEffect(function(){ load(); }, []);

  if (configured === false) return null;

  const todayIso = new Date().toISOString().slice(0,10);
  const horizon  = addDaysIso(todayIso, 7);
  const overdue  = (tasks||[]).filter(function(t){ return t.date && t.date < todayIso; });
  const dueToday = (tasks||[]).filter(function(t){ return t.date === todayIso; });
  const soon     = (tasks||[]).filter(function(t){ return t.date && t.date > todayIso && horizon && t.date <= horizon; });

  function row(t, tone) {
    return (
      <div key={t.uid} style={{ display:"flex", alignItems:"baseline", gap:10, padding:"5px 0", borderTop:`1px solid ${T.border}` }}>
        <span style={{ fontSize:13, color:T.text, flex:1, minWidth:0 }}>{t.summary}</span>
        <span style={{ fontSize:11, color:tone, whiteSpace:"nowrap", fontWeight:600 }}>
          {t.date === todayIso ? "today" : fmtDate(t.date)}
        </span>
      </div>
    );
  }

  return (
    <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:12, padding:"20px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)", marginBottom:18 }}>
      <div style={{ display:"flex", alignItems:"center", marginBottom:12, gap:10, flexWrap:"wrap" }}>
        <h3 style={{ margin:0, color:T.midBlue, fontWeight:700, fontSize:15 }}>To do</h3>
        {overdue.length > 0 && (
          <span style={{ fontSize:11, fontWeight:700, color:"#dc2626", background:"#fef2f2", padding:"2px 10px", borderRadius:8 }}>
            {overdue.length} overdue
          </span>
        )}
        <button onClick={load} style={{ marginLeft:"auto", background:"none", border:`1px solid ${T.border}`, color:T.textLight, padding:"3px 10px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:11 }}>Refresh</button>
      </div>

      {err && <div style={{ fontSize:12, color:T.red, lineHeight:1.6 }}>{err}</div>}
      {!err && tasks === null && <div style={{ fontSize:12, color:T.textLight }}>Loading...</div>}
      {!err && tasks && !overdue.length && !dueToday.length && !soon.length && (
        <div style={{ fontSize:13, color:T.textLight }}>Nothing due in the next week.</div>
      )}

      {overdue.length > 0 && (
        <div style={{ marginBottom:10 }}>
          <div style={{ fontSize:10, letterSpacing:1, textTransform:"uppercase", color:"#dc2626", fontWeight:700, marginBottom:2 }}>Overdue</div>
          {overdue.slice(0,6).map(function(t){ return row(t, "#dc2626"); })}
          {overdue.length > 6 && <div style={{ fontSize:11, color:T.textLight, paddingTop:4 }}>...and {overdue.length-6} more</div>}
        </div>
      )}
      {dueToday.length > 0 && (
        <div style={{ marginBottom:10 }}>
          <div style={{ fontSize:10, letterSpacing:1, textTransform:"uppercase", color:T.midBlue, fontWeight:700, marginBottom:2 }}>Today</div>
          {dueToday.slice(0,6).map(function(t){ return row(t, T.midBlue); })}
        </div>
      )}
      {soon.length > 0 && (
        <div>
          <div style={{ fontSize:10, letterSpacing:1, textTransform:"uppercase", color:T.textMid, fontWeight:700, marginBottom:2 }}>Next 7 days</div>
          {soon.slice(0,8).map(function(t){ return row(t, T.textLight); })}
          {soon.length > 8 && <div style={{ fontSize:11, color:T.textLight, paddingTop:4 }}>...and {soon.length-8} more</div>}
        </div>
      )}
    </div>
  );
}

// ── Backup & restore ─────────────────────────────────────────────────────────
const BACKUP_INDEX_KEY = "hbf_backup_index_v1";
const BACKUP_DATA_KEYS = [
  "hawthbush_bookings_v6", "hawthbush_staff_v5", "hbf_accom_v1", "hbf_accom_guests_v1",
  "hbf_properties_v1", "hbf_enquiries_v1", "hbf_viewings_v1", "hbf_viewing_requests_v1",
  "hbf_viewing_blocks_v1", "hbf_bar_products_v1", "hbf_bar_events_v1", "hbf_bar_pos_map_v1",
  "hbf_discount_codes_v1", "hbf_email_templates_v1", "hbf_email_log_v1", "hbf_event_invoices_v1", "hbf_terms_v1", "hbf_cleaning_email_v1", "hbf_starred_emails_v1"
];
const KEY_LABELS = {
  "hawthbush_bookings_v6":"Events", "hawthbush_staff_v5":"Staff", "hbf_accom_v1":"Lettings bookings",
  "hbf_accom_guests_v1":"Lettings guests", "hbf_properties_v1":"Properties", "hbf_enquiries_v1":"Enquiries",
  "hbf_viewings_v1":"Viewings", "hbf_viewing_requests_v1":"Viewing requests", "hbf_viewing_blocks_v1":"Viewing blocks",
  "hbf_bar_products_v1":"Bar products", "hbf_bar_events_v1":"Bar orders & stocktakes",
  "hbf_bar_pos_map_v1":"Till mappings", "hbf_discount_codes_v1":"Discount codes",
  "hbf_email_templates_v1":"Email templates", "hbf_email_log_v1":"Email log", "hbf_event_invoices_v1":"Invoice records", "hbf_terms_v1":"Terms & Conditions", "hbf_cleaning_email_v1":"Cleaning summary settings", "hbf_starred_emails_v1":"Starred emails"
};

// Compare a snapshot against what's live and report only what has been LOST:
// whole records that have vanished, and scalar fields that had a value then and
// are empty now. Deliberately one-directional — anything added or changed since
// the snapshot is never touched, so a merge can't undo recent work.
function diffSnapshot(snapData, liveData, keys) {
  const out = [];
  keys.forEach(function(k) {
    const snapArr = snapData[k];
    const liveArr = liveData[k];
    if (!Array.isArray(snapArr) || !Array.isArray(liveArr)) return;
    if (!snapArr.length || typeof snapArr[0] !== "object" || snapArr[0] === null) return;
    if (snapArr[0].id === undefined) return;

    const liveById = {};
    liveArr.forEach(function(r) { if (r && r.id !== undefined) liveById[String(r.id)] = r; });

    const missing = [];
    const blanks = [];
    snapArr.forEach(function(rec) {
      if (!rec || rec.id === undefined) return;
      const live = liveById[String(rec.id)];
      if (!live) { missing.push(rec); return; }
      Object.keys(rec).forEach(function(f) {
        const was = rec[f];
        const now = live[f];
        const isScalar = (typeof was === "string" || typeof was === "number");
        if (!isScalar) return;                       // arrays/objects left alone
        if (was === "" || was === null || was === undefined) return;
        const nowEmpty = (now === "" || now === null || now === undefined);
        if (nowEmpty) blanks.push({ id: rec.id, field: f, was: was, label: rec.couple || rec.guestName || rec.name || String(rec.id) });
      });
    });
    if (missing.length || blanks.length) out.push({ key: k, missing: missing, blanks: blanks });
  });
  return out;
}

function BackupPanel() {
  const [index, setIndex]       = useState(null);
  const [busy, setBusy]         = useState(null);   // "run" | "download" | "restore"
  const [msg, setMsg]           = useState(null);
  const [pending, setPending]   = useState(null);   // full restore awaiting confirmation
  const [diff, setDiff]         = useState(null);   // selective merge preview
  const fileRef = useRef(null);

  async function loadIndex() {
    try { setIndex((await sbGet(BACKUP_INDEX_KEY)) || []); }
    catch (e) { setIndex([]); setMsg({ kind:"error", text:"Could not read the backup list: " + e.message }); }
  }
  useEffect(function(){ loadIndex(); }, []);

  // Runs entirely in the browser rather than calling the Netlify function.
  // Once a function is given a `schedule` in netlify.toml, Netlify treats it as
  // a scheduled function and answers manual HTTP calls with an empty body —
  // which is why "take a snapshot now" failed with "Unexpected end of JSON
  // input". The nightly run still uses the function; this is the manual path.
  async function takeSnapshot() {
    const today = new Date().toISOString().slice(0, 10);
    const snapshotKey = "hbf_backup_" + today;
    const data = {}, counts = {};
    for (let i = 0; i < BACKUP_DATA_KEYS.length; i++) {
      const k = BACKUP_DATA_KEYS[i];
      const v = await sbGet(k);
      if (v === null || v === undefined) continue;
      data[k] = v;
      counts[k] = Array.isArray(v) ? v.length : 1;
    }
    if (!Object.keys(data).length) throw new Error("Nothing readable to back up — snapshot skipped.");

    const snapshot = { takenAt: new Date().toISOString(), date: today, keys: Object.keys(data), counts: counts, data: data };
    const bytes = JSON.stringify(snapshot).length;
    await sbSet(snapshotKey, snapshot);

    let idx = [];
    try { idx = (await sbGet(BACKUP_INDEX_KEY)) || []; } catch (e) { idx = []; }
    if (!Array.isArray(idx)) idx = [];
    idx = idx.filter(function(e) { return e && e.key !== snapshotKey; });
    idx.push({ key: snapshotKey, date: today, takenAt: snapshot.takenAt, counts: counts, bytes: bytes });
    idx.sort(function(a, b) { return (a.date || "") > (b.date || "") ? -1 : 1; });
    const keep = idx.slice(0, 30), drop = idx.slice(30);
    for (let i = 0; i < drop.length; i++) { try { await sbDelete(drop[i].key); } catch (e) { /* pruning is best-effort */ } }
    await sbSet(BACKUP_INDEX_KEY, keep);
    return Object.keys(data).length;
  }

  async function runBackup() {
    setBusy("run"); setMsg(null);
    try {
      const n = await takeSnapshot();
      setMsg({ kind:"ok", text:"Snapshot saved (" + n + " data sets)." });
      await loadIndex();
    } catch (e) { setMsg({ kind:"error", text:String(e.message||e) }); }
    setBusy(null);
  }

  // Reads live data straight from Supabase so the file is a true copy, not
  // whatever this tab happens to be holding.
  async function downloadNow() {
    setBusy("download"); setMsg(null);
    try {
      const data = {};
      for (let i = 0; i < BACKUP_DATA_KEYS.length; i++) {
        const k = BACKUP_DATA_KEYS[i];
        const v = await sbGet(k);
        if (v !== null && v !== undefined) data[k] = v;
      }
      const payload = { takenAt: new Date().toISOString(), source:"manual-download", data: data };
      const blob = new Blob([JSON.stringify(payload, null, 2)], { type:"application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "hawthbush-backup-" + new Date().toISOString().slice(0,10) + ".json";
      document.body.appendChild(a); a.click(); document.body.removeChild(a);
      URL.revokeObjectURL(url);
      setMsg({ kind:"ok", text:"Downloaded. Keep a copy in Google Drive or wherever suits." });
    } catch (e) { setMsg({ kind:"error", text:String(e.message||e) }); }
    setBusy(null);
  }

  function pickFile(e) {
    const f = e.target.files && e.target.files[0];
    if (!f) return;
    const reader = new FileReader();
    reader.onload = function() {
      try {
        const parsed = JSON.parse(String(reader.result));
        const data = parsed && parsed.data ? parsed.data : parsed;
        if (!data || typeof data !== "object") throw new Error("Not a backup file");
        setPending({ label: f.name, takenAt: parsed.takenAt || "unknown", data: data });
        setMsg(null);
      } catch (err) {
        setMsg({ kind:"error", text:"That file isn't a valid backup: " + err.message });
      }
    };
    reader.readAsText(f);
    e.target.value = "";
  }

  async function loadSnapshot(key) {
    setBusy("restore"); setMsg(null);
    try {
      const snap = await sbGet(key);
      if (!snap || !snap.data) throw new Error("Snapshot is empty or unreadable");
      setPending({ label: key, takenAt: snap.takenAt || snap.date || "unknown", data: snap.data });
    } catch (e) { setMsg({ kind:"error", text:String(e.message||e) }); }
    setBusy(null);
  }

  // Restore takes a safety snapshot of the CURRENT data first, so an unwanted
  // restore is itself reversible.
  async function doRestore() {
    if (!pending) return;
    setBusy("restore"); setMsg(null);
    try {
      // Safety snapshot of the CURRENT data before overwriting anything, so an
      // unwanted restore can itself be undone.
      try { await takeSnapshot(); } catch (e) { console.warn("pre-restore snapshot failed", e); }
      const keys = Object.keys(pending.data).filter(function(k){ return BACKUP_DATA_KEYS.indexOf(k) !== -1; });
      for (let i = 0; i < keys.length; i++) await sbSet(keys[i], pending.data[keys[i]]);
      setPending(null);
      setMsg({ kind:"ok", text:"Restored " + keys.length + " data sets. Reload the page to see it." });
      await loadIndex();
    } catch (e) { setMsg({ kind:"error", text:"Restore failed: " + String(e.message||e) }); }
    setBusy(null);
  }

  // ── Selective merge: put back only what's been lost ────────────────────────
  async function analyse(snapKey) {
    setBusy("diff"); setMsg(null); setDiff(null);
    try {
      const snap = await sbGet(snapKey);
      if (!snap || !snap.data) throw new Error("Snapshot is empty or unreadable");
      const live = {};
      for (let i = 0; i < BACKUP_DATA_KEYS.length; i++) {
        const k = BACKUP_DATA_KEYS[i];
        const v = await sbGet(k);
        live[k] = Array.isArray(v) ? v : [];
      }
      const d = diffSnapshot(snap.data, live, BACKUP_DATA_KEYS);
      if (!d.length) setMsg({ kind:"ok", text:"Nothing has been lost since that snapshot." });
      setDiff({ snapKey: snapKey, takenAt: snap.takenAt || snap.date, sets: d, snapData: snap.data, live: live });
    } catch (e) { setMsg({ kind:"error", text:String(e.message||e) }); }
    setBusy(null);
  }

  async function applyMerge() {
    if (!diff) return;
    setBusy("merge"); setMsg(null);
    try {
      try { await takeSnapshot(); } catch (e) { console.warn("pre-merge snapshot failed", e); }
      let restoredRecords = 0, restoredFields = 0;
      for (let i = 0; i < diff.sets.length; i++) {
        const set = diff.sets[i];
        // Re-read immediately before writing so we merge into the very latest.
        const current = (await sbGet(set.key)) || [];
        const byId = {};
        current.forEach(function(r) { if (r && r.id !== undefined) byId[String(r.id)] = r; });

        set.blanks.forEach(function(b) {
          const rec = byId[String(b.id)];
          if (!rec) return;
          const now = rec[b.field];
          if (now === "" || now === null || now === undefined) { rec[b.field] = b.was; restoredFields++; }
        });
        const toAdd = set.missing.filter(function(m) { return !byId[String(m.id)]; });
        const next = current.concat(toAdd);
        restoredRecords += toAdd.length;

        await sbSet(set.key, next);
      }
      setDiff(null);
      setMsg({ kind:"ok", text:"Restored " + restoredRecords + " missing record(s) and " + restoredFields + " blanked field(s). Reload the page to see them." });
    } catch (e) { setMsg({ kind:"error", text:"Merge failed: " + String(e.message||e) }); }
    setBusy(null);
  }

  const cnt = function(o){ return o ? Object.keys(o).reduce(function(a,k){ return a + (Number(o[k])||0); }, 0) : 0; };

  return (
    <div>
      <div style={{ background:"#eff6ff", border:"1px solid #bfdbfe", borderRadius:9, padding:"12px 16px", marginBottom:18, fontSize:13, color:"#1d4ed8", lineHeight:1.6 }}>
        A snapshot of everything is taken automatically each night and the last 30 are kept.
        Download a copy to keep in Google Drive, and restore from either a file or a snapshot if something goes wrong.
      </div>

      {msg && (
        <div style={{ background: msg.kind==="ok" ? "#f0fdf4" : "#fef2f2", border:`1px solid ${msg.kind==="ok" ? "#bbf7d0" : "#fecaca"}`,
          color: msg.kind==="ok" ? "#166534" : "#dc2626", borderRadius:9, padding:"11px 15px", marginBottom:16, fontSize:13 }}>
          {msg.text}
        </div>
      )}

      <div style={{ display:"flex", gap:10, marginBottom:20, flexWrap:"wrap" }}>
        <button onClick={downloadNow} disabled={!!busy}
          style={{ background:T.accent, color:"#fff", border:"none", padding:"10px 18px", borderRadius:8, cursor:busy?"wait":"pointer", fontFamily:"inherit", fontSize:14, fontWeight:700 }}>
          {busy==="download" ? "Preparing…" : "Download backup file"}
        </button>
        <button onClick={function(){ fileRef.current && fileRef.current.click(); }} disabled={!!busy}
          style={{ background:"#fff", color:T.text, border:`1.5px solid ${T.border}`, padding:"10px 18px", borderRadius:8, cursor:busy?"wait":"pointer", fontFamily:"inherit", fontSize:14, fontWeight:600 }}>
          Restore from file…
        </button>
        <input ref={fileRef} type="file" accept="application/json,.json" onChange={pickFile} style={{ display:"none" }}/>
        <button onClick={runBackup} disabled={!!busy}
          style={{ background:"#fff", color:T.textMid, border:`1.5px solid ${T.border}`, padding:"10px 18px", borderRadius:8, cursor:busy?"wait":"pointer", fontFamily:"inherit", fontSize:14 }}>
          {busy==="run" ? "Snapshotting…" : "Take a snapshot now"}
        </button>
      </div>

      {diff && diff.sets.length > 0 && (
        <div style={{ background:"#f0fdf4", border:"1px solid #bbf7d0", borderRadius:9, padding:"14px 16px", marginBottom:20 }}>
          <div style={{ fontSize:13, fontWeight:700, color:"#166534", marginBottom:6 }}>
            Lost since {diff.takenAt}
          </div>
          <div style={{ fontSize:12, color:"#166534", lineHeight:1.8, marginBottom:10 }}>
            {diff.sets.map(function(set) {
              return (
                <div key={set.key}>
                  <strong>{KEY_LABELS[set.key] || set.key}</strong>
                  {set.missing.length ? " — " + set.missing.length + " missing record" + (set.missing.length!==1?"s":"") : ""}
                  {set.missing.length ? " (" + set.missing.slice(0,4).map(function(m){ return m.couple || m.guestName || m.name || ("#"+m.id); }).join(", ") + (set.missing.length>4?", …":"") + ")" : ""}
                  {set.blanks.length ? (set.missing.length ? "; " : " — ") + set.blanks.length + " blanked field" + (set.blanks.length!==1?"s":"") : ""}
                  {set.blanks.length ? " (" + [...new Set(set.blanks.map(function(b){ return b.field; }))].slice(0,4).join(", ") + ")" : ""}
                </div>
              );
            })}
          </div>
          <div style={{ fontSize:11, color:"#166534", marginBottom:10, fontStyle:"italic" }}>
            This only puts back what has gone. Records added since, and any field that currently has a value, are left exactly as they are — rotas and other recent work are safe.
          </div>
          <div style={{ display:"flex", gap:10, flexWrap:"wrap" }}>
            <button onClick={applyMerge} disabled={busy==="merge"}
              style={{ background:T.green, color:"#fff", border:"none", padding:"8px 18px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>
              {busy==="merge" ? "Restoring…" : "Restore just these"}
            </button>
            <button onClick={function(){ setDiff(null); }}
              style={{ background:"#fff", color:T.textMid, border:`1.5px solid ${T.border}`, padding:"8px 18px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:13 }}>Cancel</button>
          </div>
        </div>
      )}

      {pending && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:9, padding:"14px 16px", marginBottom:20 }}>
          <div style={{ fontSize:13, fontWeight:700, color:"#92400e", marginBottom:6 }}>Restore “{pending.label}”?</div>
          <div style={{ fontSize:12, color:"#92400e", lineHeight:1.7, marginBottom:10 }}>
            Taken {pending.takenAt}. This replaces {Object.keys(pending.data).length} data sets with the contents of this backup —
            anything changed since then will be lost. A snapshot of the current data is taken first, so this can itself be undone.
          </div>
          <div style={{ display:"flex", gap:10, flexWrap:"wrap" }}>
            <button onClick={doRestore} disabled={busy==="restore"}
              style={{ background:T.red, color:"#fff", border:"none", padding:"8px 18px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>
              {busy==="restore" ? "Restoring…" : "Yes, restore"}
            </button>
            <button onClick={function(){ setPending(null); }}
              style={{ background:"#fff", color:T.textMid, border:`1.5px solid ${T.border}`, padding:"8px 18px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:13 }}>Cancel</button>
          </div>
        </div>
      )}

      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden" }}>
        <div style={{ padding:"11px 16px", background:"#eef4fd", borderBottom:`1px solid ${T.border}`, display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
          <span style={{ fontSize:13, fontWeight:700, color:T.midBlue }}>Snapshots {index ? "(" + index.length + ")" : ""}</span>
          {(function() {
            if (!index || !index.length) return null;
            const known = index.filter(function(s){ return Number(s.bytes) > 0; });
            if (!known.length) return <span style={{ fontSize:11, color:T.textLight }}>sizes recorded from the next snapshot onwards</span>;
            const total = known.reduce(function(a,s){ return a + Number(s.bytes||0); }, 0);
            const avg = total / known.length;
            const projected = avg * 30;   // what a full 30-day set will occupy
            const pct = (projected / (500 * 1024 * 1024)) * 100;
            const mb = function(b){ return (b/1024/1024).toFixed(1) + " MB"; };
            return (
              <span style={{ fontSize:11, color:T.textLight, marginLeft:"auto" }}>
                {mb(total)} stored · 30 days ≈ {mb(projected)} ({pct < 0.1 ? "<0.1" : pct.toFixed(1)}% of the 500 MB free tier)
              </span>
            );
          })()}
        </div>
        {index === null ? (
          <div style={{ padding:"16px", fontSize:13, color:T.textLight }}>Loading…</div>
        ) : !index.length ? (
          <div style={{ padding:"16px", fontSize:13, color:T.textLight }}>
            No snapshots yet. Press “Take a snapshot now” to create the first one.
          </div>
        ) : index.map(function(s, i) {
          return (
            <div key={s.key} style={{ padding:"10px 16px", borderTop: i ? `1px solid ${T.border}` : "none", display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
              <span style={{ fontSize:13, fontWeight:600, color:T.text, width:110 }}>{s.date}</span>
              <span style={{ fontSize:11, color:T.textLight, flex:1, minWidth:180 }}>
                {s.counts ? Object.keys(s.counts).slice(0,4).map(function(k){ return (KEY_LABELS[k]||k) + " " + s.counts[k]; }).join(" · ") : ""}
                {s.counts && Object.keys(s.counts).length > 4 ? " · …" : ""}
              </span>
              <span style={{ fontSize:11, color:T.textLight }}>{cnt(s.counts)} records</span>
              <span style={{ fontSize:11, color:T.textLight, width:64, textAlign:"right" }}>
                {Number(s.bytes) > 0 ? (s.bytes/1024).toFixed(0) + " KB" : "—"}
              </span>
              <button onClick={function(){ analyse(s.key); }} disabled={!!busy}
                style={{ background:T.midBlue, border:"none", color:"#fff", padding:"4px 12px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:11, fontWeight:700 }}>
                {busy==="diff" ? "Checking…" : "Recover lost items"}
              </button>
              <button onClick={function(){ loadSnapshot(s.key); }} disabled={!!busy}
                style={{ background:"none", border:`1px solid ${T.border}`, color:T.textLight, padding:"4px 12px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:11 }}>
                Full restore…
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Main Lettings view ───────────────────────────────────────────────────────
// ─── WEEKLY CLEANING SUMMARY ──────────────────────────────────────────────────
// Settings for the emailed version of the housekeeping view. The sending is
// done by a scheduled Netlify function; this only stores what it should do.
const CLEANING_EMAIL_KEY = "hbf_cleaning_email_v1";
const WEEKDAYS = [
  [1, "Monday"], [2, "Tuesday"], [3, "Wednesday"], [4, "Thursday"],
  [5, "Friday"], [6, "Saturday"], [0, "Sunday"]
];

function parseEmailList(str) {
  return String(str || "").split(",").map(function(e) { return e.trim(); })
    .filter(function(e) { return e.indexOf("@") > 0; });
}

function CleaningSummarySettings() {
  const [cfg, setCfg]   = useState(null);
  const [flash, setFlash] = useState("");
  const [busy, setBusy]   = useState(false);

  useEffect(function() {
    let cancelled = false;
    (async function() {
      try {
        const c = await sbGet(CLEANING_EMAIL_KEY);
        if (!cancelled) setCfg(c || { enabled: false, emails: "", weekday: 1 });
      } catch (e) { if (!cancelled) setCfg({ enabled: false, emails: "", weekday: 1 }); }
    })();
    return function() { cancelled = true; };
  }, []);

  if (cfg === null) return <div style={{ fontSize:13, color:T.textLight }}>Loading…</div>;

  const recipients = parseEmailList(cfg.emails);
  const upd = function(k, v) { setCfg(function(c) { return Object.assign({}, c, { [k]: v }); }); };

  const save = async function() {
    setBusy(true);
    try {
      await sbSet(CLEANING_EMAIL_KEY, cfg);
      setFlash("Saved");
    } catch (e) { setFlash("Save failed: " + (e.message || e)); }
    setBusy(false);
    setTimeout(function(){ setFlash(""); }, 3000);
  };

  const sendTest = async function() {
    setBusy(true); setFlash("");
    try {
      const res = await fetch("/.netlify/functions/send-cleaning-summary", {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ force: true })
      });
      const data = await res.json().catch(function(){ return {}; });
      if (!res.ok || data.error) throw new Error(data.error || "Send failed");
      setFlash("Sent to " + (data.sentTo || []).join(", "));
    } catch (e) { setFlash("Test failed: " + (e.message || e)); }
    setBusy(false);
    setTimeout(function(){ setFlash(""); }, 6000);
  };

  return (
    <div>
      <p style={{ fontSize:13, color:T.textMid, margin:"0 0 12px", lineHeight:1.6 }}>
        The same fortnight of check-outs, check-ins, changeovers and farm events shown in the housekeeping
        login, emailed once a week at 3am.
      </p>

      <label style={{ display:"flex", alignItems:"center", gap:9, cursor:"pointer", marginBottom:14 }}>
        <input type="checkbox" checked={!!cfg.enabled} onChange={function(e){ upd("enabled", e.target.checked); }}
          style={{ width:16, height:16, accentColor:T.green, cursor:"pointer" }}/>
        <span style={{ fontSize:13, fontWeight:600, color: cfg.enabled ? T.green : T.textMid }}>
          {cfg.enabled ? "Sending weekly" : "Not sending"}
        </span>
      </label>

      <div style={{ display:"grid", gridTemplateColumns:"2fr 1fr", gap:12, marginBottom:12 }}>
        <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
          <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Send to — comma separated</span>
          <input value={cfg.emails || ""} onChange={function(e){ upd("emails", e.target.value); }}
            placeholder="cleaner@example.com, housekeeping@example.com"
            style={{ background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text,
              fontFamily:"inherit", fontSize:13, padding:"9px 11px", outline:"none" }}/>
        </label>
        <label style={{ display:"flex", flexDirection:"column", gap:4 }}>
          <span style={{ fontSize:11, color:T.textMid, fontWeight:600 }}>Day of the week</span>
          <select value={cfg.weekday} onChange={function(e){ upd("weekday", Number(e.target.value)); }}
            style={{ background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:7, color:T.text,
              fontFamily:"inherit", fontSize:13, padding:"9px 11px", outline:"none" }}>
            {WEEKDAYS.map(function(d) { return <option key={d[0]} value={d[0]}>{d[1]}</option>; })}
          </select>
        </label>
      </div>

      {cfg.enabled && !recipients.length && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:7, padding:"8px 12px",
          marginBottom:12, fontSize:12, color:"#92400e" }}>
          Switched on, but there are no valid email addresses — nothing will be sent.
        </div>
      )}
      {cfg.enabled && recipients.length > 0 && (
        <div style={{ fontSize:12, color:T.textMid, marginBottom:12, lineHeight:1.6 }}>
          Every <strong>{(WEEKDAYS.find(function(d){ return d[0] === Number(cfg.weekday); }) || [,"Monday"])[1]}</strong> at
          3am to {recipients.length} address{recipients.length === 1 ? "" : "es"}: {recipients.join(", ")}
        </div>
      )}

      <div style={{ display:"flex", gap:10, alignItems:"center", flexWrap:"wrap" }}>
        <button onClick={save} disabled={busy}
          style={{ background:T.accent, color:"#fff", border:"none", padding:"9px 20px", borderRadius:8,
            cursor: busy ? "default" : "pointer", fontFamily:"inherit", fontSize:13, fontWeight:700, opacity: busy ? .6 : 1 }}>
          Save
        </button>
        <button onClick={sendTest} disabled={busy || !recipients.length}
          title={recipients.length ? "Send it now, whatever day it is" : "Add an email address first"}
          style={{ background:"#fff", color:T.textMid, border:`1.5px solid ${T.border}`, padding:"9px 18px",
            borderRadius:8, cursor: (busy || !recipients.length) ? "not-allowed" : "pointer",
            fontFamily:"inherit", fontSize:13, fontWeight:600, opacity: (busy || !recipients.length) ? .55 : 1 }}>
          Send one now
        </button>
        {flash && <span style={{ fontSize:12, color: flash.indexOf("fail") !== -1 ? T.red : T.green, fontWeight:600 }}>{flash}</span>}
      </div>
      <p style={{ fontSize:11, color:T.textLight, margin:"10px 0 0", lineHeight:1.6 }}>
        "Send one now" ignores the day and the on/off switch, so it can be used to check the wording without waiting a week.
      </p>
    </div>
  );
}

// ─── CLEANER VIEW ─────────────────────────────────────────────────────────────
// A read-only, three-tab app for whoever is cleaning: what's coming up, the
// lettings calendar, and the bookings list. Loads its own data rather than
// going through LettingsView, so none of the editing, pricing, payment or
// email machinery is reachable — there is nothing here that can be changed.
const CLEANER_DAYS_AHEAD = 14;

function CleanerHome({ properties, accom, events }) {
  const today = new Date().toISOString().slice(0, 10);
  const end = (function() {
    const d = new Date(today + "T00:00:00Z");
    d.setUTCDate(d.getUTCDate() + CLEANER_DAYS_AHEAD);
    return d.toISOString().slice(0, 10);
  })();

  const propOf = function(id) {
    return (properties || []).find(function(x) { return x.id === id; }) || null;
  };
  const propName = function(id) {
    const p = propOf(id);
    return p ? p.name : id;
  };
  // Rows sort by where the property sits in the configured list — Hamlet,
  // Amly, Glamping — so every day reads in the same order. Farm events sit
  // after the cottages.
  const propRank = function(id) {
    const i = (properties || []).findIndex(function(x) { return x.id === id; });
    return i === -1 ? 900 : i;
  };

  // Everything happening in the window, keyed by the day it happens on.
  const byDay = {};
  const add = function(date, item) {
    if (!date || date < today || date > end) return;
    if (!byDay[date]) byDay[date] = [];
    byDay[date].push(item);
  };

  (events || []).forEach(function(ev) {
    if (!isValidEventDate(ev.date) || ev.status === "Cancelled") return;
    add(ev.date, {
      kind: "event", rank: 999,
      label: "Grain Store",
      detail: (ev.couple || "Event") + " · " + eventTypeLabel(ev)
    });
  });

  (accom || []).forEach(function(b) {
    if (b.status === "cancelled" || b.bookingType === "Blocked") return;
    const stays = (b.stays && b.stays.length) ? b.stays : [b];
    const wedding = b.bookingType === "Wedding";
    stays.forEach(function(s) {
      const p = propOf(s.propertyId);
      const who = b.guestName || "Guest";
      const guests = b.guestCount ? b.guestCount + " guest" + (Number(b.guestCount) === 1 ? "" : "s") : "";
      // Wedding parties get earlier access and a later checkout, so the times
      // have to come from the booking type, not just the property.
      // A time typed onto the stay wins over the property's rule.
      const times = stayTimes(b, s, p);
      const inTime  = times.inTime;
      const outTime = times.outTime;
      const tail = who + (guests ? " · " + guests : "");
      add(s.checkOut, { kind: "out", rank: propRank(s.propertyId), label: propName(s.propertyId),
        time: outTime || "", detail: tail });
      add(s.checkIn,  { kind: "in",  rank: propRank(s.propertyId), label: propName(s.propertyId),
        time: inTime || "", detail: tail });
    });
  });

  const days = Object.keys(byDay).sort();

  const chip = function(kind) {
    const map = {
      out:   { text: "Check-out",  bg: "#fff7ed", fg: "#9a3412", bd: "#fdba74" },
      in:    { text: "Check-in",   bg: T.greenBg, fg: T.green,   bd: "#bbf7d0" },
      event: { text: "Farm event", bg: "#eef4fd", fg: T.midBlue, bd: "#bfdbfe" }
    };
    const c = map[kind];
    return (
      <span style={{ fontSize:10, fontWeight:700, padding:"3px 9px", borderRadius:9,
        background:c.bg, color:c.fg, border:"1px solid " + c.bd, whiteSpace:"nowrap", flexShrink:0 }}>
        {c.text}
      </span>
    );
  };

  // Check-out and check-in on the same property on the same day is a
  // changeover — the thing most worth knowing about in advance.
  const changeoverProps = function(items) {
    const outs = items.filter(function(i){ return i.kind === "out"; }).map(function(i){ return i.label; });
    return items.filter(function(i){ return i.kind === "in" && outs.indexOf(i.label) !== -1; })
                .map(function(i){ return i.label; });
  };

  return (
    <div>
      <h2 style={{ fontSize:20, fontWeight:800, color:T.text, margin:"0 0 2px" }}>The next {CLEANER_DAYS_AHEAD} days</h2>
      <div style={{ fontSize:13, color:T.textMid, marginBottom:18 }}>
        {fmtDate(today)} to {fmtDate(end)}
      </div>

      {days.length === 0 && (
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"22px 20px",
          fontSize:14, color:T.textLight }}>
          Nothing booked in the next {CLEANER_DAYS_AHEAD} days.
        </div>
      )}

      {days.map(function(d) {
        const items = byDay[d].slice().sort(function(a, z) {
          if (a.rank !== z.rank) return a.rank - z.rank;        // Hamlet, Amly, Glamping, then events
          const order = { out: 0, in: 1, event: 2 };            // out before in on the same property
          return order[a.kind] - order[z.kind];
        });
        const changeovers = changeoverProps(items);
        return (
          <div key={d} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10,
            padding:"13px 16px", marginBottom:10 }}>
            <div style={{ display:"flex", alignItems:"baseline", gap:10, marginBottom:8, flexWrap:"wrap" }}>
              <span style={{ fontSize:14, fontWeight:700, color: d === today ? T.accent : T.text }}>
                {d === today ? "Today · " : ""}{fmtWeekdayLong(d)}
              </span>
              {changeovers.length > 0 && (
                <span style={{ fontSize:10, fontWeight:700, padding:"3px 9px", borderRadius:9,
                  background:"#fef2f2", color:T.red, border:"1px solid #fca5a5" }}>
                  Changeover: {changeovers.join(", ")}
                </span>
              )}
            </div>
            {items.map(function(it, i) {
              return (
                <div key={i} style={{ display:"flex", alignItems:"center", gap:10, padding:"5px 0", flexWrap:"wrap" }}>
                  {chip(it.kind)}
                  <span style={{ fontSize:13, fontWeight:600, color:T.text, minWidth:96 }}>{it.label}</span>
                  {it.time && (
                    <span style={{ fontSize:12, fontWeight:700, color:T.accent, minWidth:42 }}>{it.time}</span>
                  )}
                  <span style={{ fontSize:12, color:T.textMid }}>{it.detail}</span>
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

function CleanerView() {
  const [properties, setProperties] = useState(INITIAL_PROPERTIES);
  const [accom, setAccom]           = useState([]);
  const [events, setEvents]         = useState([]);
  const [loaded, setLoaded]         = useState(false);
  const [tab, setTab]               = useState("home");
  const [cursor, setCursor]         = useState(new Date());
  const [filterProp, setFilterProp]     = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");

  useEffect(function() {
    let cancelled = false;
    (async function() {
      try {
        const results = await Promise.all([
          sbGet(PROPERTIES_STORAGE), sbGet(ACCOM_STORAGE), sbGet(BOOKING_STORAGE)
        ]);
        if (cancelled) return;
        if (results[0] && results[0].length) setProperties(results[0]);
        setAccom(Array.isArray(results[1]) ? results[1].map(normalizeAccom) : []);
        setEvents(Array.isArray(results[2]) ? results[2] : []);
      } catch (e) { /* leave the defaults; the view still renders */ }
      if (!cancelled) setLoaded(true);
    })();
    return function() { cancelled = true; };
  }, []);

  const tabs = [["home","What's coming up"],["calendar","Calendar"],["list","Bookings"]];

  if (!loaded) return <div style={{ padding:"40px", textAlign:"center", color:T.textLight }}>Loading…</div>;

  return (
    <div>
      <div style={{ display:"flex", gap:4, marginBottom:20, borderBottom:`1px solid ${T.border}` }}>
        {tabs.map(function(t) {
          return (
            <button key={t[0]} onClick={function(){ setTab(t[0]); }}
              style={{ background:"none", border:"none",
                borderBottom: tab===t[0] ? `3px solid ${T.accent}` : "3px solid transparent",
                color: tab===t[0] ? T.accent : T.navInactive, fontFamily:"inherit", fontSize:14,
                fontWeight: tab===t[0] ? 700 : 500, padding:"8px 16px 12px", cursor:"pointer" }}>
              {t[1]}
            </button>
          );
        })}
      </div>

      {tab === "home" && <CleanerHome properties={properties} accom={accom} events={events}/>}
      {/* onOpen is deliberately a no-op — clicking a booking must not open an
          editable form for someone who shouldn't be changing bookings. */}
      {tab === "calendar" && (
        <AccomCalendar properties={properties} bookings={accom} events={events}
          cursor={cursor} setCursor={setCursor} onOpen={function(){}} onViewEventsCalendar={null}/>
      )}
      {tab === "list" && (
        <AccomList properties={properties} bookings={accom}
          filterProp={filterProp} setFilterProp={setFilterProp}
          filterStatus={filterStatus} setFilterStatus={setFilterStatus}
          onOpen={function(){}}/>
      )}
    </div>
  );
}

function LettingsView({ events, calendarTrigger, setView: setAppView, setReportType: setAppReportType, focusBookingId, clearFocusBooking, prefillNew, clearPrefillNew, onOpenEvent }) {
  const [properties, setProperties]         = useState(INITIAL_PROPERTIES);
  const [bookings, setBookings]             = useState([]);
  const [guests, setGuests]                 = useState([]);
  const [discountCodes, setDiscountCodes]   = useState([]);
  const [emailTemplates, setEmailTemplates] = useState(DEFAULT_EMAIL_TEMPLATES);
  const [loaded, setLoaded]                 = useState(false);
  const [tab, setTab]               = useState("calendar");
  // Jump to calendar sub-tab when the Calendar nav item is clicked
  useEffect(function() { if (calendarTrigger > 0) setTab("calendar"); }, [calendarTrigger]);
  const [cursor, setCursor]         = useState(()=> new Date());
  const [form, setForm]             = useState(null);
  const [editId, setEditId]         = useState(null);
  const [filterProp, setFilterProp] = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");
  const [flash, setFlash]           = useState("");
  const [askSendConfirm, setAskSendConfirm] = useState(null); // holds the just-created booking record, or null
  const [sendingConfirm, setSendingConfirm] = useState(false);
  const [askDeleteBooking, setAskDeleteBooking] = useState(false);
  const [clashWarning, setClashWarning] = useState(null);   // { rec, stayOpen, clashes } or null

  useEffect(() => {
    (async () => {
      try { const p = await sbGet(PROPERTIES_STORAGE); if (p && p.length) setProperties(p); } catch {}
      try { const b = await sbGet(ACCOM_STORAGE);      setBookings((b || []).map(normalizeAccom)); } catch { setBookings([]); }
      try { const g = await sbGet(ACCOM_GUESTS_STORAGE); setGuests(g || []); } catch { setGuests([]); }
      try { const dc = await sbGet(DISCOUNT_CODES_STORAGE); setDiscountCodes(dc || []); } catch { setDiscountCodes([]); }
      try { const et = await sbGet(EMAIL_TEMPLATES_STORAGE); if (et && et.length) setEmailTemplates(et); } catch {}
      setLoaded(true);
    })();
  }, []);

  const saveBookings = async (data) => {
    setBookings(data);
    try { await sbSet(ACCOM_STORAGE, data); setFlash("Saved"); setTimeout(()=>setFlash(""), 1500); }
    catch (e) { console.error(e); setFlash("Save failed"); }
  };

  const saveProperties = async () => {
    try { await sbSet(PROPERTIES_STORAGE, properties); setFlash("Saved"); setTimeout(()=>setFlash(""), 1500); }
    catch (e) { console.error(e); setFlash("Save failed"); }
  };

  const saveDiscountCodes = async () => {
    try { await sbSet(DISCOUNT_CODES_STORAGE, discountCodes); setFlash("Saved"); setTimeout(()=>setFlash(""), 1500); }
    catch (e) { console.error(e); setFlash("Save failed"); }
  };

  const saveEmailTemplates = async () => {
    try { await sbSet(EMAIL_TEMPLATES_STORAGE, emailTemplates); setFlash("Saved"); setTimeout(()=>setFlash(""), 1500); }
    catch (e) { console.error(e); setFlash("Save failed"); }
  };

  const openNew  = () => { setForm(blankAccom(null, bookings)); setEditId(null); setTab("form"); };
  const openNewBlock = () => { setForm(Object.assign({}, blankAccom(null, bookings), { bookingType:"Blocked", guestName:"Not available" })); setEditId(null); setTab("form"); };
  const openEdit = (b) => {
    var editStays;
    if (b.stays && b.stays.length) {
      // Ensure each stay has guestCount and value fields
      editStays = b.stays.map(function(s) {
        return Object.assign({ guestCount:"", value:0 }, s);
      });
    } else {
      // Old flat booking — wrap into a single stay
      editStays = [{ propertyId:b.propertyId||"hamlet", propertyName:b.propertyName||"", checkIn:b.checkIn||"", checkOut:b.checkOut||"", nights:b.nights||null, guestCount:b.guestCount||"", value:Number(b.value)||0 }];
    }
    var pIds = editStays.map(function(s){ return s.propertyId; }).filter(Boolean);
    if (!pIds.length) pIds = [b.propertyId||"hamlet"];
    setForm(Object.assign({}, blankAccom(pIds[0], bookings), b, { propertyIds:pIds, propertyId:pIds[0], stays:editStays, extras:(b.extras||[]).slice(), schedule:(b.schedule||[]).slice() }));
    setEditId(b.id); setTab("form");
  };

  // "Add accommodation" from an event: open a new booking pre-filled with all
  // properties for the night before and the night of the event, already linked
  // to that event. Anything not needed can simply be unticked before saving.
  useEffect(function() {
    if (!prefillNew || !loaded) return;
    var props = (properties && properties.length ? properties : INITIAL_PROPERTIES);
    var ids = props.map(function(p) { return p.id; });
    var stays = props.map(function(p) {
      return {
        propertyId: p.id,
        propertyName: p.name,
        checkIn: prefillNew.checkIn,
        checkOut: prefillNew.checkOut,
        nights: 2,
        guestCount: "",
        value: 0
      };
    });
    setForm(Object.assign({}, blankAccom(ids[0], bookings), {
      propertyIds: ids,
      propertyId: ids[0],
      stays: stays,
      linkedEventId: prefillNew.eventId,
      guestName: prefillNew.guestName || "",
      email: prefillNew.email || "",
      bookingType: prefillNew.bookingType || "",
      source: "manual"
    }));
    setEditId(null);
    setTab("form");
    if (clearPrefillNew) clearPrefillNew();
  }, [prefillNew, loaded]);

  // Deep-link: open a specific accom booking when arriving via the Bookings accommodation column
  useEffect(function() {
    if (!focusBookingId || !loaded) return;
    var target = bookings.find(function(b) { return String(b.id) === String(focusBookingId); });
    if (target) openEdit(target);
    if (clearFocusBooking) clearFocusBooking();
  }, [focusBookingId, loaded, bookings]);

  // stayOpen: keep the form on screen after saving, so several changes can be
  // made and saved without losing your place. Exit is a separate button.
  const handleSave = async (stayOpen, force) => {
    var rawStays = (form.stays && form.stays.length) ? form.stays : [{ propertyId:form.propertyId||"hamlet", propertyName:"", checkIn:form.checkIn||"", checkOut:form.checkOut||"", nights:null, guestCount:form.guestCount||"", value:Number(form.value)||0 }];
    var stays = rawStays.map(function(s) {
      var p = properties.find(function(pp){ return pp.id===s.propertyId; });
      return Object.assign({}, s, { propertyName: p?p.name:s.propertyId, nights: nightsBetween(s.checkIn, s.checkOut) });
    });
    var totalValue = stays.reduce(function(sum,s){ return sum+(Number(s.value)||0); }, 0);
    var primary = stays[0] || {};
    var pIds = stays.map(function(s){ return s.propertyId; });
    var rec = Object.assign({}, form, {
      propertyId: primary.propertyId || form.propertyId,
      propertyName: primary.propertyName || "",
      propertyIds: pIds,
      checkIn: primary.checkIn || "",
      checkOut: primary.checkOut || "",
      nights: primary.nights || null,
      value: totalValue,
      stays: stays
    });
    // Nothing prevented a double booking before this — checkAvailability
    // existed but was never called from anywhere. A clash is now surfaced
    // before the write, listing exactly what it collides with. Overriding is
    // still possible, because otherwise an existing double booking could
    // never be edited or corrected, but it takes a deliberate second press.
    if (!force) {
      var clashes = findAccomClashes(bookings, rec);
      if (clashes.length) {
        setClashWarning({ rec: rec, stayOpen: !!stayOpen, clashes: clashes });
        return;
      }
    }

    var isNew = !editId;
    var next = editId ? bookings.map(function(b){ return b.id===editId ? rec : b; }) : bookings.concat([rec]);
    await saveBookings(next);

    if (stayOpen) {
      // Stay on the booking, but keep editing the record that was actually
      // written — otherwise a new booking would be saved again as a second
      // copy on the next press, and the send buttons would have no id to
      // work with.
      setForm(rec);
      setEditId(rec.id);
      setFlash("Booking saved");
      setTimeout(function(){ setFlash(""); }, 2000);
    } else {
      setTab("calendar"); setForm(null); setEditId(null);
    }

    // Newly-created manual booking with a guest email — offer to send the
    // Booking Confirmed email. Not offered for accommodation attached to a
    // farm event: those guests are invoiced through the event and shouldn't
    // receive a lettings confirmation. The send buttons on the booking page
    // can still fire it by hand if it's ever wanted.
    if (isNew && rec.email && rec.bookingType !== "Blocked" && !rec.linkedEventId) {
      setAskSendConfirm(rec);
    }
  };
  const sendBookingConfirmedEmail = async () => {
    if (!askSendConfirm) return;
    setSendingConfirm(true);
    try {
      await fetch("/.netlify/functions/send-accom-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ bookingId: askSendConfirm.id, emailType: "booking_confirmed" }),
      });
      setFlash("Confirmation email sent");
      setTimeout(function(){ setFlash(""); }, 2000);
    } catch (e) {
      console.error(e);
      setFlash("Email send failed");
      setTimeout(function(){ setFlash(""); }, 2500);
    }
    setSendingConfirm(false);
    setAskSendConfirm(null);
  };
  const handleDelete = async () => {
    const next = bookings.filter(b=> b.id!==editId);
    await saveBookings(next);
    setTab("calendar"); setForm(null); setEditId(null); setAskDeleteBooking(false);
  };

  const subTabs = [["calendar","Calendar"],["list","Bookings"],["report","Report"],["import","Import"],["settings","Settings"]];

  return (
    <div className="app-shell" style={{ maxWidth:1200, margin:"0 auto", padding:"24px 28px" }}>
      {askSendConfirm && (
        <ConfirmDialog
          message="Send booking confirmation email?"
          subMessage={`Email "${askSendConfirm.guestName || "this guest"}" at ${askSendConfirm.email} to confirm their new booking.`}
          confirmLabel={sendingConfirm ? "Sending…" : "Send Email"}
          cancelLabel="Skip"
          icon="✉️"
          iconBg={T.accentLight}
          confirmColor={T.accent}
          onConfirm={sendBookingConfirmedEmail}
          onCancel={()=>setAskSendConfirm(null)}
        />
      )}
      {clashWarning && (() => {
        const propNameOf = function(id) {
          const p = properties.find(function(x){ return x.id === id; });
          return p ? p.name : id;
        };
        return (
          <div style={{ position:"fixed", inset:0, background:"rgba(20,26,35,.55)", zIndex:2000,
            display:"flex", alignItems:"center", justifyContent:"center", padding:20 }}>
            <div style={{ background:"#fff", borderRadius:12, width:"min(620px,100%)", maxHeight:"85vh",
              display:"flex", flexDirection:"column", boxShadow:"0 20px 60px rgba(0,0,0,.3)" }}>
              <div style={{ padding:"18px 24px", borderBottom:`1px solid ${T.border}` }}>
                <h3 style={{ margin:0, fontSize:17, fontWeight:800, color:T.red }}>
                  These dates are already booked
                </h3>
                <div style={{ fontSize:13, color:T.textMid, marginTop:5, lineHeight:1.6 }}>
                  Saving this would double book {clashWarning.clashes.length === 1 ? "a property" : "properties"}.
                  Change the dates, or save anyway if you know it's right.
                </div>
              </div>
              <div style={{ padding:"14px 24px", overflowY:"auto", flex:1 }}>
                {clashWarning.clashes.map(function(c, i) {
                  return (
                    <div key={i} style={{ background:"#fef2f2", border:"1px solid #fca5a5", borderRadius:8,
                      padding:"10px 13px", marginBottom:9 }}>
                      <div style={{ fontSize:13, fontWeight:700, color:T.text }}>
                        {propNameOf(c.stay.propertyId)}
                      </div>
                      <div style={{ fontSize:12, color:T.textMid, marginTop:3, lineHeight:1.6 }}>
                        You are entering <strong>{fmtDate(c.stay.checkIn)} → {fmtDate(c.stay.checkOut)}</strong>
                      </div>
                      <div style={{ fontSize:12, color:"#dc2626", marginTop:2, lineHeight:1.6 }}>
                        Clashes with <strong>{c.other.guestName || "another booking"}</strong>{" "}
                        ({c.other.id}) — {fmtDate(c.otherStay.checkIn)} → {fmtDate(c.otherStay.checkOut)}
                      </div>
                    </div>
                  );
                })}
                <div style={{ fontSize:11, color:T.textLight, lineHeight:1.6, marginTop:4 }}>
                  A stay ending on the same day another begins is a changeover, not a clash, and isn't reported here.
                </div>
              </div>
              <div style={{ padding:"14px 24px", borderTop:`1px solid ${T.border}`, display:"flex",
                justifyContent:"flex-end", gap:10, flexWrap:"wrap" }}>
                <button onClick={function(){ setClashWarning(null); }}
                  style={{ padding:"10px 22px", background:T.accent, color:"#fff", border:"none", borderRadius:7,
                    fontFamily:"inherit", fontSize:13, fontWeight:700, cursor:"pointer" }}>
                  Go back and change the dates
                </button>
                <button onClick={function(){
                    const w = clashWarning;
                    setClashWarning(null);
                    handleSave(w.stayOpen, true);
                  }}
                  style={{ padding:"10px 18px", background:"#fff", color:T.red, border:"1.5px solid #fca5a5",
                    borderRadius:7, fontFamily:"inherit", fontSize:13, fontWeight:600, cursor:"pointer" }}>
                  Save anyway
                </button>
              </div>
            </div>
          </div>
        );
      })()}

      {askDeleteBooking && (
        <ConfirmDialog
          message="Delete this booking?"
          subMessage={`"${(form && form.guestName) || "This booking"}" will be permanently removed. This cannot be undone.`}
          confirmLabel="Yes, Delete"
          cancelLabel="Cancel"
          onConfirm={handleDelete}
          onCancel={()=>setAskDeleteBooking(false)}
        />
      )}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:18 }}>
        <div>
          <h2 style={{ fontSize:22, fontWeight:800, color:T.text, margin:0 }}>Lettings</h2>
          <div style={{ fontSize:13, color:T.textMid, marginTop:3 }}>Holiday lets across {properties.map(p=>p.name).join(", ")} · read-only alongside Bookalet</div>
        </div>
        <div style={{ display:"flex", gap:10, alignItems:"center" }}>
          {flash && <span style={{ fontSize:12, fontWeight:600, color:T.green }}>{flash}</span>}
          <button onClick={openNewBlock} style={{ background:"#fff", color:T.textMid, border:`1.5px solid ${T.border}`, padding:"10px 16px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:600 }}>+ Block dates</button>
          <button onClick={openNew} style={{ background:T.accent, color:"#fff", border:"none", padding:"10px 18px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:700 }}>+ New booking</button>
        </div>
      </div>

      {tab!=="form" && (
        <div style={{ display:"flex", gap:4, marginBottom:20, borderBottom:`1px solid ${T.border}` }}>
          {subTabs.map(([id,label])=>(
            <button key={id} onClick={()=>setTab(id)} style={{ background:"none", border:"none", borderBottom: tab===id?`3px solid ${T.accent}`:"3px solid transparent",
              color: tab===id?T.accent:T.navInactive, fontFamily:"inherit", fontSize:14, fontWeight: tab===id?700:500, padding:"8px 16px 12px", cursor:"pointer" }}>{label}</button>
          ))}
        </div>
      )}

      {!loaded && <div style={{ padding:"40px", textAlign:"center", color:T.textLight }}>Loading…</div>}

      {loaded && tab==="calendar" && <AccomCalendar properties={properties} bookings={bookings} events={events||[]} cursor={cursor} setCursor={setCursor} onOpen={openEdit} onViewEventsCalendar={setAppView && setAppReportType ? function(){ setAppReportType("calendar"); setAppView("reports"); } : null} />}
      {loaded && tab==="list" && <AccomList properties={properties} bookings={bookings} filterProp={filterProp} setFilterProp={setFilterProp} filterStatus={filterStatus} setFilterStatus={setFilterStatus} onOpen={openEdit} />}
      {loaded && tab==="report" && <AccomReport properties={properties} bookings={bookings} />}
      {loaded && tab==="import" && <AccomImport onImported={(p,g,b)=>{ setProperties(p); setGuests(g); setBookings(b.map(normalizeAccom)); setTab("calendar"); }} saveBookings={saveBookings} bookings={bookings} />}
      {loaded && tab==="settings" && (
        <LettingsSetup
          properties={properties} setProperties={setProperties} onSaveProperties={saveProperties}
          discountCodes={discountCodes} setDiscountCodes={setDiscountCodes} onSaveDiscountCodes={saveDiscountCodes}
          emailTemplates={emailTemplates} setEmailTemplates={setEmailTemplates} onSaveEmailTemplates={saveEmailTemplates}
        />
      )}
      {tab==="form" && form && (
        <div>
          <div style={{ fontSize:16, fontWeight:700, color:T.text, marginBottom:16 }}>{editId ? "Edit booking" : "New booking"}</div>
          <AccomForm properties={properties} discountCodes={discountCodes} events={events||[]} form={form} setForm={setForm} onSave={handleSave} onExit={()=>{ setTab("calendar"); setForm(null); setEditId(null); }} onDelete={editId ? ()=>setAskDeleteBooking(true) : null} onOpenEvent={onOpenEvent} />
        </div>
      )}
    </div>
  );
}


// ─── MAIN APP ─────────────────────────────────────────────────────────────────
export default function App({ role = "admin", onSignOut } = {}) {
  const [bookings, setBookings] = useState([]);
  const [staff, setStaff]       = useState([]);
  // Navigation history. setView is used in dozens of places, so rather than
  // change every call site it's wrapped: the real setter is renamed and a
  // recording version takes its place. Every jump pushes the view being left,
  // and Back pops it — without pushing, or Back would toggle between two
  // pages forever.
  const [view, setViewRaw]      = useState("home");
  const [viewHistory, setViewHistory] = useState([]);
  const goingBackRef = useRef(false);

  const setView = useCallback(function(next) {
    setViewRaw(function(current) {
      const target = typeof next === "function" ? next(current) : next;
      if (!goingBackRef.current && target !== current) {
        setViewHistory(function(h) { return h.concat([current]).slice(-25); });
      }
      goingBackRef.current = false;
      return target;
    });
  }, []);

  const goBack = useCallback(function() {
    setViewHistory(function(h) {
      if (!h.length) return h;
      goingBackRef.current = true;
      setViewRaw(h[h.length - 1]);
      return h.slice(0, -1);
    });
  }, []);
  const [lettingsCalTrigger, setLettingsCalTrigger] = useState(0);
  const [xeroToken, setXeroToken]   = useState(() => xeroGetToken());
  const [gmailToken, setGmailToken] = useState(() => gmailGetToken());

  // Handle Gmail OAuth2 implicit flow callback — reads access_token from URL hash
  useEffect(() => {
    const hash = window.location.hash;
    if (!hash.includes("access_token")) return;
    const params = new URLSearchParams(hash.replace("#",""));
    const accessToken = params.get("access_token");
    const expiresIn   = parseInt(params.get("expires_in")||"3600");
    const state       = params.get("state");
    if (!accessToken) return;
    if (state !== sessionStorage.getItem("gmail_state")) return;
    // Clean URL
    window.history.replaceState({}, document.title, window.location.pathname);
    const token = { access_token: accessToken, expires_at: Date.now() + expiresIn * 1000 };
    gmailSetToken(token);
    setGmailToken(token);
    sessionStorage.removeItem("gmail_state");
  }, []);

  const handleGmailConnect = () => {
    const state = Math.random().toString(36).slice(2);
    sessionStorage.setItem("gmail_state", state);
    const url = "https://accounts.google.com/o/oauth2/v2/auth?" + new URLSearchParams({
      client_id:     GMAIL_CLIENT_ID,
      redirect_uri:  GMAIL_REDIRECT,
      response_type: "token",
      scope:         GMAIL_SCOPE,
      state,
      include_granted_scopes: "true",
    });
    window.location.href = url;
  };

  const handleGmailDisconnect = () => { gmailClearToken(); setGmailToken(null); };

  // Handle Xero OAuth2 callback — runs once on load if ?code= is in URL
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const code = params.get("code");
    const state = params.get("state");
    if (!code) return;
    const savedState    = sessionStorage.getItem("xero_state");
    const codeVerifier  = sessionStorage.getItem("xero_code_verifier");
    if (state !== savedState) { console.error("Xero state mismatch"); return; }
    // Clean URL immediately
    window.history.replaceState({}, document.title, window.location.pathname);
    // Exchange code for token
    (async () => {
      try {
        const res = await fetch("https://identity.xero.com/connect/token", {
          method: "POST",
          headers: { "Content-Type": "application/x-www-form-urlencoded" },
          body: new URLSearchParams({
            grant_type: "authorization_code",
            code,
            redirect_uri: XERO_REDIRECT_URI,
            client_id: xeroClientId(),
            code_verifier: codeVerifier,
          }),
        });
        if (!res.ok) throw new Error(await res.text());
        const data = await res.json();
        const token = { ...data, expires_at: Date.now() + data.expires_in * 1000 };
        xeroSetToken(token);
        setXeroToken(token);
        sessionStorage.removeItem("xero_state");
        sessionStorage.removeItem("xero_code_verifier");
      } catch(err) { console.error("Xero token exchange failed:", err); }
    })();
  }, []);

  const handleXeroConnect = async () => {
    const verifier  = xeroGenerateCodeVerifier();
    const challenge = await xeroGenerateCodeChallenge(verifier);
    const state     = xeroGenerateCodeVerifier(); // reuse as random state
    sessionStorage.setItem("xero_code_verifier", verifier);
    sessionStorage.setItem("xero_state", state);
    const url = "https://login.xero.com/identity/connect/authorize?" + new URLSearchParams({
      response_type: "code",
      client_id: xeroClientId(),
      redirect_uri: XERO_REDIRECT_URI,
      scope: xeroScopes(),
      state,
      code_challenge: challenge,
      code_challenge_method: "S256",
    });
    window.location.href = url;
  };

  const handleXeroDisconnect = () => { xeroClearToken(); setXeroToken(null); };
  const [editId, setEditId]     = useState(null);
  const [formData, setFormData] = useState(null);
  const [search, setSearch]     = useState("");
  const [reportType, setReportType] = useState("summary");
  const [loaded, setLoaded]     = useState(false);
  const [enquiries, setEnquiries]         = useState([]);
  const [viewingRequests, setViewingRequests] = useState([]);
  const [viewingBlocks,   setViewingBlocks]   = useState([]);
  const [editStaffId, setEditStaffId] = useState(null);
  const [staffForm, setStaffForm]     = useState(null);
  const [focusEnquiryId, setFocusEnquiryId] = useState(null);
  const [focusAccomBookingId, setFocusAccomBookingId] = useState(null);
  const [accomBookings, setAccomBookings]     = useState([]);
  const [accomProperties, setAccomProperties] = useState([]);
  const [invoiceRecords, setInvoiceRecords]   = useState([]);
  const [accomPrefill, setAccomPrefill]       = useState(null);
  const [staleBuild, setStaleBuild]           = useState(null);   // newer build seen
  const barOnly     = role === "bar";
  const cleanerOnly = role === "cleaner";

  // Publish this build on load, then watch for a newer one. Any tab left open
  // across a deploy finds out within a minute instead of silently running old
  // code — and is blocked from saving in the meantime.
  useEffect(function() {
    let stopped = false;
    (async function() {
      const latest = await publishBuild();
      if (!stopped && latest && buildIsNewer(latest, APP_BUILD)) setStaleBuild(latest);
    })();
    const t = setInterval(async function() {
      const latest = await fetchLatestBuild();
      if (!stopped && latest && buildIsNewer(latest, APP_BUILD)) setStaleBuild(latest);
    }, 60000);
    // Also check the moment the tab is brought back to the front.
    function onFocus() {
      fetchLatestBuild().then(function(latest) {
        if (!stopped && latest && buildIsNewer(latest, APP_BUILD)) setStaleBuild(latest);
      });
    }
    window.addEventListener("focus", onFocus);
    return function() { stopped = true; clearInterval(t); window.removeEventListener("focus", onFocus); };
  }, []);

  // Open a specific event's detail page from anywhere — used by the link on a
  // letting that's attached to an event.
  const goToEvent = (id) => {
    const b = bookings.find(x => String(x.id) === String(id));
    if (!b) { alert("That event could not be found — it may have been deleted."); return; }
    handleEdit(b.id);
  };

  // Navigate straight to a specific enquiry's detail page (used from Viewings + Year Calendar)
  const goToEnquiry = (id) => { setFocusEnquiryId(id); setView("enquiries"); };
  // Navigate straight to a specific lettings booking (used from the Bookings accommodation column)
  const goToAccomBooking = (id) => { setFocusAccomBookingId(id); setView("lettings"); };

  // Start a new accommodation booking for an event: every property, the night
  // before and the night of the event, pre-linked so it's billed via the event.
  const addAccomForEvent = (ev) => {
    if (!ev || !isValidEventDate(ev.date)) { alert("Set a valid event date first."); return; }
    setAccomPrefill({
      eventId: ev.id,
      checkIn: addDaysIso(ev.date, -1),
      checkOut: addDaysIso(ev.date, 1),   // 2 nights: day before + event day
      guestName: ev.couple || "",
      email: ev.email || "",
      bookingType: /wedding/i.test(ev.eventType || "") ? "Wedding" : ""
    });
    setView("lettings");
  };

  useEffect(()=>{
    (async()=>{
      try {
        const raw = (await sbGet(BOOKING_STORAGE)) || INITIAL_BOOKINGS;
        const migrated = raw.map(b => ({
          ...b,
          amlyBooked:    b.amlyBooked === true ? "yes" : b.amlyBooked === false ? "no" : b.amlyBooked || "no",
          hamletBooked:  b.hamletBooked === true ? "yes" : b.hamletBooked === false ? "no" : b.hamletBooked || "no",
          campingBooked: b.campingBooked === true ? "yes" : b.campingBooked === false ? "no" : b.campingBooked || "no",
          status: b.status || "Confirmed",
          eventType: b.eventType || "Wedding (Peak)",
          depositPaid: b.depositPaid || false,
          xeroContactId: b.xeroContactId || "",
        }));
        setBookings(migrated);
      } catch { setBookings(INITIAL_BOOKINGS); }
      try { const r = await sbGet(STAFF_STORAGE); setStaff(r || INITIAL_STAFF); } catch { setStaff(INITIAL_STAFF); }
      try { const r = await sbGet(ENQUIRIES_STORAGE); setEnquiries(r || []); } catch { setEnquiries([]); }
        try { const r = await sbGet(VR_STORAGE); setViewingRequests(r || []); } catch { setViewingRequests([]); }
        try { const r = await sbGet(VB_STORAGE); setViewingBlocks(r || []); } catch { setViewingBlocks([]); }
      try { const r = await sbGet(ACCOM_STORAGE); setAccomBookings((r||[]).map(normalizeAccom)); } catch { setAccomBookings([]); }
      try { const r = await sbGet(PROPERTIES_STORAGE); setAccomProperties(r||INITIAL_PROPERTIES); } catch { setAccomProperties(INITIAL_PROPERTIES); }
      try { const r = await sbGet(EVENT_INVOICES_STORAGE); setInvoiceRecords(r||[]); } catch { setInvoiceRecords([]); }
      setLoaded(true);
    })();
  },[]);

  // NOTE: there is deliberately no whole-array "saveBookings" at this level.
  // Writing the entire events array from a component's snapshot is what
  // destroyed records before. Use mutateBookings / saveBookingRecord /
  // patchBooking below, which all re-read from the server first.

  // ── Safe mutation of the events array ─────────────────────────────────────
  // Everything that changes events goes through here.
  //
  // The whole array lives under one Supabase key, so ANY save rewrites all of
  // it. Merging against React state is not enough: that state is a snapshot
  // taken when this tab loaded, so a save from a tab (or phone, or yesterday's
  // still-open window) that hasn't seen a newly-added event will write the
  // array back WITHOUT it — destroying records it never knew existed. That is
  // how whole events and a batch of Xero contact IDs disappeared.
  //
  // So: re-read the current array from Supabase, apply the change to THAT, and
  // write it straight back. If the read fails we abort rather than write, since
  // writing from an unknown base is exactly what causes the damage.
  const mutateBookings = useCallback(async (mutator) => {
    // Refuse to write from a tab running an out-of-date build. An old tab holds
    // old code AND an old snapshot of the data, so letting it save is exactly
    // how events and Xero ids were wiped after a fix had already gone live.
    const latest = await fetchLatestBuild();
    if (latest && buildIsNewer(latest, APP_BUILD)) {
      setStaleBuild(latest);
      throw new Error(
        "This page is running an old version (" + APP_BUILD + "; " + latest + " is live). " +
        "Nothing was saved — reload the page and try again."
      );
    }

    let server;
    try {
      server = await sbGet(BOOKING_STORAGE);
    } catch (e) {
      console.error("Aborting save — could not read current bookings:", e);
      throw new Error("Could not reach the database, so nothing was saved. Please try again.");
    }
    const base = Array.isArray(server) ? server : [];
    const next = mutator(base);
    if (!Array.isArray(next)) throw new Error("Internal error: bookings mutation produced no array");
    // Tripwire: a single edit should never remove more than the one record a
    // delete targets. Anything larger means we're about to write a truncated
    // array — refuse rather than destroy records, and say so loudly.
    if (next.length < base.length - 1) {
      const lost = base.length - next.length;
      console.error("Refusing to save: would drop " + lost + " events", { base: base.length, next: next.length });
      throw new Error(
        "Save cancelled — this would have deleted " + lost + " events. Nothing was changed. " +
        "Please reload the page and try again."
      );
    }
    await sbSet(BOOKING_STORAGE, next);
    setBookings(next);
    return next;
  }, []);

  // Insert or update one event, leaving every other record exactly as the
  // server has it.
  const saveBookingRecord = useCallback((id, data) => {
    return mutateBookings(function(base) {
      let found = false;
      let next = base.map(function(b) {
        if (String(b.id) === String(id)) { found = true; return Object.assign({}, data, { id: b.id }); }
        return b;
      });
      if (!found) next = next.concat([Object.assign({}, data, { id: id })]);
      return next.sort(function(a, b) { return (a.date || "") > (b.date || "") ? 1 : -1; });
    });
  }, [mutateBookings]);

  // Apply a change to a single event without touching the rest.
  const patchBooking = useCallback((id, patchFn) => {
    return mutateBookings(function(base) {
      return base.map(function(b) { return String(b.id) === String(id) ? patchFn(b) : b; });
    });
  }, [mutateBookings]);
  const saveStaff    = useCallback(async data=>{ setStaff(data);    try{await sbSet(STAFF_STORAGE, data);}catch(e){console.error(e);} },[]);

  // Delete a lettings booking outright. Used for unpaid online bookings that
  // are never going to be paid — reads the server's copy first so a booking
  // added elsewhere since this tab loaded isn't wiped along with it.
  const deleteAccomBooking = useCallback(async (booking) => {
    try {
      const server = await sbGet(ACCOM_STORAGE);
      const base = Array.isArray(server) ? server : [];
      const next = base.filter(function(b) { return String(b.id) !== String(booking.id); });
      await sbSet(ACCOM_STORAGE, next);
      setAccomBookings(next);
    } catch (e) {
      console.error("Could not delete booking:", e);
      alert("Could not delete that booking — the database didn't respond. Nothing was changed.");
    }
  }, []);

  const saveAccomBooking = useCallback(async (bookingId, patch) => {
    setAccomBookings(function(prev) {
      var next = prev.map(function(b) { return b.id===bookingId ? Object.assign({}, b, patch) : b; });
      sbSet(ACCOM_STORAGE, next).catch(function(e){ console.error(e); });
      return next;
    });
  }, []);

  // createdAt is new on events; older records simply don't have one, which is
  // correct — they weren't created recently and shouldn't appear as new.
  const emptyBooking = ()=>({ createdAt: new Date().toISOString(), couple:"", date:"", endDate:"", status:"Confirmed", eventType:"Wedding (Peak)", setup:[], dayManager:[], dayStaff:[], barSupervisor:[], sunday:[], bar:[], dayHandy:[], eveHandy:[], mealGuests:"", mealChildren:"", mealBabies:"", eveGuests:"", phone:"", email:"", email2:"", email3:"", ceremony:"", guestArrivalTime:"", caterers:"", foodTruck:"", eveFood:"", otherVendors:"", amlyBooked:"undecided", amlyFee:"", amly50Paid:false, amly100Paid:false, hamletBooked:"undecided", hamletFee:"", hamlet50Paid:false, hamlet100Paid:false, campingBooked:"undecided", campingFee:"", camping50Paid:false, camping100Paid:false, nonStandard:"", venueFee:"", deposit:"", depositPaid:false, xeroContactId:"", payment2:"", finalPayment:"", extras:"", corkage:"", corkageTotal:"", pets:"", barTakeGross:"", circaCommission:"", hairdresser:"", makeup:"", florist:"", band:"", paSystem:"", notes:"", hoursWorked:{}, contacts:[], invoiceEmails:"" });

  const safeArr = v => Array.isArray(v) ? v : [];
  const [confirmDlg, setConfirmDlg] = useState(null);
  const askConfirm = (message, subMessage, onConfirm) => setConfirmDlg({ message, subMessage, onConfirm });

  const handleNew    = ()=>{ setFormData(emptyBooking()); setEditId(null); setView("form"); };
  const handleEdit   = id=>{ const b=bookings.find(x=>x.id===id); setFormData({...b, setup:safeArr(b.setup), dayManager:safeArr(b.dayManager), dayStaff:safeArr(b.dayStaff), barSupervisor:safeArr(b.barSupervisor), sunday:safeArr(b.sunday), bar:safeArr(b.bar), dayHandy:safeArr(b.dayHandy), eveHandy:safeArr(b.eveHandy) }); setEditId(id); setView("form"); };
  const handleDelete = id => {
    const b = bookings.find(x=>x.id===id);
    askConfirm("Delete this booking?", `"${b?.couple||"This booking"}" will be permanently removed.`,
      async () => {
        setConfirmDlg(null);
        // Delete against the server's current array, not this tab's snapshot —
        // otherwise deleting one event also silently removes any events added
        // elsewhere since this tab loaded.
        await mutateBookings(function(base) {
          return base.filter(function(x) { return String(x.id) !== String(id); });
        });
      });
  };
  // stayOpen: save and remain on the form, so several tabs can be filled in
  // without bouncing back to the list each time.
  const handleSubmit = async (stayOpen)=>{
    if(!formData.couple||!formData.date){ alert("Event name and date are required."); return; }
    // Single-record merge against the latest state (see saveBookingRecord) so
    // an explicit Save can't roll back edits made elsewhere in the meantime.
    const id = editId != null ? editId : nextBookingId(bookings);
    await saveBookingRecord(id, {...formData, id, createdAt: formData.createdAt || new Date().toISOString()});

    if (stayOpen) {
      // Keep editing the record that was written. Without this a new event
      // would be saved again as a second record on the next press.
      setEditId(id);
      setFormData(function(f){ return Object.assign({}, f, { id: id }); });
      return;
    }
    setView("list");
  };

  const handleConvertEnquiryToBooking = (enq) => {
    const sortedContacts = [...(enq.contacts||[])].sort((a,b)=> (a.date||"") > (b.date||"") ? 1 : -1);
    const methodLabel = m => m==="phone" ? "Phone" : m==="other" ? "Other" : "Email";
    const contactLines = sortedContacts.map(c => `${c.date||"No date"} (${methodLabel(c.method)}): ${c.note||""}`).join("\n\n");

    const extraLines = [];
    if (enq.source) extraLines.push(`Source: ${enq.source}`);
    if (enq.eventType) extraLines.push(`Enquiry event type: ${enq.eventType}`);
    if (enq.numbers) extraLines.push(`Numbers (from enquiry): ${enq.numbers}`);
    if (enq.datePreference) extraLines.push(`Date preference (from enquiry): ${enq.datePreference}`);

    const notesParts = [`Converted from enquiry${enq.name ? ` — ${enq.name}` : ""}.`];
    if (extraLines.length) notesParts.push(extraLines.join("\n"));
    if (contactLines) notesParts.push(`Contact History:\n${contactLines}`);

    // Pick up an ISO date (YYYY-MM-DD) if the date preference happens to contain one
    const dateMatch = (enq.datePreference||"").match(/\d{4}-\d{2}-\d{2}/);

    const newBooking = {
      ...emptyBooking(),
      couple: enq.name || "",
      date: dateMatch ? dateMatch[0] : "",
      email: enq.email || "",
      phone: enq.phone || "",
      notes: notesParts.join("\n\n"),
      viewings: enq.viewings || [],
      files: enq.files || [],
    };

    const newId = nextBookingId(bookings);
    const withId = { ...newBooking, id:newId };
    saveBookingRecord(newId, withId);

    setFormData(withId);
    setEditId(newId);
    setView("form");
  };

  const emptyStaff = ()=>({ id:"", name:"", email:"", phone:"", rate:"", dob:"", role:"Bar Staff", active:true, notes:"" });
  const handleNewStaff    = ()=>{ setStaffForm(emptyStaff()); setEditStaffId(null); };
  const handleEditStaff   = id=>{ const s=staff.find(x=>x.id===id); setStaffForm({...s}); setEditStaffId(id); };
  // Strip a person out of every rota they're assigned to — but leave them on
  // any event where hours are logged against them, since that's a pay record.
  // Without this a deleted person stays on rotas forever and can't be removed,
  // because the UI only offers to untick people who still exist.
  const removeStaffFromRotas = useCallback(async (staffId) => {
    let cleared = 0, kept = 0;
    await mutateBookings(function(base) {
      return base.map(function(b) {
        const hrs = Number((b.hoursWorked || {})[staffId] || 0);
        if (hrs > 0) { kept++; return b; }
        let touched = false;
        const next = Object.assign({}, b);
        ["setup"].concat(STAFFING_FIELDS).forEach(function(f) {
          const arr = b[f];
          if (!Array.isArray(arr) || arr.indexOf(staffId) === -1) return;
          next[f] = arr.filter(function(x) { return x !== staffId; });
          touched = true;
        });
        if (touched) cleared++;
        return touched ? next : b;
      });
    });
    return { cleared: cleared, kept: kept };
  }, [mutateBookings]);

  const handleDeleteStaff = id => {
    const s = staff.find(x=>x.id===id);
    const onRotas = bookings.filter(b => ["setup"].concat(STAFFING_FIELDS)
      .some(f => Array.isArray(b[f]) && b[f].indexOf(id) !== -1)).length;
    const withHours = bookings.filter(b => Number((b.hoursWorked||{})[id] || 0) > 0).length;
    askConfirm("Remove this staff member?",
      `${s?.name||"This person"} will be removed from the staff list` +
      (onRotas ? `, and taken off ${onRotas} rota${onRotas!==1?"s":""}` : "") +
      (withHours ? `. They will stay on ${withHours} event${withHours!==1?"s":""} where hours are recorded against them, so pay records aren't lost` : "") + ".",
      async () => {
        setConfirmDlg(null);
        try { await removeStaffFromRotas(id); } catch (e) { console.error(e); }
        await saveStaff(staff.filter(x=>x.id!==id));
      });
  };
  const handleSubmitStaff = async ()=>{
    if(!staffForm.id||!staffForm.name){ alert("Initials and name are required."); return; }
    let updated;
    if(editStaffId) updated=staff.map(s=>s.id===editStaffId?{...staffForm}:s);
    else { if(staff.find(s=>s.id===staffForm.id)){ alert(`Initials "${staffForm.id}" already exists.`); return; } updated=[...staff,staffForm]; }
    await saveStaff(updated); setStaffForm(null); setEditStaffId(null);
  };

  const filtered = bookings.filter(b=>{ const q=search.toLowerCase(); return !q||(b.couple||"").toLowerCase().includes(q)||(b.email||"").toLowerCase().includes(q)||(b.date||"").includes(q); });

  const saveInvoiceRecords = useCallback(async (next) => {
    setInvoiceRecords(next);
    try { await sbSet(EVENT_INVOICES_STORAGE, next); } catch(e) { console.error(e); }
  }, []);

  // How many invoice stages are due to be raised right now (badge on the
  // Invoices button). Counts unpushed stages whose ready date has arrived,
  // plus any pushed draft whose figures have since changed.
  const invoiceDueCount = (function() {
    const todayIso = new Date().toISOString().slice(0,10);
    let n = 0;
    bookings.forEach(function(ev) {
      if (!isValidEventDate(ev.date)) return;
      if (!isFutureEvent(ev, todayIso)) return;  // past events are never invoiceable
      if (!isInvoiceableYear(ev)) return;        // pre-cutover seasons were invoiced by hand
      computeEventInvoiceStages(ev, accomBookings).forEach(function(st) {
        const pushed = findPushedInvoice(invoiceRecords, ev.id, st.stage);
        if (pushed) {
          if (pushed.fingerprint !== invoiceLinesFingerprint(st.lines)) n++;
        } else if (st.total > 0 && (!st.readyFrom || st.readyFrom <= todayIso)) {
          n++;
        }
      });
    });
    return n;
  })();

  if(!loaded) return <div style={{ display:"flex",alignItems:"center",justifyContent:"center",height:"100vh",background:T.bg,color:T.accent,fontFamily:"system-ui,sans-serif",fontSize:20 }}>Loading…</div>;

  // Restricted logins: one section, no navigation to anything else.
  if (barOnly || cleanerOnly) {
    const shellTitle = barOnly ? "Bar Management" : "Housekeeping";
    return (
      <div style={{ minHeight:"100vh", background:T.bg, color:T.text, fontFamily:"system-ui,-apple-system,sans-serif" }}>
        <MobileGlobalStyles/>
        {staleBuild && (
          <div style={{ position:"fixed", top:0, left:0, right:0, zIndex:9999, background:"#dc2626", color:"#fff",
            padding:"12px 20px", display:"flex", alignItems:"center", gap:14, flexWrap:"wrap" }}>
            <span style={{ fontSize:14, fontWeight:700 }}>A newer version is available</span>
            <button onClick={function(){ window.location.reload(true); }}
              style={{ background:"#fff", color:"#dc2626", border:"none", padding:"9px 20px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:800 }}>
              Reload now
            </button>
          </div>
        )}
        <header style={{ background:"#fff", borderBottom:`2px solid ${T.border}`, padding:"14px 24px", display:"flex", alignItems:"center", gap:14 }}>
          <img src={`data:image/png;base64,${LOGO_B64}`} alt="Hawthbush Farm" style={{ height:40, width:"auto" }} />
          <span style={{ fontSize:16, fontWeight:700, color:T.midBlue }}>{shellTitle}</span>
          <span style={{ marginLeft:"auto", fontSize:11, color:T.textLight }}>build {APP_BUILD}</span>
          {onSignOut && (
            <button onClick={onSignOut}
              style={{ background:"none", border:`1.5px solid ${T.border}`, color:T.textMid, padding:"7px 14px", borderRadius:7, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600 }}>
              Sign out
            </button>
          )}
        </header>
        <div className="app-shell" style={{ maxWidth:1240, margin:"0 auto", padding:"24px 24px 60px" }}>
          {barOnly ? <BarView/> : <CleanerView/>}
        </div>
      </div>
    );
  }

  return (
    <div style={{ minHeight:"100vh", background:T.bg, color:T.text, fontFamily:"system-ui,-apple-system,sans-serif" }}>
      <MobileGlobalStyles/>

      {/* An out-of-date tab is dangerous, not just inconvenient — saving from
          it can destroy records. Make it impossible to miss. */}
      {staleBuild && (
        <div style={{ position:"fixed", top:0, left:0, right:0, zIndex:9999, background:"#dc2626", color:"#fff",
          padding:"12px 20px", display:"flex", alignItems:"center", gap:14, flexWrap:"wrap",
          boxShadow:"0 2px 12px rgba(0,0,0,.25)" }}>
          <span style={{ fontSize:14, fontWeight:700 }}>A newer version of this app is available</span>
          <span style={{ fontSize:12, opacity:.9, flex:1, minWidth:220 }}>
            This page is running {APP_BUILD} and {staleBuild} is live. Saving is disabled until you reload,
            because an out-of-date page can overwrite newer data.
          </span>
          <button onClick={function(){ window.location.reload(true); }}
            style={{ background:"#fff", color:"#dc2626", border:"none", padding:"9px 20px", borderRadius:7,
              cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:800, whiteSpace:"nowrap" }}>
            Reload now
          </button>
        </div>
      )}
      {confirmDlg && <ConfirmDialog message={confirmDlg.message} subMessage={confirmDlg.subMessage} onConfirm={confirmDlg.onConfirm} onCancel={()=>setConfirmDlg(null)}/>}
      <Header view={view} setView={setView} onNew={handleNew} xeroToken={xeroToken} onXeroConnect={handleXeroConnect} onXeroDisconnect={handleXeroDisconnect} gmailToken={gmailToken} onGmailConnect={handleGmailConnect} onGmailDisconnect={handleGmailDisconnect} onCalendarTab={()=>{ setView("lettings"); setLettingsCalTrigger(function(n){ return n+1; }); }} onBack={goBack} canGoBack={viewHistory.length>0}/>
      <div className="app-shell" style={{ maxWidth:1240, margin:"0 auto", padding:"0 24px 60px" }}>
        {view==="home"    && <DashboardView bookings={bookings} viewingRequests={viewingRequests} setView={setView} xeroToken={xeroToken} onDeleteAccom={deleteAccomBooking} accomProperties={accomProperties} onOpenAccom={goToAccomBooking} onOpenEvent={goToEvent}/>}
        {view==="list"    && <ListView bookings={filtered} search={search} setSearch={setSearch} onEdit={handleEdit} onDelete={handleDelete} onNew={handleNew} staff={staff} accomBookings={accomBookings} onOpenAccom={goToAccomBooking} xeroToken={xeroToken} onOpenInvoices={()=>setView("invoices")} invoiceDueCount={invoiceDueCount}/>}
        {view==="invoices" && <InvoiceWorklistView bookings={bookings} accomBookings={accomBookings} records={invoiceRecords} onSaveRecords={saveInvoiceRecords} onBack={()=>setView("list")} onEdit={handleEdit} xeroToken={xeroToken}/>}
        {view==="form"    && <FormView formData={formData} setFormData={setFormData} onSubmit={handleSubmit} onCancel={()=>setView("list")} isEdit={!!editId} staff={staff} xeroToken={xeroToken} gmailToken={gmailToken} onDelete={editId ? ()=>handleDelete(editId) : null} accomBookings={accomBookings} accomProperties={accomProperties} onSaveAccomBooking={saveAccomBooking} onOpenAccomBooking={goToAccomBooking} allBookings={bookings} invoiceRecords={invoiceRecords} onSaveInvoiceRecords={saveInvoiceRecords} onAddAccom={addAccomForEvent}
          onAutoSave={async(fd)=>{
            // Only a name is required to start persisting. This previously also
            // required a date and returned silently otherwise, which meant edits
            // to any event with a missing date (e.g. a Xero contact ID typed
            // into one) were quietly thrown away with no indication at all.
            if(staleBuild) { const e=new Error("stale-build"); e.code="stale-build"; throw e; }
            if(!fd.couple) { const e=new Error("no-name"); e.code="no-name"; throw e; }
            if(editId) {
              await saveBookingRecord(editId, fd);
            } else {
              // First autosave of a brand-new booking: mint an id and remember it,
              // so subsequent autosaves update this same record instead of creating duplicates
              const newId=nextBookingId(bookings);
              setEditId(newId);
              setFormData(f=>({...f, id:newId}));
              await saveBookingRecord(newId, {...fd, id:newId, createdAt: fd.createdAt || new Date().toISOString()});
            }
          }}
        />}
        {view==="staff"   && <StaffView staff={staff} bookings={bookings} staffForm={staffForm} setStaffForm={setStaffForm} editStaffId={editStaffId} onNew={handleNewStaff} onEdit={handleEditStaff} onDelete={handleDeleteStaff} onPurgeOrphan={removeStaffFromRotas} onSubmit={handleSubmitStaff} onCancel={()=>{setStaffForm(null);setEditStaffId(null);}}/>}
        {view==="bar"        && <BarView/>}
        {view==="lettings"   && <LettingsView events={bookings} calendarTrigger={lettingsCalTrigger} setView={setView} setReportType={setReportType} focusBookingId={focusAccomBookingId} clearFocusBooking={()=>setFocusAccomBookingId(null)} prefillNew={accomPrefill} clearPrefillNew={()=>setAccomPrefill(null)} onOpenEvent={goToEvent}/>}
        {view==="enquiries"  && <EnquiriesView gmailToken={gmailToken} onConvertToBooking={handleConvertEnquiryToBooking} focusEnquiryId={focusEnquiryId} clearFocus={()=>setFocusEnquiryId(null)}/>}
        {view==="viewings"   && <ViewingsView bookings={bookings} setBookings={setBookings} setView={setView} setReportType={setReportType} onEditBooking={handleEdit}
          viewingRequests={viewingRequests} setViewingRequests={setViewingRequests}
          viewingBlocks={viewingBlocks} setViewingBlocks={setViewingBlocks}
          enquiries={enquiries} setEnquiries={setEnquiries}
          saveEnquiries={async(e)=>{ setEnquiries(e); await sbSet(ENQUIRIES_STORAGE,e); }}
          patchBooking={patchBooking}
          onSelectEnquiry={goToEnquiry}/>}
        {view==="boxoffice"  && <BoxOfficeView bookings={bookings}/>}
        {view==="reports"    && <ReportsView bookings={bookings} staff={staff} reportType={reportType} setReportType={setReportType} enquiries={enquiries} setView={setView} onEditBooking={handleEdit} onSelectEnquiry={goToEnquiry} accomBookings={accomBookings} accomProperties={accomProperties}/>}
        {view==="settings"   && <SettingsView xeroToken={xeroToken} onXeroConnect={handleXeroConnect} onXeroDisconnect={handleXeroDisconnect} gmailToken={gmailToken} onGmailConnect={handleGmailConnect} onGmailDisconnect={handleGmailDisconnect} setView={setView}/>}
      </div>
    </div>
  );
}

// ─── HEADER ───────────────────────────────────────────────────────────────────
function Header({ view, setView, onNew, xeroToken, onXeroConnect, onXeroDisconnect, gmailToken, onGmailConnect, onGmailDisconnect, onCalendarTab, onBack, canGoBack }) {
  // "calendar" is a virtual tab that maps to view="lettings" (calendar sub-tab)
  const tabs = [
    {id:"home",label:"Home"},
    {id:"calendar",label:"Calendar",virtual:true},
    {id:"lettings",label:"Lettings"},
    {id:"list",label:"Events"},
    {id:"enquiries",label:"Enquiries"},
    {id:"viewings",label:"Viewings"},
    {id:"bar",label:"Bar"},
    // Not "Events" — that has always meant weddings in this app.
    {id:"boxoffice",label:"Box Office"},
    {id:"reports",label:"Reports"},
    {id:"settings",label:"Settings"},
  ];
  const isXeroConnected  = !!xeroToken;
  const isGmailConnected = !!gmailToken;
  const isMobile = useIsMobile();
  const [menuOpen, setMenuOpen] = useState(false);
  // "calendar" virtual tab is active when we're on lettings (it switches to lettings calendar sub-tab)
  function isActive(t) {
    if (t.id === "calendar") return false; // never highlight calendar; lettings tab is the real home
    return view === t.id;
  }
  const connectButtons = (
    <>
      {isXeroConnected
        ? <button onClick={onXeroDisconnect} title="Disconnect Xero" style={{ background:"#e6f7fd", border:"1px solid #13B5EA", color:"#0e8ab0", padding:"5px 12px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600, display:"flex", alignItems:"center", gap:5 }}><span style={{ color:"#13B5EA" }}>✓</span> Xero</button>
        : <button onClick={onXeroConnect} style={{ background:"#13B5EA", border:"none", color:"#fff", padding:"5px 12px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600 }}>Connect Xero</button>
      }
      {isGmailConnected
        ? <button onClick={onGmailDisconnect} title="Disconnect Gmail" style={{ background:"#fef2f2", border:"1px solid #fca5a5", color:"#dc2626", padding:"5px 12px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600, display:"flex", alignItems:"center", gap:5 }}><span style={{ color:"#ea4335" }}>✓</span> Gmail</button>
        : <button onClick={onGmailConnect} style={{ background:"#ea4335", border:"none", color:"#fff", padding:"5px 12px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:600 }}>Connect Gmail</button>
      }
    </>
  );

  if (isMobile) {
    return (
      <header style={{ background:"#ffffff", borderBottom:`2px solid ${T.border}`, boxShadow:"0 2px 12px rgba(37,99,235,.08)", position:"relative" }}>
        <div style={{ padding:"0 14px", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
          <div style={{ display:"flex", alignItems:"center", padding:"8px 0" }}>
            <img src={`data:image/png;base64,${LOGO_B64}`} alt="Hawthbush Farm" style={{ height:38, width:"auto", imageRendering:"crisp-edges" }} />
          </div>
          <div style={{ display:"flex", alignItems:"center", gap:8 }}>
            {canGoBack && onBack && (
            <button onClick={onBack} title="Back to the previous page"
              style={{ background:"none", border:`1.5px solid ${T.border}`, borderRadius:7, width:34, height:34,
                cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
                fontSize:17, color:T.textMid, fontFamily:"inherit", flexShrink:0 }}>
              ←
            </button>
          )}
            <button onClick={onNew} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"8px 14px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>+ New</button>
            <button onClick={()=>setMenuOpen(function(v){ return !v; })} aria-label="Menu"
              style={{ background:"none", border:`1.5px solid ${T.border}`, borderRadius:6, width:38, height:38, cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center", fontSize:18, color:T.text }}>
              {menuOpen ? "✕" : "☰"}
            </button>
          </div>
        </div>
        {menuOpen && (
          <div style={{ position:"absolute", top:"100%", left:0, right:0, background:"#fff", borderBottom:`2px solid ${T.border}`, boxShadow:"0 8px 20px rgba(0,0,0,.12)", zIndex:50, maxHeight:"80vh", overflowY:"auto" }}>
            <nav style={{ display:"flex", flexDirection:"column", padding:"6px 0" }}>
              {tabs.map(t=>(
                <button key={t.id} onClick={function(){ setMenuOpen(false); if (t.virtual) onCalendarTab(); else setView(t.id); }}
                  style={{ background: isActive(t) ? T.accentLight : "none", border:"none", borderLeft: isActive(t) ? `3px solid ${T.accent}` : "3px solid transparent", color:isActive(t)?T.navActive:T.navInactive, fontFamily:"inherit", fontSize:15, fontWeight:isActive(t)?700:400, padding:"13px 18px", textAlign:"left", cursor:"pointer" }}>{t.label}</button>
              ))}
            </nav>
            <div style={{ display:"flex", gap:8, padding:"12px 18px", borderTop:`1px solid ${T.border}`, flexWrap:"wrap" }}>
              {connectButtons}
            </div>
          </div>
        )}
      </header>
    );
  }

  return (
    <header style={{ background:"#ffffff", borderBottom:`2px solid ${T.border}`, padding:"0 28px", display:"flex", alignItems:"center", gap:0, boxShadow:"0 2px 12px rgba(37,99,235,.08)" }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginRight:36, padding:"8px 0", flexShrink:0 }}>
        {canGoBack && onBack && (
          <button onClick={onBack} title="Back to the previous page"
            style={{ background:"none", border:`1.5px solid ${T.border}`, borderRadius:8, width:36, height:36,
              cursor:"pointer", display:"flex", alignItems:"center", justifyContent:"center",
              fontSize:18, color:T.textMid, fontFamily:"inherit" }}>
            ←
          </button>
        )}
        <img src={`data:image/png;base64,${LOGO_B64}`} alt="Hawthbush Farm" style={{ height:52, width:"auto", imageRendering:"crisp-edges" }} />
      </div>
      <nav style={{ display:"flex", gap:0, flex:1 }}>
        {tabs.map(t=>(
          <button key={t.id} onClick={t.virtual ? onCalendarTab : ()=>setView(t.id)}
            style={{ background:"none", border:"none", color:isActive(t)?T.navActive:T.navInactive, fontFamily:"inherit", fontSize:14, fontWeight:isActive(t)?700:400, padding:"22px 20px 18px", cursor:"pointer", borderBottom:isActive(t)?`3px solid ${T.accent}`:"3px solid transparent", transition:"all .2s", letterSpacing:.2 }}>{t.label}</button>
        ))}
        <div style={{ marginLeft:"auto", display:"flex", alignItems:"center", gap:6, paddingRight:8 }}>
          {connectButtons}
        </div>
      </nav>
      <button onClick={onNew} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"9px 22px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:600, boxShadow:"0 2px 8px rgba(30,77,140,.25)", flexShrink:0 }}>
        + New Booking
      </button>
    </header>
  );
}

// ─── BOOKINGS LIST ────────────────────────────────────────────────────────────
// A valid ISO date we can actually sort/compare on. Anything else (missing,
// null, half-typed) is treated as "needs attention" rather than being silently
// dropped from the list.
function isValidEventDate(d) {
  return typeof d === "string" && /^\d{4}-\d{2}-\d{2}$/.test(d);
}

// Next free numeric id. Math.max(0, ...ids) returns NaN if ANY id is
// non-numeric (undefined, a string, etc.), which would save the new event with
// id NaN — and NaN serialises to null in JSON, so the record would come back
// with no usable id and could no longer be matched or linked. Filtering to real
// numbers first keeps id allocation safe whatever else is in the data.
function nextBookingId(bookings) {
  var nums = (bookings || [])
    .map(function(b) { return Number(b && b.id); })
    .filter(function(n) { return Number.isFinite(n); });
  return (nums.length ? Math.max.apply(null, nums) : 0) + 1;
}

// Events that share one or more days with the given date range.
// Used to warn (never block) when double-booking the venue.
function overlappingEvents(bookings, date, endDate, ignoreId) {
  if (!isValidEventDate(date)) return [];
  var start = date;
  var end = (isValidEventDate(endDate) && endDate > date) ? endDate : date;
  return (bookings || []).filter(function(b) {
    if (ignoreId != null && String(b.id) === String(ignoreId)) return false;
    if (!isValidEventDate(b.date)) return false;
    var bStart = b.date;
    var bEnd = eventEndDate(b) || b.date;
    // Inclusive overlap on both ends — events occupy whole days.
    return bStart <= end && bEnd >= start;
  });
}

// The last day an event actually occupies — multi-day events run date..endDate.
function eventEndDate(b) {
  if (!b) return null;
  if (isValidEventDate(b.endDate) && isValidEventDate(b.date) && b.endDate > b.date) return b.endDate;
  return isValidEventDate(b.date) ? b.date : null;
}

// Buckets are exhaustive: every booking lands in exactly one, so nothing can
// disappear from the Events tab. Previously an event whose date was missing or
// null matched neither `date >= today` nor `date < today` (both comparisons are
// false against undefined/null) and vanished from the list entirely while still
// existing in the data — which is how an event could be linked from a lettings
// booking yet be nowhere to be found here.
function classifyEventRow(b, today) {
  if (!isValidEventDate(b.date)) return "problem";
  var end = eventEndDate(b);
  // An event that started earlier but is still running counts as current.
  return (end >= today) ? "upcoming" : "past";
}

// ─── INVOICE WORKLIST ─────────────────────────────────────────────────────────
// Pushes one stage of one event to Xero. Kept at module scope; takes the token
// getter so it can reuse the existing sessionStorage/refresh flow.
// A valid token that is guaranteed to carry a tenant_id.
async function xeroTokenWithTenant() {
  const token = await xeroGetValidToken();
  if (!token) throw new Error("Not connected to Xero — connect it in the header first.");

  if (!token.tenant_id) {
    const tenantsRes = await fetch("/api/xero-connections", {
      headers: { Authorization: "Bearer " + token.access_token, "Content-Type": "application/json" }
    });
    if (!tenantsRes.ok) throw new Error("Could not fetch Xero organisations");
    const tenants = await tenantsRes.json();
    if (!tenants.length) throw new Error("No Xero organisations found");
    token.tenant_id = tenants[0].tenantId;
    xeroSetToken(token);
  }
  return token;
}

// Look the customer up in Xero by the "YY-MM Couple Name" convention and
// create it if it isn't there. Returns the ContactID either way, so pressing
// the button on an event whose customer already exists simply adopts it.
async function xeroFindOrCreateContact(ev) {
  const token = await xeroTokenWithTenant();
  const emails = parseInvoiceEmails(ev);
  if (!emails.length && (ev.email || "").trim()) emails.push(ev.email.trim());

  const res = await fetch("/.netlify/functions/xero-invoice", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      action: "contact",
      accessToken: token.access_token,
      tenantId: token.tenant_id,
      themeName: XERO_BRANDING_THEME,
      contactNames: [xeroContactName(ev), xeroContactNameLegacy(ev)],
      emails: emails
    })
  });
  const data = await res.json();
  if (!res.ok || data.error) throw new Error(data.error || "Could not create the contact");
  return data;
}

async function pushInvoiceToXero(ev, stageObj, accomBookings) {
  const token = await xeroTokenWithTenant();

  const emails = parseInvoiceEmails(ev);
  if (!emails.length && (ev.email || "").trim()) emails.push(ev.email.trim());

  const res = await fetch("/.netlify/functions/xero-invoice", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      action: "push",
      accessToken: token.access_token,
      tenantId: token.tenant_id,
      themeName: XERO_BRANDING_THEME,
      contactId: (ev.xeroContactId || "").trim() || null,
      contactNames: [xeroContactName(ev), xeroContactNameLegacy(ev)],
      emails: emails,
      invoiceDate: stageObj.invoiceDate || new Date().toISOString().slice(0, 10),
      dueDate: stageObj.invoiceDate || new Date().toISOString().slice(0, 10),
      reference: eventTypeLabel(ev) + " " + fmtDateLong(ev.date),
      lines: stageObj.lines
    })
  });
  const data = await res.json();
  if (!res.ok || data.error) throw new Error(data.error || "Push failed");
  return data;
}

const XERO_ORG_SHORTCODE = "!qhzr2";
function xeroInvoiceUrl(invoiceId) {
  return "https://go.xero.com/app/" + XERO_ORG_SHORTCODE + "/invoicing/view/" + invoiceId;
}
function invMoney(n) {
  return "£" + Number(n || 0).toLocaleString("en-GB", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

// Payment state of a linked invoice, taken from the live Xero record.
function XeroInvoiceSummary({ linked, xeroInv, onUnlink }) {
  const status  = String((xeroInv && xeroInv.Status) || "").toUpperCase();
  const total   = xeroInv ? Number(xeroInv.Total || 0) : Number(linked.total || 0);
  const due     = xeroInv ? Number(xeroInv.AmountDue || 0) : null;
  const paidAmt = xeroInv ? Number(xeroInv.AmountPaid || 0) : null;

  let badge;
  if (!xeroInv)                       badge = { t:"In Xero",    bg:"#eef4fd", c:T.midBlue, b:T.border };
  else if (status === "PAID")         badge = { t:"Paid",       bg:T.greenBg, c:T.green,   b:"#86efac" };
  else if (status === "DRAFT")        badge = { t:"Draft",      bg:"#f1f5f9", c:"#64748b", b:"#cbd5e1" };
  else if (status === "VOIDED")       badge = { t:"Voided",     bg:"#fef2f2", c:"#dc2626", b:"#fecaca" };
  else if (paidAmt > 0 && due > 0)    badge = { t:"Part paid",  bg:"#fffbeb", c:"#92400e", b:"#fde68a" };
  else                                badge = { t:"Awaiting payment", bg:"#fffbeb", c:"#92400e", b:"#fde68a" };

  return (
    <span style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", justifyContent:"flex-end" }}>
      <span style={{ fontSize:11, fontWeight:700, padding:"3px 9px", borderRadius:10, background:badge.bg, color:badge.c, border:`1px solid ${badge.b}` }}>
        {badge.t}
      </span>
      <span style={{ fontSize:12, color:T.textMid }}>
        {invMoney(total)}
        {due > 0 && due !== total ? <span style={{ color:T.textLight }}> · {invMoney(due)} due</span> : null}
      </span>
      {linked.xeroInvoiceId && (
        <a href={xeroInvoiceUrl(linked.xeroInvoiceId)} target="_blank" rel="noreferrer"
          style={{ background:"#13B5EA", color:"#fff", borderRadius:5, padding:"3px 10px", fontSize:11, fontWeight:700, textDecoration:"none", whiteSpace:"nowrap" }}>
          {linked.invoiceNumber || "View"} ↗
        </a>
      )}
      <button onClick={onUnlink} title="Unlink this invoice — the stage becomes available to generate again"
        style={{ background:"none", border:`1px solid ${T.border}`, color:T.textLight, padding:"3px 8px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:11 }}>Unlink</button>
    </span>
  );
}

function InvoiceStageRow({ ev, stageObj, linked, drifted, blockers, busy, candidates, xeroInv, onPush, onLink, onUnlink, onOpenEvent }) {
  const canPush = !linked && !blockers.length && stageObj.total > 0 && !busy;
  return (
    <div style={{ borderTop:`1px solid ${T.border}`, padding:"10px 16px", display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
      <button onClick={onOpenEvent} title="Open this event"
        style={{ background:"none", border:"none", padding:0, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700,
          color:T.accent, textDecoration:"underline", textDecorationStyle:"dotted", textUnderlineOffset:3, textAlign:"left",
          flex:1, minWidth:150, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
        {ev.couple || "(no name)"}
      </button>
      <span style={{ fontSize:12, color:T.accent, fontWeight:600, width:95, flexShrink:0 }}>{fmtDate(ev.date)}</span>
      <span style={{ fontSize:11, color:T.textLight, width:95, flexShrink:0 }}>
        {stageObj.invoiceDate ? "inv " + fmtDate(stageObj.invoiceDate) : "at booking"}
      </span>
      <span style={{ fontSize:14, fontWeight:700, color:T.text, width:95, textAlign:"right", flexShrink:0 }}>
        {invMoney(stageObj.total)}
      </span>

      {linked ? (
        <span style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", justifyContent:"flex-end", minWidth:280 }}>
          {drifted && (
            <span title="The event or accommodation figures have changed since this invoice was raised."
              style={{ fontSize:11, fontWeight:700, padding:"3px 9px", borderRadius:10, background:"#fffbeb", color:"#92400e", border:"1px solid #fde68a" }}>
              Figures changed
            </span>
          )}
          <XeroInvoiceSummary linked={linked} xeroInv={xeroInv} onUnlink={onUnlink}/>
        </span>
      ) : blockers.length ? (
        <span style={{ fontSize:11, color:T.red, minWidth:280, textAlign:"right" }}>{blockers.join(" · ")}</span>
      ) : (
        <span style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", justifyContent:"flex-end", minWidth:280 }}>
          {candidates && candidates.length > 0 && (
            <select defaultValue="" onChange={function(e){ if(e.target.value) onLink(e.target.value); }}
              style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:11, padding:"5px 8px", maxWidth:210 }}>
              <option value="">Link existing invoice…</option>
              {candidates.map(function(inv){
                return <option key={inv.InvoiceID} value={inv.InvoiceID}>
                  {(inv.InvoiceNumber||"(no number)") + " · " + (xeroDateToIso(inv.DateString||inv.Date)||"") + " · " + invMoney(Number(inv.Total||0))}
                </option>;
              })}
            </select>
          )}
          <button onClick={onPush} disabled={!canPush}
            style={{ background: canPush ? T.midBlue : "#c7c2b8", color:"#fff", border:"none", padding:"7px 16px", borderRadius:6,
              cursor: canPush ? "pointer" : "not-allowed", fontFamily:"inherit", fontSize:12, fontWeight:700 }}>
            {busy ? "Generating…" : "Generate"}
          </button>
        </span>
      )}
    </div>
  );
}

function InvoiceWorklistView({ bookings, accomBookings, records, onSaveRecords, onBack, onEdit, xeroToken }) {
  const today = new Date().toISOString().slice(0,10);
  const [busyKey, setBusyKey] = useState(null);
  const [msg, setMsg] = useState(null);
  const [showAll, setShowAll] = useState(false);
  const [xeroByContact, setXeroByContact] = useState(null); // null = not loaded yet
  const [xeroErr, setXeroErr] = useState(null);
  const [autoLinked, setAutoLinked] = useState(0);
  const autoRunRef = useRef(false);

  // Only future events, and only from the cutover year onwards — the 2026
  // season and earlier were invoiced manually and are already correct.
  const allFuture = (bookings||[]).filter(function(ev) {
    return isFutureEvent(ev, today) && (ev.couple || isValidEventDate(ev.date));
  });
  const futureEvents = allFuture.filter(isInvoiceableYear);
  const preCutoverCount = allFuture.length - futureEvents.length;

  // ── Pull existing invoices for every linked Xero contact, in one call ──────
  useEffect(function() {
    if (!xeroToken) { setXeroByContact({}); return; }
    const ids = [];
    futureEvents.forEach(function(ev) {
      const cid = (ev.xeroContactId||"").trim();
      if (cid && ids.indexOf(cid) === -1) ids.push(cid);
    });
    if (!ids.length) { setXeroByContact({}); return; }
    let cancelled = false;
    (async function() {
      try {
        const map = {};
        // Xero caps URL length, so chunk the contact list.
        for (let i = 0; i < ids.length; i += 40) {
          const chunk = ids.slice(i, i + 40);
          const data = await xeroFetch("Invoices?ContactIDs=" + chunk.join(",") + "&order=Date DESC");
          ((data && data.Invoices) || []).forEach(function(inv) {
            const cid = inv.Contact && inv.Contact.ContactID;
            if (!cid) return;
            if (!map[cid]) map[cid] = [];
            map[cid].push(inv);
          });
        }
        if (!cancelled) { setXeroByContact(map); setXeroErr(null); }
      } catch (e) {
        if (!cancelled) { setXeroByContact({}); setXeroErr(String(e.message||e)); }
      }
    })();
    return function(){ cancelled = true; };
  }, [xeroToken, bookings.length]);

  // ── Auto-link exact matches once the Xero data has arrived ────────────────
  // Only runs once per mount, and only creates links for stages that have no
  // record yet. Every auto-link is reversible via Unlink.
  useEffect(function() {
    if (!xeroByContact || autoRunRef.current) return;
    autoRunRef.current = true;
    const claimed = (records||[]).map(function(r){ return r.xeroInvoiceId; }).filter(Boolean);
    const additions = [];
    futureEvents.forEach(function(ev) {
      const cid = (ev.xeroContactId||"").trim();
      if (!cid || !xeroByContact[cid]) return;
      const stages = computeEventInvoiceStages(ev, accomBookings);
      const unmatchedStages = stages.filter(function(st){ return !findPushedInvoice(records, ev.id, st.stage); });
      if (!unmatchedStages.length) return;
      const matches = matchStagesToXeroInvoices(unmatchedStages, xeroByContact[cid], claimed);
      unmatchedStages.forEach(function(st) {
        const inv = matches[st.stage];
        if (!inv) return;
        claimed.push(inv.InvoiceID);
        additions.push({
          id: "inv_" + ev.id + "_" + st.stage,
          eventId: ev.id, stage: st.stage,
          invoiceDate: st.invoiceDate, total: st.total,
          lines: st.lines, fingerprint: invoiceLinesFingerprint(st.lines),
          xeroInvoiceId: inv.InvoiceID, invoiceNumber: inv.InvoiceNumber || "",
          pushedAt: new Date().toISOString(), source: "auto"
        });
      });
    });
    if (additions.length) {
      setAutoLinked(additions.length);
      onSaveRecords((records||[]).concat(additions));
    }
  }, [xeroByContact]);

  const allClaimedIds = (records||[]).map(function(r){ return r.xeroInvoiceId; }).filter(Boolean);

  // ── Build one bucket per stage ────────────────────────────────────────────
  // Each stage has its own natural window of relevance:
  //   1  Deposit — anything not yet raised (in practice, recent bookings)
  //   2  1 Dec   — from mid-November of the year before the event
  //   3  Final   — events happening within the next 8 weeks
  // "Show everything" lifts the windows so nothing is ever truly hidden.
  const STAGE3_WEEKS = 8;
  const stage3Horizon = addDaysIso(today, STAGE3_WEEKS * 7);

  function inStageWindow(ev, st) {
    if (showAll) return true;
    if (st.stage === 3) return !!(ev.date && stage3Horizon && ev.date <= stage3Horizon);
    return !st.readyFrom || st.readyFrom <= today;
  }

  const buckets = { 1: [], 2: [], 3: [] };
  futureEvents.forEach(function(ev) {
    const stages = computeEventInvoiceStages(ev, accomBookings);
    const blockers = invoiceBlockers(ev, accomBookings);
    const cid = (ev.xeroContactId||"").trim();
    const contactInvoices = (xeroByContact && cid && xeroByContact[cid]) ? xeroByContact[cid] : [];
    stages.forEach(function(st) {
      const linked = findPushedInvoice(records, ev.id, st.stage);
      if (st.total <= 0 && !linked) return;
      if (!inStageWindow(ev, st)) return;
      const drifted = linked && linked.fingerprint !== invoiceLinesFingerprint(st.lines);
      // The live Xero record for a linked invoice — gives us paid status.
      const xeroInv = linked
        ? contactInvoices.find(function(i){ return i.InvoiceID === linked.xeroInvoiceId; }) || null
        : null;
      const candidates = contactInvoices.filter(function(inv) {
        const s = String(inv.Status||"").toUpperCase();
        return s!=="VOIDED" && s!=="DELETED" && allClaimedIds.indexOf(inv.InvoiceID) === -1;
      }).slice(0, 25);
      buckets[st.stage].push({ ev:ev, st:st, linked:linked, drifted:drifted, blockers:blockers, xeroInv:xeroInv, candidates:candidates });
    });
  });
  // Within a stage, order by when the invoice is due to be raised, then by event.
  Object.keys(buckets).forEach(function(k) {
    buckets[k].sort(function(a,b){
      const ad = a.st.invoiceDate || a.ev.date || "0000";
      const bd = b.st.invoiceDate || b.ev.date || "0000";
      if (ad !== bd) return ad > bd ? 1 : -1;
      return (a.ev.date||"") > (b.ev.date||"") ? 1 : -1;
    });
  });

  const sections = [
    { stage:1, title:"Deposit invoices", blurb:"New bookings — deposit not yet raised." },
    { stage:2, title:"Second invoices (1 Dec)", blurb:"50% venue + 50% accommodation, less the deposit. Raised from mid-November of the year before the event." },
    { stage:3, title:"Final invoices (4 weeks before)", blurb: showAll ? "50% venue + 50% accommodation." : "50% venue + 50% accommodation — events in the next " + STAGE3_WEEKS + " weeks." }
  ];

  function linkExisting(ev, st, invoiceId) {
    const cid = (ev.xeroContactId||"").trim();
    const list = (xeroByContact && xeroByContact[cid]) || [];
    const inv = list.find(function(i){ return i.InvoiceID === invoiceId; });
    if (!inv) return;
    const rec = {
      id: "inv_" + ev.id + "_" + st.stage,
      eventId: ev.id, stage: st.stage,
      invoiceDate: st.invoiceDate, total: st.total,
      lines: st.lines, fingerprint: invoiceLinesFingerprint(st.lines),
      xeroInvoiceId: inv.InvoiceID, invoiceNumber: inv.InvoiceNumber || "",
      pushedAt: new Date().toISOString(), source: "manual"
    };
    const next = (records||[]).filter(function(r){
      return !(String(r.eventId)===String(ev.id) && Number(r.stage)===Number(st.stage));
    }).concat([rec]);
    onSaveRecords(next);
  }

  function unlink(ev, st) {
    onSaveRecords((records||[]).filter(function(r){
      return !(String(r.eventId)===String(ev.id) && Number(r.stage)===Number(st.stage));
    }));
  }

  async function doPush(ev, st) {
    const key = ev.id + "-" + st.stage;
    setBusyKey(key); setMsg(null);
    try {
      const res = await pushInvoiceToXero(ev, st, accomBookings);
      const rec = {
        id: "inv_" + ev.id + "_" + st.stage,
        eventId: ev.id, stage: st.stage,
        invoiceDate: st.invoiceDate, total: st.total,
        lines: st.lines, fingerprint: invoiceLinesFingerprint(st.lines),
        xeroInvoiceId: res.invoiceId, invoiceNumber: res.invoiceNumber,
        pushedAt: new Date().toISOString(), source: "push",
        totalMismatch: !!res.totalMismatch
      };
      const next = (records||[]).filter(function(r){
        return !(String(r.eventId)===String(ev.id) && Number(r.stage)===Number(st.stage));
      }).concat([rec]);
      await onSaveRecords(next);
      setMsg({
        kind: res.totalMismatch ? "error" : "ok",
        text: res.totalMismatch
          ? res.warning
          : "Draft " + (res.invoiceNumber || "") + " created in Xero" +
            (res.contactCreated ? " (new contact " + res.contactName + ")" : "") +
            (res.warning ? " — " + res.warning : "")
      });
    } catch (e) {
      setMsg({ kind:"error", text: String(e.message || e) });
    }
    setBusyKey(null);
  }

  return (
    <div style={{ paddingTop:24 }}>
      <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:16, flexWrap:"wrap" }}>
        <button onClick={onBack} style={{ background:T.midBlueBg, border:`1px solid ${T.border}`, color:T.midBlue, padding:"7px 16px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>&#8592; Back to events</button>
        <h2 style={{ margin:0, fontSize:20, fontWeight:700, color:T.text }}>Invoice worklist</h2>
        <label style={{ marginLeft:"auto", display:"flex", alignItems:"center", gap:7, fontSize:12, color:T.textMid, cursor:"pointer" }}>
          <input type="checkbox" checked={showAll} onChange={e=>setShowAll(e.target.checked)} style={{ width:14, height:14, accentColor:T.accent, cursor:"pointer" }}/>
          Show everything (future stages and already-raised invoices)
        </label>
      </div>

      <div style={{ background:"#eff6ff", border:"1px solid #bfdbfe", borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:"#1d4ed8", lineHeight:1.6 }}>
        Invoices are created in Xero as <strong>drafts</strong> — nothing is sent to the client until you approve and send it in Xero.
        All figures are treated as VAT-inclusive. Only events that haven’t happened yet are shown.
      </div>

      {preCutoverCount > 0 && (
        <div style={{ background:"#f8fafd", border:`1px solid ${T.border}`, borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:T.textMid, lineHeight:1.6 }}>
          <strong>{preCutoverCount}</strong> event{preCutoverCount!==1?"s":""} before {INVOICE_FIRST_EVENT_YEAR} {preCutoverCount!==1?"are":"is"} excluded — those were invoiced manually in Xero and are confirmed correct.
          Everything from {INVOICE_FIRST_EVENT_YEAR} onwards is generated and linked here.
        </div>
      )}

      {xeroByContact === null && (
        <div style={{ background:"#f8fafd", border:`1px solid ${T.border}`, borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:T.textMid }}>
          Checking Xero for invoices that already exist…
        </div>
      )}
      {autoLinked > 0 && (
        <div style={{ background:"#f0fdf4", border:"1px solid #bbf7d0", borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:"#166534", lineHeight:1.6 }}>
          Matched <strong>{autoLinked}</strong> stage{autoLinked!==1?"s":""} to invoices already in Xero (same total, nearest date) so they aren’t offered again.
          Tick “Show all stages” to review them — anything matched wrongly can be unlinked.
        </div>
      )}
      {xeroErr && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:"#92400e", lineHeight:1.6 }}>
          Could not read existing invoices from Xero ({xeroErr}). Stages already invoiced may still be listed below — check in Xero before pushing.
        </div>
      )}
      {!xeroToken && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:"#92400e" }}>
          Xero isn’t connected, so existing invoices can’t be matched. Connect Xero in the header first.
        </div>
      )}

      {msg && (
        <div style={{ background: msg.kind==="ok" ? "#f0fdf4" : "#fef2f2", border:`1px solid ${msg.kind==="ok" ? "#bbf7d0" : "#fecaca"}`,
          color: msg.kind==="ok" ? "#166534" : "#dc2626", borderRadius:9, padding:"11px 15px", marginBottom:16, fontSize:13, lineHeight:1.6 }}>
          {msg.text}
        </div>
      )}

      {sections.every(function(s){ return !buckets[s.stage].length; }) ? (
        <div style={{ textAlign:"center", padding:60, color:T.textLight }}>
          <p style={{ fontSize:16 }}>Nothing to invoice right now.</p>
          <p style={{ fontSize:13 }}>Tick “Show everything” to see future stages and already-raised invoices.</p>
        </div>
      ) : sections.map(function(sec) {
        const items = buckets[sec.stage];
        const toRaise = items.filter(function(r){ return !r.linked && !r.blockers.length; }).length;
        return (
          <div key={sec.stage} style={{ marginBottom:22 }}>
            <div style={{ display:"flex", alignItems:"baseline", gap:10, marginBottom:8, flexWrap:"wrap" }}>
              <h3 style={{ margin:0, fontSize:16, fontWeight:700, color:T.text }}>{sec.title}</h3>
              {toRaise > 0 && (
                <span style={{ fontSize:11, fontWeight:800, padding:"2px 9px", borderRadius:10, background:T.midBlue, color:"#fff" }}>
                  {toRaise} to generate
                </span>
              )}
              <span style={{ fontSize:11, color:T.textLight, flex:1, minWidth:180 }}>{sec.blurb}</span>
            </div>

            {!items.length ? (
              <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"16px 18px", fontSize:12, color:T.textLight }}>
                Nothing in this stage.
              </div>
            ) : (
              <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
                <div style={{ padding:"8px 16px", background:"#f5f9ff", display:"flex", alignItems:"center", gap:12, flexWrap:"wrap",
                  fontSize:10, letterSpacing:1, textTransform:"uppercase", fontWeight:700, color:T.textMid }}>
                  <span style={{ flex:1, minWidth:150 }}>Event</span>
                  <span style={{ width:95, flexShrink:0 }}>Event date</span>
                  <span style={{ width:95, flexShrink:0 }}>Invoice date</span>
                  <span style={{ width:95, textAlign:"right", flexShrink:0 }}>Amount</span>
                  <span style={{ minWidth:280, textAlign:"right" }}>Status</span>
                </div>
                {items.map(function(r) {
                  return (
                    <InvoiceStageRow key={r.ev.id + "-" + r.st.stage} ev={r.ev} stageObj={r.st} linked={r.linked} drifted={r.drifted}
                      blockers={r.blockers} busy={busyKey === (r.ev.id + "-" + r.st.stage)} candidates={r.candidates} xeroInv={r.xeroInv}
                      onPush={function(){ doPush(r.ev, r.st); }}
                      onLink={function(invId){ linkExisting(r.ev, r.st, invId); }}
                      onUnlink={function(){ unlink(r.ev, r.st); }}
                      onOpenEvent={function(){ onEdit(r.ev.id); }}/>
                  );
                })}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

// ─── MISSING-EVENT DETECTION ──────────────────────────────────────────────────
// Accommodation bookings live under a different Supabase key to events, so when
// an event record is lost the accom booking keeps pointing at it. Those dangling
// references are the most reliable evidence that an event has disappeared —
// it's how the missing "event 219" was spotted in the first place.
function findOrphanedEventLinks(bookings, accomBookings) {
  var have = {};
  (bookings || []).forEach(function(b) { if (b && b.id != null) have[String(b.id)] = true; });
  var byEvent = {};
  (accomBookings || []).forEach(function(ab) {
    if (!ab || !ab.linkedEventId) return;
    var key = String(ab.linkedEventId);
    if (have[key]) return;
    if (!byEvent[key]) byEvent[key] = { eventId: ab.linkedEventId, bookings: [] };
    byEvent[key].bookings.push(ab);
  });
  return Object.keys(byEvent).map(function(k) { return byEvent[k]; });
}

function ListView({ bookings, search, setSearch, onEdit, onDelete, onNew, staff, accomBookings, onOpenAccom, xeroToken, onOpenInvoices, invoiceDueCount }) {
  const today = new Date().toISOString().slice(0,10);
  const upcoming = bookings.filter(b => classifyEventRow(b, today) === "upcoming");
  const past     = bookings.filter(b => classifyEventRow(b, today) === "past");
  const problem  = bookings.filter(b => classifyEventRow(b, today) === "problem");
  const missingName = bookings.filter(b => isValidEventDate(b.date) && !b.couple);
  const accountedFor = upcoming.length + past.length + problem.length;
  const orphans = findOrphanedEventLinks(bookings, accomBookings);

  return (
    <div>
      <div style={{ padding:"28px 0 18px", display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
        <input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search by name, email or date…"
          style={{ flex:1, minWidth:180, background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:8, color:T.text, fontFamily:"inherit", fontSize:14, padding:"10px 14px", outline:"none", boxShadow:"0 1px 3px rgba(37,99,235,.06)" }}/>
        {onOpenInvoices && (
          <button onClick={onOpenInvoices}
            style={{ background:T.midBlue, color:"#fff", border:"none", padding:"10px 18px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700, flexShrink:0, display:"flex", alignItems:"center", gap:8, whiteSpace:"nowrap" }}>
            Invoices
            {invoiceDueCount > 0 && (
              <span style={{ background:"#fff", color:T.midBlue, borderRadius:10, padding:"1px 8px", fontSize:11, fontWeight:800 }}>{invoiceDueCount}</span>
            )}
          </button>
        )}
        <span style={{ color:T.textLight, fontSize:13, flexShrink:0 }}>{bookings.length} event{bookings.length!==1?"s":""}</span>
      </div>

      {/* Missing events: accommodation still pointing at an event that's gone */}
      {orphans.length > 0 && !search && (
        <div style={{ background:"#fef2f2", border:"1px solid #fecaca", borderRadius:9, padding:"12px 16px", marginBottom:16 }}>
          <div style={{ fontSize:13, fontWeight:700, color:"#dc2626", marginBottom:5 }}>
            {orphans.length} event{orphans.length!==1?"s":""} referenced by accommodation but missing from this list
          </div>
          <div style={{ fontSize:12, color:"#dc2626", lineHeight:1.7 }}>
            {orphans.map(function(o) {
              const names = o.bookings.map(function(ab){ return ab.guestName || "(no name)"; }).join(", ");
              return (
                <div key={String(o.eventId)}>
                  Event #{String(o.eventId)} — linked from {o.bookings.length} accommodation booking{o.bookings.length!==1?"s":""} ({names})
                  {o.bookings[0] && o.bookings[0].id && (
                    <button onClick={function(){ if (onOpenAccom) onOpenAccom(o.bookings[0].id); }}
                      style={{ marginLeft:8, background:"none", border:"1px solid #fecaca", color:"#dc2626", padding:"1px 8px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:11 }}>
                      Open booking
                    </button>
                  )}
                </div>
              );
            })}
          </div>
          <div style={{ fontSize:11, color:"#b91c1c", marginTop:6, lineHeight:1.6 }}>
            These event records are no longer in the database. Recreate the event and re-link the accommodation, or clear the link on the booking.
          </div>
        </div>
      )}

      {/* Data-integrity notice: events that can't be placed on the calendar */}
      {(problem.length > 0 || missingName.length > 0) && !search && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:9, padding:"12px 16px", marginBottom:16 }}>
          <div style={{ fontSize:13, fontWeight:700, color:"#92400e", marginBottom:4 }}>
            {problem.length + missingName.length} event{(problem.length+missingName.length)!==1?"s":""} need attention
          </div>
          <div style={{ fontSize:12, color:"#92400e", lineHeight:1.6 }}>
            {problem.length > 0 && <div>{problem.length} with a missing or invalid date — these can’t appear on the calendar until a date is set.</div>}
            {missingName.length > 0 && <div>{missingName.length} with no event/couple name — these are hidden from the year calendar.</div>}
            <div style={{ marginTop:4 }}>They’re listed below so you can open and fix them.</div>
          </div>
        </div>
      )}

      {search ? <BookingTable rows={bookings} onEdit={onEdit} onDelete={onDelete} label="Results" staff={staff} accomBookings={accomBookings} onOpenAccom={onOpenAccom} xeroToken={xeroToken}/> : <>
        {problem.length>0 && <BookingTable rows={problem} onEdit={onEdit} onDelete={onDelete} label="Needs a valid date" staff={staff} accomBookings={accomBookings} onOpenAccom={onOpenAccom} xeroToken={xeroToken}/>}
        <BookingTable rows={upcoming} onEdit={onEdit} onDelete={onDelete} label="Upcoming" staff={staff} accomBookings={accomBookings} onOpenAccom={onOpenAccom} xeroToken={xeroToken}/>
        {past.length>0 && <BookingTable rows={past} onEdit={onEdit} onDelete={onDelete} label="Past" dimmed staff={staff} accomBookings={accomBookings} onOpenAccom={onOpenAccom} xeroToken={xeroToken}/>}
      </>}

      {/* Safety net: if the buckets ever fail to account for every record, say so
          loudly rather than quietly showing the user an incomplete list. */}
      {!search && accountedFor !== bookings.length && (
        <div style={{ background:"#fef2f2", border:"1px solid #fecaca", borderRadius:9, padding:"12px 16px", marginTop:16, fontSize:13, color:"#dc2626" }}>
          {bookings.length - accountedFor} event(s) could not be displayed. Please report this.
        </div>
      )}

      {bookings.length===0 && <div style={{ textAlign:"center", padding:60, color:T.textLight }}><p style={{ fontSize:18, marginBottom:16 }}>No bookings yet</p><button onClick={onNew} style={{ background:T.accent, color:"#fff", border:"none", padding:"11px 28px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:15 }}>Create First Booking</button></div>}
    </div>
  );
}

// Small presentational pieces shared between BookingTable's desktop <table>
// rows and its mobile card layout. Kept at module scope (not nested inside
// BookingTable) so they aren't redefined as new component types every render.
function AccomBadgeList({ accomBadges, onOpenAccom }) {
  return accomBadges.length===0 ? <span style={{ color:T.textLight, fontSize:11 }}>—</span>
    : accomBadges.map(function(entry){
        return entry.labels.map(function(lbl){
          return (
            <span key={entry.id+"-"+lbl}
              onClick={function(e){ e.stopPropagation(); if (onOpenAccom) onOpenAccom(entry.id); }}
              title="Open lettings booking"
              style={{ fontSize:10, background:T.midBlueBg, color:T.midBlue, borderRadius:4, padding:"2px 6px", marginRight:3, fontWeight:600, cursor: onOpenAccom ? "pointer" : "default", textDecoration: onOpenAccom ? "underline" : "none", textDecorationStyle:"dotted" }}>
              {lbl}
            </span>
          );
        });
      });
}

function BookingStatusBadge({ b }) {
  return b.status==="Holding"
    ? <span style={{ fontSize:11, padding:"3px 9px", borderRadius:12, background:"#fef9c3", color:"#854d0e", fontWeight:600 }}>Holding</span>
    : b.status==="Confirmed"
      ? <span style={{ fontSize:11, padding:"3px 9px", borderRadius:12, background:T.greenBg, color:T.green, fontWeight:600 }}>Confirmed</span>
      : <span style={{ color:T.textLight, fontSize:11 }}>—</span>;
}

function BookingPaymentBadge({ payment }) {
  return payment.mode==="xero"
    ? <span style={{ fontSize:11, padding:"3px 9px", borderRadius:12, background:payment.isFullyPaid?T.greenBg:payment.due>0?T.amberBg:T.redBg, color:payment.isFullyPaid?T.green:payment.due>0?T.amber:T.red, fontWeight:600 }}>{payment.isFullyPaid?"✓ Paid":payment.due>0?`£${payment.due.toLocaleString()} due`:"Overpaid"}</span>
    : <span style={{ color:T.textLight, fontSize:11 }} title="No Xero invoices linked to this booking">N/A</span>;
}

function BookingFileTicks({ b }) {
  const bFiles = b.files||[];
  const has = (type) => bFiles.some(f=>f.docType===type);
  const Tick = ({label,short}) => (
    <span title={label} style={{ display:"inline-flex",alignItems:"center",justifyContent:"center",width:24,height:20,borderRadius:4,marginRight:2,fontSize:9,fontWeight:700,background:has(label)?T.greenBg:"#f1f5f9",color:has(label)?T.green:T.textLight,border:`1px solid ${has(label)?"#86efac":T.border}` }}>{short}</span>
  );
  return <div style={{display:"flex",alignItems:"center",gap:1}}>
    <Tick label="Event Booking Form" short="EBF"/>
    <Tick label="Accommodation Booking Form" short="ABF"/>
    <Tick label="Event Timesheet" short="TS"/>
  </div>;
}

function BookingViewingsList({ b }) {
  return (b.viewings||[]).length===0
    ? <span style={{ color:T.textLight, fontSize:11 }}>—</span>
    : <div style={{ display:"flex", flexDirection:"column", gap:3 }}>
        {[...(b.viewings||[])].sort((a,z)=>a.date>z.date?1:-1).map((v,i)=>(
          <div key={i} style={{ fontSize:10, background:T.midBlueBg, color:T.midBlue, borderRadius:4, padding:"2px 6px", whiteSpace:"nowrap", fontWeight:600 }}>
            📅 {v.date}{v.time?" "+v.time:""}
          </div>
        ))}
      </div>;
}

function BookingTable({ rows, onEdit, onDelete, label, dimmed, staff, accomBookings, onOpenAccom, xeroToken }) {
  if(rows.length===0) return null;

  // Bulk-fetch Xero invoices (one request covering every contact ID on this
  // page) so the Payment column reflects real Xero data instead of the
  // manually-typed deposit/2nd payment/final payment fields.
  const [xeroInvoicesByContact, setXeroInvoicesByContact] = useState({});
  const contactIds = rows.map(function(b){ return (b.xeroContactId||"").trim(); }).filter(Boolean);
  const contactIdsKey = contactIds.slice().sort().join(",");

  useEffect(function() {
    if (!xeroToken || !contactIds.length) { setXeroInvoicesByContact({}); return; }
    let cancelled = false;
    (async function() {
      try {
        const data = await xeroFetch(`Invoices?ContactIDs=${contactIds.join(",")}&order=Date DESC`);
        if (cancelled) return;
        const byContact = {};
        (data.Invoices||[]).forEach(function(inv){
          const cid = inv.Contact && inv.Contact.ContactID;
          if (!cid) return;
          if (!byContact[cid]) byContact[cid] = [];
          byContact[cid].push(inv);
        });
        setXeroInvoicesByContact(byContact);
      } catch(e) {
        console.warn("Xero invoice bulk fetch failed:", e.message);
        if (!cancelled) setXeroInvoicesByContact({});
      }
    })();
    return function(){ cancelled = true; };
  }, [xeroToken?.access_token, contactIdsKey]);

  const isMobile = useIsMobile();

  // Compute the extra per-row data (accom badges, payment status) once,
  // shared between the desktop table and the mobile card layout below.
  const rowsData = rows.map(function(b) {
    const total = parseMoney(b.venueFee);
    const xeroContactId = (b.xeroContactId||"").trim();
    const xeroInvoices = xeroContactId ? xeroInvoicesByContact[xeroContactId] : null;
    let payment;
    if (!xeroToken || !xeroContactId || !xeroInvoices || xeroInvoices.length===0) {
      payment = { mode:"na" };
    } else {
      const xTotal = xeroInvoices.reduce(function(s,inv){ return s+(Number(inv.Total)||0); }, 0);
      const xDue   = xeroInvoices.reduce(function(s,inv){ return s+(Number(inv.AmountDue)||0); }, 0);
      payment = { mode:"xero", due:xDue, isFullyPaid: xTotal>0 && xDue<=0.01 };
    }
    const linkedAccom = (accomBookings||[]).filter(function(ab){ return ab.linkedEventId && String(ab.linkedEventId)===String(b.id); });
    const accomBadges = linkedAccom.map(function(ab) {
      var stays = (ab.stays&&ab.stays.length) ? ab.stays : [ab];
      var labels = stays.map(function(s){
        var n = s.propertyName || s.propertyId || "Accom";
        if (/hamlet/i.test(n)) return "Hamlet";
        if (/amly/i.test(n)) return "Amly";
        if (/glamp/i.test(n) || /camping/i.test(n)) return "Glamp";
        return n;
      }).filter(function(v,i,arr){ return arr.indexOf(v)===i; });
      return { id: ab.id, labels: labels };
    });
    return { b: b, total: total, payment: payment, accomBadges: accomBadges };
  });

  if (isMobile) {
    return (
      <div style={{ marginBottom:28 }}>
        <h3 style={{ color:T.midBlue, fontSize:11, letterSpacing:2, textTransform:"uppercase", marginBottom:10, fontWeight:700 }}>{label} ({rows.length})</h3>
        <div style={{ display:"flex", flexDirection:"column", gap:10, opacity:dimmed?.65:1 }}>
          {rowsData.map(function({ b, total, payment, accomBadges }) {
            return (
              <div key={b.id} onClick={()=>onEdit(b.id)}
                style={{ background:"#fff", borderRadius:10, border:`1px solid ${T.border}`, boxShadow:"0 2px 8px rgba(37,99,235,.06)", padding:"12px 14px", cursor:"pointer" }}>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start", marginBottom:6 }}>
                  <div>
                    <div style={{ fontWeight:700, color:T.text, fontSize:15 }}>{b.couple||"—"}</div>
                    <div style={{ fontSize:12, color:T.accent, fontWeight:600, marginTop:2 }}>
                      {b.date?fmtDate(b.date)+(b.endDate&&b.endDate>b.date?" – "+fmtDate(b.endDate):""):"—"}
                      {" · "}<DayBadge dateStr={b.date} endDate={b.endDate}/>
                    </div>
                  </div>
                  <BookingStatusBadge b={b}/>
                </div>
                <div style={{ fontSize:12, color:T.textMid, marginBottom:8 }}>{b.eventType||"—"}</div>
                <div style={{ display:"flex", flexWrap:"wrap", gap:"6px 16px", fontSize:12, color:T.textMid, marginBottom:8 }}>
                  <span>Day guests: <strong style={{ color:T.text }}>{b.mealGuests||"—"}</strong></span>
                  <span>Eve guests: <strong style={{ color:T.text }}>{b.eveGuests||"—"}</strong></span>
                  <span>Venue fee: <strong style={{ color:T.text }}>{total>0?`£${total.toLocaleString()}`:"—"}</strong></span>
                </div>
                <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:8, paddingTop:8, borderTop:`1px solid ${T.border}` }}>
                  <div onClick={e=>e.stopPropagation()}><AccomBadgeList accomBadges={accomBadges} onOpenAccom={onOpenAccom}/></div>
                  <BookingPaymentBadge payment={payment}/>
                </div>
                {(b.viewings||[]).length>0 && <div style={{ marginTop:8 }}><BookingViewingsList b={b}/></div>}
                <div style={{ marginTop:8 }}><BookingFileTicks b={b}/></div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div style={{ marginBottom:36 }}>
      <h3 style={{ color:T.midBlue, fontSize:11, letterSpacing:2, textTransform:"uppercase", marginBottom:10, fontWeight:700 }}>{label} ({rows.length})</h3>
      <div style={{ background:"#fff", borderRadius:10, border:`1px solid ${T.border}`, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <table style={{ width:"100%", borderCollapse:"collapse", opacity:dimmed?.65:1 }}>
          <thead>
            <tr style={{ background:"#eef4fd", borderBottom:`1px solid ${T.border}` }}>
              {["Date","Day","Couple / Event","Event Type","Day Guests","Eve Guests","Venue Fee","Accommodation","Status","Payment","Viewings","Files"].map(h=>(
                <th key={h} style={{ color:T.textMid, fontSize:11, letterSpacing:1.2, textTransform:"uppercase", padding:"10px 12px", textAlign:"left", fontWeight:700 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rowsData.map(function({ b, total, payment, accomBadges }, i) {
              return (
                <tr key={b.id} style={{ borderTop:i>0?`1px solid ${T.border}`:"none", transition:"background .12s", cursor:"pointer" }}
                  onClick={()=>onEdit(b.id)}
                  onMouseEnter={e=>e.currentTarget.style.background="#f0f6ff"}
                  onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                  {/* Multi-day events stack the end date under the start date,
                      keeping this column narrow so the file icons stay inside
                      the table rather than being pushed off the right edge. */}
                  <td style={{ padding:"10px 12px", fontSize:13, color:T.accent, whiteSpace:"nowrap", fontWeight:600, lineHeight:1.35 }}>
                    {b.date ? (
                      <>
                        <div>{fmtDate(b.date)}</div>
                        {b.endDate && b.endDate > b.date && (
                          <div style={{ fontSize:11, color:T.textLight, fontWeight:500 }}>to {fmtDate(b.endDate)}</div>
                        )}
                      </>
                    ) : "—"}
                  </td>
                  <td style={{ padding:"10px 12px", whiteSpace:"nowrap" }}><DayBadge dateStr={b.date} endDate={b.endDate}/></td>
                  <td style={{ padding:"10px 12px", maxWidth:180 }}>
                    <div style={{ fontWeight:600, color:T.text, fontSize:14 }}>{b.couple||"—"}</div>
                  </td>
                  <td style={{ padding:"10px 12px", fontSize:12, color:T.textMid }}>{b.eventType||"—"}</td>
                  <td style={{ padding:"10px 12px", fontSize:13, color:T.textMid }}>{b.mealGuests||"—"}</td>
                  <td style={{ padding:"10px 12px", fontSize:13, color:T.textMid }}>{b.eveGuests||"—"}</td>
                  <td style={{ padding:"10px 12px", fontSize:13, color:T.text, fontWeight:500 }}>{total>0?`£${total.toLocaleString()}`:"—"}</td>
                  <td style={{ padding:"10px 12px" }} onClick={e=>e.stopPropagation()}>
                    <AccomBadgeList accomBadges={accomBadges} onOpenAccom={onOpenAccom}/>
                  </td>
                  <td style={{ padding:"10px 12px" }}>
                    <BookingStatusBadge b={b}/>
                  </td>
                  <td style={{ padding:"10px 12px" }}>
                    <BookingPaymentBadge payment={payment}/>
                  </td>
                  <td style={{ padding:"10px 12px", minWidth:120 }}>
                    <BookingViewingsList b={b}/>
                  </td>
                  <td style={{ padding:"10px 12px", whiteSpace:"nowrap" }}>
                    <BookingFileTicks b={b}/>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

