function CatBadge({ cat }) {
  const c = CAT_COLOURS[cat] || { bg:T.accentLight, text:T.accent, border:T.border };
  return <span style={{ fontSize:11, fontWeight:700, padding:"2px 9px", borderRadius:10, background:c.bg, color:c.text, border:`1px solid ${c.border}`, whiteSpace:"nowrap" }}>{cat}</span>;
}

function fmt2(n) { return n == null ? "—" : `£${Number(n).toFixed(2)}`; }
function fmtN(n) { return n == null || n === "" ? "—" : Number(n).toLocaleString(); }

// ─── currentStock: derive from events ────────────────────────────────────────
function computeStock(products, events) {
  // returns { productId: qty }
  const stock = {};
  products.forEach(p => { stock[p.id] = 0; });
  const sorted = [...events].sort((a,b) => a.date > b.date ? 1 : -1);
  sorted.forEach(ev => {
    Object.entries(ev.lines || {}).forEach(([pid, qty]) => {
      if (ev.type === "order") stock[pid] = (stock[pid] || 0) + Number(qty || 0);
      if (ev.type === "stocktake") stock[pid] = Number(qty || 0); // absolute
    });
  });
  return stock;
}

// ─── Dashboard (Slice 2) ──────────────────────────────────────────────────────
// ─── NEW LETTINGS ─────────────────────────────────────────────────────────────
// Anything that arrived in the last week, from the website, from Airbnb's feed
// or typed in here. Airbnb bookings in particular land silently on an hourly
// sync, so without this the first you'd know is spotting it on the calendar.
const NEW_LETTING_DAYS = 7;

function NewLettings({ bookings, properties, onOpen, events, onOpenEvent }) {
  const cutoff = Date.now() - NEW_LETTING_DAYS * 24 * 60 * 60 * 1000;
  const isRecent = function(rec) {
    const t = rec && rec.createdAt ? new Date(rec.createdAt).getTime() : NaN;
    return isFinite(t) && t > cutoff;
  };

  const recentLets = (bookings || []).filter(function(b) {
    if (!b || b.status === "cancelled" || b.bookingType === "Blocked") return false;
    // Unpaid website bookings have their own panel; listing them twice would
    // just be noise.
    if (b.status === "pending") return false;
    return isRecent(b);
  }).map(function(b) { return { kind: "let", rec: b, createdAt: b.createdAt }; });

  // Events only carry a createdAt from this build onward, so nothing older
  // appears — which is right, since it wasn't added recently.
  const recentEvents = (events || []).filter(function(e) {
    if (!e || e.status === "Cancelled") return false;
    return isRecent(e);
  }).map(function(e) { return { kind: "event", rec: e, createdAt: e.createdAt }; });

  const recent = recentLets.concat(recentEvents)
    .sort(function(x, z) { return (z.createdAt || "") > (x.createdAt || "") ? 1 : -1; });

  if (!recent.length) return null;

  const sourceChip = function(b) {
    const map = {
      airbnb: { text: "Airbnb", bg: "#fff1f2", fg: "#be123c", bd: "#fecdd3" },
      direct: { text: "Website", bg: T.greenBg, fg: T.green, bd: "#bbf7d0" }
    };
    const c = map[b.source] || { text: "Added here", bg: T.bgInput, fg: T.textMid, bd: T.border };
    return (
      <span style={{ fontSize:10, fontWeight:700, padding:"2px 8px", borderRadius:9,
        background:c.bg, color:c.fg, border:"1px solid " + c.bd, whiteSpace:"nowrap", flexShrink:0 }}>
        {c.text}
      </span>
    );
  };

  return (
    <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:12, padding:"18px 22px",
      marginBottom:20, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
      <div style={{ display:"flex", alignItems:"baseline", gap:10, marginBottom:10, flexWrap:"wrap" }}>
        <h3 style={{ margin:0, fontSize:15, fontWeight:800, color:T.accent }}>New bookings</h3>
        <span style={{ fontSize:11, fontWeight:700, padding:"2px 8px", borderRadius:9, background:T.accentLight, color:T.accent }}>
          {recent.length}
        </span>
        <span style={{ fontSize:12, color:T.textLight }}>added in the last {NEW_LETTING_DAYS} days</span>
      </div>

      {recent.map(function(item) {
        // Farm events read differently from lettings — one date, a venue fee,
        // no properties — so they get their own row rather than being forced
        // through the lettings shape.
        if (item.kind === "event") {
          const e = item.rec;
          const fee = round2(parseMoney(e.venueFee));
          return (
            <div key={"ev-" + e.id} onClick={onOpenEvent ? function(){ onOpenEvent(e.id); } : undefined}
              style={{ borderTop:`1px solid ${T.border}`, padding:"9px 0", display:"flex", gap:10,
                alignItems:"center", flexWrap:"wrap", cursor: onOpenEvent ? "pointer" : "default" }}>
              <span style={{ fontSize:10, fontWeight:700, padding:"2px 8px", borderRadius:9,
                background:"#eef4fd", color:T.midBlue, border:"1px solid #bfdbfe", whiteSpace:"nowrap", flexShrink:0 }}>
                Event
              </span>
              <span style={{ fontSize:13, fontWeight:600, color:T.text, minWidth:130 }}>{e.couple || "(no name)"}</span>
              <span style={{ fontSize:12, color:T.textMid, flex:1, minWidth:200 }}>
                {eventTypeLabel(e)}{isValidEventDate(e.date) ? " · " + fmtDate(e.date) : ""}
                {e.status ? " · " + e.status : ""}
              </span>
              <span style={{ fontSize:12, color:T.textLight, whiteSpace:"nowrap" }}>
                {e.createdAt ? new Date(e.createdAt).toLocaleDateString("en-GB", { day:"numeric", month:"short" }) : ""}
              </span>
              <span style={{ fontSize:13, fontWeight:700, color:T.text, width:96, textAlign:"right", whiteSpace:"nowrap" }}>
                {fee > 0 ? String(fmtMoney(fee)) : "—"}
              </span>
            </div>
          );
        }

        const b = item.rec;
        const stays = (b.stays && b.stays.length) ? b.stays : [b];
        const v = lettingValue(b, properties);
        return (
          <div key={b.id} onClick={onOpen ? function(){ onOpen(b.id); } : undefined}
            style={{ borderTop:`1px solid ${T.border}`, padding:"9px 0", display:"flex", gap:10,
              alignItems:"center", flexWrap:"wrap", cursor: onOpen ? "pointer" : "default" }}>
            {sourceChip(b)}
            <span style={{ fontSize:13, fontWeight:600, color:T.text, minWidth:130 }}>
              {b.guestName || "(no name)"}
            </span>
            <span style={{ fontSize:12, color:T.textMid, flex:1, minWidth:200 }}>
              {stays.map(function(st, i) {
                return (i ? " · " : "") + (st.propertyName || st.propertyId) + " " +
                       fmtDate(st.checkIn) + " → " + fmtDate(st.checkOut);
              }).join("")}
            </span>
            <span style={{ fontSize:12, color:T.textLight, whiteSpace:"nowrap" }}>
              {b.createdAt ? new Date(b.createdAt).toLocaleDateString("en-GB", { day:"numeric", month:"short" }) : ""}
            </span>
            <span style={{ fontSize:13, fontWeight:700, color:T.text, width:96, textAlign:"right", whiteSpace:"nowrap" }}>
              {v.value > 0 ? String(fmtMoney(v.value)) : "—"}
              {v.estimated && <span style={{ marginLeft:4, fontSize:10, color:T.amber, fontWeight:700 }}>(est)</span>}
            </span>
          </div>
        );
      })}
    </div>
  );
}

// ─── UNPAID ONLINE BOOKINGS ───────────────────────────────────────────────────
// Someone booked through the website and never paid the deposit. The booking
// is recorded as "pending" and holds its dates everywhere, including on
// Airbnb, so it can't be double-sold while you decide what to do. It's listed
// here so it doesn't sit unnoticed: chase them, or delete it to free the
// dates. Nothing expires it automatically — releasing someone's dates without
// being asked to is the more dangerous mistake.
const UNPAID_GRACE_MINUTES = 30;   // may still be at the card screen

function UnpaidOnlineBookings({ bookings, onDelete }) {
  const [busy, setBusy] = useState(null);

  const now = Date.now();
  const unpaid = (bookings || []).filter(function(b) {
    if (!b || b.status !== "pending" || b.source !== "direct") return false;
    const dep = (b.schedule || []).find(function(s) { return s.label === "Deposit"; });
    if (dep && dep.paid) return false;                     // paid; status just hasn't caught up
    const age = b.createdAt ? (now - new Date(b.createdAt).getTime()) : Infinity;
    return !isFinite(age) || age > UNPAID_GRACE_MINUTES * 60 * 1000;
  }).sort(function(x, z) { return (z.createdAt || "") > (x.createdAt || "") ? 1 : -1; });

  if (!unpaid.length) return null;

  return (
    <div style={{ background:"#fff", border:"1px solid #fdba74", borderRadius:12, padding:"18px 22px", marginBottom:20 }}>
      <div style={{ display:"flex", alignItems:"baseline", gap:10, marginBottom:4, flexWrap:"wrap" }}>
        <h3 style={{ margin:0, fontSize:15, fontWeight:800, color:"#9a3412" }}>
          Booked online but not paid
        </h3>
        <span style={{ fontSize:11, fontWeight:700, padding:"2px 8px", borderRadius:9, background:"#fff7ed", color:"#9a3412", border:"1px solid #fdba74" }}>
          {unpaid.length}
        </span>
      </div>
      <div style={{ fontSize:12, color:T.textMid, marginBottom:12, lineHeight:1.6 }}>
        These are holding their dates — on the website and on Airbnb. Chase them, or delete to release the dates.
      </div>

      {unpaid.map(function(b) {
        const stays = (b.stays && b.stays.length) ? b.stays : [b];
        const dep = (b.schedule || []).find(function(s) { return s.label === "Deposit"; });
        return (
          <div key={b.id} style={{ borderTop:`1px solid ${T.border}`, padding:"11px 0", display:"flex",
            gap:12, alignItems:"flex-start", flexWrap:"wrap" }}>
            <div style={{ flex:1, minWidth:240 }}>
              <div style={{ fontSize:13, fontWeight:700, color:T.text }}>
                {b.guestName || "No name given"}
                <span style={{ fontWeight:400, color:T.textLight }}> · {b.id}</span>
                {b.guestCount ? <span style={{ fontWeight:400, color:T.textLight }}> · {b.guestCount} guest{Number(b.guestCount) === 1 ? "" : "s"}</span> : null}
              </div>
              {stays.map(function(st, i) {
                return (
                  <div key={i} style={{ fontSize:12, color:T.textMid, marginTop:2 }}>
                    {st.propertyName || st.propertyId} · {fmtDate(st.checkIn)} → {fmtDate(st.checkOut)}
                    {Number(st.value) > 0 ? " · " + String(fmtMoney(st.value)) : ""}
                  </div>
                );
              })}
              <div style={{ fontSize:12, color:T.textMid, marginTop:3 }}>
                {b.email ? <a href={"mailto:" + b.email} style={{ color:T.accent }}>{b.email}</a> : <span style={{ color:T.textLight }}>no email</span>}
                {b.phone ? " · " + b.phone : ""}
              </div>
              <div style={{ fontSize:11, color:T.textLight, marginTop:3 }}>
                Booked {b.createdAt ? new Date(b.createdAt).toLocaleString("en-GB", { day:"numeric", month:"short", hour:"2-digit", minute:"2-digit" }) : "—"}
                {dep && Number(dep.amount) > 0 ? " · deposit " + String(fmtMoney(dep.amount)) + " unpaid" : ""}
              </div>
            </div>
            <button onClick={function(){ setBusy(b.id); Promise.resolve(onDelete(b)).then(function(){ setBusy(null); }); }}
              disabled={busy === b.id}
              title="Delete this booking and free the dates"
              style={{ background:"#fff", color:T.red, border:"1.5px solid #fca5a5", borderRadius:7,
                padding:"7px 14px", fontFamily:"inherit", fontSize:12, fontWeight:600,
                cursor: busy === b.id ? "default" : "pointer", flexShrink:0 }}>
              {busy === b.id ? "…" : "Delete"}
            </button>
          </div>
        );
      })}
    </div>
  );
}

function DashboardView({ bookings, viewingRequests, setView, xeroToken, onDeleteAccom, accomProperties, onOpenAccom, onOpenEvent }) {
  const [accomBookings, setAccomBookings] = useState([]);
  const [emailLog, setEmailLog]           = useState([]);
  const [viewEmail, setViewEmail]         = useState(null);
  const [invoiceRecs, setInvoiceRecs]     = useState([]);
  const [xeroUnpaid, setXeroUnpaid]       = useState([]);
  const [xeroContactEvent, setXeroContactEvent] = useState({});
  const [xeroInvErr, setXeroInvErr]       = useState(null);
  const [loaded, setLoaded]               = useState(false);

  useEffect(()=>{
    (async()=>{
      try { const b = await sbGet(ACCOM_STORAGE); setAccomBookings((b||[]).map(normalizeAccom)); } catch { setAccomBookings([]); }
      try { const l = await sbGet(EMAIL_LOG_STORAGE); setEmailLog(l||[]); } catch { setEmailLog([]); }
      try { const r = await sbGet(EVENT_INVOICES_STORAGE); setInvoiceRecs(r||[]); } catch { setInvoiceRecs([]); }
      setLoaded(true);
    })();
  }, []);

  // Unpaid invoices for every event that has a Xero contact — not just the ones
  // this app raised. Invoices entered directly in Xero (everything before the
  // app started invoicing) count just as much when chasing money, and keying
  // off app-raised records alone left this permanently empty.
  useEffect(function() {
    if (!loaded || !xeroToken) return;
    const contactIds = [];
    const eventByContact = {};
    (bookings || []).forEach(function(ev) {
      const cid = (ev.xeroContactId || "").trim();
      if (!cid) return;
      if (contactIds.indexOf(cid) === -1) contactIds.push(cid);
      if (!eventByContact[cid]) eventByContact[cid] = ev;   // first/earliest match
    });
    if (!contactIds.length) { setXeroUnpaid([]); return; }

    let cancelled = false;
    (async function() {
      try {
        const found = [];
        for (let i = 0; i < contactIds.length; i += 40) {
          const chunk = contactIds.slice(i, i + 40);
          // Statuses that can still be owed. DRAFT is excluded server-side —
          // an unapproved draft hasn't been sent, so it can't be late.
          const data = await xeroFetch(
            "Invoices?ContactIDs=" + chunk.join(",") +
            "&Statuses=AUTHORISED,SUBMITTED&order=DueDate ASC"
          );
          ((data && data.Invoices) || []).forEach(function(inv) { found.push(inv); });
        }
        if (!cancelled) {
          setXeroUnpaid(found);
          setXeroContactEvent(eventByContact);
          setXeroInvErr(null);
        }
      } catch (e) {
        if (!cancelled) setXeroInvErr(String(e.message || e));
      }
    })();
    return function(){ cancelled = true; };
  }, [loaded, xeroToken, bookings.length]);

  const today = new Date().toISOString().slice(0,10);
  const in7   = new Date(Date.now() + 7*86400000).toISOString().slice(0,10);

  // Upcoming wedding events in next 7 days
  const upcomingEvents = bookings
    .filter(b => b.couple && b.date && b.date >= today && b.date <= in7)
    .sort((a,b)=>a.date>b.date?1:-1);

  // Upcoming accom check-ins in next 7 days
  const upcomingCheckIns = accomBookings.filter(b => {
    if (b.status==="cancelled") return false;
    const stays = b.stays||[];
    return stays.some(s => s.checkIn && s.checkIn>=today && s.checkIn<=in7);
  }).sort((a,z)=>{
    const aCI = (a.stays||[]).map(s=>s.checkIn||"").filter(d=>d>=today).sort()[0] || "9999";
    const zCI = (z.stays||[]).map(s=>s.checkIn||"").filter(d=>d>=today).sort()[0] || "9999";
    return aCI > zCI ? 1 : aCI < zCI ? -1 : 0;
  });

  // ── Overdue money ─────────────────────────────────────────────────────────
  // Two separate flows, deliberately kept apart:
  //   Event invoices  — stages whose invoice date has passed but which have
  //                     never been raised in Xero.
  //   Accommodation   — schedule entries past their due date and unpaid, for
  //                     standard lets only. Event-linked accommodation is
  //                     billed through the event, so it is excluded here or it
  //                     would be chased twice.
  // Raised invoices still unpaid more than OVERDUE_AFTER_DAYS past their due
  // date. Payment status has to come from Xero — the app only knows an invoice
  // was pushed, not whether it has since been settled. Drafts are excluded:
  // they haven't been sent, so they can't be late.
  // Which invoice belongs to which stage, where the app raised it. Invoices
  // entered straight into Xero simply have no stage label.
  const stageByInvoiceId = {};
  (invoiceRecs || []).forEach(function(r) {
    if (r.xeroInvoiceId) stageByInvoiceId[r.xeroInvoiceId] = r.stage;
  });

  const overdueInvoices = [];
  (xeroUnpaid || []).forEach(function(inv) {
    const status = String(inv.Status || "").toUpperCase();
    if (status === "PAID" || status === "VOIDED" || status === "DELETED" || status === "DRAFT") return;
    if (!(Number(inv.AmountDue || 0) > 0)) return;
    const due = xeroDateToIso(inv.DueDateString || inv.DueDate) ||
                xeroDateToIso(inv.DateString || inv.Date);
    if (!due) return;
    const daysLate = Math.round((new Date(today) - new Date(due)) / 86400000);
    if (daysLate <= OVERDUE_AFTER_DAYS) return;
    const cid = inv.Contact && inv.Contact.ContactID;
    overdueInvoices.push({
      inv: inv,
      ev: cid ? xeroContactEvent[cid] : null,
      contactName: (inv.Contact && inv.Contact.Name) || "",
      stage: stageByInvoiceId[inv.InvoiceID] || null,
      due: due,
      daysLate: daysLate,
      amountDue: Number(inv.AmountDue || 0)
    });
  });
  overdueInvoices.sort(function(a,b){ return b.daysLate - a.daysLate; });

  const overdueAccom = [];
  accomBookings.forEach(function(b) {
    if (b.status === "cancelled" || b.bookingType === "Blocked") return;
    if (b.linkedEventId) return;   // billed via the event invoices instead
    (b.schedule || []).forEach(function(s) {
      if (s.paid) return;
      if (!s.dueDate || s.dueDate >= today) return;
      if (!(Number(s.amount) > 0)) return;
      overdueAccom.push({ b: b, s: s, daysLate: Math.round((new Date(today) - new Date(s.dueDate)) / 86400000) });
    });
  });
  overdueAccom.sort(function(a,b){ return b.daysLate - a.daysLate; });

  const overdueInvoiceTotal = overdueInvoices.reduce(function(a,r){ return a + r.amountDue; }, 0);
  const overdueAccomTotal   = overdueAccom.reduce(function(a,r){ return a + Number(r.s.amount||0); }, 0);

  // Guests already checked in and still on site (checked in before today, not
  // yet checked out) — shown at the top of the check-ins list alongside
  // upcoming arrivals so the dashboard reflects who is actually here now too.
  const currentlyStaying = accomBookings.filter(b => {
    if (b.status==="cancelled") return false;
    if (b.bookingType==="Blocked") return false;
    const stays = b.stays||[];
    return stays.some(s => s.checkIn && s.checkOut && s.checkIn<today && s.checkOut>=today);
  }).sort((a,z)=>{
    const aCI = (a.stays||[]).map(s=>s.checkIn||"").filter(Boolean).sort()[0] || "9999";
    const zCI = (z.stays||[]).map(s=>s.checkIn||"").filter(Boolean).sort()[0] || "9999";
    return aCI > zCI ? 1 : aCI < zCI ? -1 : 0;
  });

  // Pending viewing requests
  const pendingViewings = (viewingRequests||[]).filter(r=>r.status==="pending");

  // Overdue accom payments: schedule entries where paid=false AND dueDate < today AND booking not cancelled
  // A schedule row worth nothing isn't a debt. Zero-value rows get left behind
  // when a booking's price is changed to nil, and chasing someone for £0.00 is
  // worse than useless. Event-linked lettings are billed on the event's Xero
  // invoices, so they don't belong here either.
  const overduePayments = [];
  accomBookings.forEach(b => {
    if (b.status==="cancelled" || b.bookingType==="Blocked") return;
    if (b.linkedEventId) return;
    (b.schedule||[]).forEach(s => {
      if (s.paid) return;
      if (!s.dueDate || s.dueDate >= today) return;
      if (!(Number(s.amount) > 0)) return;
      overduePayments.push({ booking:b, entry:s });
    });
  });

  const sectionStyle = { background:"#fff", border:`1px solid ${T.border}`, borderRadius:12, padding:"20px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)", marginBottom:18 };
  const secHead = (label, count, colour) => (
    <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:14 }}>
      <h3 style={{ margin:0, color:T.midBlue, fontWeight:700, fontSize:15 }}>{label}</h3>
      {count!=null && <span style={{ fontSize:12, fontWeight:700, color:colour||T.textMid, background: colour ? colour+"22" : T.bgInput, padding:"2px 10px", borderRadius:8 }}>{count}</span>}
    </div>
  );

  const fmtDay = (d) => d ? new Date(d+"T00:00:00").toLocaleDateString("en-GB",{weekday:"short",day:"numeric",month:"short"}) : "—";

  return (
    <div style={{ maxWidth:1100, margin:"0 auto", padding:"28px 28px 60px" }}>
      <h2 style={{ fontSize:22, fontWeight:800, color:T.text, margin:"0 0 6px" }}>Home</h2>
      <p style={{ color:T.textMid, fontSize:13, margin:"0 0 24px" }}>
        Today: {fmtDay(today)}
        <span style={{ color:T.textLight, marginLeft:10, fontSize:11 }}>build {APP_BUILD}</span>
      </p>

      {/* Payment status can only come from Xero — say so rather than letting an
          empty list read as "nothing outstanding". */}
      {(!xeroToken || xeroInvErr) && (
        <div style={{ background:"#fffbeb", border:"1px solid #fde68a", borderRadius:9, padding:"10px 15px", marginBottom:16, fontSize:12, color:"#92400e", lineHeight:1.6 }}>
          {!xeroToken
            ? "Connect Xero to see unpaid event invoices."
            : "Couldn’t read unpaid invoices from Xero (" + xeroInvErr + ")."}
        </div>
      )}

      {/* Ticketed nights — sales at a glance, and anything owing */}
      <BoxOfficeDashboardCard setView={setView}/>

      {/* Overdue money — unpaid raised invoices, and unpaid accommodation */}
      <NewLettings bookings={accomBookings} properties={accomProperties} onOpen={onOpenAccom}
        events={bookings} onOpenEvent={onOpenEvent}/>
      <UnpaidOnlineBookings bookings={accomBookings} onDelete={onDeleteAccom}/>

      {/* A zero is not "overdue" — it's nothing owed. Rows worth nothing are
          filtered above; this also stops a section rendering a £0.00 header
          if one ever gets through. */}
      {(overdueInvoiceTotal > 0 || overdueAccomTotal > 0) && (
        <div style={{ background:"#fff", border:"1px solid #fecaca", borderRadius:12, padding:"18px 22px", boxShadow:"0 2px 8px rgba(220,38,38,.08)", marginBottom:18 }}>
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:14, flexWrap:"wrap", gap:8 }}>
            <h3 style={{ margin:0, color:"#dc2626", fontWeight:700, fontSize:15 }}>Overdue</h3>
            <span style={{ fontSize:12, fontWeight:700, color:"#dc2626", background:"#fef2f2", padding:"2px 10px", borderRadius:8 }}>
              {overdueInvoices.length + overdueAccom.length}
            </span>
          </div>

          {overdueInvoiceTotal > 0 && (
            <div style={{ marginBottom: overdueAccom.length ? 16 : 0 }}>
              <div style={{ fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, fontWeight:700, marginBottom:7 }}>
                Event invoices unpaid — £{overdueInvoiceTotal.toLocaleString("en-GB",{minimumFractionDigits:2,maximumFractionDigits:2})}
              </div>
              {overdueInvoices.slice(0,8).map(function(r) {
                return (
                  <a key={r.inv.InvoiceID} href={xeroInvoiceUrl(r.inv.InvoiceID)} target="_blank" rel="noreferrer"
                    style={{ display:"flex", alignItems:"center", gap:10, padding:"7px 0", borderTop:`1px solid ${T.border}`, flexWrap:"wrap", textDecoration:"none", color:"inherit" }}>
                    <span style={{ fontSize:13, fontWeight:600, color:T.text, flex:1, minWidth:140 }}>
                      {r.ev ? (r.ev.couple || "(no name)") : (r.contactName || "(unknown)")}
                    </span>
                    {r.stage && <span style={{ fontSize:11, color:T.textLight }}>{INVOICE_STAGE_LABELS[r.stage]}</span>}
                    <span style={{ fontSize:11, color:"#13B5EA", fontWeight:600 }}>{r.inv.InvoiceNumber || "—"}</span>
                    <span style={{ fontSize:11, color:T.textLight }}>due {fmtDate(r.due)}</span>
                    <span style={{ fontSize:11, fontWeight:700, color:"#dc2626" }}>{r.daysLate}d late</span>
                    <span style={{ fontSize:13, fontWeight:700, color:T.text, width:90, textAlign:"right" }}>
                      £{r.amountDue.toLocaleString("en-GB",{minimumFractionDigits:2,maximumFractionDigits:2})}
                    </span>
                  </a>
                );
              })}
              {overdueInvoices.length > 8 && (
                <div style={{ fontSize:11, color:T.textLight, paddingTop:6 }}>…and {overdueInvoices.length-8} more.</div>
              )}
            </div>
          )}

          {overdueAccomTotal > 0 && (
            <div>
              <div style={{ fontSize:11, letterSpacing:1, textTransform:"uppercase", color:T.textMid, fontWeight:700, marginBottom:7 }}>
                Accommodation unpaid — £{overdueAccomTotal.toLocaleString("en-GB",{minimumFractionDigits:2,maximumFractionDigits:2})}
              </div>
              {overdueAccom.slice(0,8).map(function(r,i) {
                return (
                  <div key={r.b.id + "-" + r.s.label + "-" + i} onClick={()=>setView("lettings")}
                    style={{ display:"flex", alignItems:"center", gap:10, padding:"7px 0", borderTop:`1px solid ${T.border}`, cursor:"pointer", flexWrap:"wrap" }}>
                    <span style={{ fontSize:13, fontWeight:600, color:T.text, flex:1, minWidth:140 }}>{r.b.guestName || "(no name)"}</span>
                    <span style={{ fontSize:11, color:T.textLight }}>{r.s.label}</span>
                    <span style={{ fontSize:11, color:T.textLight }}>due {fmtDate(r.s.dueDate)}</span>
                    <span style={{ fontSize:11, fontWeight:700, color:"#dc2626" }}>{r.daysLate}d late</span>
                    <span style={{ fontSize:13, fontWeight:700, color:T.text, width:90, textAlign:"right" }}>
                      £{Number(r.s.amount||0).toLocaleString("en-GB",{minimumFractionDigits:2,maximumFractionDigits:2})}
                    </span>
                  </div>
                );
              })}
              {overdueAccom.length > 8 && (
                <div style={{ fontSize:11, color:T.textLight, paddingTop:6 }}>…and {overdueAccom.length-8} more — see Lettings.</div>
              )}
            </div>
          )}
        </div>
      )}

      <div style={{ display:"grid", gridTemplateColumns:"1fr 1fr", gap:18 }}>

        {/* Upcoming events */}
        <div style={sectionStyle}>
          {secHead("Upcoming Events — next 7 days", upcomingEvents.length, upcomingEvents.length?T.green:null)}
          {!loaded && <div style={{ color:T.textLight, fontSize:13 }}>Loading…</div>}
          {loaded && upcomingEvents.length===0 && <div style={{ color:T.textLight, fontSize:13 }}>No events this week.</div>}
          {upcomingEvents.map(b=>(
            <div key={b.id} onClick={()=>setView("list")} style={{ display:"flex", alignItems:"center", gap:10, padding:"9px 0", borderBottom:`1px solid #f0f6ff`, cursor:"pointer" }}>
              <span style={{ fontSize:11, fontWeight:700, color:T.accent, background:T.accentLight, padding:"2px 8px", borderRadius:6, flexShrink:0 }}>{fmtDay(b.date)}</span>
              <span style={{ fontSize:13, fontWeight:600, color:T.text }}>{b.couple}</span>
              {b.eventType && <span style={{ fontSize:10, color:T.textLight }}>{b.eventType}</span>}
            </div>
          ))}
        </div>

        {/* Upcoming accom check-ins (currently-staying guests shown first) */}
        <div style={sectionStyle}>
          {secHead("Accom Check-ins — next 7 days", currentlyStaying.length + upcomingCheckIns.length, (currentlyStaying.length + upcomingCheckIns.length) ? T.green : null)}
          {!loaded && <div style={{ color:T.textLight, fontSize:13 }}>Loading…</div>}
          {loaded && currentlyStaying.length===0 && upcomingCheckIns.length===0 && <div style={{ color:T.textLight, fontSize:13 }}>No check-ins this week.</div>}
          {currentlyStaying.map(b=>{
            const stay = (b.stays||[]).filter(s=>s.checkIn&&s.checkOut&&s.checkIn<today&&s.checkOut>=today).sort((a,z)=>a.checkIn>z.checkIn?1:-1)[0];
            return (
              <div key={"staying-"+b.id} onClick={()=>setView("lettings")} style={{ display:"flex", alignItems:"center", gap:10, padding:"9px 0", borderBottom:`1px solid #f0f6ff`, cursor:"pointer" }}>
                <span title={stay ? "Checked in "+fmtDay(stay.checkIn)+" · leaves "+fmtDay(stay.checkOut) : "Currently staying"}
                  style={{ fontSize:11, fontWeight:700, color:T.midBlue, background:T.midBlueBg, padding:"2px 8px", borderRadius:6, flexShrink:0, whiteSpace:"nowrap" }}>In house</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:13, fontWeight:600, color:T.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{b.guestName||"(no name)"}</div>
                  <div style={{ fontSize:11, color:T.textLight }}>{(b.stays||[]).map(s=>s.propertyName||s.propertyId).join(" + ")}{stay ? " · leaves "+fmtDay(stay.checkOut) : ""}</div>
                </div>
              </div>
            );
          })}
          {upcomingCheckIns.map(b=>{
            const nextStay = (b.stays||[]).filter(s=>s.checkIn&&s.checkIn>=today&&s.checkIn<=in7).sort((a,z)=>a.checkIn>z.checkIn?1:-1)[0];
            return (
              <div key={b.id} onClick={()=>setView("lettings")} style={{ display:"flex", alignItems:"center", gap:10, padding:"9px 0", borderBottom:`1px solid #f0f6ff`, cursor:"pointer" }}>
                <span style={{ fontSize:11, fontWeight:700, color:T.green, background:T.greenBg, padding:"2px 8px", borderRadius:6, flexShrink:0 }}>{fmtDay(nextStay&&nextStay.checkIn)}</span>
                <div style={{ flex:1, minWidth:0 }}>
                  <div style={{ fontSize:13, fontWeight:600, color:T.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{b.guestName||"(no name)"}</div>
                  <div style={{ fontSize:11, color:T.textLight }}>{(b.stays||[]).map(s=>s.propertyName||s.propertyId).join(" + ")}</div>
                </div>
              </div>
            );
          })}
        </div>

        {/* Pending viewing requests */}
        <div style={sectionStyle}>
          {secHead("Viewing Requests", pendingViewings.length, pendingViewings.length?T.amber:null)}
          {pendingViewings.length===0 && <div style={{ color:T.textLight, fontSize:13 }}>No unresponded requests.</div>}
          {pendingViewings.slice(0,6).map((r,i)=>(
            <div key={r.id||i} onClick={()=>setView("viewings")} style={{ display:"flex", alignItems:"center", gap:10, padding:"9px 0", borderBottom:`1px solid #f0f6ff`, cursor:"pointer" }}>
              <span style={{ fontSize:11, fontWeight:700, color:T.amber, background:T.amberBg, padding:"2px 8px", borderRadius:6, flexShrink:0 }}>Pending</span>
              <div style={{ flex:1 }}>
                <div style={{ fontSize:13, fontWeight:600, color:T.text }}>{r.name||"(no name)"}</div>
                <div style={{ fontSize:11, color:T.textLight }}>{r.eventType||""}{r.date?" - "+fmtDay(r.date):""}</div>
              </div>
            </div>
          ))}
          {pendingViewings.length>6 && <div style={{ fontSize:12, color:T.accent, marginTop:8, cursor:"pointer" }} onClick={()=>setView("viewings")}>+ {pendingViewings.length-6} more</div>}
        </div>

        {/* Overdue payments */}
        <div style={sectionStyle}>
          {secHead("Overdue Accom Payments", overduePayments.length, overduePayments.length?T.red:null)}
          {!loaded && <div style={{ color:T.textLight, fontSize:13 }}>Loading…</div>}
          {loaded && overduePayments.length===0 && <div style={{ color:T.textLight, fontSize:13 }}>No overdue payments.</div>}
          {overduePayments.slice(0,8).map(({ booking:b, entry:s },i)=>(
            <div key={b.id+"-"+i} onClick={()=>setView("lettings")} style={{ display:"flex", alignItems:"center", gap:10, padding:"9px 0", borderBottom:`1px solid #f0f6ff`, cursor:"pointer" }}>
              <span style={{ fontSize:11, fontWeight:700, color:T.red, background:T.redBg, padding:"2px 8px", borderRadius:6, flexShrink:0 }}>Due {fmtDay(s.dueDate)}</span>
              <div style={{ flex:1, minWidth:0 }}>
                <div style={{ fontSize:13, fontWeight:600, color:T.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{b.guestName||"(no name)"} — {s.label}</div>
                <div style={{ fontSize:11, color:T.red, fontWeight:600 }}>{fmtMoney(s.amount)}</div>
              </div>
            </div>
          ))}
          {overduePayments.length>8 && <div style={{ fontSize:12, color:T.accent, marginTop:8, cursor:"pointer" }} onClick={()=>setView("lettings")}>+ {overduePayments.length-8} more</div>}
        </div>
      </div>

      {/* Email log */}
      <div style={sectionStyle}>
        {secHead("Recent Automated Emails", emailLog.length||null)}
        {emailLog.length===0 && (
          <div style={{ color:T.textLight, fontSize:13 }}>No emails logged yet. When the system sends automated emails (phase 2), they will appear here.</div>
        )}
        {emailLog.slice().reverse().slice(0,10).map(e=>(
          <div key={e.id} onClick={()=>setViewEmail(e)} title="Click to read the full email"
            style={{ display:"flex", alignItems:"center", gap:12, padding:"8px 0", borderBottom:`1px solid #f0f6ff`, fontSize:13, cursor:"pointer" }}>
            <span style={{ color:T.textLight, fontSize:11, flexShrink:0 }}>{e.sentAt ? new Date(e.sentAt).toLocaleDateString("en-GB",{day:"numeric",month:"short",hour:"2-digit",minute:"2-digit"}) : "—"}</span>
            <span style={{ fontWeight:600, color:T.text, flex:1, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{e.subject||"(no subject)"}</span>
            <span style={{ color:T.textLight, fontSize:11 }}>{e.to||""}</span>
            {e.opened && <span style={{ fontSize:10, fontWeight:700, color:T.green, background:T.greenBg, padding:"1px 6px", borderRadius:6 }}>Opened</span>}
          </div>
        ))}
        <EmailViewerModal email={viewEmail} onClose={()=>setViewEmail(null)}/>
      </div>

      <TodoBox/>
    </div>
  );
}

// ─── BarView ──────────────────────────────────────────────────────────────────
function BarView() {
  const [products, setProducts] = useState([]);
  const [events, setEvents]     = useState([]);
  const [farmEvents, setFarmEvents] = useState([]);
  const [staff, setStaff]       = useState([]);
  const [loaded, setLoaded]     = useState(false);
  const [barView, setBarView]   = useState("stock");
  const [editProduct, setEditProduct] = useState(null);
  const [productForm, setProductForm] = useState(null);
  const [editingEvent, setEditingEvent] = useState(null);
  const [confirmDlg, setConfirmDlg]   = useState(null);

  useEffect(() => {
    (async () => {
      try { const r = await sbGet(BAR_PRODUCTS_KEY); setProducts(r || INITIAL_PRODUCTS); } catch { setProducts(INITIAL_PRODUCTS); }
      try { const r = await sbGet(BAR_EVENTS_KEY);   setEvents(r || INITIAL_BAR_EVENTS); }   catch { setEvents(INITIAL_BAR_EVENTS); }
      // Farm events + staff, so the rota reports can live here too — bar staff
      // need their rota without being given the run of the whole app.
      try { const r = await sbGet(BOOKING_STORAGE); setFarmEvents(r || []); } catch { setFarmEvents([]); }
      try { const r = await sbGet(STAFF_STORAGE);   setStaff(r || INITIAL_STAFF); } catch { setStaff(INITIAL_STAFF); }
      setLoaded(true);
    })();
  }, []);

  const saveProducts = async p => { setProducts(p); try { await sbSet(BAR_PRODUCTS_KEY, p); } catch(e) { console.error(e); } };
  const saveEvents   = async e => { setEvents(e);   try { await sbSet(BAR_EVENTS_KEY,   e); } catch(e) { console.error(e); } };

  const handleDeleteEvent = async id => {
    const ev = events.find(e=>e.id===id);
    setConfirmDlg({
      message: `Delete this ${ev?.type || "entry"}?`,
      subMessage: `"${ev?.label||ev?.date}" will be permanently removed. This will affect current stock calculations.`,
      onConfirm: async () => { setConfirmDlg(null); await saveEvents(events.filter(e => e.id !== id)); }
    });
  };

  const handleEditEvent = ev => {
    setEditingEvent(ev);
    setBarView(ev.type === "order" ? "order" : "stocktake");
  };

  const handleSaveEvent = async ev => {
    let updated;
    if (editingEvent) {
      updated = events.map(e => e.id === editingEvent.id ? { ...ev, id: editingEvent.id } : e);
    } else {
      updated = [...events, ev];
    }
    await saveEvents(updated);
    setEditingEvent(null);
    setBarView("history");
  };

  const stock = computeStock(products, events);

  if (!loaded) return <div style={{ padding:40, color:T.textLight }}>Loading bar data…</div>;

  const subTabs = [
    { id:"stock",      label:"Current Stock" },
    { id:"order",      label:"+ New Order" },
    { id:"stocktake",  label:"+ New Stocktake" },
    { id:"history",    label:"History" },
    { id:"report",     label:"Usage Report" },
    { id:"reconcile",  label:"Till Reconciliation" },
    { id:"products",   label:"Products" },
    { id:"rota",       label:"Rota Overview" },
    { id:"eventrota",  label:"Event Rota" },
  ];

  return (
    <div style={{ paddingTop:28 }}>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:22 }}>
        <h2 style={{ margin:0, color:T.midBlue, fontWeight:700, fontSize:22 }}>Bar Management</h2>
      </div>
      {confirmDlg && <ConfirmDialog message={confirmDlg.message} subMessage={confirmDlg.subMessage} onConfirm={confirmDlg.onConfirm} onCancel={()=>setConfirmDlg(null)}/>}

      {/* Sub-navigation */}
      <div style={{ display:"flex", gap:6, marginBottom:24, flexWrap:"wrap" }}>
        {subTabs.map(t => (
          <button key={t.id} onClick={() => { setEditingEvent(null); setBarView(t.id); }} style={{ background: barView===t.id ? T.midBlue : "#fff", color: barView===t.id ? "#fff" : T.textMid, border:`1.5px solid ${barView===t.id ? T.midBlue : T.border}`, padding:"8px 18px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:barView===t.id?700:400 }}>
            {t.label}
          </button>
        ))}
      </div>

      {barView === "stock"     && <StockView products={products} stock={stock} events={events}/>}
      {barView === "order"     && <EventEntryView type="order"     products={products} stock={stock} events={events} staff={staff} editingEvent={editingEvent} onSave={handleSaveEvent} onCancel={() => { setEditingEvent(null); setBarView("history"); }}/>}
      {barView === "stocktake" && <EventEntryView type="stocktake" products={products} stock={stock} events={events} staff={staff} editingEvent={editingEvent} onSave={handleSaveEvent} onCancel={() => { setEditingEvent(null); setBarView("history"); }}/>}
      {barView === "history"   && <EventHistoryView events={events} products={products} onEdit={handleEditEvent} onDelete={handleDeleteEvent}/>}
      {barView === "report"    && <BarReportView  products={products} events={events}/>}
      {barView === "reconcile" && <BarReconcileView products={products} events={events}/>}
      {barView === "rota"      && <StaffingRota bookings={farmEvents} staff={staff}/>}
      {barView === "eventrota" && <StaffTimelineReport bookings={farmEvents} staff={staff}/>}
      {barView === "products"  && <ProductsView   products={products} onSave={saveProducts}/>}
    </div>
  );
}

// ─── Current Stock ────────────────────────────────────────────────────────────
function StockView({ products, stock, events }) {
  const lastStocktake = [...events].filter(e=>e.type==="stocktake").sort((a,b)=>b.date>a.date?1:-1)[0];
  const lastOrder     = [...events].filter(e=>e.type==="order").sort((a,b)=>b.date>a.date?1:-1)[0];

  return (
    <div>
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:16, marginBottom:24 }}>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:6 }}>Last Stocktake</div>
          <div style={{ fontSize:18, fontWeight:700, color:T.midBlue }}>{lastStocktake ? lastStocktake.date : "None yet"}</div>
          {lastStocktake && <div style={{ fontSize:12, color:T.textLight, marginTop:3 }}>{lastStocktake.label || ""}</div>}
        </div>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:6 }}>Last Order</div>
          <div style={{ fontSize:18, fontWeight:700, color:T.midBlue }}>{lastOrder ? lastOrder.date : "None yet"}</div>
          {lastOrder && <div style={{ fontSize:12, color:T.textLight, marginTop:3 }}>{lastOrder.label || ""}</div>}
        </div>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:6 }}>Stock Value (Cost)</div>
          <div style={{ fontSize:18, fontWeight:700, color:T.midBlue }}>
            {fmt2(products.reduce((s,p) => s + (stock[p.id]||0) * (p.costUnit||0), 0))}
          </div>
        </div>
      </div>

      {BAR_CATEGORIES.map(cat => {
        const prods = products.filter(p => p.category === cat);
        if (!prods.length) return null;
        const cc = CAT_COLOURS[cat];
        return (
          <div key={cat} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, marginBottom:16, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
            <div style={{ padding:"12px 20px", background:cc.bg, borderBottom:`1px solid ${cc.border}`, display:"flex", alignItems:"center", gap:10 }}>
              <CatBadge cat={cat}/>
              <span style={{ fontSize:12, color:cc.text, fontWeight:500 }}>{prods.length} products</span>
              <span style={{ marginLeft:"auto", fontSize:12, color:cc.text, fontWeight:600 }}>
                Stock value: {fmt2(prods.reduce((s,p) => s + (stock[p.id]||0) * (p.costUnit||0), 0))}
              </span>
            </div>
            <table style={{ width:"100%", borderCollapse:"collapse" }}>
              <thead>
                <tr style={{ background:"#f5f9ff" }}>
                  {["Product","Supplier","Buy Price","Multiple","Est. Sale Price","Current Stock","Stock Value"].map(h => (
                    <th key={h} style={{ padding:"8px 14px", textAlign:"left", color:T.textMid, fontSize:11, letterSpacing:1.1, textTransform:"uppercase", fontWeight:700 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {prods.map((p,i) => {
                  const qty = stock[p.id] || 0;
                  const stockVal = p.costUnit ? qty * p.costUnit : null;
                  const salePrice = p.costUnit ? p.costUnit * p.multiple : null;
                  const low = qty <= 2;
                  return (
                    <tr key={p.id} style={{ borderTop:i>0?`1px solid ${T.border}`:"none", background:low&&qty===0?"#fff5f5":low?"#fffbeb":"transparent" }}>
                      <td style={{ padding:"10px 14px", fontSize:13, fontWeight:600, color:T.text }}>{p.name}</td>
                      <td style={{ padding:"10px 14px", fontSize:12, color:T.textLight }}>{p.supplier}</td>
                      <td style={{ padding:"10px 14px", fontSize:13 }}>{fmt2(p.costUnit)}</td>
                      <td style={{ padding:"10px 14px", fontSize:13, color:T.textMid }}>{p.multiple}x</td>
                      <td style={{ padding:"10px 14px", fontSize:13, color:T.green, fontWeight:500 }}>{fmt2(salePrice)}</td>
                      <td style={{ padding:"10px 14px" }}>
                        <span style={{ fontSize:14, fontWeight:700, color:qty===0?T.red:qty<=3?T.amber:T.text }}>{qty}</span>
                        {qty===0 && <span style={{ fontSize:10, color:T.red, marginLeft:6, fontWeight:600 }}>OUT</span>}
                        {qty>0&&qty<=3 && <span style={{ fontSize:10, color:T.amber, marginLeft:6, fontWeight:600 }}>LOW</span>}
                      </td>
                      <td style={{ padding:"10px 14px", fontSize:13, color:T.textMid }}>{stockVal != null ? fmt2(stockVal) : "—"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        );
      })}
    </div>
  );
}

// ─── Order / Stocktake Entry ──────────────────────────────────────────────────
function ProductEntryCard({ p, lines, stock, setLine, isOrder, prevCount, tillUse, ordered }) {
  const val      = lines[p.id];
  const curStock = stock[p.id] || 0;
  const hasVal   = val !== "" && val != null && Number(val) !== 0;
  // On a stocktake, what the count *should* be: last count + anything delivered
  // since, less what the till says was sold.
  const showCols = !isOrder && prevCount !== undefined;
  // Expected always resolves to a number so the three columns visibly add up,
  // even when nothing was delivered or nothing sold. A missing till figure is
  // treated as zero rather than blanking the whole calculation.
  const tillNum  = Number(tillUse) || 0;
  const expected = showCols ? (Number(prevCount)||0) + (Number(ordered)||0) - tillNum : null;
  const entered  = val === "" || val == null ? null : Number(val);
  const drift    = (expected !== null && entered !== null) ? entered - expected : null;
  const stockOut  = curStock === 0;
  const stockLow  = curStock <= 3;
  const stockColour = stockOut ? T.red : stockLow ? T.amber : T.green;
  const stockBg    = stockOut ? T.redBg : stockLow ? T.amberBg : T.greenBg;
  return (
    <div style={{ display:"flex", alignItems:"center", gap:10, padding:"8px 12px", background:hasVal?T.accentLight:T.bgInput, border:`1.5px solid ${hasVal?T.accentMid:T.border}`, borderRadius:8, transition:"all .15s" }}>
      <div style={{ flex:1, minWidth:0 }}>
        <div style={{ fontSize:13, fontWeight:600, color:T.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{p.name}</div>
        <div style={{ fontSize:11, color:T.textLight, marginTop:2 }}>Buy: {fmt2(p.costUnit)}</div>
      </div>
      {isOrder && (
        <div style={{ flexShrink:0, display:"flex", flexDirection:"column", alignItems:"center", background:stockBg, border:`1px solid ${stockColour}`, borderRadius:6, padding:"3px 8px", minWidth:44 }}>
          <span style={{ fontSize:16, fontWeight:700, color:stockColour, lineHeight:1.1 }}>{curStock}</span>
          <span style={{ fontSize:9, fontWeight:600, color:stockColour, textTransform:"uppercase", letterSpacing:.5 }}>{stockOut?"out":stockLow?"low":"in stock"}</span>
        </div>
      )}
      {/* Stocktake: last stocktake · added · till use · expected · actual */}
      {showCols && (
        <>
          <div style={{ flexShrink:0, textAlign:"center", width:62, fontSize:15, fontWeight:700, color:T.textMid }}>{prevCount}</div>
          <div style={{ flexShrink:0, textAlign:"center", width:52, fontSize:15, fontWeight:700, color: ordered > 0 ? T.midBlue : T.textLight }}>
            {ordered > 0 ? "+" + ordered : "0"}
          </div>
          <div style={{ flexShrink:0, textAlign:"center", width:62, fontSize:15, fontWeight:700, color: tillNum > 0 ? T.accent : T.textLight }}>
            {tillNum > 0 ? "−" + (Math.round(tillNum*100)/100) : "0"}
          </div>
          <div style={{ flexShrink:0, textAlign:"center", width:62, fontSize:15, fontWeight:800, color:T.text, background:T.bgInput, borderRadius:6, padding:"3px 0" }}>
            {Math.round(expected*100)/100}
          </div>
        </>
      )}

      <div style={{ display:"flex", alignItems:"center", justifyContent:"center", gap:6, flexShrink:0, width: showCols ? 104 : undefined }}>
        {isOrder && (
          <button onClick={()=>setLine(p.id, Math.max(0,(Number(val)||0)-1))} style={{ width:26, height:26, border:`1px solid ${T.border}`, borderRadius:4, background:"#fff", cursor:"pointer", fontSize:16, color:T.textMid, display:"flex", alignItems:"center", justifyContent:"center" }}>−</button>
        )}
        <div style={{ display:"flex", flexDirection:"column", alignItems:"center", gap:2 }}>
          {/* Counted figure — left blank so it's a genuine count, not a nudge
              towards whatever the system already thinks is on the shelf. */}
          <input
            type="number" min="0" step={isOrder ? 1 : (p.category === "Softs" ? 1 : 0.5)}
            value={val ?? ""}
            placeholder={isOrder ? "" : "count"}
            onChange={e => setLine(p.id, e.target.value)}
            style={{ width:70, textAlign:"center", background:"#fff", border:`1.5px solid ${drift!==null&&Math.abs(drift)>=1?T.red:T.border}`, borderRadius:6, color:T.text, fontSize:14, padding:"5px 6px", outline:"none" }}
          />
          {showCols && drift !== null && Math.abs(drift) >= 0.01 && (
            <span style={{ fontSize:9, fontWeight:700, color: Math.abs(drift)>=1 ? T.red : T.amber, whiteSpace:"nowrap" }}>
              {(drift>0?"+":"") + (Math.round(drift*100)/100)}
            </span>
          )}
        </div>
        {isOrder && (
          <button onClick={()=>setLine(p.id, (Number(val)||0)+1)} style={{ width:26, height:26, border:`1px solid ${T.border}`, borderRadius:4, background:"#fff", cursor:"pointer", fontSize:16, color:T.textMid, display:"flex", alignItems:"center", justifyContent:"center" }}>+</button>
        )}
        {isOrder && <span style={{ fontSize:11, color:T.textLight, width:28 }}>units</span>}
        {!isOrder && !showCols && <span style={{ fontSize:11, color:T.textLight, width:28 }}>in stock</span>}
      </div>
    </div>
  );
}

function EventEntryView({ type, products, stock, onSave, onCancel, editingEvent, events, staff }) {
  const today = new Date().toISOString().slice(0,10);
  const [date,  setDate]  = useState(editingEvent?.date  || today);
  const [label, setLabel] = useState(editingEvent?.label || "");
  const [lines, setLines] = useState(editingEvent?.lines || {});
  const [countedBy, setCountedBy] = useState(editingEvent?.countedBy || "");
  const [saving, setSaving] = useState(false);

  // ── Stocktake helper columns: last count, deliveries since, till usage ──────
  const [tillUse, setTillUse]         = useState(null);   // productId -> containers
  const [tillState, setTillState]     = useState("idle"); // idle | loading | ok | error
  const [tillErr, setTillErr]         = useState(null);
  const [posMap, setPosMap]           = useState(null);

  // The stocktake immediately before this one (ignoring the one being edited).
  const prevStocktake = (function() {
    const prior = (events || [])
      .filter(function(e) {
        return e.type === "stocktake" && e.date <= date &&
               (!editingEvent || e.id !== editingEvent.id);
      })
      .sort(function(a,b){ return a.date > b.date ? 1 : -1; });
    return prior.length ? prior[prior.length - 1] : null;
  })();

  // Deliveries booked in between that stocktake and this one.
  const orderedSince = (function() {
    const out = {};
    if (!prevStocktake) return out;
    (events || []).forEach(function(e) {
      if (e.type !== "order") return;
      if (!(e.date >= prevStocktake.date && e.date <= date)) return;
      Object.entries(e.lines || {}).forEach(function(kv) {
        out[kv[0]] = (out[kv[0]] || 0) + Number(kv[1] || 0);
      });
    });
    return out;
  })();

  useEffect(function() {
    if (type !== "stocktake") return;
    (async function() {
      try { const r = await sbGet(BAR_POS_MAP_KEY); setPosMap(r || {}); } catch (e) { setPosMap({}); }
    })();
  }, [type]);

  // Pull till usage automatically once the recipe mapping is available, so the
  // expected figures are there before anyone starts counting. The button stays
  // for a manual refresh. Guarded by a ref so it fires once per stocktake
  // rather than on every render — Zettle rate-limits repeated calls.
  const autoTillRef = useRef(false);
  useEffect(function() {
    if (type !== "stocktake") return;
    if (posMap === null) return;          // mapping still loading
    if (!prevStocktake) return;           // nothing to measure from
    if (autoTillRef.current) return;
    autoTillRef.current = true;
    loadTillUse();
  }, [type, posMap, prevStocktake && prevStocktake.date]);

  async function loadTillUse() {
    if (!prevStocktake) { setTillErr("No earlier stocktake to measure from."); setTillState("error"); return; }
    setTillState("loading"); setTillErr(null);
    try {
      const res = await fetch("/.netlify/functions/zettle-sales", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ startDate: prevStocktake.date, endDate: date })
      });
      const data = await res.json();
      if (!res.ok || data.error) throw new Error(data.error || "Could not load till sales");
      const cons = consumptionFromSales(data.byProduct || [], posMap || {}, products);
      const perProduct = {};
      products.forEach(function(p) {
        const c = cons[p.id];
        if (!c) return;
        const containers = containersFromConsumption(c, p);
        if (containers !== null) perProduct[p.id] = containers;
      });
      setTillUse(perProduct);
      setTillState("ok");
    } catch (e) {
      setTillErr(String(e.message || e));
      setTillState("error");
    }
  }

  // A stocktake starts EMPTY. Pre-filling with the system's current figure
  // invites confirming it rather than counting, which defeats the point.
  const initStocktake = () => {
    if (editingEvent) return; // editing: keep whatever was recorded
    setLines({});
  };

  useEffect(() => {
    if (type === "stocktake" && !editingEvent) initStocktake();
  }, []);

  const setLine = (pid, val) => setLines(l => ({ ...l, [pid]: val === "" ? "" : Number(val) }));

  const handleSave = async () => {
    if (!date) { alert("Please set a date."); return; }
    setSaving(true);
    const ev = {
      id:    editingEvent?.id || `ev_${Date.now()}`,
      type,
      date,
      label: label || (type === "order" ? "Order" : "Stocktake"),
      countedBy: type === "order" ? undefined : (countedBy || "").trim(),
      // Orders: 0/blank means "don't order this", so those lines are dropped.
      // Stocktakes: 0 is a genuine, meaningful count (out of stock) and must
      // be kept — computeStock() sets stock absolutely from the latest
      // stocktake's lines, so dropping a 0 here meant that product's stock
      // silently kept its old (non-zero) value instead of being zeroed out.
      lines: Object.fromEntries(Object.entries(lines).filter(([,v]) => v !== "" && v != null && (type === "order" ? v !== 0 : true))),
    };
    await onSave(ev);
    setSaving(false);
  };

  const isOrder  = type === "order";
  const isEditing = !!editingEvent;
  const title    = isEditing
    ? `Edit ${isOrder ? "Order" : "Stocktake"}: ${editingEvent.label}`
    : isOrder ? "New Order" : "New Stocktake";
  const hint     = isOrder
    ? "Enter quantities ordered for each product. Leave blank or 0 to skip."
    : "Enter actual counted stock for each product.";

  // On a stocktake a counted zero is a real answer, so count anything entered.
  const totalLines = Object.entries(lines).filter(([,v]) => v !== "" && v != null && (isOrder ? Number(v) > 0 : true)).length;
  const uncounted  = isOrder ? 0 : Math.max(0, products.length - totalLines);
  const totalCost  = isOrder
    ? products.reduce((s,p) => s + (Number(lines[p.id]||0)) * (p.costUnit||0), 0)
    : null;

  return (
    <div>
      {/* Header */}
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 24px", marginBottom:20, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <h3 style={{ margin:"0 0 16px", color:T.midBlue, fontWeight:700, fontSize:17 }}>{title}</h3>
        <p style={{ margin:"0 0 16px", fontSize:13, color:T.textMid }}>{hint}</p>
        <div style={{ display:"flex", gap:20, flexWrap:"wrap", alignItems:"flex-end" }}>
          <div>
            <FLabel>Date</FLabel>
            <FInput type="date" value={date} onChange={setDate}/>
          </div>
          <div style={{ flex:1, minWidth:180 }}>
            <FLabel>Label (optional)</FLabel>
            <FInput value={label} onChange={setLabel} placeholder={isOrder ? "e.g. Order before 14 June wedding" : "e.g. After 14 June wedding"}/>
          </div>
          {!isOrder && (
            <div style={{ minWidth:170 }}>
              <FLabel>Counted by</FLabel>
              <input list="hbf-staff-names" value={countedBy} onChange={function(e){ setCountedBy(e.target.value); }}
                placeholder="Who did the count?"
                style={{ width:"100%", background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:14, padding:"8px 11px", outline:"none" }}/>
              <datalist id="hbf-staff-names">
                {(staff || []).map(function(s){ return <option key={s.id} value={s.name}/>; })}
              </datalist>
            </div>
          )}
          {(totalLines > 0 || !isOrder) && (
            <div style={{ background:T.accentLight, borderRadius:8, padding:"10px 16px", display:"flex", gap:20, flexWrap:"wrap" }}>
              <span style={{ fontSize:13, color:T.midBlue }}>
                <strong>{totalLines}</strong>{isOrder ? " lines" : " of " + products.length + " counted"}
              </span>
              {!isOrder && uncounted > 0 && (
                <span style={{ fontSize:13, color:T.amber, fontWeight:600 }} title="Products left blank keep their previous stock figure">
                  {uncounted} not counted
                </span>
              )}
              {totalCost > 0 && <span style={{ fontSize:13, color:T.midBlue }}>Est. cost: <strong>{fmt2(totalCost)}</strong></span>}
            </div>
          )}
        </div>

        {/* Till usage since the last count */}
        {!isOrder && (
          <div style={{ marginTop:14, paddingTop:14, borderTop:`1px solid ${T.border}`, display:"flex", alignItems:"center", gap:12, flexWrap:"wrap" }}>
            {prevStocktake ? (
              <>
                <span style={{ fontSize:12, color:T.textMid }}>
                  Last count <strong>{prevStocktake.date}</strong>{prevStocktake.label ? " — " + prevStocktake.label : ""}
                </span>
                <button type="button" onClick={function(){ autoTillRef.current = true; loadTillUse(); }} disabled={tillState==="loading"}
                  style={{ background: tillState==="ok" ? "#fff" : T.midBlue, color: tillState==="ok" ? T.midBlue : "#fff",
                    border: tillState==="ok" ? `1.5px solid ${T.midBlue}` : "none",
                    padding:"7px 16px", borderRadius:6, cursor: tillState==="loading"?"wait":"pointer", fontFamily:"inherit", fontSize:12, fontWeight:700 }}>
                  {tillState==="loading" ? "Loading till…" : tillState==="ok" ? "Refresh till usage" : "Load till usage"}
                </button>
                {tillState==="loading" && (
                  <span style={{ fontSize:11, color:T.textLight }}>Reading the till…</span>
                )}
                {tillState==="ok" && (
                  <span style={{ fontSize:11, color:T.textLight }}>
                    Expected = last count + added − till use.
                  </span>
                )}
                {tillState==="idle" && (
                  <span style={{ fontSize:11, color:T.amber }}>
                    Till usage not loaded — expected figures assume nothing was sold.
                  </span>
                )}
                {tillState==="error" && <span style={{ fontSize:11, color:T.red }}>{tillErr}</span>}
              </>
            ) : (
              <span style={{ fontSize:12, color:T.textLight }}>No earlier stocktake, so there's nothing to compare against yet.</span>
            )}
          </div>
        )}
      </div>

      {/* Product lines — orders: by supplier then category; stocktakes: by category only */}
      {isOrder ? (
        // ORDER: group by supplier, then category within each supplier
        (() => {
          const suppliers = [...new Set(products.map(p => p.supplier))].sort();
          return suppliers.map(supplier => {
            const supplierProds = products.filter(p => p.supplier === supplier);
            if (!supplierProds.length) return null;
            const cats = [...new Set(supplierProds.map(p => p.category))];
            return (
              <div key={supplier} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, marginBottom:14, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
                <div style={{ padding:"10px 18px", background:T.midBlueBg, borderBottom:`1px solid ${T.border}`, display:"flex", alignItems:"center", gap:10 }}>
                  <span style={{ fontSize:13, fontWeight:700, color:T.midBlue }}>{supplier}</span>
                  <span style={{ fontSize:11, color:T.textLight }}>{supplierProds.length} product{supplierProds.length!==1?"s":""}</span>
                </div>
                {cats.map(cat => {
                  const prods = supplierProds.filter(p => p.category === cat);
                  const cc = CAT_COLOURS[cat];
                  return (
                    <div key={cat}>
                      <div style={{ padding:"6px 18px", background:cc.bg, borderBottom:`1px solid ${cc.border}`, borderTop:`1px solid ${cc.border}`, display:"flex", alignItems:"center", gap:8 }}>
                        <CatBadge cat={cat}/>
                      </div>
                      <div style={{ padding:"12px 18px", display:"grid", gridTemplateColumns:"1fr", gap:"8px" }}>
                        {prods.map(p => <ProductEntryCard key={p.id} p={p} lines={lines} stock={stock} setLine={setLine} isOrder={true}/>)}
                      </div>
                    </div>
                  );
                })}
              </div>
            );
          });
        })()
      ) : (
        // STOCKTAKE: group by category only
        BAR_CATEGORIES.map(cat => {
          const prods = products.filter(p => p.category === cat);
          if (!prods.length) return null;
          const cc = CAT_COLOURS[cat];
          return (
            <div key={cat} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, marginBottom:14, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
              <div style={{ padding:"10px 18px", background:cc.bg, borderBottom:`1px solid ${cc.border}` }}>
                <CatBadge cat={cat}/>
              </div>
              {/* Column headings, so the four figures either side of the count
                  box are labelled once rather than only under each number. */}
              <div style={{ padding:"6px 18px", display:"flex", alignItems:"center", gap:10, background:"#f8fafd", borderBottom:`1px solid ${T.border}`,
                fontSize:9, letterSpacing:.6, textTransform:"uppercase", fontWeight:700, color:T.textLight }}>
                <span style={{ flex:1, minWidth:0 }}>Product</span>
                <span style={{ width:62, textAlign:"center", flexShrink:0 }}>Last check</span>
                <span style={{ width:52, textAlign:"center", flexShrink:0 }}>Ordered</span>
                <span style={{ width:62, textAlign:"center", flexShrink:0 }}>Till use</span>
                <span style={{ width:62, textAlign:"center", flexShrink:0 }}>Expected</span>
                <span style={{ width:104, textAlign:"center", flexShrink:0 }}>Stock check</span>
              </div>
              <div style={{ padding:"14px 18px", display:"grid", gridTemplateColumns:"1fr", gap:"8px" }}>
                {prods.map(p => <ProductEntryCard key={p.id} p={p} lines={lines} stock={stock} setLine={setLine} isOrder={false}
                  prevCount={prevStocktake ? Number(prevStocktake.lines?.[p.id] || 0) : 0}
                  ordered={orderedSince[p.id] || 0}
                  tillUse={tillUse ? (tillUse[p.id] !== undefined ? tillUse[p.id] : 0) : 0}/>)}
              </div>
            </div>
          );
        })
      )}

      <div style={{ display:"flex", gap:12, marginTop:8, position:"sticky", bottom:20 }}>
        <button onClick={handleSave} disabled={saving} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"13px 36px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:15, fontWeight:700, boxShadow:"0 2px 8px rgba(30,77,140,.25)" }}>
          {saving ? "Saving…" : isEditing ? "Save Changes" : isOrder ? "Save Order" : "Save Stocktake"}
        </button>
        {onCancel && (
          <button onClick={onCancel} style={{ background:"none", color:T.textMid, border:`1px solid ${T.border}`, padding:"13px 24px", borderRadius:8, cursor:"pointer", fontFamily:"inherit", fontSize:14 }}>
            Cancel
          </button>
        )}
      </div>
    </div>
  );
}

// ─── Event History ────────────────────────────────────────────────────────────
function EventHistoryView({ events, products, onEdit, onDelete }) {
  const [printMode, setPrintMode] = useState(false);
  const sorted = [...events].sort((a,b) => b.date > a.date ? 1 : -1);
  const [expanded, setExpanded] = useState(null);

  const printText = sorted.map(ev => {
    const isOrder = ev.type === "order";
    const lines = Object.entries(ev.lines||{}).map(([pid,qty]) => {
      const prod = products.find(p=>p.id===pid);
      return `  ${prod ? prod.name : pid}: ${qty}`;
    });
    const head = `${ev.date} — ${isOrder?"ORDER":"STOCKTAKE"}: ${ev.label||""}` + (ev.countedBy ? `  (counted by ${ev.countedBy})` : "");
    return [head, ...lines].join("\n");
  }).join("\n\n");

  if(printMode) return (
    <div>
      <button onClick={()=>setPrintMode(false)} style={{ marginBottom:14, background:T.midBlueBg, border:`1px solid ${T.border}`, color:T.midBlue, padding:"7px 16px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>← Back</button>
      <pre style={{ background:"#f8fafd", border:`1px solid ${T.border}`, borderRadius:8, padding:"16px 20px", fontSize:13, fontFamily:"inherit", lineHeight:1.8, whiteSpace:"pre-wrap", color:T.text }}>{printText||"No history yet."}</pre>
    </div>
  );

  if (!sorted.length) {
    return (
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:48, textAlign:"center", color:T.textLight }}>
        <p style={{ fontSize:16 }}>No orders or stocktakes recorded yet.</p>
      </div>
    );
  }

  return (
    <div>
      <div style={{ display:"flex", justifyContent:"flex-end", marginBottom:14 }}>
        <button onClick={()=>window.print()} style={{ background:T.midBlueBg, border:`1px solid ${T.border}`, color:T.midBlue, padding:"7px 16px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>🖨 Print / Save as PDF</button>
      </div>
      <div style={{ display:"flex", gap:16, marginBottom:18 }}>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"14px 20px", flex:1, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:4 }}>Stocktakes</div>
          <div style={{ fontSize:24, fontWeight:700, color:T.midBlue }}>{sorted.filter(e=>e.type==="stocktake").length}</div>
        </div>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"14px 20px", flex:1, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:4 }}>Orders</div>
          <div style={{ fontSize:24, fontWeight:700, color:T.midBlue }}>{sorted.filter(e=>e.type==="order").length}</div>
        </div>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"14px 20px", flex:1, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:4 }}>Total Est. Ordered</div>
          <div style={{ fontSize:24, fontWeight:700, color:T.midBlue }}>
            {fmt2(sorted.filter(e=>e.type==="order").reduce((sum,ev) =>
              sum + products.reduce((s,p) => s + (Number(ev.lines?.[p.id]||0)) * (p.costUnit||0), 0), 0
            ))}
          </div>
        </div>
      </div>

      <div style={{ display:"flex", flexDirection:"column", gap:10 }}>
        {sorted.map(ev => {
          const isOrder     = ev.type === "order";
          const isExpanded  = expanded === ev.id;
          const lineCount   = Object.keys(ev.lines||{}).length;
          const orderCost   = isOrder ? products.reduce((s,p) => s + (Number(ev.lines?.[p.id]||0)) * (p.costUnit||0), 0) : null;
          const typeColour  = isOrder
            ? { bg:T.midBlueBg, text:T.midBlue, border:T.border, label:"Order" }
            : { bg:T.greenBg,   text:T.green,   border:"#86efac", label:"Stocktake" };

          return (
            <div key={ev.id} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
              {/* Row header */}
              <div style={{ display:"flex", alignItems:"center", gap:14, padding:"14px 18px", cursor:"pointer" }}
                onClick={() => setExpanded(isExpanded ? null : ev.id)}>
                {/* Type badge */}
                <span style={{ fontSize:11, fontWeight:700, padding:"3px 10px", borderRadius:10, background:typeColour.bg, color:typeColour.text, border:`1px solid ${typeColour.border}`, flexShrink:0 }}>
                  {typeColour.label}
                </span>
                {/* Date */}
                <span style={{ fontSize:14, fontWeight:700, color:T.accent, flexShrink:0 }}>
                  {new Date(ev.date+"T00:00:00").toLocaleDateString("en-GB",{day:"numeric",month:"short",year:"numeric"})}
                </span>
                <span style={{ fontSize:12, color:T.textLight, flexShrink:0 }}>
                  {dayOfWeek(ev.date)}
                </span>
                {/* Label */}
                <span style={{ fontSize:14, color:T.text, fontWeight:500, flex:1, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                  {ev.label}
                </span>
                {/* Meta */}
                {ev.countedBy && <span style={{ fontSize:11, color:T.textMid, flexShrink:0 }}>counted by {ev.countedBy}</span>}
                <span style={{ fontSize:12, color:T.textLight, flexShrink:0 }}>{lineCount} product{lineCount!==1?"s":""}</span>
                {orderCost > 0 && <span style={{ fontSize:13, fontWeight:600, color:T.midBlue, flexShrink:0 }}>{fmt2(orderCost)}</span>}
                {/* Actions */}
                <div style={{ display:"flex", gap:6, flexShrink:0 }} onClick={e=>e.stopPropagation()}>
                  <button onClick={()=>onEdit(ev)} style={{ background:T.accentLight, border:"none", color:T.accent, padding:"4px 12px", borderRadius:5, cursor:"pointer", fontSize:12, fontFamily:"inherit", fontWeight:600 }}>Edit</button>
                  <button onClick={()=>onDelete(ev.id)} style={{ background:T.redBg, border:"none", color:T.red, padding:"4px 10px", borderRadius:5, cursor:"pointer", fontSize:12, fontFamily:"inherit" }}>✕</button>
                </div>
                <span style={{ fontSize:14, color:T.textLight }}>{isExpanded?"▲":"▼"}</span>
              </div>

              {/* Expanded product lines */}
              {isExpanded && (
                <div style={{ borderTop:`1px solid ${T.border}`, background:T.bg, padding:"12px 18px" }}>
                  <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fill, minmax(240px,1fr))", gap:"8px 16px" }}>
                    {Object.entries(ev.lines||{}).map(([pid, qty]) => {
                      const prod = products.find(p=>p.id===pid);
                      if (!prod) return null;
                      const lineVal = isOrder && prod.costUnit ? qty * prod.costUnit : null;
                      return (
                        <div key={pid} style={{ display:"flex", alignItems:"center", gap:8, padding:"6px 10px", background:"#fff", borderRadius:6, border:`1px solid ${T.border}` }}>
                          <CatBadge cat={prod.category}/>
                          <span style={{ flex:1, fontSize:12, fontWeight:500, color:T.text, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>{prod.name}</span>
                          <span style={{ fontSize:13, fontWeight:700, color:T.midBlue, flexShrink:0 }}>{qty}</span>
                          {lineVal != null && <span style={{ fontSize:11, color:T.textLight, flexShrink:0 }}>{fmt2(lineVal)}</span>}
                        </div>
                      );
                    })}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Bar Usage Report ─────────────────────────────────────────────────────────
// ═══════════════════════════════════════════════════════════════════════════════
// POS RECONCILIATION (Zettle / PayPal)
// ═══════════════════════════════════════════════════════════════════════════════
const BAR_POS_MAP_KEY = "hbf_bar_pos_map_v1";

// Loose name matching so most till products pair themselves with bar products
// without anyone having to map them by hand.
function normaliseProductName(s) {
  return String(s || "")
    .toLowerCase()
    .replace(/[^a-z0-9 ]+/g, " ")
    .replace(/\b(bottle|btl|glass|gls|pint|half|single|double|shot|small|large|sml|lrg|ml|cl|ltr|l)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function nameSimilarity(a, b) {
  const A = normaliseProductName(a), B = normaliseProductName(b);
  if (!A || !B) return 0;
  if (A === B) return 1;
  const aw = A.split(" ").filter(Boolean), bw = B.split(" ").filter(Boolean);
  if (!aw.length || !bw.length) return 0;
  let hits = 0;
  aw.forEach(function(w) { if (w.length > 2 && bw.indexOf(w) !== -1) hits++; });
  return hits / Math.max(aw.length, bw.length);
}

// Suggest a bar product for a POS line. Only reasonably confident pairings are
// auto-applied; the rest are left for manual mapping so nothing is quietly wrong.
function suggestProductMatch(posName, products) {
  let best = null, bestScore = 0;
  (products || []).forEach(function(p) {
    const s = nameSimilarity(posName, p.name);
    if (s > bestScore) { bestScore = s; best = p; }
  });
  return bestScore >= 0.5 ? { product: best, score: bestScore } : null;
}

// ── Recipes ───────────────────────────────────────────────────────────────────
// A till product maps to one or more bar products with a measure each, so a
// cocktail can draw down several bottles:
//   "Aperol Spritz" -> [{ Aperol, 100, ml }, { Prosecco, 200, ml }]
//   "Tequila shot"  -> [{ Tequila, 25, ml }]
//   "Bottled beer"  -> [{ Peroni, 1, each }]
// Stored as { components: [...] }; an empty components list means "ignore".
const DEFAULT_MEASURE_BY_CATEGORY = {
  Spirits:   { qty: 25,  unit: "ml"   },
  Wine:      { qty: 175, unit: "ml"   },
  Cocktails: { qty: 50,  unit: "ml"   },
  Beer:      { qty: 1,   unit: "each" },
  Softs:     { qty: 1,   unit: "each" }
};

function defaultMeasureFor(product) {
  const d = DEFAULT_MEASURE_BY_CATEGORY[product && product.category];
  if (d) return { qty: d.qty, unit: d.unit };
  return { qty: 1, unit: "each" };
}

// Normalise whatever is stored for a till product into a recipe object.
// Tolerates the earlier "just a product id string" format.
function normaliseRecipe(entry) {
  if (entry === "" || entry === null) return { components: [] };           // explicitly ignored
  if (typeof entry === "string") return { components: [{ productId: entry, qty: 1, unit: "each" }] };
  if (entry && Array.isArray(entry.components)) return entry;
  return null;                                                             // unmapped
}

// Millilitres (or whole units) of each bar product implied by the till sales.
function consumptionFromSales(posLines, mapping, products) {
  const out = {};   // productId -> { ml, each, gross }
  (posLines || []).forEach(function(line) {
    const recipe = normaliseRecipe(mapping[line.key]);
    if (!recipe || !recipe.components.length) return;
    const totalQty = recipe.components.reduce(function(s, c) { return s + (Number(c.qty) || 0); }, 0) || 1;
    recipe.components.forEach(function(c) {
      if (!c.productId) return;
      if (!out[c.productId]) out[c.productId] = { ml: 0, each: 0, gross: 0 };
      const amount = (Number(c.qty) || 0) * line.units;
      if (c.unit === "each") out[c.productId].each += amount;
      else out[c.productId].ml += amount;
      // Apportion the till value across components by their share of the recipe,
      // so a cocktail's revenue isn't counted once per ingredient.
      out[c.productId].gross += line.gross * ((Number(c.qty) || 0) / totalQty);
    });
  });
  return out;
}

// Containers implied, given the product's container volume.
function containersFromConsumption(cons, product) {
  if (!cons) return null;
  const vol = Number(product && product.volumeMl) || 0;
  if (cons.ml > 0 && vol <= 0) return null;      // can't convert without a volume
  const fromMl = vol > 0 ? cons.ml / vol : 0;
  return fromMl + cons.each;
}

function BarReconcileView({ products, events }) {
  const stocktakes = [...events].filter(e => e.type === "stocktake").sort((a,b) => a.date > b.date ? 1 : -1);
  const [fromIdx, setFromIdx] = useState(Math.max(0, stocktakes.length - 2));
  const [toIdx,   setToIdx]   = useState(Math.max(0, stocktakes.length - 1));
  const [sales, setSales]     = useState(null);
  const [loading, setLoading] = useState(false);
  const [err, setErr]         = useState(null);
  const [map, setMap]         = useState({});      // posKey -> recipe ({components:[]} = ignore)
  const [mapLoaded, setMapLoaded] = useState(false);
  const [catalogue, setCatalogue] = useState(null); // full Zettle product library
  const [catLoading, setCatLoading] = useState(false);
  const [unmappedOnly, setUnmappedOnly] = useState(false);
  const [mapSearch, setMapSearch] = useState("");

  useEffect(function() {
    (async function() {
      try { const r = await sbGet(BAR_POS_MAP_KEY); setMap(r || {}); } catch (e) { setMap({}); }
      setMapLoaded(true);
    })();
  }, []);

  async function saveMap(next) {
    setMap(next);
    try { await sbSet(BAR_POS_MAP_KEY, next); } catch (e) { console.error(e); }
  }

  if (stocktakes.length < 2) {
    return (
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:48, textAlign:"center", color:T.textLight }}>
        <p style={{ fontSize:16, fontWeight:600, color:T.textMid, marginBottom:8 }}>At least two stocktakes needed</p>
        <p style={{ fontSize:13 }}>Record two stocktakes to reconcile stock usage against till sales.</p>
      </div>
    );
  }

  const fromST = stocktakes[fromIdx];
  const toST   = stocktakes[toIdx];

  async function loadSales() {
    if (!fromST || !toST || fromST.date >= toST.date) { setErr("Pick an earlier 'from' stocktake."); return; }
    setLoading(true); setErr(null); setSales(null);
    try {
      const res = await fetch("/.netlify/functions/zettle-sales", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ startDate: fromST.date, endDate: toST.date })
      });
      const data = await res.json();
      if (!res.ok || data.error) throw new Error(data.error || "Could not load Zettle sales");
      setSales(data);
    } catch (e) {
      setErr(String(e.message || e));
    }
    setLoading(false);
  }

  // ── Stock usage between the two stocktakes (same maths as the usage report) ─
  const ordersInRange = events.filter(e => e.type === "order" && e.date >= fromST.date && e.date < toST.date);
  const usage = {};
  products.forEach(function(p) {
    const opening = Number(fromST.lines?.[p.id] || 0);
    const ordered = ordersInRange.reduce((s,o) => s + Number(o.lines?.[p.id]||0), 0);
    const closing = Number(toST.lines?.[p.id] || 0);
    usage[p.id] = opening + ordered - closing;
  });

  const expectedValue = products.reduce(function(s, p) {
    const u = usage[p.id] || 0;
    return s + (u > 0 && p.costUnit ? u * p.costUnit * (p.multiple || 0) : 0);
  }, 0);

  async function loadCatalogue() {
    setCatLoading(true); setErr(null);
    try {
      const res = await fetch("/.netlify/functions/zettle-sales", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "catalogue" })
      });
      const data = await res.json();
      if (!res.ok || data.error) throw new Error(data.error || "Could not load the Zettle catalogue");
      setCatalogue(data.catalogue || []);
    } catch (e) {
      setErr(String(e.message || e));
    }
    setCatLoading(false);
  }

  // ── Pair POS lines with bar products ──────────────────────────────────────
  // The mapping list is the union of the till catalogue (so everything can be
  // mapped up front) and whatever actually sold in the period (so nothing that
  // sold is ever missing, even if it has since been deleted from the library).
  const salesLines = (sales && sales.byProduct) || [];
  const posLines = (function() {
    const byKey = {};
    (catalogue || []).forEach(function(c) {
      byKey[c.key] = { key:c.key, name:c.name, variantName:c.variantName, category:c.category,
                       units:0, gross:0, inCatalogue:true };
    });
    salesLines.forEach(function(s) {
      const existing = byKey[s.key];
      if (existing) { existing.units = s.units; existing.gross = s.gross; }
      else byKey[s.key] = { key:s.key, name:s.name, variantName:s.variantName, category:"",
                            units:s.units, gross:s.gross, inCatalogue:false };
    });
    return Object.keys(byKey).map(function(k){ return byKey[k]; })
      .sort(function(a,b){
        if (b.gross !== a.gross) return b.gross - a.gross;   // best sellers first
        return (a.name||"").localeCompare(b.name||"");
      });
  })();

  // Effective mapping: stored recipes, plus a suggested single-ingredient
  // recipe for anything not yet mapped (using a sensible default measure for
  // the category). Suggestions are shown as such and are not saved until
  // confirmed, so nothing is silently assumed.
  const effectiveMap = {};
  const suggestedKeys = {};
  posLines.forEach(function(line) {
    const stored = normaliseRecipe(map[line.key]);
    if (stored) { effectiveMap[line.key] = stored; return; }
    const s = suggestProductMatch(line.name + " " + (line.variantName||""), products);
    if (s) {
      const m = defaultMeasureFor(s.product);
      effectiveMap[line.key] = { components: [{ productId: s.product.id, qty: m.qty, unit: m.unit }] };
      suggestedKeys[line.key] = true;
    }
  });

  const consumption = consumptionFromSales(posLines, effectiveMap, products);
  const unmapped = posLines.filter(function(l) { return !effectiveMap[l.key]; });
  const suggestedCount = Object.keys(suggestedKeys).length;

  // Revenue excludes gift-card redemptions (counted when the card was sold),
  // so it can be compared with the value of stock that actually moved.
  const posGross  = sales ? (sales.revenue !== undefined ? sales.revenue : sales.gross) : 0;
  const variance  = posGross - expectedValue;
  const variancePct = expectedValue > 0 ? (variance / expectedValue) * 100 : 0;

  const rows = products.map(function(p) {
    const used = usage[p.id] || 0;
    const cons = consumption[p.id] || null;
    const soldContainers = containersFromConsumption(cons, p);
    const diff = (soldContainers !== null) ? (used - soldContainers) : null;
    return { p:p, used:used, cons:cons, soldContainers:soldContainers, diff:diff,
             soldGross: cons ? cons.gross : null };
  }).filter(r => r.used !== 0 || r.cons);

  function setRecipe(posKey, components) {
    const next = Object.assign({}, map);
    next[posKey] = { components: components };
    saveMap(next);
  }
  function ignoreLine(posKey) {
    const next = Object.assign({}, map);
    next[posKey] = { components: [] };
    saveMap(next);
  }

  const money = n => "£" + Number(n||0).toLocaleString("en-GB",{minimumFractionDigits:2,maximumFractionDigits:2});

  return (
    <div>
      {/* Period picker */}
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"16px 20px", marginBottom:18, display:"flex", alignItems:"flex-end", gap:16, flexWrap:"wrap", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <div>
          <FLabel>From stocktake</FLabel>
          <select value={fromIdx} onChange={e=>setFromIdx(Number(e.target.value))} style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:13, padding:"7px 10px" }}>
            {stocktakes.map((s,i) => <option key={s.id} value={i}>{s.date} — {s.label}</option>)}
          </select>
        </div>
        <div>
          <FLabel>To stocktake</FLabel>
          <select value={toIdx} onChange={e=>setToIdx(Number(e.target.value))} style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:13, padding:"7px 10px" }}>
            {stocktakes.map((s,i) => <option key={s.id} value={i}>{s.date} — {s.label}</option>)}
          </select>
        </div>
        <button onClick={loadSales} disabled={loading}
          style={{ background:T.midBlue, color:"#fff", border:"none", padding:"9px 22px", borderRadius:7, cursor: loading?"wait":"pointer", fontFamily:"inherit", fontSize:13, fontWeight:700 }}>
          {loading ? "Loading Zettle…" : "Load till sales"}
        </button>
        <button onClick={loadCatalogue} disabled={catLoading}
          style={{ background:"#fff", color:T.midBlue, border:`1.5px solid ${T.midBlue}`, padding:"9px 18px", borderRadius:7, cursor: catLoading?"wait":"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>
          {catLoading ? "Loading…" : catalogue ? "Reload catalogue (" + catalogue.length + ")" : "Load full till catalogue"}
        </button>
      </div>

      {err && (
        <div style={{ background:"#fef2f2", border:"1px solid #fecaca", color:"#dc2626", borderRadius:9, padding:"11px 15px", marginBottom:16, fontSize:13, lineHeight:1.6 }}>
          {err}
        </div>
      )}

      {!sales && !catalogue && !loading && !catLoading && !err && (
        <div style={{ background:"#eff6ff", border:"1px solid #bfdbfe", borderRadius:9, padding:"12px 16px", fontSize:13, color:"#1d4ed8", lineHeight:1.6 }}>
          Load the full till catalogue to map your products and recipes up front, or pick two stocktakes
          and load the sales for that period. Stock usage is compared against what Zettle actually rang up.
        </div>
      )}

      {sales && (
        <>
          {/* Headline value comparison */}
          <div style={{ display:"grid", gridTemplateColumns:"repeat(auto-fit,minmax(190px,1fr))", gap:14, marginBottom:18 }}>
            <StatCard label="Expected from stock" value={money(expectedValue)} sub={`${fromST.date} → ${toST.date}`}/>
            <StatCard label="Zettle takings" value={money(posGross)} sub={`${sales.purchaseCount} sales${sales.refundCount ? ", " + sales.refundCount + " refunds" : ""}`}/>
            <StatCard label="Variance" value={(variance>=0?"+":"") + money(variance)} sub={expectedValue>0 ? variancePct.toFixed(1) + "% of expected" : "—"}/>
          </div>

          <div style={{ background: Math.abs(variancePct) > 10 ? "#fffbeb" : "#f0fdf4",
            border:`1px solid ${Math.abs(variancePct) > 10 ? "#fde68a" : "#bbf7d0"}`,
            color: Math.abs(variancePct) > 10 ? "#92400e" : "#166534",
            borderRadius:9, padding:"11px 15px", marginBottom:18, fontSize:13, lineHeight:1.6 }}>
            {Math.abs(variancePct) > 10
              ? "Takings are " + Math.abs(variancePct).toFixed(1) + "% " + (variance < 0 ? "below" : "above") + " the value of stock used — worth investigating."
              : "Takings are within 10% of the value of stock used."}
            {sales.customAmountTotal > 0 && (
              <span> {money(sales.customAmountTotal)} was rung up as custom amounts with no product attached, so can’t be matched to stock.</span>
            )}
            {sales.giftCardsSold > 0 && (
              <span> {money(sales.giftCardsSold)} of gift cards were sold — counted as takings, but no stock moved.</span>
            )}
            {sales.giftCardsRedeemed > 0 && (
              <span> {money(sales.giftCardsRedeemed)} was spent using gift cards — the drinks drew down stock, but the money was taken when the cards were sold, so it isn’t counted again here.</span>
            )}
          </div>
        </>
      )}

      {/* Till product recipes — available as soon as either the catalogue or a
          period's sales have been loaded, so mapping can be done up front. */}
      {posLines.length > 0 && (
        <>
          <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, marginBottom:18, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
            <div style={{ padding:"12px 16px", background:"#eef4fd", borderBottom:`1px solid ${T.border}`, display:"flex", alignItems:"center", gap:10, flexWrap:"wrap" }}>
              <span style={{ fontSize:13, fontWeight:700, color:T.midBlue }}>Till products &amp; recipes</span>
              {unmapped.length > 0 && <span style={{ fontSize:11, fontWeight:700, padding:"2px 9px", borderRadius:10, background:"#fef2f2", color:"#dc2626", border:"1px solid #fecaca" }}>{unmapped.length} unmapped</span>}
              {suggestedCount > 0 && <span style={{ fontSize:11, fontWeight:700, padding:"2px 9px", borderRadius:10, background:"#fffbeb", color:"#92400e", border:"1px solid #fde68a" }}>{suggestedCount} suggested</span>}
              <span style={{ fontSize:11, color:T.textLight, flex:1, minWidth:140 }}>
                A till product can draw on several bar products — add a line per ingredient.
              </span>
              <input value={mapSearch} onChange={e=>setMapSearch(e.target.value)} placeholder="Search till products…"
                style={{ background:"#fff", border:`1.5px solid ${T.border}`, borderRadius:6, fontFamily:"inherit", fontSize:12, padding:"5px 10px", width:180 }}/>
              <label style={{ display:"flex", alignItems:"center", gap:6, fontSize:11, color:T.textMid, cursor:"pointer", whiteSpace:"nowrap" }}>
                <input type="checkbox" checked={unmappedOnly} onChange={e=>setUnmappedOnly(e.target.checked)} style={{ width:13, height:13, accentColor:T.accent, cursor:"pointer" }}/>
                Needs attention only
              </label>
            </div>
            {posLines.filter(function(line) {
              if (mapSearch) {
                const q = mapSearch.toLowerCase();
                const hay = (line.name + " " + (line.variantName||"") + " " + (line.category||"")).toLowerCase();
                if (hay.indexOf(q) === -1) return false;
              }
              if (unmappedOnly) {
                const stored = normaliseRecipe(map[line.key]);
                if (stored && stored.components.length >= 0 && !suggestedKeys[line.key]) return false;
              }
              return true;
            }).map(function(line) {
              const recipe = effectiveMap[line.key];
              const isSuggested = !!suggestedKeys[line.key];
              const comps = recipe ? recipe.components : [];
              const ignored = !!(recipe && comps.length === 0);
              return (
                <div key={line.key} style={{ padding:"10px 16px", borderTop:`1px solid ${T.border}`,
                  background: !recipe ? "#fff8f8" : isSuggested ? "#fffdf5" : "#fff" }}>
                  <div style={{ display:"flex", alignItems:"center", gap:12, flexWrap:"wrap", marginBottom: comps.length ? 7 : 0 }}>
                    <span style={{ fontSize:13, fontWeight:600, flex:1, minWidth:160 }}>
                      {line.name}{line.variantName ? " · " + line.variantName : ""}
                    </span>
                    <span style={{ fontSize:12, color:T.textLight, whiteSpace:"nowrap" }}>{line.units} sold · {money(line.gross)}</span>
                    {isSuggested && <span style={{ fontSize:10, fontWeight:700, padding:"2px 7px", borderRadius:9, background:"#fffbeb", color:"#92400e", border:"1px solid #fde68a" }}>suggested</span>}
                    {ignored && <span style={{ fontSize:10, fontWeight:700, padding:"2px 7px", borderRadius:9, background:"#f1f5f9", color:"#64748b" }}>ignored</span>}
                    <button onClick={function(){ setRecipe(line.key, comps.concat([{ productId:"", qty:25, unit:"ml" }])); }}
                      style={{ background:"none", border:`1px solid ${T.border}`, color:T.midBlue, padding:"3px 10px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:11, fontWeight:600 }}>
                      + ingredient
                    </button>
                    {!ignored && (
                      <button onClick={function(){ ignoreLine(line.key); }}
                        style={{ background:"none", border:`1px solid ${T.border}`, color:T.textLight, padding:"3px 10px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:11 }}>
                        Ignore
                      </button>
                    )}
                  </div>
                  {comps.map(function(c, ci) {
                    return (
                      <div key={ci} style={{ display:"flex", alignItems:"center", gap:8, flexWrap:"wrap", paddingLeft:14, marginBottom:5 }}>
                        <select value={c.productId||""} onChange={function(e){
                            const next = comps.slice(); next[ci] = Object.assign({}, c, { productId:e.target.value }); setRecipe(line.key, next);
                          }}
                          style={{ background:T.bgInput, border:`1.5px solid ${c.productId?T.border:"#fecaca"}`, borderRadius:6, fontFamily:"inherit", fontSize:12, padding:"5px 8px", minWidth:200 }}>
                          <option value="">Choose bar product…</option>
                          {products.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
                        </select>
                        <input type="number" value={c.qty} min="0" step="any"
                          onChange={function(e){ const next = comps.slice(); next[ci] = Object.assign({}, c, { qty:Number(e.target.value)||0 }); setRecipe(line.key, next); }}
                          style={{ width:74, background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, fontFamily:"inherit", fontSize:12, padding:"5px 8px" }}/>
                        <select value={c.unit||"ml"} onChange={function(e){
                            const next = comps.slice(); next[ci] = Object.assign({}, c, { unit:e.target.value }); setRecipe(line.key, next);
                          }}
                          style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, fontFamily:"inherit", fontSize:12, padding:"5px 8px" }}>
                          <option value="ml">ml</option>
                          <option value="each">whole units</option>
                        </select>
                        {(function(){
                          const prod = products.find(p=>p.id===c.productId);
                          if (c.unit === "ml" && prod && !Number(prod.volumeMl)) {
                            return <span style={{ fontSize:10, color:T.red }}>set container volume on {prod.name}</span>;
                          }
                          return null;
                        })()}
                        <button onClick={function(){ const next = comps.slice(); next.splice(ci,1); setRecipe(line.key, next); }}
                          style={{ background:"none", border:"none", color:T.red, cursor:"pointer", fontFamily:"inherit", fontSize:14, padding:"0 4px" }}>×</button>
                      </div>
                    );
                  })}
                  {!recipe && (
                    <div style={{ fontSize:11, color:"#dc2626", paddingLeft:14 }}>
                      Not mapped — sales of this product aren’t being compared to stock.
                    </div>
                  )}
                </div>
              );
            })}
          </div>

          {/* Product level table — only meaningful once sales are loaded */}
          {sales && (
          <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
            <div style={{ padding:"12px 18px", background:"#eef4fd", borderBottom:`1px solid ${T.border}`, fontSize:13, fontWeight:700, color:T.midBlue }}>
              Product detail
            </div>
            <div style={{ overflowX:"auto" }}>
              <table style={{ width:"100%", borderCollapse:"collapse" }}>
                <thead>
                  <tr style={{ background:"#f5f9ff" }}>
                    {["Product","Used (containers)","Container ml","Sold (ml)","Sold (units)","Implied containers","Difference","Till value"].map(h=>(
                      <th key={h} style={{ padding:"9px 12px", textAlign:"left", color:T.textMid, fontSize:10, letterSpacing:1, textTransform:"uppercase", fontWeight:700, whiteSpace:"nowrap" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map(function(r,i) {
                    const bad = r.diff !== null && Math.abs(r.diff) >= 1;
                    const needsVol = r.cons && r.cons.ml > 0 && !Number(r.p.volumeMl);
                    return (
                      <tr key={r.p.id} style={{ borderTop:i>0?`1px solid ${T.border}`:"none" }}>
                        <td style={{ padding:"8px 12px", fontSize:13 }}>{r.p.name}</td>
                        <td style={{ padding:"8px 12px", fontSize:13, fontWeight:600 }}>{r.used}</td>
                        <td style={{ padding:"8px 12px", fontSize:12, color: r.p.volumeMl ? T.textMid : T.red }}>
                          {r.p.volumeMl || (needsVol ? "not set" : "—")}
                        </td>
                        <td style={{ padding:"8px 12px", fontSize:13 }}>{r.cons && r.cons.ml ? Math.round(r.cons.ml).toLocaleString() : <span style={{color:T.textLight}}>—</span>}</td>
                        <td style={{ padding:"8px 12px", fontSize:13 }}>{r.cons && r.cons.each ? r.cons.each : <span style={{color:T.textLight}}>—</span>}</td>
                        <td style={{ padding:"8px 12px", fontSize:13 }}>{r.soldContainers !== null ? r.soldContainers.toFixed(2) : <span style={{color:T.textLight}}>—</span>}</td>
                        <td style={{ padding:"8px 12px", fontSize:13, fontWeight:700, color: r.diff===null ? T.textLight : bad ? T.red : T.green }}>
                          {r.diff === null ? "—" : (r.diff>0?"+":"") + r.diff.toFixed(2)}
                        </td>
                        <td style={{ padding:"8px 12px", fontSize:13 }}>{r.soldGross !== null ? money(r.soldGross) : <span style={{color:T.textLight}}>—</span>}</td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
            <div style={{ padding:"10px 18px", borderTop:`1px solid ${T.border}`, fontSize:11, color:T.textLight, lineHeight:1.6 }}>
              “Difference” is containers used less containers implied by till sales — a positive number means more stock went than was sold.
              Millilitres sold are divided by the container volume, so a product needs its volume set on the Products tab before it can be compared.
            </div>
          </div>
          )}
        </>
      )}
    </div>
  );
}

function BarReportView({ products, events }) {
  const stocktakes = [...events].filter(e=>e.type==="stocktake").sort((a,b)=>a.date>b.date?1:-1);
  const [fromIdx, setFromIdx] = useState(0);
  const [toIdx,   setToIdx]   = useState(Math.min(1, stocktakes.length-1));

  if (stocktakes.length < 2) {
    return (
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:48, textAlign:"center", color:T.textLight, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <div style={{ fontSize:32, marginBottom:12 }}>📦</div>
        <p style={{ fontSize:16, fontWeight:600, color:T.textMid, marginBottom:8 }}>At least two stocktakes needed</p>
        <p style={{ fontSize:13 }}>Record two stocktakes to see usage between them. Any orders placed between stocktakes will be accounted for automatically.</p>
      </div>
    );
  }

  const fromST = stocktakes[fromIdx];
  const toST   = stocktakes[toIdx];

  // Orders between the two stocktake dates (inclusive of from, exclusive of to)
  const ordersInRange = events.filter(e =>
    e.type === "order" && e.date >= fromST.date && e.date < toST.date
  );

  // Usage per product: opening + ordered - closing = used
  const rows = products.map(p => {
    const opening = Number(fromST.lines?.[p.id] || 0);
    const ordered = ordersInRange.reduce((s,o) => s + Number(o.lines?.[p.id]||0), 0);
    const closing = Number(toST.lines?.[p.id] || 0);
    const used    = opening + ordered - closing;
    const costVal = p.costUnit ? used * p.costUnit : null;
    const saleVal = p.costUnit ? used * p.costUnit * p.multiple : null;
    return { ...p, opening, ordered, closing, used, costVal, saleVal };
  }).filter(r => r.used !== 0 || r.ordered > 0);

  const totCost = rows.reduce((s,r) => s + (r.costVal||0), 0);
  const totSale = rows.reduce((s,r) => s + (r.saleVal||0), 0);
  const totUsed = rows.filter(r=>r.used>0).length;

  const handlePrint = () => {
    const win = window.open("", "_blank");
    if (!win) return;
    const tableRows = rows.map(r =>
      `<tr>
        <td>${r.name}</td>
        <td>${r.category}</td>
        <td>${r.opening}</td>
        <td>${r.ordered > 0 ? "+"+r.ordered : "0"}</td>
        <td>${r.closing}</td>
        <td style="font-weight:700;color:${r.used<0?"#c0392b":r.used>0?"#111":"#aaa"}">${r.used}</td>
        <td>${r.costUnit!=null?"£"+r.costUnit.toFixed(2):"—"}</td>
        <td>${r.costVal!=null&&r.used>0?"£"+r.costVal.toFixed(2):"—"}</td>
        <td>${r.saleVal!=null&&r.used>0?"£"+r.saleVal.toFixed(2):"—"}</td>
      </tr>`
    ).join("");
    win.document.write(`<!DOCTYPE html><html><head><title>Bar Usage Report</title>
    <style>
      body { font-family: Arial, sans-serif; font-size: 12px; color: #222; padding: 24px; }
      h1 { font-size: 20px; margin-bottom: 4px; }
      .sub { color: #666; font-size: 13px; margin-bottom: 20px; }
      .summary { display: flex; gap: 32px; margin-bottom: 24px; }
      .summary div { border: 1px solid #ddd; border-radius: 6px; padding: 12px 18px; min-width: 140px; }
      .summary .label { font-size: 10px; text-transform: uppercase; letter-spacing: 1px; color: #888; margin-bottom: 4px; }
      .summary .val { font-size: 22px; font-weight: 700; color: #1e40af; }
      table { width: 100%; border-collapse: collapse; }
      th { background: #f0f4ff; padding: 8px 10px; text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: 1px; color: #555; border-bottom: 2px solid #ddd; }
      td { padding: 7px 10px; border-bottom: 1px solid #eee; }
      tr:nth-child(even) td { background: #fafafa; }
      @media print { button { display: none; } }
    </style>
    </head><body>
    <h1>Bar Usage Report</h1>
    <div class="sub">${fromST.date} (${fromST.label}) &rarr; ${toST.date} (${toST.label})</div>
    <div class="summary">
      <div><div class="label">Products Used</div><div class="val">${totUsed}</div></div>
      <div><div class="label">Est. Cost of Stock</div><div class="val">£${totCost.toFixed(2)}</div></div>
      <div><div class="label">Est. Sale Value</div><div class="val">£${totSale.toFixed(2)}</div></div>
      ${totCost>0?`<div><div class="label">Implied Margin</div><div class="val">${Math.round((1-totCost/totSale)*100)}%</div></div>`:""}
    </div>
    <table>
      <thead><tr>
        <th>Product</th><th>Category</th><th>Opening</th><th>Ordered</th>
        <th>Closing</th><th>Used</th><th>Buy Price</th><th>Cost of Usage</th><th>Est. Sale Value</th>
      </tr></thead>
      <tbody>${tableRows}</tbody>
    </table>
    <p style="margin-top:24px;color:#aaa;font-size:11px">Hawthbush Farm Bar Usage Report — printed ${new Date().toLocaleDateString("en-GB")}</p>
    </body></html>`);
    win.document.close();
    win.focus();
    setTimeout(() => win.print(), 500);
  };

  return (
    <div>
      {/* Print button */}
      <div style={{ display:"flex", justifyContent:"flex-end", marginBottom:10 }}>
        <button onClick={handlePrint} style={{ background:T.midBlueBg, border:`1px solid ${T.border}`, color:T.midBlue, padding:"7px 16px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>🖨 Print / Save as PDF</button>
      </div>
      {/* Controls */}
      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 24px", marginBottom:22, boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <h3 style={{ margin:"0 0 14px", color:T.midBlue, fontWeight:700, fontSize:16 }}>Compare Stocktakes</h3>
        <div style={{ display:"flex", gap:24, flexWrap:"wrap", alignItems:"flex-end" }}>
          <div>
            <FLabel>From stocktake</FLabel>
            <select value={fromIdx} onChange={e=>setFromIdx(Number(e.target.value))} style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:13, padding:"8px 11px", outline:"none" }}>
              {stocktakes.map((s,i) => <option key={s.id} value={i}>{s.date} — {s.label}</option>)}
            </select>
          </div>
          <div>
            <FLabel>To stocktake</FLabel>
            <select value={toIdx} onChange={e=>setToIdx(Number(e.target.value))} style={{ background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:13, padding:"8px 11px", outline:"none" }}>
              {stocktakes.map((s,i) => <option key={s.id} value={i}>{s.date} — {s.label}</option>)}
            </select>
          </div>
          {ordersInRange.length > 0 && (
            <div style={{ background:T.midBlueBg, borderRadius:8, padding:"8px 14px", fontSize:12, color:T.midBlue, fontWeight:600 }}>
              {ordersInRange.length} order{ordersInRange.length!==1?"s":""} included between dates
            </div>
          )}
        </div>
      </div>

      {/* Summary cards */}
      <div style={{ display:"grid", gridTemplateColumns:"repeat(3,1fr)", gap:16, marginBottom:22 }}>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:6 }}>Products Used</div>
          <div style={{ fontSize:28, fontWeight:700, color:T.midBlue }}>{totUsed}</div>
        </div>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:6 }}>Est. Cost of Stock Used</div>
          <div style={{ fontSize:28, fontWeight:700, color:T.midBlue }}>{fmt2(totCost)}</div>
        </div>
        <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, padding:"18px 22px", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
          <div style={{ fontSize:11, letterSpacing:1.5, textTransform:"uppercase", color:T.textLight, fontWeight:600, marginBottom:6 }}>Est. Sale Value</div>
          <div style={{ fontSize:28, fontWeight:700, color:T.green }}>{fmt2(totSale)}</div>
          {totCost > 0 && <div style={{ fontSize:12, color:T.textLight, marginTop:3 }}>Implied margin: {Math.round((1-totCost/totSale)*100)}%</div>}
        </div>
      </div>

      {/* Breakdown by category */}
      {BAR_CATEGORIES.map(cat => {
        const catRows = rows.filter(r => r.category === cat);
        if (!catRows.length) return null;
        const cc = CAT_COLOURS[cat];
        const catCost = catRows.reduce((s,r)=>s+(r.costVal||0),0);
        const catSale = catRows.reduce((s,r)=>s+(r.saleVal||0),0);
        return (
          <div key={cat} style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, marginBottom:14, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
            <div style={{ padding:"12px 20px", background:cc.bg, borderBottom:`1px solid ${cc.border}`, display:"flex", alignItems:"center", gap:12 }}>
              <CatBadge cat={cat}/>
              <span style={{ marginLeft:"auto", fontSize:12, color:cc.text, fontWeight:600 }}>Cost: {fmt2(catCost)} · Est. sale: {fmt2(catSale)}</span>
            </div>
            <table style={{ width:"100%", borderCollapse:"collapse" }}>
              <thead>
                <tr style={{ background:"#f5f9ff" }}>
                  {["Product","Opening","Ordered","Closing","Used","Buy Price","Cost of Usage","Est. Sale Value"].map(h=>(
                    <th key={h} style={{ padding:"8px 12px", textAlign:"left", color:T.textMid, fontSize:11, letterSpacing:1.1, textTransform:"uppercase", fontWeight:700 }}>{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {catRows.map((r,i) => (
                  <tr key={r.id} style={{ borderTop:i>0?`1px solid ${T.border}`:"none", background:r.used<0?"#fff5f5":"transparent" }}>
                    <td style={{ padding:"9px 12px", fontSize:13, fontWeight:600 }}>{r.name}</td>
                    <td style={{ padding:"9px 12px", fontSize:13, color:T.textMid }}>{fmtN(r.opening)}</td>
                    <td style={{ padding:"9px 12px", fontSize:13, color:r.ordered>0?T.green:T.textLight }}>{r.ordered>0?`+${r.ordered}`:"—"}</td>
                    <td style={{ padding:"9px 12px", fontSize:13, color:T.textMid }}>{fmtN(r.closing)}</td>
                    <td style={{ padding:"9px 12px" }}>
                      <span style={{ fontSize:14, fontWeight:700, color:r.used>0?T.text:r.used<0?T.red:T.textLight }}>{r.used>0?r.used:r.used<0?`${r.used} ⚠`:"—"}</span>
                    </td>
                    <td style={{ padding:"9px 12px", fontSize:13, color:T.textMid }}>{fmt2(r.costUnit)}</td>
                    <td style={{ padding:"9px 12px", fontSize:13, fontWeight:500 }}>{r.costVal!=null&&r.used>0?fmt2(r.costVal):"—"}</td>
                    <td style={{ padding:"9px 12px", fontSize:13, color:T.green, fontWeight:500 }}>{r.saleVal!=null&&r.used>0?fmt2(r.saleVal):"—"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );
      })}
    </div>
  );
}

// ─── Products Admin ───────────────────────────────────────────────────────────
function ProductsView({ products, onSave }) {
  const [editId, setEditId]   = useState(null);
  const [form, setForm]       = useState(null);
  const [filterCat, setFilterCat] = useState("All");

  const updateForm = (k,v) => setForm(f=>({...f,[k]:v}));
  // `volumeMl` = the volume of one container (750 for a 75cl bottle of tequila,
  // 700 for 70cl, 330 for a bottle of beer). Till Reconciliation divides the
  // millilitres sold by this to work out how many containers that represents.
  // Blank means the product is only reconciled by unit, not by volume.
  const emptyProduct = () => ({ id:`p${Date.now()}`, name:"", category:"Wine", supplier:"", multiple:1, costUnit:"", volumeMl:"" });

  const handleEdit = p => { setForm({...p}); setEditId(p.id); };
  const handleNew  = () => { setForm(emptyProduct()); setEditId("new"); };
  const handleDelete = id => {
    const p = products.find(x=>x.id===id);
    if (!confirm(`Delete "${p?.name||"this product"}"? This cannot be undone.`)) return;
    onSave(products.filter(p=>p.id!==id));
  };
  const handleSubmit = () => {
    if (!form.name) { alert("Product name required."); return; }
    let updated;
    if (editId==="new") updated = [...products, {...form, multiple:Number(form.multiple), costUnit:form.costUnit?Number(form.costUnit):null, volumeMl:form.volumeMl?Number(form.volumeMl):null}];
    else updated = products.map(p=>p.id===editId?{...form,multiple:Number(form.multiple),costUnit:form.costUnit?Number(form.costUnit):null}:p);
    onSave(updated);
    setEditId(null); setForm(null);
  };

  const visibleCats = ["All", ...BAR_CATEGORIES];
  const filtered = filterCat==="All" ? products : products.filter(p=>p.category===filterCat);

  return (
    <div>
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", marginBottom:18 }}>
        <div style={{ display:"flex", gap:6 }}>
          {visibleCats.map(c=>(
            <button key={c} onClick={()=>setFilterCat(c)} style={{ background:filterCat===c?T.midBlue:"#fff", color:filterCat===c?"#fff":T.textMid, border:`1px solid ${filterCat===c?T.midBlue:T.border}`, padding:"6px 14px", borderRadius:5, cursor:"pointer", fontFamily:"inherit", fontSize:12, fontWeight:filterCat===c?700:400 }}>{c}</button>
          ))}
        </div>
        <button onClick={handleNew} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"8px 18px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13, fontWeight:600 }}>+ Add Product</button>
      </div>

      {/* Edit/Add form */}
      {form && (
        <div style={{ background:"#fff", border:`2px solid ${T.accentMid}`, borderRadius:10, padding:24, marginBottom:20, boxShadow:"0 4px 16px rgba(59,130,246,.1)" }}>
          <h3 style={{ margin:"0 0 16px", color:T.midBlue, fontWeight:700, fontSize:16 }}>{editId==="new"?"New Product":"Edit Product"}</h3>
          <div style={{ display:"grid", gridTemplateColumns:"2fr 1fr 1fr 1fr 1fr", gap:"12px 18px" }}>
            <div><FLabel required>Product Name</FLabel><FInput value={form.name} onChange={v=>updateForm("name",v)}/></div>
            <div>
              <FLabel>Category</FLabel>
              <select value={form.category} onChange={e=>updateForm("category",e.target.value)} style={{ width:"100%", background:T.bgInput, border:`1.5px solid ${T.border}`, borderRadius:6, color:T.text, fontFamily:"inherit", fontSize:14, padding:"8px 11px", outline:"none" }}>
                {BAR_CATEGORIES.map(c=><option key={c}>{c}</option>)}
              </select>
            </div>
            <div><FLabel>Supplier</FLabel><FInput value={form.supplier||""} onChange={v=>updateForm("supplier",v)}/></div>
            <div><FLabel>Buy Price (£)</FLabel><FInput type="number" value={form.costUnit||""} onChange={v=>updateForm("costUnit",v)}/></div>
            <div><FLabel>Multiple</FLabel><FInput type="number" value={form.multiple||""} onChange={v=>updateForm("multiple",v)}/></div>
            <div>
              <FLabel>Container volume (ml)</FLabel>
              <FInput type="number" value={form.volumeMl||""} onChange={v=>updateForm("volumeMl",v)} placeholder="e.g. 750"/>
              <div style={{ fontSize:10, color:T.textLight, marginTop:3 }}>Volume of one bottle/container. Used by Till Reconciliation. Leave blank for items sold whole.</div>
            </div>
          </div>
          <div style={{ display:"flex", gap:10, marginTop:16 }}>
            <button onClick={handleSubmit} style={{ background:T.midBlue, color:"#fff", border:"none", padding:"9px 22px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:14, fontWeight:700 }}>Save</button>
            <button onClick={()=>{setForm(null);setEditId(null);}} style={{ background:"none", color:T.textMid, border:`1px solid ${T.border}`, padding:"9px 18px", borderRadius:6, cursor:"pointer", fontFamily:"inherit", fontSize:13 }}>Cancel</button>
          </div>
        </div>
      )}

      <div style={{ background:"#fff", border:`1px solid ${T.border}`, borderRadius:10, overflow:"hidden", boxShadow:"0 2px 8px rgba(37,99,235,.06)" }}>
        <table style={{ width:"100%", borderCollapse:"collapse" }}>
          <thead>
            <tr style={{ background:"#eef4fd" }}>
              {["Product","Category","Supplier","Buy Price","Multiple","Est. Sale",""].map(h=>(
                <th key={h} style={{ padding:"10px 14px", textAlign:"left", color:T.textMid, fontSize:11, letterSpacing:1.2, textTransform:"uppercase", fontWeight:700 }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((p,i)=>(
              <tr key={p.id} style={{ borderTop:i>0?`1px solid ${T.border}`:"none" }}
                onMouseEnter={e=>e.currentTarget.style.background="#f5f9ff"}
                onMouseLeave={e=>e.currentTarget.style.background="transparent"}>
                <td style={{ padding:"10px 14px", fontSize:13, fontWeight:600, color:T.text }}>{p.name}</td>
                <td style={{ padding:"10px 14px" }}><CatBadge cat={p.category}/></td>
                <td style={{ padding:"10px 14px", fontSize:12, color:T.textLight }}>{p.supplier}</td>
                <td style={{ padding:"10px 14px", fontSize:13 }}>{fmt2(p.costUnit)}</td>
                <td style={{ padding:"10px 14px", fontSize:13, color:T.textMid }}>{p.multiple}x</td>
                <td style={{ padding:"10px 14px", fontSize:13, color:T.green, fontWeight:500 }}>{p.costUnit ? fmt2(p.costUnit*p.multiple) : "—"}</td>
                <td style={{ padding:"10px 14px", whiteSpace:"nowrap" }}>
                  <button onClick={()=>handleEdit(p)} style={{ background:T.accentLight, border:"none", color:T.accent, padding:"4px 12px", borderRadius:5, cursor:"pointer", fontSize:12, fontFamily:"inherit", fontWeight:600, marginRight:6 }}>Edit</button>
                  <button onClick={()=>handleDelete(p.id)} style={{ background:T.redBg, border:"none", color:T.red, padding:"4px 10px", borderRadius:5, cursor:"pointer", fontSize:12, fontFamily:"inherit" }}>✕</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

